local function forget_clone(item)
    if not item then
        return
    end
    for i = #all_source_clones, 1, -1 do
        if all_source_clones[i] == item then
            table.remove(all_source_clones, i)
        end
    end
    for i = #auto_cleanup, 1, -1 do
        if auto_cleanup[i] == item then
            table.remove(auto_cleanup, i)
        end
    end
    if item._unload_cleanup and obs and obs._unload then
        for i = #obs._unload, 1, -1 do
            if obs._unload[i] == item._unload_cleanup then
                table.remove(obs._unload, i)
            end
        end
        item._unload_cleanup = nil
    end
end
local EASING_FUNCS = {
    linear = function(t)
        return t
    end,

    quad_in = function(t)
        return t * t
    end,
    quad_out = function(t)
        return t * (2 - t)
    end,
    quad_inout = function(t)
        if t < 0.5 then
            return 2 * t * t
        else
            return -1 + (4 - 2 * t) * t
        end
    end,

    sine_inout = function(t)
        return 0.5 * (1 - math.cos(math.pi * t))
    end,

    back_out = function(t)
        local c1 = 1.70158
        local c3 = c1 + 1
        return 1 + c3 * math.pow(t - 1, 3) + c1 * math.pow(t - 1, 2)
    end,

    elastic_out = function(t)
        if t == 0 then
            return 0
        end
        if t == 1 then
            return 1
        end
        return math.pow(2, -10 * t) * math.sin((t * 10 - 0.75) * (2 * math.pi) / 3) + 1
    end,

    bounce_out = function(t)
        local n1 = 7.5625
        local d1 = 2.75
        if t < 1 / d1 then
            return n1 * t * t
        elseif t < 2 / d1 then
            t = t - 1.5 / d1
            return n1 * t * t + 0.75
        elseif t < 2.5 / d1 then
            t = t - 2.25 / d1
            return n1 * t * t + 0.9375
        else
            t = t - 2.625 / d1
            return n1 * t * t + 0.984375
        end
    end
}
