        row[1].x,row[1].y,row[1].z,row[1].w=cy*sr*object.width,(sy*sp*sr+cp*cr)*object.height,(sy*cp*sr-sp*cr)*object.depth,object.y
        row[2].x,row[2].y,row[2].z,row[2].w=-sy*object.width,cy*sp*object.height,cy*cp*object.depth,object.z
        row[3].x,row[3].y,row[3].z,row[3].w=object.red/255,object.green/255,object.blue/255,1
