local world3d_source_info = {}
for key, value in pairs(raymaze_source_info) do world3d_source_info[key] = value end
world3d_source_info.id = "im3_world3d_renderer"
world3d_source_info.get_name = function() return "4IM3 3D Renderer" end
world3d_source_info.update = function(data, settings)
    raymaze_source_info.update(data, settings)
    local world = world3d_worlds[data.name]
    if world then world.width, world.height = data.width, data.height end
end
world3d_source_info.video_render = function(data)
    local world = data._view_world or world3d_worlds[data.name]
    if not world then return end
    local graphics, library_error = raymaze_graphics()
    if not graphics then
        if not data.logged_error then
            obslua.script_log(obslua.LOG_ERROR, "[4IM3-SCRIPT] 3D renderer unavailable: " .. library_error)
            data.logged_error = true
        end
        return
    end
    if not data.effect and not data.effect_failed then
        local errors = ffi.new("char *[1]")
        data.effect = graphics.gs_effect_create(world3d_effect_source, "4im3_builtin_3d.effect", errors)
        if errors[0] ~= nil then
            obslua.script_log(obslua.LOG_ERROR, "[4IM3-SCRIPT] 3D effect: " .. ffi.string(errors[0]))
            graphics.bfree(errors[0])
        end
        if data.effect == nil then data.effect_failed = true end
        if data.effect then
            data.tint_param = graphics.gs_effect_get_param_by_name(data.effect, "Tint")
            data.texture_mode_param = graphics.gs_effect_get_param_by_name(data.effect,"TextureMode")
            data.diffuse_param = graphics.gs_effect_get_param_by_name(data.effect,"Diffuse")
            data.spot_origin_param = graphics.gs_effect_get_param_by_name(data.effect,"SpotOrigin")
            data.spot_direction_param = graphics.gs_effect_get_param_by_name(data.effect,"SpotDirection")
            data.spot_color_param = graphics.gs_effect_get_param_by_name(data.effect,"SpotColor")
            data.spot_settings_param = graphics.gs_effect_get_param_by_name(data.effect,"SpotSettings")
            data.object_scale_param = graphics.gs_effect_get_param_by_name(data.effect,"ObjectScale")
            data.clip_plane_param = graphics.gs_effect_get_param_by_name(data.effect,"ClipPlane")
            data.clip_settings_param = graphics.gs_effect_get_param_by_name(data.effect,"ClipSettings")
        end
    end
    if not data.effect then return end
    if not data.cube then data.cube = world3d_build_box(graphics) end
    if not data.cube then return end
    if not data.texrender then data.texrender = graphics.gs_texrender_create(3, 2) end
    if not data.texrender then return end
    if data.mesh_world_ref ~= world then
        world3d_mesh_spares_clear(graphics,data)
        for _, cached in pairs(data.mesh_cache or {}) do
            world3d_mesh_release(graphics,cached)
        end
        for _,upload in pairs(data.mesh_uploads or {}) do
            world3d_mesh_release(graphics,upload)
        end
        data.mesh_uploads={}
        data.mesh_cache, data.mesh_world_ref, data.mesh_pool = {}, world, {}
        for _,pooled in pairs(data.texture_pool or {}) do
            if pooled.texture then graphics.gs_texture_destroy(pooled.texture) end
        end
        data.texture_cache={}
        data.texture_pool={}
    end
    for name, cached in pairs(data.mesh_cache) do
        local object = world.objects[name]
        if not object or object.kind ~= "mesh" or
           ((object.geometry_version ~= cached.version or object~=cached.object) and not object._mesh_packets) then
            world3d_mesh_release(graphics,cached)
            data.mesh_cache[name] = nil
        end
    end
    if not data._view_pass then
        world3d_mesh_uploads(graphics,data,world)
        world3d_render_views(data,world)
    end
    for name,cached in pairs(data.texture_cache) do
        local object=world.objects[name]
        if not object or object~=cached.object or
           object.texture_version~=cached.version then
            if cached.pool then
                cached.pool.refs=cached.pool.refs-1
                if cached.pool.refs==0 then
                    if cached.pool.texture then graphics.gs_texture_destroy(cached.pool.texture) end
                    data.texture_pool[cached.key]=nil
                end
            end
            data.texture_cache[name]=nil
        end
    end
    if data.world_ref ~= world or data.rendered_version ~= world.version or
       data.rendered_width ~= data.width or data.rendered_height ~= data.height then
        graphics.gs_texrender_reset(data.texrender)
        if graphics.gs_texrender_begin(data.texrender, data.width, data.height) then
            local old_cull = graphics.gs_get_cull_mode()
            graphics.gs_blend_state_push()
            graphics.gs_enable_blending(false)
            graphics.gs_enable_depth_test(true)
            graphics.gs_set_cull_mode(2) -- GS_NEITHER: both sides of a triangle are visible.
            local ok, render_error = pcall(function()
                local bg = world.background
                data.clear_vec = data.clear_vec or ffi.new("im3_vec4[1]")
                local clear_color = data.clear_vec
                clear_color[0].x, clear_color[0].y = bg.red / 255, bg.green / 255
                clear_color[0].z, clear_color[0].w = bg.blue / 255, 1
                graphics.gs_clear(3, clear_color, 1, 0) -- GS_CLEAR_COLOR | GS_CLEAR_DEPTH
                local camera = world.camera
                if camera.offcenter==1 then
                    -- Match gs_perspective's ymin/ymax argument order. Script
                    -- frustum bounds use world up, while OBS's top is ymin.
                    graphics.gs_frustum(camera.left,camera.right,camera.bottom,camera.top,camera.near,camera.far)
