                end
                graphics.gs_matrix_rotaa4f(0, 0, 1, -math.rad(camera.roll or 0))
                graphics.gs_matrix_rotaa4f(1, 0, 0, -math.rad(camera.pitch))
                graphics.gs_matrix_rotaa4f(0, 1, 0, -math.rad(camera.yaw))
                graphics.gs_matrix_translate3f(-camera.x, -camera.y, -camera.z)
                data.tint_vec = data.tint_vec or ffi.new("im3_vec4[1]")
                data.spot_vec = data.spot_vec or ffi.new("im3_vec4[1]")
                local light = world.spotlight or {enabled=0}
                local spot_yaw, spot_pitch = math.rad(light.yaw or 0), math.rad(light.pitch or 0)
                local lx = -math.sin(spot_yaw)*math.cos(spot_pitch)
                local ly = math.sin(spot_pitch)
                local lz = -math.cos(spot_yaw)*math.cos(spot_pitch)
                local function set_spot(param,x,y,z,w)
                    if not param then return end
                    local vec=data.spot_vec
                    vec[0].x,vec[0].y,vec[0].z,vec[0].w=x,y,z,w
                    graphics.gs_effect_set_vec4(param,vec)
                end
                set_spot(data.spot_color_param,
                    (light.red or 255)/255,(light.green or 255)/255,
                    (light.blue or 255)/255,light.ambient or 0.35)
                set_spot(data.spot_settings_param,light.enabled or 0,
                    math.cos(math.rad((light.angle or 60)*0.5)),
                    light.range or 20,light.intensity or 2)
                set_spot(data.spot_origin_param,0,0,0,0)
                set_spot(data.spot_direction_param,0,-1,0,0)
                set_spot(data.clip_settings_param,camera.clip_enabled or 0,0,0,0)
                local drawn_instances={}
                data.instance_draws,data.instanced_objects=0,0
                for object_index, name in ipairs(world.order) do
                    local box = world.objects[name]
                    -- Draw the complete previous object while a replacement uploads.
                    if box and box._mesh_packets then
                        local cached=data.mesh_cache[name]
