                    if box and box.visible~=0 and not drawn_instances[name] and not (data._view_pass and box.view) then
                        local buffer, vertex_count = data.cube, 36
                        if box.kind == "mesh" then
                            local cached = data.mesh_cache[name]
                            if not cached then
                                cached=world3d_mesh_shared(data,box)
                                if not cached then
                                    local mesh_buffer = world3d_build_mesh(graphics, box)
                                    if not mesh_buffer then error("Mesh '" .. name .. "' GPU buffer creation failed") end
                                    cached=world3d_mesh_shared(data,box,{buffer=mesh_buffer,count=#box.triangles})
                                end
                                data.mesh_cache[name] = cached
