                        local instances,instance_names,native
                        if box.kind=="mesh" and not box._mesh_packets and not box.view then
                            -- Consecutive copies preserve opaque equal-depth draw
                            -- ordering. A different material/geometry ends a group.
                            for index=object_index+1,math.min(#world.order,object_index+255) do
                                local other_name=world.order[index]
                                local other=world.objects[other_name]
                                if not other or other.visible==0 or other._mesh_packets or other.view or
                                   other.kind~="mesh" or other.vertices~=box.vertices or
                                   other.triangles~=box.triangles or other.uvs~=box.uvs or
                                   other.texture_path~=box.texture_path or other.texture_bytes~=box.texture_bytes or
                                   other.texture_mime~=box.texture_mime then break end
