                                        local key=instance_names[index]
                                        if not data.mesh_cache[key] then
                                            data.mesh_cache[key]=world3d_mesh_shared(data,instances[index])
                                        end
                                    end
                                end
                            end
                        end
                        graphics.gs_matrix_push()
                        local object_ok, object_error = pcall(function()
                            if not instances then
                                graphics.gs_matrix_translate3f(box.x, box.y, box.z)
                                graphics.gs_matrix_rotaa4f(0, 0, 1, math.rad(box.roll))
                                graphics.gs_matrix_rotaa4f(0, 1, 0, math.rad(box.yaw))
                                graphics.gs_matrix_rotaa4f(1, 0, 0, math.rad(box.pitch))
                                graphics.gs_matrix_scale3f(box.width, box.height, box.depth)
                            end
                            if instances then
                                set_spot(data.spot_origin_param,light.x or 0,light.y or 0,light.z or 0,0)
                                set_spot(data.spot_direction_param,lx,ly,lz,0)
                            elseif light.enabled==1 then
                                local dx,dy,dz=lx,ly,lz
                                local ox=(light.x or 0)-box.x
                                local oy=(light.y or 0)-box.y
                                local oz=(light.z or 0)-box.z
                                local roll=-math.rad(box.roll)
                                local cr,sr=math.cos(roll),math.sin(roll)
                                ox,oy=ox*cr-oy*sr,ox*sr+oy*cr
                                dx,dy=dx*cr-dy*sr,dx*sr+dy*cr
                                local yaw=-math.rad(box.yaw)
                                local cy,sy=math.cos(yaw),math.sin(yaw)
