                                dx,dz=dx*cy+dz*sy,-dx*sy+dz*cy
                                local pitch=-math.rad(box.pitch)
                                local cp,sp=math.cos(pitch),math.sin(pitch)
                                oy,oz=oy*cp-oz*sp,oy*sp+oz*cp
                                dy,dz=dy*cp-dz*sp,dy*sp+dz*cp
                                set_spot(data.spot_origin_param,
                                    ox/box.width,oy/box.height,oz/box.depth,0)
                                set_spot(data.spot_direction_param,dx,dy,dz,0)
                            end
                            set_spot(data.object_scale_param,
                                instances and 1 or box.width,instances and 1 or box.height,instances and 1 or box.depth,0)
                            set_spot(data.clip_plane_param,world3d_object_clip(camera,box,instances~=nil))
                            if data.tint_param ~= nil then
                                local tint = data.tint_vec
                                tint[0].x, tint[0].y = instances and 1 or box.red / 255, instances and 1 or box.green / 255
                                tint[0].z, tint[0].w = instances and 1 or box.blue / 255, 1
                                graphics.gs_effect_set_vec4(data.tint_param, tint)
                            end
                            local texture
                            if box.view and data.view_targets and data.view_targets[box.view] then
                                local target=data.view_targets[box.view]
                                if target.texrender then texture=graphics.gs_texrender_get_texture(target.texrender) end
                            elseif box.kind=="mesh" and box.uvs and
                               (box.texture_path or box.texture_bytes) then
                                local cached=data.texture_cache[name]
                                if not cached then
                                    local key=box.texture_path or box.texture_bytes
                                    local pooled=data.texture_pool[key]
                                    local why
                                    if not pooled then
                                        local loaded
                                        loaded,why=world3d_load_texture(graphics,box)
                                        pooled={texture=loaded,refs=0}
                                        data.texture_pool[key]=pooled
                                    end
                                    pooled.refs=pooled.refs+1
                                    cached={object=box,version=box.texture_version,
                                            texture=pooled.texture,pool=pooled,key=key}
                                    data.texture_cache[name]=cached
                                    if not pooled.texture and not data.logged_texture_error then
                                        obslua.script_log(obslua.LOG_ERROR,
                                            "[4IM3-SCRIPT] 3D texture for '" .. name ..
                                            "' could not load: " .. tostring(why or box.texture_path))
                                        data.logged_texture_error=true
                                    end
                                end
                                texture=cached.texture
                            end
                            if data.texture_mode_param then
                                local mode=data.tint_vec
                                mode[0].x=texture and 1 or 0
                                mode[0].y=box.view and 1 or 0
                                mode[0].z=(box.view and box.unlit~=0) and 1 or 0
                                mode[0].w=0
                                graphics.gs_effect_set_vec4(data.texture_mode_param,mode)
                            end
                            if texture and data.diffuse_param then
                                graphics.gs_effect_set_texture(data.diffuse_param,texture)
                            end
                            graphics.gs_load_indexbuffer(nil)
                            while graphics.gs_effect_loop(data.effect, "Draw") do
                                local cached=box.kind=="mesh" and data.mesh_cache[name]
                                if cached and cached.parts then
                                    for _,part in ipairs(cached.parts) do
                                        if instances then
                                            local ok,why=WORLD3D_NATIVE.draw(native,graphics,part.buffer,part.count,#instances)
                                            if not ok then error(why) end
                                            data.instance_draws=data.instance_draws+1
                                        else
                                            graphics.gs_load_vertexbuffer(part.buffer)
                                            graphics.gs_draw(3,0,part.count)
                                        end
                                    end
                                elseif instances then
                                    local ok,why=WORLD3D_NATIVE.draw(native,graphics,buffer,vertex_count,#instances)
                                    if not ok then error(why) end
                                    data.instance_draws=data.instance_draws+1
                                else
                                    graphics.gs_load_vertexbuffer(buffer)
                                    graphics.gs_draw(3, 0, vertex_count) -- GS_TRIS
                                end
                            end
                        end)
                        graphics.gs_matrix_pop()
                        if not object_ok then
                            if instances then
                                data.native_instances_error=tostring(object_error)
                                WORLD3D_NATIVE.destroy(data,graphics,false);data.native_instances=false
                            end
                            error(object_error)
                        end
                        if instances then
                            data.instanced_objects=data.instanced_objects+#instances
                            for _,key in ipairs(instance_names) do drawn_instances[key]=true end
                        end
                    end
                end
            end)
            graphics.gs_enable_depth_test(false)
            graphics.gs_set_cull_mode(old_cull)
            graphics.gs_blend_state_pop()
            graphics.gs_texrender_end(data.texrender)
            if ok then
                world._mesh_stats={backend=data.instance_draws>0 and "d3d11_instancing" or "portable",
                    instance_draws=data.instance_draws,instanced_objects=data.instanced_objects,
                    native_available=type(data.native_instances)=="table" and 1 or 0,
                    view_count=data.view_count or 0,view_ms=data.view_ms or 0}
                data.world_ref, data.rendered_version = world, world.version
                data.rendered_width, data.rendered_height = data.width, data.height
            elseif not data.logged_render_error then
                obslua.script_log(obslua.LOG_ERROR,
                    "[4IM3-SCRIPT] 3D renderer '" .. data.name .. "': " .. tostring(render_error))
                data.logged_render_error = true
            end
        end
    end
    if data._view_pass then return end
    local texture = graphics.gs_texrender_get_texture(data.texrender)
    if texture then
        -- OBS_SOURCE_CUSTOM_DRAW does not supply the default image effect.
        -- Present the finished render target under that effect explicitly.
        local output_effect = graphics.obs_get_base_effect(0) -- OBS_EFFECT_DEFAULT
        if (world.blur or 0) > 0 and not data.blur_effect_failed then
            if not data.blur_effect then
                local errors = ffi.new("char *[1]")
                data.blur_effect = graphics.gs_effect_create(
                    world3d_blur_effect_source, "4im3_builtin_blur.effect", errors)
                if errors[0] ~= nil then
                    obslua.script_log(obslua.LOG_ERROR,
                        "[4IM3-SCRIPT] 3D blur effect: " .. ffi.string(errors[0]))
                    graphics.bfree(errors[0])
                end
                if data.blur_effect then
                    data.blur_step_param = graphics.gs_effect_get_param_by_name(
                        data.blur_effect, "BlurStep")
                else
                    data.blur_effect_failed = true
                end
            end
            if data.blur_effect and data.blur_step_param then
                data.blur_step_vec = data.blur_step_vec or ffi.new("im3_vec4[1]")
                data.blur_step_vec[0].x = world.blur / data.width
                data.blur_step_vec[0].y = world.blur / data.height
                data.blur_step_vec[0].z, data.blur_step_vec[0].w = 0, 0
                graphics.gs_effect_set_vec4(data.blur_step_param,
                                            data.blur_step_vec)
                output_effect = data.blur_effect
            end
        end
        if output_effect then
            local image_param = graphics.gs_effect_get_param_by_name(output_effect, "image")
            if image_param then
                graphics.gs_effect_set_texture(image_param, texture)
                while graphics.gs_effect_loop(output_effect, "Draw") do
                    -- The offscreen 3D target has the opposite vertical origin
                    -- from the scene quad. Flip only this final presentation.
                    graphics.obs_source_draw(texture, 0, 0, data.width, data.height, true)
                end
            end
        end
    end
end
world3d_source_info.destroy = function(data)
    if interaction_current == data then interaction_current = nil end
    for _,target in pairs(data.view_targets or {}) do world3d_source_info.destroy(target) end
    data.view_targets=nil
    if data.texrender or data.effect or data.blur_effect or data.cube or data.mesh_cache or data.texture_cache then
        local graphics = raymaze_graphics()
        if graphics then
            WORLD3D_NATIVE.destroy(data,graphics,true)
            world3d_mesh_spares_clear(graphics,data,nil,true)
            for _, cached in pairs(data.mesh_cache or {}) do
                world3d_mesh_release(graphics,cached,true)
            end
            for _,upload in pairs(data.mesh_uploads or {}) do
                world3d_mesh_release(graphics,upload,true)
            end
            for _,pooled in pairs(data.texture_pool or {}) do
                queue_graphics_destroy(graphics, "gs_texture_destroy", pooled.texture)
            end
            queue_graphics_destroy(graphics, "gs_texrender_destroy", data.texrender)
            queue_graphics_destroy(graphics, "gs_vertexbuffer_destroy", data.cube)
            queue_graphics_destroy(graphics, "gs_effect_destroy", data.effect)
            queue_graphics_destroy(graphics, "gs_effect_destroy", data.blur_effect)
        end
    end
    data.mesh_cache = nil
    data.mesh_uploads = nil
    data.mesh_spares = nil
    data.texture_cache = nil
    data.texture_pool = nil
    data.texrender,data.effect,data.blur_effect,data.cube=nil,nil,nil,nil
    if data._view_pass then return end
    local removed_world = world3d_worlds[data.name]
    if world3d_cancel_builds then world3d_cancel_builds(removed_world) end
    world3d_worlds[data.name] = nil
    -- OBS may destroy a renderer while an Execute loop still uses it. Defer
    -- stopping that loop until the next tick, outside the source callback.
    if removed_world and src and src.isInitialized and
       src.world3d_selected == data.name then
        src.world3d_removed_source = data.name
    end
end

function world3d_object_clip(camera,object,instanced)
    if camera.clip_enabled~=1 then return 0,0,0,0 end
    local nx,ny,nz,d=camera.clip_x,camera.clip_y,camera.clip_z,camera.clip_d
    if instanced then return nx,ny,nz,d end
    local cp,sp=math.cos(math.rad(object.pitch)),math.sin(math.rad(object.pitch))
    local cy,sy=math.cos(math.rad(object.yaw)),math.sin(math.rad(object.yaw))
    local cr,sr=math.cos(math.rad(object.roll)),math.sin(math.rad(object.roll))
    return (nx*cy*cr+ny*cy*sr-nz*sy)*object.width,
        (nx*(sy*sp*cr-cp*sr)+ny*(sy*sp*sr+cp*cr)+nz*cy*sp)*object.height,
        (nx*(sy*cp*cr+sp*sr)+ny*(sy*cp*sr-sp*cr)+nz*cy*cp)*object.depth,
        d+nx*object.x+ny*object.y+nz*object.z
end
function world3d_render_views(data,world)
    local started=engine_tick_now_ms()
    local count=0
    data.view_targets=data.view_targets or {}
    for name,target in pairs(data.view_targets) do
        local view=world.views and world.views[name]
        if not view or view.enabled==0 or target._view_source~=world then
            world3d_source_info.destroy(target);data.view_targets[name]=nil
        end
    end
    for name,view in pairs(world.views or {}) do
        if view.enabled~=0 then
            count=count+1
            local target=data.view_targets[name]
            if not target then
                target={name=data.name,_view_pass=true,_view_source=world,_view_world={}}
                data.view_targets[name]=target
            end
            local proxy=target._view_world
            proxy.objects,proxy.order,proxy.background,proxy.spotlight=world.objects,world.order,world.background,world.spotlight
            proxy.version,proxy.camera=world.version,view
            target.width,target.height=view.width,view.height
            world3d_source_info.video_render(target)
        end
    end
    data.view_count,data.view_ms=count,engine_tick_now_ms()-started
end
WORLD3D_VIEW_FIELDS={"x","y","z","yaw","pitch","roll","fov","near","far","width","height",
    "enabled","offcenter","left","right","top","bottom","clip_enabled","clip_x","clip_y","clip_z","clip_d"}
function world3d_view_record(ctx,previous,fields)
    local view={x=0,y=0,z=0,yaw=0,pitch=0,roll=0,fov=70,near=.05,far=1000,width=512,height=512,
        enabled=1,offcenter=0,left=-.05,right=.05,top=.05,bottom=-.05,
        clip_enabled=0,clip_x=0,clip_y=0,clip_z=1,clip_d=0}
    for _,key in ipairs(WORLD3D_VIEW_FIELDS) do
        if previous then view[key]=previous[key] end
        if fields[key] then
            local value=resolve_path(ctx,fields[key])
            if is_fatal(value) or type(value)~="number" or value~=value or math.abs(value)==math.huge then
                return nil,key.." must be a finite number"
            end
            view[key]=value
        end
    end
    if view.near<=0 or view.near>=view.far or view.fov<=0 or view.fov>=180 then return nil,"view needs 0<near<far and 0<fov<180" end
    for _,key in ipairs({"width","height"}) do
        if view[key]<1 or view[key]>8192 or view[key]%1~=0 then return nil,"view dimensions must be whole pixels from 1 to 8192" end
    end
    for _,key in ipairs({"enabled","offcenter","clip_enabled"}) do
        if view[key]~=0 and view[key]~=1 then return nil,key.." must be 0 or 1" end
    end
    if view.left>=view.right or view.bottom>=view.top then return nil,"view needs left<right and bottom<top" end
    if view.clip_enabled==1 and view.clip_x^2+view.clip_y^2+view.clip_z^2<1e-16 then return nil,"clip plane needs a nonzero normal" end
    return view
end

-- Named graphics arguments are optional. Positional commands keep their
-- original meaning; named attributes may appear in any order and may share
-- a pipe-delimited field when separated by commas.
local graphics_aliases = {
    r = "red", g = "green", b = "blue", w = "width", h = "height",
    renderer = "name", source = "name", type = "kind",
    message = "text", content = "text", xs = "x_table", ys = "y_table",
    old_x = "previous_x", old_y = "previous_y", alpha = "interpolation",
}
local graphics_schemas = {
    renderer_ensure = {fields = {"name", "kind", "width", "height", "scale", "locked"},
                       required = 4, defaults = {scale = "1"}},
    canvas_init = {fields = {"name", "width", "height"}, required = 3},
    canvas_select = {fields = {"name"}, required = 1},
    canvas_clear = {fields = {"red", "green", "blue", "opacity"},
                    required = 3, defaults = {opacity = "255"}},
    canvas_rect = {fields = {"x", "y", "width", "height", "red", "green", "blue"}, required = 7},
    canvas_circle = {fields = {"x", "y", "radius", "red", "green", "blue"}, required = 6},
    canvas_text = {fields = {"text", "x", "y", "scale", "red", "green", "blue", "font"},
                   required = {"text", "x", "y", "red", "green", "blue"},
                   defaults = {scale = "1", font = "classic"}},
    canvas_rects = {fields = {"x_table", "y_table", "first", "last",
        "origin_x", "origin_y", "stride_x", "stride_y", "inset_x", "inset_y",
        "width", "height", "red", "green", "blue", "previous_x",
        "previous_y", "interpolation"}, required = 15},
}
for _, schema in pairs(graphics_schemas) do
    schema.allowed = {}
    for _, field in ipairs(schema.fields) do schema.allowed[field] = true end
end
-- Split comma-grouped named fields without splitting quoted strings or
-- expressions such as x:math.min(left,right).
local function split_named_attribute_group(raw)
    local parts, start = {}, 1
    local quote, escaped = nil, false
    local paren, bracket, brace = 0, 0, 0
    for i = 1, #raw do
        local char = raw:sub(i, i)
        if quote then
            if escaped then escaped = false
            elseif char == "\\" then escaped = true
            elseif char == quote then quote = nil end
        elseif char == '"' or char == "'" then quote = char
        elseif char == "(" then paren = paren + 1
        elseif char == ")" then paren = paren - 1
        elseif char == "[" then bracket = bracket + 1
        elseif char == "]" then bracket = bracket - 1
        elseif char == "{" then brace = brace + 1
        elseif char == "}" then brace = brace - 1
        elseif char == "," and paren == 0 and bracket == 0 and brace == 0 then
            local part = raw:sub(start, i - 1):match("^%s*(.-)%s*$")
            if part == "" then return nil, "Empty attribute in comma group" end
            parts[#parts + 1] = part
            start = i + 1
        end
    end
    local part = raw:sub(start):match("^%s*(.-)%s*$")
    if part == "" then return nil, "Empty attribute in comma group" end
    parts[#parts + 1] = part
    return parts
end
local function normalize_graphics_arguments(args, schema_name)
    local schema = graphics_schemas[schema_name]
    if not schema then return args end
    -- Old positional draw calls are common inside frame loops. Inspect only
    -- their first value so they pay no per-attribute parsing cost.
    local first_key = tostring(args[2] or ""):match("^%s*([%a_][%w_]*)%s*:")
    local first_field = first_key and
        (graphics_aliases[first_key:lower()] or first_key:lower())
    if not first_field or not schema.allowed[first_field] then return args end
    local values = {}
    for i = 2, #args do
        local parts, split_error = split_named_attribute_group(tostring(args[i] or ""))
        if not parts then return nil, split_error end
        for _, part in ipairs(parts) do
            local key, value = part:match("^%s*([%a_][%w_]*)%s*:%s*(.-)%s*$")
            if not key then return nil, "Named arguments cannot be mixed with positional arguments" end
            local field = graphics_aliases[key:lower()] or key:lower()
            if not schema.allowed[field] then
                return nil, "Unknown attribute '" .. key .. "' for " .. schema_name:gsub("_", " ")
            end
            if values[field] ~= nil then return nil, "Duplicate attribute '" .. field .. "'" end
            if value == "" then return nil, "Attribute '" .. field .. "' needs a value" end
            values[field] = value
        end
    end
    for field, value in pairs(schema.defaults or {}) do
        if values[field] == nil then values[field] = value end
    end
    local required = schema.required
    if type(required) == "number" then
        for i = 1, required do
            local field = schema.fields[i]
            if values[field] == nil then return nil, "Missing attribute '" .. field .. "'" end
        end
    else
        for _, field in ipairs(required) do
            if values[field] == nil then return nil, "Missing attribute '" .. field .. "'" end
        end
    end
    local normalized = {args[1]}
    for i, field in ipairs(schema.fields) do normalized[i + 1] = values[field] end
    return normalized
end

-- !renderer | create | name:View | kind:pixel | width:640 | height:360 | scale:2 | locked:true
-- Legacy alias: !renderer | ensure | source_name | kind | width | height | scale
-- Creates a direct item in the active scene, or configures an existing item
-- with the same name and source type. A name collision of another type fails.
engine["renderer"] = function(ctx, state, args)
    local function fail(message)
        local detail = "Renderer Error: " .. message
        obslua.script_log(obslua.LOG_ERROR, "[4IM3-SCRIPT] " .. detail)
        return false, detail
    end
    local action = tostring(args[1] or "")
    if action ~= "create" and action ~= "ensure" then
        return fail("Expected create | name | kind | width | height | optional_scale")
    end
    local normalized, named_error = normalize_graphics_arguments(args, "renderer_ensure")
    if not normalized then return fail(named_error) end
    args = normalized
    local name = tostring(args[2] or "")
    if name == "" then return fail("Missing source name") end
    local kinds = {
        shader = shader_source_info.id,
        pixel = raymaze_source_info.id,
        ["3d"] = world3d_source_info.id,
    }
    local kind = tostring(args[3] or "")
    local source_id = kinds[kind]
    if not source_id then return fail("Unknown renderer kind '" .. kind .. "'") end
    local function number(raw, label)
        local result = evaluate_math(ctx, tostring(raw or ""))
        if is_fatal(result) then return nil, label .. ": " .. tostring(result.msg) end
        result = tonumber(result)
        if not result or result ~= result then return nil, label .. " must be numeric" end
        return result
    end
    local width, width_error = number(args[4], "width")
    local height, height_error = number(args[5], "height")
    local scale, scale_error = number(args[6] or "1", "scale")
    local lock_setting=args[7]
    local locked
    if lock_setting~=nil and tostring(lock_setting)~="" then
        local value=tostring(lock_setting):lower()
        if value~="true" and value~="false" and value~="1" and value~="0" then
            return fail("locked must be true or false")
        end
        locked=value=="true" or value=="1"
    end
    if not width or not height or not scale then
        return fail(width_error or height_error or scale_error)
    end
    if width < 1 or width > 8192 or width % 1 ~= 0 or
       height < 1 or height > 8192 or height % 1 ~= 0 or
       scale <= 0 or scale > 32 then
        return fail("Dimensions must be whole numbers from 1 to 8192; scale must be above 0 and at most 32")
    end
    local scene_source = obslua.obs_frontend_get_current_scene()
    if not scene_source then return fail("No active scene") end
    local scene_name = obslua.obs_source_get_name(scene_source)
    local scene = obslua.obs_scene_from_source(scene_source)
    if not scene then
        obslua.obs_source_release(scene_source)
        return fail("Active source '" .. tostring(scene_name) .. "' is not a scene")
    end
    local item = obslua.obs_scene_find_source(scene, name)
    local source
    if item then
        source = obslua.obs_sceneitem_get_source(item)
        local actual = obslua.obs_source_get_id(source)
        if actual ~= source_id and actual ~= source_id .. "_v2" then
            obslua.obs_source_release(scene_source)
            return fail("Source '" .. name .. "' in scene '" .. scene_name ..
                "' has type '" .. tostring(actual) .. "'; expected '" .. source_id .. "'")
        end
    else
        local collision = obslua.obs_get_source_by_name(name)
        if collision then
            obslua.obs_source_release(collision)
            obslua.obs_source_release(scene_source)
            return fail("Source name '" .. name .. "' is already used outside active scene '" .. scene_name .. "'")
        end
    end
    local settings = obslua.obs_data_create()
    obslua.obs_data_set_int(settings, "width", width)
    obslua.obs_data_set_int(settings, "height", height)
    if source then
        obslua.obs_source_update(source, settings)
    else
        source = obslua.obs_source_create(source_id, name, settings, nil)
    end
    obslua.obs_data_release(settings)
    if not source then
        obslua.obs_source_release(scene_source)
        return fail("OBS could not create source '" .. name .. "'")
    end
    if not item then
        item = obslua.obs_scene_add(scene, source)
        obslua.obs_source_release(source)
        if not item then
            obslua.obs_source_release(scene_source)
            return fail("OBS could not add source '" .. name .. "' to scene '" .. scene_name .. "'")
        end
    end
    local position = obslua.vec2()
    position.x, position.y = 0, 0
    local size = obslua.vec2()
    size.x, size.y = scale, scale
    obslua.obs_sceneitem_set_alignment(item, 5)
    obslua.obs_sceneitem_set_pos(item, position)
    obslua.obs_sceneitem_set_scale(item, size)
    if locked~=nil then obslua.obs_sceneitem_set_locked(item,locked) end
    if state and state._capture_ui_item then
        -- Capture while the renderer already has its item. UI polling must
        -- never find/enumerate scene items while holding OBS's Lua lock.
        obslua.obs_sceneitem_addref(item)
        state.ui_item,state.ui_scene,state.ui_scene_source=item,scene,scene_source
    else obslua.obs_source_release(scene_source) end
    if kind == "3d" then
        if not world3d_worlds[name] then world3d_worlds[name] = world3d_new_world() end
        world3d_worlds[name].width, world3d_worlds[name].height = width, height
        ctx.world3d_selected = name
    end
    return true
end

-- !world3d | camera | x:0,y:0,z:0 | fov:70 |+|
-- !world3d | box | name:Crate | x:0,y:0,z:-4 | width:1,height:1,depth:1 |+|
-- !world3d | mesh | name:Pyramid | vertices:"-1,-1,0;1,-1,0;0,1,0" | triangles:"1,2,3" |+|
-- The last 3D renderer created is selected automatically; use switches it.
local world3d_field_aliases = {r="red",g="green",b="blue",w="width",h="height",d="depth",
                                faces="triangles"}
local world3d_allowed = {
    view={name=true,delete=true,into=true,x=true,y=true,z=true,yaw=true,pitch=true,roll=true,fov=true,near=true,far=true,
          width=true,height=true,enabled=true,offcenter=true,left=true,right=true,top=true,bottom=true,
          clip_enabled=true,clip_x=true,clip_y=true,clip_z=true,clip_d=true},
    use={name=true}, remove={name=true}, clear={}, cancel={name=true},
    list={into=true}, stats={into=true}, get={name=true,into=true}, bounds={name=true,into=true},
    snapshot={into=true}, restore={from=true},
    duplicate={name=true,as=true}, rename={name=true,as=true},
    vertex={name=true,index=true,x=true,y=true,z=true,delete=true},
    triangle={name=true,index=true,a=true,b=true,c=true,delete=true},
    edit={name=true,mode=true},
    pick={x=true,y=true,into=true},
    save={path=true,into=true}, load={path=true,into=true}, export={path=true,into=true},
    import={path=true,name=true,x=true,y=true,z=true,scale=true,into=true},
    animate={name=true,clip=true,mode=true,loop=true,speed=true,time=true,into=true},
    update={objects=true,camera=true},
    camera={x=true,y=true,z=true,yaw=true,pitch=true,roll=true,fov=true,near=true,far=true,into=true},
    spotlight={enabled=true,x=true,y=true,z=true,yaw=true,pitch=true,
               angle=true,range=true,intensity=true,ambient=true,
               red=true,green=true,blue=true,into=true},
    background={red=true,green=true,blue=true,into=true},
    blur={amount=true},
    box={name=true,x=true,y=true,z=true,width=true,height=true,depth=true,visible=true,
         yaw=true,pitch=true,roll=true,red=true,green=true,blue=true},
    set={name=true,x=true,y=true,z=true,width=true,height=true,depth=true,visible=true,
         yaw=true,pitch=true,roll=true,red=true,green=true,blue=true},
    mesh={name=true,x=true,y=true,z=true,width=true,height=true,depth=true,visible=true,
          yaw=true,pitch=true,roll=true,red=true,green=true,blue=true,
          vertices=true,triangles=true,uvs=true,texture=true,image=true,mime=true,view=true,unlit=true,
          async=true,into=true},
    instances={name=true,mesh=true,transforms=true,async=true,into=true},
