local function world3d_parse_fields(args, allowed, action)
    local result = {}
    for i=2,#args do
        local parts, split_error = split_named_attribute_group(tostring(args[i]))
        if not parts then return nil, split_error end
        for _, part in ipairs(parts) do
            local key, value = part:match("^%s*([%a_][%w_]*)%s*:%s*(.-)%s*$")
            if not key then return nil, "Use named fields such as x:0,y:1,z:-4" end
            key = key:lower()
            if action ~= "triangle" or (key ~= "a" and key ~= "b" and key ~= "c") then
                key = world3d_field_aliases[key] or key
            end
            if not allowed[key] then return nil, "Unknown field '" .. key .. "'" end
            if result[key] ~= nil then return nil, "Duplicate field '" .. key .. "'" end
            if value == "" then return nil, "Field '" .. key .. "' needs a value" end
            result[key] = value
        end
    end
    return result
end
local function world3d_number(ctx, raw, field)
    local result = evaluate_math(ctx, raw)
    if is_fatal(result) then return nil, tostring(result.msg) end
    result = tonumber(result)
    if not result or result ~= result or result == math.huge or result == -math.huge then
        return nil, "Field '" .. field .. "' must be a finite number"
    end
    if field == "red" or field == "green" or field == "blue" then
        if result < 0 or result > 255 then return nil, field .. " must be 0 to 255" end
    elseif field == "visible" or field == "enabled" then
        if result~=0 and result~=1 then return nil,field .. " must be 0 or 1" end
    elseif field == "width" or field == "height" or field == "depth" then
        if result <= 0 then return nil, field .. " must be above 0" end
    elseif field == "fov" then
        if result < 1 or result > 179 then return nil, "fov must be 1 to 179 degrees" end
    elseif field == "near" or field == "far" then
        if result <= 0 then return nil, field .. " must be above 0" end
    elseif field == "angle" then
        if result < 1 or result > 179 then return nil,"angle must be 1 to 179 degrees" end
    elseif field == "range" then
        if result <= 0 then return nil,"range must be above 0" end
    elseif field == "intensity" then
        if result < 0 or result > 100 then return nil,"intensity must be 0 to 100" end
    elseif field == "ambient" then
        if result < 0 or result > 1 then return nil,"ambient must be 0 to 1" end
    end
    return result
end
function world3d_numeric_rows(value,width,label,integer,checkpoint)
    if type(value)~="table" then return nil,label.." needs a numeric table" end
    local count=#value
    local inspected=0
    for key in pairs(value) do
        if type(key)~="number" or key%1~=0 or key<1 or key>count then
            return nil,label.." must be a dense list"
        end
        inspected=inspected+1
        if checkpoint and inspected%128==0 then checkpoint() end
    end
    local nested=type(value[1])=="table"
    if count==0 or (not nested and count%width~=0) then return nil,label.." has an invalid length" end
    local rows={}
    for i=1,(nested and count or count/width) do
        local source=nested and value[i] or value
        if nested then
            if type(source)~="table" or #source~=width then return nil,label.." has an invalid row" end
            for key in pairs(source) do
                if type(key)~="number" or key%1~=0 or key<1 or key>width then return nil,label.." has an invalid row" end
            end
        end
        local row={}
        for j=1,width do
            local number=source[nested and j or ((i-1)*width+j)]
            if type(number)~="number" or number~=number or math.abs(number)==math.huge or
               (integer and number%1~=0) then
                return nil,label.." contains an invalid number"
            end
            row[j]=number
        end
        rows[i]=row
        if checkpoint and i%64==0 then checkpoint() end
    end
    return rows
end
local function world3d_mesh_geometry(ctx, vertex_raw, triangle_raw,checkpoint,resolved)
    checkpoint=checkpoint or ctx.world3d_mesh_checkpoint
    local function input_text(raw, field)
        local value = resolved and raw or resolve_path(ctx, tostring(raw))
        if is_fatal(value) then return nil, field .. ": " .. tostring(value.msg) end
        if (type(value) ~= "string" and type(value)~="table") or value == "" then
            return nil, field .. " must be a quoted list or numeric table"
        end
        return value
    end
    local vertex_text, error_text = input_text(vertex_raw, "vertices")
    if not vertex_text then return nil, nil, error_text end
    local triangle_text
    triangle_text, error_text = input_text(triangle_raw, "triangles")
    if not triangle_text then return nil, nil, error_text end
    local function triples(value, label, integer)
        if type(value)=="table" then return world3d_numeric_rows(value,3,label,integer,checkpoint) end
        local result = {}
        for part in (value .. ";"):gmatch("(.-);") do
            local row = {}
            for token in (part .. ","):gmatch("(.-),") do
                local number = tonumber(token:match("^%s*(.-)%s*$"))
                if not number or number ~= number or number == math.huge or number == -math.huge or
                   (integer and number % 1 ~= 0) then
                    return nil, label .. " needs numeric x,y,z triples separated by semicolons"
                end
                row[#row+1] = number
            end
            if #row ~= 3 then
                return nil, label .. " needs exactly three numbers per entry"
            end
            result[#result+1] = row
            if checkpoint and #result%64==0 then checkpoint() end
        end
        if #result == 0 then return nil, label .. " cannot be empty" end
        return result
    end
    local vertices
    vertices, error_text = triples(vertex_text, "vertices", false)
    if not vertices then return nil, nil, error_text end
    local faces
    faces, error_text = triples(triangle_text, "triangles", true)
    if not faces then return nil, nil, error_text end
    local indices = {}
    for face_number, face in ipairs(faces) do
        local a, b, c = face[1], face[2], face[3]
        if a < 1 or b < 1 or c < 1 or a > #vertices or b > #vertices or c > #vertices then
            return nil, nil, "triangle " .. face_number .. " uses a vertex outside 1.." .. #vertices
        end
        local va, vb, vc = vertices[a], vertices[b], vertices[c]
        local ux, uy, uz = vb[1]-va[1], vb[2]-va[2], vb[3]-va[3]
        local vx, vy, vz = vc[1]-va[1], vc[2]-va[2], vc[3]-va[3]
        local nx, ny, nz = uy*vz-uz*vy, uz*vx-ux*vz, ux*vy-uy*vx
        if nx*nx + ny*ny + nz*nz < 1e-12 then
            return nil, nil, "triangle " .. face_number .. " has zero area"
        end
        indices[#indices+1], indices[#indices+2], indices[#indices+3] = a, b, c
        if checkpoint and face_number%64==0 then checkpoint() end
    end
    return vertices, indices
end
local function world3d_name(ctx, raw)
    if raw == nil or raw == "" then return nil, "Missing object name" end
    local value = raw
    if raw:match('^".*"$') or raw:match("^'.*'$") then
        value=raw:sub(2,-2)
    elseif raw:match("^%b()$") then
        value = resolve_path(ctx, raw)
        if is_fatal(value) then return nil, tostring(value.msg) end
    end
    if type(value) ~= "string" and type(value) ~= "number" then
        return nil, "Object name must resolve to text or a number"
    end
    value = tostring(value)
    if value == "" or #value > 256 then return nil, "Object name must have 1 to 256 bytes" end
    return value
end
local function world3d_copy(value)
    if type(value) ~= "table" then return value end
    local copy = {}
    for key, item in pairs(value) do
        -- A suspended pose owns references to its original world and buffers.
        -- Restored snapshots rebuild pending poses instead of sharing a coroutine.
        if key~="animation_job" and tostring(key):sub(1,6)~="_mesh_" and key~="mesh_jobs" then
            copy[key] = world3d_copy(item)
        end
    end
    return copy
end
local function world3d_triangle_has_area(va,vb,vc)
    local ux,uy,uz=vb[1]-va[1],vb[2]-va[2],vb[3]-va[3]
    local vx,vy,vz=vc[1]-va[1],vc[2]-va[2],vc[3]-va[3]
    local nx,ny,nz=uy*vz-uz*vy,uz*vx-ux*vz,ux*vy-uy*vx
    local wx,wy,wz=vc[1]-vb[1],vc[2]-vb[2],vc[3]-vb[3]
    local longest=math.max(ux*ux+uy*uy+uz*uz,
        vx*vx+vy*vy+vz*vz,wx*wx+wy*wy+wz*wz)
    return longest>0 and nx*nx+ny*ny+nz*nz>longest*longest*1e-18
end
local function world3d_mesh_valid(vertices, triangles)
    if #vertices < 3 then return false, "mesh needs at least 3 vertices" end
    if #triangles < 3 or #triangles % 3 ~= 0 then
        return false, "mesh needs one or more triangles"
    end
    for i=1,#triangles,3 do
        local a,b,c=triangles[i],triangles[i+1],triangles[i+2]
        if not a or not b or not c or a%1~=0 or b%1~=0 or c%1~=0 or
           a<1 or b<1 or c<1 or a>#vertices or b>#vertices or c>#vertices then
            return false, "triangle " .. math.floor((i+2)/3) .. " uses an invalid vertex"
        end
        -- Compare relative to edge length: small but valid model triangles
        -- must not fail merely because the model uses small coordinate units.
        if not world3d_triangle_has_area(vertices[a],vertices[b],vertices[c]) then
            return false,"triangle " .. math.floor((i+2)/3) .. " has zero area"
        end
    end
    return true
end
local function world3d_rotate_x(x,y,z,angle)
    local c,s=math.cos(angle),math.sin(angle)
    return x,y*c-z*s,y*s+z*c
end
local function world3d_rotate_y(x,y,z,angle)
    local c,s=math.cos(angle),math.sin(angle)
    return x*c+z*s,y,-x*s+z*c
end
local function world3d_rotate_z(x,y,z,angle)
    local c,s=math.cos(angle),math.sin(angle)
    return x*c-y*s,x*s+y*c,z
end
local function world3d_screen_bounds(world, object)
    if object.visible==0 then return {found=0} end
    local camera=world.camera
    local half_fov=math.tan(math.rad(camera.fov)*0.5)
    local aspect=world.width/world.height
    local pc,ps=math.cos(math.rad(object.pitch)),math.sin(math.rad(object.pitch))
    local yc,ys=math.cos(math.rad(object.yaw)),math.sin(math.rad(object.yaw))
    local rc,rs=math.cos(math.rad(object.roll)),math.sin(math.rad(object.roll))
    local cy,sy=math.cos(math.rad(camera.yaw)),math.sin(math.rad(camera.yaw))
    local cp,sp=math.cos(math.rad(camera.pitch)),math.sin(math.rad(camera.pitch))
    local left,top,right,bottom
    local function project(vx,vy,vz)
        local x,y,z=vx*object.width,vy*object.height,vz*object.depth
        x,y,z=x,y*pc-z*ps,y*ps+z*pc
        x,y,z=x*yc+z*ys,y,-x*ys+z*yc
        x,y,z=x*rc-y*rs,x*rs+y*rc,z
        x,y,z=x+object.x-camera.x,y+object.y-camera.y,z+object.z-camera.z
        x,y,z=x*cy-z*sy,y,x*sy+z*cy
        x,y,z=x,y*cp+z*sp,-y*sp+z*cp
        local roll=-math.rad(camera.roll or 0)
        x,y= x*math.cos(roll)-y*math.sin(roll),x*math.sin(roll)+y*math.cos(roll)
        local depth=-z
        if depth<=camera.near or depth>=camera.far then return end
        local sx=(1+x/(depth*aspect*half_fov))*world.width*0.5
        local sy=(1-y/(depth*half_fov))*world.height*0.5
        left=left and math.min(left,sx) or sx
        right=right and math.max(right,sx) or sx
        top=top and math.min(top,sy) or sy
        bottom=bottom and math.max(bottom,sy) or sy
    end
    if object.kind=="mesh" then
        for _,vertex in ipairs(object.vertices) do
            project(vertex[1],vertex[2],vertex[3])
        end
    else
        for _,vx in ipairs({-0.5,0.5}) do
            for _,vy in ipairs({-0.5,0.5}) do
                for _,vz in ipairs({-0.5,0.5}) do project(vx,vy,vz) end
            end
        end
    end
    if not left or right<0 or bottom<0 or left>=world.width or top>=world.height then
        return {found=0}
    end
    left=math.max(0,math.floor(left)-6)
    top=math.max(0,math.floor(top)-6)
    right=math.min(world.width-1,math.ceil(right)+6)
    bottom=math.min(world.height-1,math.ceil(bottom)+6)
    return {found=1,x=left,y=top,width=right-left+1,height=bottom-top+1}
end
local function world3d_mesh_pick_bounds(object)
    if object._pick_bounds and object._pick_bounds_version==object.geometry_version then
        return object._pick_bounds
    end
    local first=object.vertices[1]
    if not first then return nil end
    local xmin,xmax=first[1],first[1]
    local ymin,ymax=first[2],first[2]
    local zmin,zmax=first[3],first[3]
    for i=2,#object.vertices do
        local point=object.vertices[i]
        xmin,xmax=math.min(xmin,point[1]),math.max(xmax,point[1])
        ymin,ymax=math.min(ymin,point[2]),math.max(ymax,point[2])
        zmin,zmax=math.min(zmin,point[3]),math.max(zmax,point[3])
    end
    object._pick_bounds={xmin,xmax,ymin,ymax,zmin,zmax}
    object._pick_bounds_version=object.geometry_version
    return object._pick_bounds
end
local function world3d_ray_hits_bounds(ox,oy,oz,rx,ry,rz,bounds,near,best)
    local entry,exit=-math.huge,math.huge
    local starts={ox,oy,oz}
    local directions={rx,ry,rz}
    for axis=1,3 do
        local origin,direction=starts[axis],directions[axis]
        local low,high=bounds[axis*2-1],bounds[axis*2]
        if math.abs(direction)<1e-12 then
            if origin<low or origin>high then return false end
        else
            local a,b=(low-origin)/direction,(high-origin)/direction
            if a>b then a,b=b,a end
            entry,exit=math.max(entry,a),math.min(exit,b)
            if entry>exit then return false end
        end
    end
    return exit>=near and entry<best
end
local function world3d_pick(world, px, py)
    local camera=world.camera
    local aspect=world.width/world.height
    local scale=math.tan(math.rad(camera.fov)*0.5)
    local dx=(2*(px+0.5)/world.width-1)*aspect*scale
    local dy=(1-2*(py+0.5)/world.height)*scale
    local dz=-1
    dx,dy,dz=world3d_rotate_z(dx,dy,dz,math.rad(camera.roll or 0))
    dx,dy,dz=world3d_rotate_x(dx,dy,dz,math.rad(camera.pitch))
    dx,dy,dz=world3d_rotate_y(dx,dy,dz,math.rad(camera.yaw))
    local norm=math.sqrt(dx*dx+dy*dy+dz*dz)
    dx,dy,dz=dx/norm,dy/norm,dz/norm
    local nearest={found=0}
    local best=camera.far
    -- Imported pieces normally follow the board in draw order. Test them first
    -- so a near piece can reject the much larger board using its bounding box.
    for order_index=#world.order,1,-1 do
        local name=world.order[order_index]
        local object=world.objects[name]
        if object and object.visible~=0 then
            local ox,oy,oz=camera.x-object.x,camera.y-object.y,camera.z-object.z
            local rx,ry,rz=dx,dy,dz
            ox,oy,oz=world3d_rotate_z(ox,oy,oz,-math.rad(object.roll))
            rx,ry,rz=world3d_rotate_z(rx,ry,rz,-math.rad(object.roll))
            ox,oy,oz=world3d_rotate_y(ox,oy,oz,-math.rad(object.yaw))
            rx,ry,rz=world3d_rotate_y(rx,ry,rz,-math.rad(object.yaw))
            ox,oy,oz=world3d_rotate_x(ox,oy,oz,-math.rad(object.pitch))
            rx,ry,rz=world3d_rotate_x(rx,ry,rz,-math.rad(object.pitch))
            ox,oy,oz=ox/object.width,oy/object.height,oz/object.depth
            rx,ry,rz=rx/object.width,ry/object.height,rz/object.depth
            local hit_t,hit_triangle,hit_vertex
            if object.kind=="mesh" then
                local bounds=world3d_mesh_pick_bounds(object)
                if bounds and world3d_ray_hits_bounds(ox,oy,oz,rx,ry,rz,
                                                      bounds,camera.near,best) then
                for i=1,#object.triangles,3 do
                    local ia,ib,ic=object.triangles[i],object.triangles[i+1],object.triangles[i+2]
                    local a,b,c=object.vertices[ia],object.vertices[ib],object.vertices[ic]
                    local e1x,e1y,e1z=b[1]-a[1],b[2]-a[2],b[3]-a[3]
                    local e2x,e2y,e2z=c[1]-a[1],c[2]-a[2],c[3]-a[3]
                    local px1,py1,pz1=ry*e2z-rz*e2y,rz*e2x-rx*e2z,rx*e2y-ry*e2x
                    local det=e1x*px1+e1y*py1+e1z*pz1
                    if math.abs(det)>1e-10 then
                        local inv=1/det
                        local tx,ty,tz=ox-a[1],oy-a[2],oz-a[3]
                        local u=(tx*px1+ty*py1+tz*pz1)*inv
                        if u>=-1e-8 and u<=1+1e-8 then
                            local qx,qy,qz=ty*e1z-tz*e1y,tz*e1x-tx*e1z,tx*e1y-ty*e1x
                            local v=(rx*qx+ry*qy+rz*qz)*inv
                            if v>=-1e-8 and u+v<=1+1e-8 then
                                local t=(e2x*qx+e2y*qy+e2z*qz)*inv
                                if t>=camera.near and t<best and (not hit_t or t<hit_t) then
                                    hit_t,hit_triangle=t,math.floor((i+2)/3)
                                    local hx,hy,hz=ox+rx*t,oy+ry*t,oz+rz*t
                                    local indices={ia,ib,ic}
                                    local closest=math.huge
                                    for _, vertex_index in ipairs(indices) do
                                        local point=object.vertices[vertex_index]
                                        local vx=(hx-point[1])*object.width
                                        local vy=(hy-point[2])*object.height
                                        local vz=(hz-point[3])*object.depth
                                        local distance=vx*vx+vy*vy+vz*vz
                                        if distance<closest then
                                            closest,hit_vertex=distance,vertex_index
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                end
            else
                local entry,exit=-math.huge,math.huge
                for _, axis in ipairs({{ox,rx},{oy,ry},{oz,rz}}) do
                    local origin,direction=axis[1],axis[2]
                    if math.abs(direction)<1e-12 then
                        if origin<-.5 or origin>.5 then entry=math.huge; break end
                    else
                        local t1,t2=(-.5-origin)/direction,(.5-origin)/direction
                        if t1>t2 then t1,t2=t2,t1 end
                        entry,exit=math.max(entry,t1),math.min(exit,t2)
                    end
                end
                if entry<=exit then
                    local t=entry>=camera.near and entry or exit
                    if t>=camera.near and t<best then hit_t=t end
                end
            end
            if hit_t and hit_t<best then
                best=hit_t
                nearest={found=1,name=name,kind=object.kind or "box",
                         distance=hit_t,x=camera.x+dx*hit_t,
                         y=camera.y+dy*hit_t,z=camera.z+dz*hit_t,
                         triangle=hit_triangle or 0,vertex=hit_vertex or 0}
            end
        end
    end
    return nearest
end
local world3d_properties={"x","y","z","width","height","depth",
                          "yaw","pitch","roll","red","green","blue"}
local function world3d_text_number(value)
    return string.format("%.17g", value)
end
local function world3d_geometry_text(object)
    local vertices,faces={},{}
    for _, point in ipairs(object.vertices) do
        vertices[#vertices+1]=world3d_text_number(point[1]) .. "," ..
            world3d_text_number(point[2]) .. "," .. world3d_text_number(point[3])
    end
    for i=1,#object.triangles,3 do
        faces[#faces+1]=object.triangles[i] .. "," .. object.triangles[i+1] ..
            "," .. object.triangles[i+2]
    end
    return table.concat(vertices,";"),table.concat(faces,";")
end
local world3d_base64
local function world3d_encode64(raw)
    if not raw then return "" end
    local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local result={}
    for i=1,#raw,3 do
        local a,b,c=raw:byte(i,i+2)
        local number=a*65536+(b or 0)*256+(c or 0)
        result[#result+1]=alphabet:sub(math.floor(number/262144)%64+1,
                                     math.floor(number/262144)%64+1)
        result[#result+1]=alphabet:sub(math.floor(number/4096)%64+1,
                                     math.floor(number/4096)%64+1)
        result[#result+1]=b and alphabet:sub(math.floor(number/64)%64+1,
                                            math.floor(number/64)%64+1) or "="
        result[#result+1]=c and alphabet:sub(number%64+1,number%64+1) or "="
    end
    return table.concat(result)
end
local function world3d_uv_text(object)
    if not object.uvs then return "" end
    local rows={}
    for _,uv in ipairs(object.uvs) do
        rows[#rows+1]=world3d_text_number(uv[1]) .. "," .. world3d_text_number(uv[2])
    end
    return table.concat(rows,";")
end
local function world3d_parse_uvs(text, vertex_count,checkpoint)
    if type(text)=="table" then
        local rows,why=world3d_numeric_rows(text,2,"uvs",false,checkpoint)
        if not rows then return nil,why end
        if #rows~=vertex_count then return nil,"UV count must match vertex count" end
        return rows
    end
    if text=="" then return nil end
    local result={}
    for row in (text .. ";"):gmatch("(.-);") do
        local u,v=row:match("^([%d%.eE+-]+),([%d%.eE+-]+)$")
        u,v=tonumber(u),tonumber(v)
        if not u or not v or u~=u or v~=v or math.abs(u)==math.huge or math.abs(v)==math.huge then
            return nil,"invalid UV pair"
        end
        result[#result+1]={u,v}
        if checkpoint and #result%64==0 then checkpoint() end
    end
    if #result~=vertex_count then return nil,"UV count must match vertex count" end
    return result
end
local function world3d_escape(value)
    return (tostring(value):gsub("[^%w_.%-]",function(char)
        return string.format("%%%02X",char:byte())
    end))
end
local function world3d_unescape(value)
    if value:gsub("%%(%x%x)",""):find("%",1,true) then return nil end
    return (value:gsub("%%(%x%x)",function(hex)
        return string.char(tonumber(hex,16))
    end))
end
local function world3d_model_text(world)
    local extended=false
    for _,name in ipairs(world.order) do
        local object=world.objects[name]
        if object and object.kind=="mesh" and (object.uvs or object.texture_path or
                                                  object.texture_bytes) then
            extended=true
            break
        end
    end
    local lines={extended and "4IM3-WORLD3D-2" or "4IM3-WORLD3D-1"}
    local camera={"CAMERA"}
    for _, field in ipairs({"x","y","z","yaw","pitch","fov","near","far"}) do
        camera[#camera+1]=world3d_text_number(world.camera[field])
    end
    lines[#lines+1]=table.concat(camera,"\t")
    lines[#lines+1]="CAMERA_ROLL\t"..world3d_text_number(world.camera.roll or 0)
    local background={"BACKGROUND"}
    for _, field in ipairs({"red","green","blue"}) do
        background[#background+1]=world3d_text_number(world.background[field])
    end
    lines[#lines+1]=table.concat(background,"\t")
    local spotlight={"SPOTLIGHT"}
    for _, field in ipairs({"enabled","x","y","z","yaw","pitch",
                            "angle","range","intensity","ambient",
                            "red","green","blue"}) do
        spotlight[#spotlight+1]=world3d_text_number(world.spotlight[field])
    end
    lines[#lines+1]=table.concat(spotlight,"\t")
    for name,view in pairs(world.views or {}) do
        local row={"VIEW",world3d_escape(name)}
        for _,key in ipairs(WORLD3D_VIEW_FIELDS) do row[#row+1]=world3d_text_number(view[key]) end
        lines[#lines+1]=table.concat(row,"\t")
    end
    for _, name in ipairs(world.order) do
        local object=world.objects[name]
        if object then
            local row={object.kind=="mesh" and "MESH" or "BOX",world3d_escape(name)}
            for _, field in ipairs(world3d_properties) do
                row[#row+1]=world3d_text_number(object[field])
            end
            if object.kind=="mesh" then
                local vertices,faces=world3d_geometry_text(object)
                row[#row+1],row[#row+2]=vertices,faces
                if extended then
                    row[#row+1]=world3d_uv_text(object)
                    row[#row+1]=world3d_escape(object.texture_path or "")
                    row[#row+1]=world3d_escape(object.texture_mime or "")
                    row[#row+1]=world3d_encode64(object.texture_bytes)
                end
            end
            if object.visible==0 then row[#row+1]="0" end
            lines[#lines+1]=table.concat(row,"\t")
        end
    end
    for _,name in ipairs(world.order) do
        local object=world.objects[name]
        if object and object.view then
            lines[#lines+1]=table.concat({"SURFACE",world3d_escape(name),world3d_escape(object.view),object.unlit==0 and "0" or "1"},"\t")
        end
    end
    return table.concat(lines,"\n") .. "\n"
end
local function world3d_split_tabs(line)
    local parts={}
    for part in (line .. "\t"):gmatch("(.-)\t") do parts[#parts+1]=part end
    return parts
end
local function world3d_parse_model(ctx, text, width, height)
    local rows={}
    for line in (text .. "\n"):gmatch("(.-)\n") do
        rows[#rows+1]=world3d_split_tabs(line:gsub("\r$",""))
    end
    while #rows>0 and rows[#rows][1]=="" do table.remove(rows) end
    local version=rows[1] and rows[1][1]
    if not rows[1] or (version~="4IM3-WORLD3D-1" and
                       version~="4IM3-WORLD3D-2") or #rows[1]~=1 then
        return nil,"unsupported model file header"
    end
    local world=world3d_new_world()
    world.width,world.height=width,height
    local camera_seen,background_seen,spotlight_seen,roll_seen=false,false,false,false
    for row_index=2,#rows do
        local row=rows[row_index]
        local kind=row[1]
        local target, fields, offset
        if kind=="CAMERA" then
            if camera_seen or #row~=9 then return nil,"invalid CAMERA row " .. row_index end
            camera_seen=true
            target=world.camera
            fields={"x","y","z","yaw","pitch","fov","near","far"}
            offset=1
        elseif kind=="CAMERA_ROLL" then
            if roll_seen or #row~=2 then return nil,"invalid CAMERA_ROLL row "..row_index end
            roll_seen=true
            local value,why=world3d_number(ctx,row[2],"roll")
            if not value then return nil,why end
            world.camera.roll=value
            fields={}
            offset=1
        elseif kind=="BACKGROUND" then
            if background_seen or #row~=4 then return nil,"invalid BACKGROUND row " .. row_index end
            background_seen=true
            target=world.background
            fields={"red","green","blue"}
            offset=1
        elseif kind=="SPOTLIGHT" then
            if spotlight_seen or #row~=14 then
                return nil,"invalid SPOTLIGHT row " .. row_index
            end
            spotlight_seen=true
            target=world.spotlight
            fields={"enabled","x","y","z","yaw","pitch",
                    "angle","range","intensity","ambient",
                    "red","green","blue"}
            offset=1
        elseif kind=="VIEW" then
            local name=world3d_unescape(row[2] or "")
            world.views=world.views or {}
            if #row~=#WORLD3D_VIEW_FIELDS+2 or not name or name=="" or #name>256 or world.views[name] then return nil,"invalid VIEW row "..row_index end
            local raw={}
            for i,key in ipairs(WORLD3D_VIEW_FIELDS) do raw[key]=row[i+2] end
            local view,why=world3d_view_record(ctx,nil,raw)
            if not view then return nil,"invalid VIEW row "..row_index..": "..why end
            world.views[name]=view;fields={};offset=1
        elseif kind=="SURFACE" then
            local name=world3d_unescape(row[2] or "")
            local view=world3d_unescape(row[3] or "")
            local object=name and world.objects[name]
            if #row~=4 or not object or object.kind~="mesh" or not object.uvs or
               not (world.views and world.views[view]) or (row[4]~="0" and row[4]~="1") then return nil,"invalid SURFACE row "..row_index end
            object.view,object.unlit=view,tonumber(row[4]);fields={};offset=1
        elseif kind=="BOX" or kind=="MESH" then
            local expected=kind=="MESH" and (version=="4IM3-WORLD3D-2" and 20 or 16) or 14
            if #row~=expected and #row~=expected+1 then
                return nil,"invalid " .. kind .. " row " .. row_index
            end
            local name=world3d_unescape(row[2])
            if not name or name=="" or #name>256 or world.objects[name] then
                return nil,"invalid or duplicate object name on row " .. row_index
            end
            target={kind=kind:lower(),visible=1}
            if #row==expected+1 then
                if row[expected+1]~="0" and row[expected+1]~="1" then
                    return nil,"invalid visibility on row " .. row_index
                end
                target.visible=tonumber(row[expected+1])
            end
            fields=world3d_properties
            offset=2
            world.objects[name]=target
            world.order[#world.order+1]=name
        else
            return nil,"unknown row type on row " .. row_index
        end
        for i, field in ipairs(fields) do
            local value, why=world3d_number(ctx,row[offset+i],field)
            if not value then return nil,"row " .. row_index .. ": " .. why end
            target[field]=value
        end
        if kind=="MESH" then
            local vertices,triangles,why=world3d_mesh_geometry(ctx,
                '"' .. row[15] .. '"','"' .. row[16] .. '"')
            if not vertices then return nil,"row " .. row_index .. ": " .. why end
            target.vertices,target.triangles=vertices,triangles
            target.geometry_version=1
            if version=="4IM3-WORLD3D-2" then
                local uv,uv_error=world3d_parse_uvs(row[17],#vertices)
                if uv_error then return nil,"row " .. row_index .. ": " .. uv_error end
                target.uvs=uv
                target.texture_path=world3d_unescape(row[18])
                target.texture_mime=world3d_unescape(row[19])
                if not target.texture_path or not target.texture_mime then
                    return nil,"row " .. row_index .. ": invalid texture metadata"
                end
                if target.texture_path=="" then target.texture_path=nil end
                if target.texture_mime=="" then target.texture_mime=nil end
                if row[20]~="" then
                    target.texture_bytes,why=world3d_base64(row[20])
                    if not target.texture_bytes then
                        return nil,"row " .. row_index .. ": " .. tostring(why)
                    end
                end
                if (target.texture_path or target.texture_bytes) and not target.uvs then
                    return nil,"row " .. row_index .. ": texture needs UV coordinates"
                end
            end
        end
    end
    if not camera_seen or not background_seen or
       world.camera.near>=world.camera.far then
        return nil,"model needs a valid camera and background"
    end
    return world
end
local function world3d_export_text(world)
    local lines={
        "-- Exported 3D model. The engine creates its renderer source automatically.",
        "!renderer | create | name:ModelView | kind:3d | width:" .. world.width ..
            " | height:" .. world.height .. " |+|",
    }
    local function fields(object, names)
        local values={}
        for _, name in ipairs(names) do
            values[#values+1]=name .. ":" .. world3d_text_number(object[name])
        end
        return table.concat(values,",")
    end
    lines[#lines+1]="!world3d | camera | " .. fields(world.camera,
        {"x","y","z","yaw","pitch","roll","fov","near","far"}) .. " |+|"
    lines[#lines+1]="!world3d | background | " .. fields(world.background,
        {"red","green","blue"}) .. " |+|"
    lines[#lines+1]="!world3d | spotlight | " .. fields(world.spotlight,
        {"enabled","x","y","z","yaw","pitch","angle","range",
         "intensity","ambient","red","green","blue"}) .. " |+|"
    local view_alias={}
    local view_index=0
    for name,view in pairs(world.views or {}) do
        view_index=view_index+1
        local alias="SavedCameraView"..view_index
        view_alias[name]=alias
        lines[#lines+1]="!world3d | view | name:"..alias.." | "..fields(view,WORLD3D_VIEW_FIELDS).." |+|"
    end
    local used={}
    for _, name in ipairs(world.order) do
        if name:match("^[A-Za-z_][%w_]*$") then used[name]=true end
    end
    local next_alias=1
    for _, name in ipairs(world.order) do
        local object=world.objects[name]
        if object then
            local export_name=name
            if not name:match("^[A-Za-z_][%w_]*$") then
                repeat
                    export_name="ExportPart" .. next_alias
                    next_alias=next_alias+1
                until not used[export_name]
                used[export_name]=true
            end
            local command="!world3d | " .. (object.kind=="mesh" and "mesh" or "box") ..
                " | name:" .. export_name .. " | " ..
                fields(object,world3d_properties)
            if object.kind=="mesh" then
                local vertices,faces=world3d_geometry_text(object)
                command=command .. ' | vertices:"' .. vertices ..
                    '" | triangles:"' .. faces .. '"'
                if object.uvs then
                    command=command .. ' | uvs:"' .. world3d_uv_text(object) .. '"'
                end
                if object.texture_path then
                    command=command .. ' | texture:"' .. object.texture_path .. '"'
                end
                if object.view then
                    command=command.." | view:"..view_alias[object.view].." | unlit:"..(object.unlit==0 and "0" or "1")
                end
                if object.texture_bytes then
                    command=command .. ' | image:"' .. world3d_encode64(object.texture_bytes) .. '"' ..
                        ' | mime:"' .. (object.texture_mime or "image/png") .. '"'
                end
            end
            if object.visible==0 then command=command .. " | visible:0" end
            lines[#lines+1]=command .. " |+|"
        end
    end
    return table.concat(lines,"\n") .. "\n"
end
local function world3d_file_path(ctx, raw)
    if not raw then return nil,"path is required" end
    local path
    if raw:match('^".*"$') or raw:match("^'.*'$") then
        path=raw:sub(2,-2)
    else
        path=resolve_path(ctx,raw)
    end
    if is_fatal(path) then return nil,tostring(path.msg) end
    if type(path)~="string" or path=="" or path:find("%z") then
        return nil,"path must be a quoted string or string variable"
    end
    if not path:match("^%a:[/\\]") and not path:match("^[/\\]") then
        path=(ctx.program_directory or script_path()) .. path
    end
    return path
end
local function world3d_write_file(path, content)
    local file,why=io.open(path,"wb")
    if not file then return false,why end
    local ok,write_error=file:write(content)
    local close_ok,close_error=file:close()
    if not ok or not close_ok then return false,write_error or close_error end
    return true
end
-- Read model assets on request, outside the render callback.
local function world3d_read_asset(path)
    local file, why = io.open(path, "rb")
    if not file then return nil, tostring(why) end
    local ok,content=pcall(file.read,file,"*a")
    file:close()
    if not ok or not content then return nil,tostring(content or "could not read asset") end
    return content
end
local function world3d_asset_sibling(path, name)
    if type(name) ~= "string" or name == "" or name:find("%z") or
       name:match("^%a:[/\\]") or name:match("^[/\\]") or
       name:find("..", 1, true) or name:find("\\", 1, true) then
        return nil, "referenced asset must be a file beside the model"
    end
    return (path:match("^(.*[/\\])") or "") .. name
end
local function world3d_json(text)
    local at, depth = 1, 0
    local function space() at = (text:find("%S", at) or (#text + 1)) end
    local function string_value()
        if text:sub(at, at) ~= '"' then error("expected JSON string at byte " .. at) end
        at = at + 1
        local pieces, begin = {}, at
        while at <= #text do
            local ch = text:sub(at, at)
            if ch == '"' then
                pieces[#pieces + 1] = text:sub(begin, at - 1)
                at = at + 1
                return table.concat(pieces)
            elseif ch == "\\" then
                pieces[#pieces + 1] = text:sub(begin, at - 1)
                local escaped = text:sub(at + 1, at + 1)
                local simple = {['"']='"', ['\\']='\\', ['/']='/', b='\b', f='\f',
                                n='\n', r='\r', t='\t'}
                if simple[escaped] then
                    pieces[#pieces + 1] = simple[escaped]
                    at = at + 2
                elseif escaped == "u" then
                    local hex = text:sub(at + 2, at + 5)
                    local code = #hex == 4 and tonumber(hex, 16)
                    if not code then error("invalid JSON escape at byte " .. at) end
                    if code < 128 then pieces[#pieces + 1] = string.char(code)
                    elseif code < 2048 then pieces[#pieces + 1] =
                        string.char(192 + math.floor(code / 64), 128 + code % 64)
                    else pieces[#pieces + 1] = string.char(224 + math.floor(code / 4096),
                        128 + math.floor(code / 64) % 64, 128 + code % 64) end
                    at = at + 6
                else error("invalid JSON escape at byte " .. at) end
                begin = at
            elseif ch:byte() < 32 then error("control character in JSON string")
            else at = at + 1 end
        end
        error("unterminated JSON string")
    end
    local value
    value = function()
        space()
        depth = depth + 1
        if depth > 64 then error("JSON nesting exceeds 64 levels") end
        local ch = text:sub(at, at)
        local result
        if ch == '"' then result = string_value()
        elseif ch == "{" or ch == "[" then
            local object = ch == "{"
            local closing = object and "}" or "]"
            result = {}
            at = at + 1
            space()
            if text:sub(at, at) == closing then at = at + 1
            else
                while true do
                    local key
                    if object then
                        key = string_value()
                        space()
                        if text:sub(at, at) ~= ":" then error("expected JSON colon at byte " .. at) end
                        at = at + 1
                    else key = #result + 1 end
                    result[key] = value()
                    space()
                    local separator = text:sub(at, at)
                    at = at + 1
                    if separator == closing then break end
                    if separator ~= "," then error("expected JSON comma at byte " .. (at - 1)) end
                    space()
                end
            end
        elseif text:sub(at, at + 3) == "true" then result, at = true, at + 4
        elseif text:sub(at, at + 4) == "false" then result, at = false, at + 5
        elseif text:sub(at, at + 3) == "null" then result, at = false, at + 4
        else
            local number = text:match("^-?%d+%.?%d*[eE]?[+-]?%d*", at)
            if not number or number == "" then error("invalid JSON value at byte " .. at) end
            result = tonumber(number)
            if not result or result ~= result or math.abs(result) == math.huge then
                error("invalid JSON number at byte " .. at)
            end
            at = at + #number
        end
        depth = depth - 1
        return result
    end
    local ok, result = pcall(value)
    if not ok then return nil, tostring(result) end
    space()
    if at <= #text or type(result) ~= "table" then return nil, "invalid JSON document" end
    return result
end
world3d_base64 = function(raw)
    local values = {}
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for i = 1, #alphabet do values[alphabet:byte(i)] = i - 1 end
    if #raw % 4 ~= 0 then
        return nil, "invalid base64 buffer"
    end
    local out = {}
    for i = 1, #raw, 4 do
        local a,b,c,d = raw:byte(i, i + 3)
        local x,y,z,w = values[a],values[b],values[c],values[d]
        if not x or not y or (c ~= 61 and not z) or (d ~= 61 and not w) or
           (c == 61 and d ~= 61) or ((c == 61 or d == 61) and i + 3 ~= #raw) then
            return nil, "invalid base64 buffer"
        end
        local packed = x * 262144 + y * 4096 + (z or 0) * 64 + (w or 0)
        out[#out + 1] = string.char(math.floor(packed / 65536) % 256)
        if c ~= 61 then out[#out + 1] = string.char(math.floor(packed / 256) % 256) end
        if d ~= 61 then out[#out + 1] = string.char(packed % 256) end
    end
    local result = table.concat(out)
    return result
end
local function world3d_obj(path, content)
    local positions, texcoords, groups, order, materials = {}, {}, {}, {}, {}
    local current = ""
    local function group()
        if not groups[current] then
            groups[current] = {vertices={},uvs={},triangles={},indices={},material=current}
            order[#order + 1] = groups[current]
        end
        return groups[current]
    end
    local function vertex_index(token, line_number, available, label)
        local raw = token:match("^([+-]?%d+)")
        local index = raw and tonumber(raw)
        if not index or index == 0 then error("OBJ line " .. line_number .. ": invalid " .. label .. " index") end
        if index < 0 then index = available + index + 1 end
        if index < 1 or index > available then
            error("OBJ line " .. line_number .. ": " .. label .. " index outside the list")
        end
        return index
    end
    local line_number = 0
    for line in (content .. "\n"):gmatch("(.-)\n") do
        line_number = line_number + 1
        line = line:gsub("#.*$", ""):gsub("\r$", "")
        local command, rest = line:match("^%s*(%S+)%s*(.-)%s*$")
        if command == "v" then
            local values = {}
            for word in rest:gmatch("%S+") do values[#values + 1] = tonumber(word) end
            if #values < 3 or not values[1] or not values[2] or not values[3] then
                error("OBJ line " .. line_number .. ": vertex needs x y z")
            end
            for i=1,3 do
                if values[i]~=values[i] or math.abs(values[i])==math.huge then
                    error("OBJ line " .. line_number .. ": vertex must be finite")
                end
            end
            positions[#positions + 1] = {values[1],values[2],values[3]}
        elseif command == "vt" then
            local u,v=rest:match("^([%d%.eE+-]+)%s+([%d%.eE+-]+)")
            u,v=tonumber(u),tonumber(v)
            if not u or not v or u~=u or v~=v or math.abs(u)==math.huge or math.abs(v)==math.huge then
                error("OBJ line " .. line_number .. ": invalid texture coordinate")
            end
            texcoords[#texcoords+1]={u,1-v}
        elseif command == "usemtl" then current = rest
        elseif command == "mtllib" then
            local sibling, path_error = world3d_asset_sibling(path, rest)
            if not sibling then error("OBJ line " .. line_number .. ": " .. path_error) end
            local mtl,mtl_error = world3d_read_asset(sibling)
            if not mtl then error("OBJ material file: " .. mtl_error) end
            if mtl then
                local active
                for entry in (mtl .. "\n"):gmatch("(.-)\n") do
                    local key, value = entry:match("^%s*(%S+)%s*(.-)%s*$")
                    if key == "newmtl" then active = value
                    elseif key == "Kd" and active then
                        local r,g,b = value:match("^([%d%.eE+-]+)%s+([%d%.eE+-]+)%s+([%d%.eE+-]+)")
                        r,g,b = tonumber(r),tonumber(g),tonumber(b)
                        if r and g and b then
                            materials[active]=materials[active] or {}
                            materials[active].color = {math.floor(math.max(0,math.min(1,r))*255+0.5),
                                math.floor(math.max(0,math.min(1,g))*255+0.5),
                                math.floor(math.max(0,math.min(1,b))*255+0.5)}
                        end
                    elseif key == "map_Kd" and active then
                        local image_path,image_error=world3d_asset_sibling(sibling,value)
                        if not image_path then error("OBJ material texture: " .. image_error) end
                        local image,read_error=world3d_read_asset(image_path)
                        if not image then error("OBJ material texture: " .. read_error) end
                        materials[active]=materials[active] or {}
                        materials[active].texture_path=image_path
                    end
                end
            end
        elseif command == "f" then
            local face = {}
            for token in rest:gmatch("%S+") do
                local position,uv=token:match("^([^/]+)/?([^/]*)")
                local position_index=vertex_index(position,line_number,#positions,"vertex")
                local uv_index=uv~="" and vertex_index(uv,line_number,#texcoords,"texture") or nil
                face[#face + 1] = {position_index,uv_index}
            end
            if #face < 3 then error("OBJ line " .. line_number .. ": face needs 3 corners") end
            local part = group()
            for i = 2, #face - 1 do
                local corners={face[1],face[i],face[i+1]}
                for _, index in ipairs(corners) do
                    local key=index[1] .. "/" .. (index[2] or "")
                    local local_index = part.indices[key]
                    if not local_index then
                        local_index = #part.vertices + 1
                        part.indices[key] = local_index
                        part.vertices[local_index] = positions[index[1]]
                        part.uvs[local_index] = index[2] and texcoords[index[2]] or {0,0}
                    end
                    part.triangles[#part.triangles + 1] = local_index
                end
            end
        end
    end
    local result = {}
    for _,part in ipairs(order) do
        local name=part.material
        local material=materials[name] or {}
        local color = material.color or {200,200,200}
        local valid, why = world3d_mesh_valid(part.vertices,part.triangles)
        if not valid then error("OBJ material '" .. name .. "': " .. why) end
