end
local function world3d_track_value(track,time)
    local times,values=track.times,track.values
    local count=#times
    local left=1
    while left<count and time>=times[left+1] do left=left+1 end
    local right=math.min(left+1,count)
    local a,b=values[left],values[right]
    if right==left or track.interpolation=="STEP" then
        local value=a.value or a
        local copy={}
        for i=1,#value do copy[i]=value[i] end
        return copy
    end
    local dt=times[right]-times[left]
    local u=dt>0 and (time-times[left])/dt or 0
    u=math.max(0,math.min(1,u))
    local av,bv=a.value or a,b.value or b
    local out={}
    if track.interpolation=="CUBICSPLINE" then
        local u2,u3=u*u,u*u*u
        for i=1,#av do
            out[i]=(2*u3-3*u2+1)*av[i]+(u3-2*u2+u)*dt*a.out_tangent[i]+ 
                   (-2*u3+3*u2)*bv[i]+(u3-u2)*dt*b.in_tangent[i]
        end
    elseif track.path=="rotation" then
        local dot=av[1]*bv[1]+av[2]*bv[2]+av[3]*bv[3]+av[4]*bv[4]
        local sign=dot<0 and -1 or 1
        dot=math.min(1,math.abs(dot))
        local wa,wb=1-u,u
        if dot<0.9995 then
            local theta=math.acos(dot)
            local denominator=math.sin(theta)
            wa=math.sin((1-u)*theta)/denominator
            wb=math.sin(u*theta)/denominator
        end
        for i=1,4 do out[i]=wa*av[i]+wb*sign*bv[i] end
    else
        for i=1,#av do out[i]=av[i]+(bv[i]-av[i])*u end
    end
    if track.path=="rotation" then return world3d_quat_normalize(out) end
    return out
end
local function world3d_animation_apply(world,model,clip,time,yield_check)
    local pose,matrices,skin_matrices={},{},{}
    for i,node in ipairs(model.nodes) do
        pose[i]={translation=node.translation,rotation=node.rotation,
                 scale=node.scale,weights=node.weights}
    end
    if clip then
        for _,track in ipairs(clip.tracks) do
            pose[track.node][track.path]=world3d_track_value(track,time)
        end
    end
    local visiting={}
    local function matrix(index)
        if matrices[index] then return matrices[index] end
        if visiting[index] then error("glTF node hierarchy is cyclic") end
        visiting[index]=true
        local node,p=model.nodes[index],pose[index]
        local local_matrix=node.matrix or world3d_mat_node(p.translation,p.rotation,p.scale)
        local result=node.parent and world3d_mat_mul(matrix(node.parent),local_matrix) or local_matrix
        matrices[index]=result
        visiting[index]=nil
        return result
    end
    for i=1,#model.nodes do
        matrix(i)
        if yield_check and i%32==0 then yield_check() end
    end
    local prepared={}
    for _,binding in ipairs(model.bindings) do
        local object=world.objects[binding.name]
        if object then
            local weights=pose[binding.node].weights or {}
            local skin=binding.skin and model.skins[binding.skin]
            local joints
            if skin then
                -- All primitives using one skin share its palette for this pose.
                -- Characters commonly split their limbs into many primitives.
                joints=skin_matrices[binding.skin]
                if not joints then
                    joints={}
                    for j,node_index in ipairs(skin.joints) do
                        joints[j]=world3d_mat_mul(matrices[node_index],skin.inverse[j])
                    end
                    skin_matrices[binding.skin]=joints
                end
            end
            local vertices={}
            for i=1,#binding.positions do
                local source_index=i
                local original=binding.positions[source_index]
                local x,y,z=original[1],original[2],original[3]
                for target_index,target in ipairs(binding.targets) do
                    local weight=weights[target_index] or 0
                    local delta=target[source_index]
                    if delta and weight~=0 then
                        x,y,z=x+weight*delta[1],y+weight*delta[2],z+weight*delta[3]
                    end
                end
                if skin then
                    local ox,oy,oz=0,0,0
                    local joint_ids=binding.joints[source_index]
                    local joint_weights=binding.joint_weights[source_index]
                    for j=1,4 do
                        local weight=joint_weights[j]
                        if weight~=0 then
                            local m=joints[joint_ids[j]+1]
                            ox=ox+weight*(m[1]*x+m[5]*y+m[9]*z+m[13])
                            oy=oy+weight*(m[2]*x+m[6]*y+m[10]*z+m[14])
                            oz=oz+weight*(m[3]*x+m[7]*y+m[11]*z+m[15])
                        end
                    end
                    x,y,z=ox,oy,oz
                else
                    local m=matrices[binding.node]
                    x,y,z=m[1]*x+m[5]*y+m[9]*z+m[13],
                          m[2]*x+m[6]*y+m[10]*z+m[14],
                          m[3]*x+m[7]*y+m[11]*z+m[15]
                end
