                target.geometry_version=(target.geometry_version or 0)+1
            end
        end
    end
    model.pose_time=time or 0
    world.version=world.version+1
end
local function world3d_animation_tick(dt,deadline,owner)
    local pending={}
    for world_name,world in pairs(world3d_worlds) do
        for model_name,model in pairs(world.animations or {}) do
            local playback=model.playback
            if playback and playback.playing then
                local clip=model.clips[playback.clip]
                local next_time=playback.time+math.max(0,math.min(0.5,dt or 0))*playback.speed
                if clip.duration>0 then
                    if playback.loop then next_time=next_time%clip.duration
                    elseif next_time>=clip.duration then
                        next_time=clip.duration
                        playback.playing=false
                        playback._ending=true
                    end
                else playback.playing=false;playback._ending=not playback.loop end
                playback.time=next_time
                model.animation_dirty=true
            end
            if playback and (model.animation_dirty or model.animation_job) then
                pending[#pending+1]={world=world,model=model,key=world_name.."\0"..model_name}
            end
        end
    end
    table.sort(pending,function(a,b) return a.key<b.key end)
    if #pending==0 then return end
    owner=owner or {}
    local index=((owner.world3d_animation_cursor or 1)-1)%#pending+1
    for _=1,#pending do
        if deadline and engine_tick_now_ms()>=deadline then break end
        local entry=pending[index]
        local model,world=entry.model,entry.world
        local playback=model.playback
        local job=model.animation_job
        if not job then
            job={time=playback.time,clip=playback.clip}
            job.thread=coroutine.create(function()
                world3d_animation_apply(world,model,model.clips[job.clip],job.time,
                    deadline and function()
                        if job.deadline and engine_tick_now_ms()>=job.deadline then coroutine.yield() end
                    end or nil)
            end)
            model.animation_job=job
        end
        job.deadline=deadline
        local ok,why=coroutine.resume(job.thread)
        if not ok then
            model.animation_job=nil
            model.animation_dirty=false
            playback.playing=false
            obslua.script_log(obslua.LOG_ERROR,
                "[4IM3-SCRIPT] 3D animation stopped: "..tostring(why))
        elseif coroutine.status(job.thread)=="dead" then
            model.animation_job=nil
            model.animation_dirty=playback.time~=job.time or playback.clip~=job.clip
            if not model.animation_dirty and playback._ending then
                playback._ending=nil
                model.completion_serial=(model.completion_serial or 0)+1
                model.completed_clip,model.completed_time=playback.clip,playback.time
            end
        end
        index=index%#pending+1
        owner.world3d_animation_cursor=index
    end
end
local function world3d_gltf(path, content)
    local function u32(data, offset)
