        elseif i == 1 then data = binary end
        if not data then error("glTF buffer " .. i .. ": " .. tostring(why or "missing data")) end
        if type(description.byteLength) ~= "number" or description.byteLength > #data then
            error("glTF buffer " .. i .. " is shorter than byteLength")
        end
