    end
    local component_size = {[5121]=1,[5123]=2,[5125]=4,[5126]=4}
    local component_count = {SCALAR=1,VEC2=2,VEC3=3,VEC4=4,MAT4=16}
    local byte_pointer_type=ffi.typeof("const uint8_t*")
    local float_pointer_type=ffi.typeof("const float*")
