        local view_size = view.byteLength
        if type(view_size) ~= "number" or stride < element_size or
           start < (view.byteOffset or 0) or
           start + math.max(0,meta.count-1)*stride + (meta.count>0 and element_size or 0) >
               (view.byteOffset or 0) + view_size or
           start + math.max(0,meta.count-1)*stride + (meta.count>0 and element_size or 0) > #data then
