            end
            part=world3d_prepare_import_part(part)
            result[#result+1]=part
            if node_index then
                model.bindings[#model.bindings+1]={part=#result,node=node_index,
                    skin=skin_index and skin_index+1 or nil,positions=positions,
                    targets=targets,joints=joints,joint_weights=weights}
            end
        end
    end
    local nodes=document.nodes or {}
    for i,node in ipairs(nodes) do
        local mesh=node.mesh and (document.meshes or {})[node.mesh+1]
        model.nodes[i]={translation=node.translation or {0,0,0},
            rotation=node.rotation or {0,0,0,1},scale=node.scale or {1,1,1},
            matrix=node.matrix,weights=node.weights or (mesh and mesh.weights) or {},
            parent=nil}
    end
    for i,node in ipairs(nodes) do
        for _,child in ipairs(node.children or {}) do
            if not model.nodes[child+1] or model.nodes[child+1].parent then
                error("glTF node has missing child or multiple parents")
            end
            model.nodes[child+1].parent=i
        end
    end
    for _,skin in ipairs(document.skins or {}) do
        local joints=skin.joints or {}
        if #joints==0 then error("glTF skin has no joints") end
        local inverse={}
        if skin.inverseBindMatrices~=nil then
            local count,_,read=accessor(skin.inverseBindMatrices,"MAT4",5126)
            if count~=#joints then error("glTF inverse bind matrix count differs from joints") end
            for i=0,count-1 do
                local m={}
                for j=0,15 do m[j+1]=read(i,j) end
                inverse[i+1]=m
            end
        else
            for i=1,#joints do inverse[i]=world3d_mat_identity() end
        end
        local resolved={}
        for i,index in ipairs(joints) do
            if not model.nodes[index+1] then error("glTF skin references missing joint") end
            resolved[i]=index+1
        end
        model.skins[#model.skins+1]={joints=resolved,inverse=inverse}
    end
    local scenes=document.scenes or {}
    local scene=scenes[(document.scene or 0)+1]
    if scene then
        local visiting={}
        local function visit(index,parent,depth)
            if depth>64 or visiting[index] then error("glTF node hierarchy is cyclic or too deep") end
            local node=nodes[index+1]
            if not node then error("glTF scene references missing node") end
            visiting[index]=true
            local transform=world3d_mat_mul(parent,node_matrix(node))
            if node.mesh~=nil then add_mesh(node.mesh,transform,index+1,node.skin) end
            for _,child in ipairs(node.children or {}) do visit(child,transform,depth+1) end
            visiting[index]=nil
        end
        for _,root in ipairs(scene.nodes or {}) do visit(root,world3d_mat_identity(),1) end
    else
        for index=1,#(document.meshes or {}) do
            add_mesh(index-1,world3d_mat_identity())
        end
    end
    local clip_names={}
    for clip_index,animation in ipairs(document.animations or {}) do
        local name=animation.name or ("Clip_" .. clip_index)
        if clip_names[name] then error("glTF has duplicate animation name '"..name.."'") end
        clip_names[name]=true
        local clip={name=name,tracks={},duration=0}
        for _,channel in ipairs(animation.channels or {}) do
            local target=channel.target or {}
            local path_name=target.path
            local node_index=target.node and target.node+1
            if not node_index or not model.nodes[node_index] or
               (path_name~="translation" and path_name~="rotation" and
                path_name~="scale" and path_name~="weights") then
                error("glTF animation channel has unsupported target")
            end
            if model.nodes[node_index].matrix and path_name~="weights" then
                error("glTF animated node cannot use a matrix transform")
            end
            local sampler=(animation.samplers or {})[(channel.sampler or -1)+1]
            if not sampler then error("glTF animation channel references missing sampler") end
            local mode=sampler.interpolation or "LINEAR"
            if mode~="LINEAR" and mode~="STEP" and mode~="CUBICSPLINE" then
                error("glTF animation uses unsupported interpolation")
            end
            local key_count,_,read_time=accessor(sampler.input,"SCALAR",5126)
            if key_count<1 then error("glTF animation channel has no keyframes") end
            local times={}
            for i=0,key_count-1 do
                times[i+1]=read_time(i,0)
                if times[i+1]<0 or (i>0 and times[i+1]<=times[i]) then
                    error("glTF animation key times must increase")
                end
            end
            local dimensions=path_name=="weights" and
                #(model.nodes[node_index].weights or {}) or
                (path_name=="rotation" and 4 or 3)
            if path_name=="weights" and dimensions==0 then
                local node=nodes[node_index]
                local mesh=(document.meshes or {})[(node.mesh or -1)+1]
                dimensions=mesh and mesh.primitives and
                    #(mesh.primitives[1].targets or {}) or 0
            end
            if dimensions<1 then error("glTF animation weights have no morph targets") end
            local expected_type=path_name=="weights" and "SCALAR" or
                (path_name=="rotation" and "VEC4" or "VEC3")
            local output_count,_,read_output=accessor(sampler.output,expected_type,5126)
            local spline_factor=mode=="CUBICSPLINE" and 3 or 1
            local expected=key_count*spline_factor*(path_name=="weights" and dimensions or 1)
            if output_count~=expected then
                error("glTF animation output count does not match keyframes")
            end
            local values={}
            local function value_at(key,section)
                local v={}
                for axis=0,dimensions-1 do
                    if path_name=="weights" then
                        v[axis+1]=read_output((key*spline_factor+section)*dimensions+axis,0)
                    else
                        v[axis+1]=read_output(key*spline_factor+section,axis)
                    end
                end
                return v
            end
            for key=0,key_count-1 do
                if spline_factor==3 then
                    values[key+1]={in_tangent=value_at(key,0),value=value_at(key,1),
                                   out_tangent=value_at(key,2)}
                else values[key+1]=value_at(key,0) end
            end
            clip.tracks[#clip.tracks+1]={node=node_index,path=path_name,
                interpolation=mode,times=times,values=values}
            clip.duration=math.max(clip.duration,times[#times])
        end
        model.clips[name]=clip
        model.clip_order=model.clip_order or {}
        model.clip_order[#model.clip_order+1]=name
    end
    if #result==0 then error("glTF scene has no triangle meshes") end
    return result,model
end
-- Validate the complete scene update first, then publish object and camera
-- transforms together. An animated import name addresses all of its parts.
function world3d_apply_updates(ctx,world,rows,camera)
    local prepared={}
    if type(rows)~="table" then return false,"World3D Error: objects must be a list" end
    local count=#rows
    for key in pairs(rows) do
        if type(key)~="number" or key%1~=0 or key<1 or key>count then
            return false,"World3D Error: objects must be a dense list"
        end
    end
    local function changes(record,allowed)
        local out={}
        for key,value in pairs(record) do
            if key~="name" then
                if not allowed[key] or key=="into" then
                    return nil,"Unknown update field '"..tostring(key).."'"
                end
                if type(value)~="number" then return nil,"Update field '"..key.."' must be numeric" end
                local number,why=world3d_number(ctx,value,key)
                if number==nil then return nil,why end
                out[key]=number
            end
        end
        return out
    end
    for i=1,count do
        local row=rows[i]
        if type(row)~="table" or type(row.name)~="string" or row.name=="" then
            return false,"World3D Error: each object update needs a name"
        end
        local values,why=changes(row,world3d_allowed.set)
        if not values then return false,"World3D Error: "..why end
        local targets={}
        if world.objects[row.name] then targets[1]=world.objects[row.name]
        elseif world.animations and world.animations[row.name] then
            for _,binding in ipairs(world.animations[row.name].bindings) do
                local object=world.objects[binding.name]
                if not object then return false,"World3D Error: missing imported part '"..binding.name.."'" end
                targets[#targets+1]=object
            end
        else return false,"World3D Error: No object or imported model named '"..row.name.."'" end
        for _,target in ipairs(targets) do prepared[#prepared+1]={target=target,values=values} end
    end
    if camera~=nil then
        if type(camera)~="table" or camera.name~=nil then
            return false,"World3D Error: camera must be a camera-field record"
        end
        local values,why=changes(camera,world3d_allowed.camera)
        if not values then return false,"World3D Error: "..why end
        if (values.near or world.camera.near)>=(values.far or world.camera.far) then
            return false,"World3D Error: near must be smaller than far"
        end
        prepared[#prepared+1]={target=world.camera,values=values}
    end
    local changed=false
    for _,change in ipairs(prepared) do
        for key,value in pairs(change.values) do
            if change.target[key]~=value then
                change.target[key]=value
                changed=true
            end
            if change.target._mesh_previous then
                change.target._mesh_previous[key]=value
            end
        end
    end
    if changed then world.version=world.version+1 end
    return true
end
-- Async geometry preparation owns its coroutine and temporary arrays. Input
-- tables are borrowed read-only until preparation completes; the live mesh is
-- never modified by a partially completed job.
function world3d_mesh_cancel(world,name)
    local job=world.mesh_jobs and world.mesh_jobs[name]
    if job then
        if job.status._started_ms then
            job.status.elapsed_ms=engine_tick_now_ms()-job.status._started_ms
            job.status._started_ms=nil
        end
        job.status.state,job.status.stage="cancelled","cancelled"
        job.co=nil
        world.mesh_jobs[name]=nil
    end
    local object=world.objects[name]
    if object and object._mesh_packets then
        if object._mesh_status then
            if object._mesh_status._started_ms then
                object._mesh_status.elapsed_ms=engine_tick_now_ms()-object._mesh_status._started_ms
                object._mesh_status._started_ms=nil
            end
            object._mesh_status.state,object._mesh_status.stage="cancelled","cancelled"
        end
        world.objects[name]=object._mesh_previous
        object._mesh_packets,object._mesh_previous=nil,nil
        if not world.objects[name] then
            for i=#world.order,1,-1 do
                if world.order[i]==name then table.remove(world.order,i);break end
            end
        end
        world.version=world.version+1
    end
end
function world3d_cancel_builds(world)
    if not world then return end
    local names={}
    for name in pairs(world.mesh_jobs or {}) do names[name]=true end
    for name,object in pairs(world.objects) do
        if object._mesh_packets then names[name]=true end
    end
    for name in pairs(names) do world3d_mesh_cancel(world,name) end
end
function world3d_prepare_packets(object,checkpoint)
    local packets={}
    local triangles,vertices=object.triangles,object.vertices
    -- A work packet, not a model capacity limit. Any number of packets is valid.
    for start=1,#triangles,12288 do
        local count=math.min(12288,#triangles-start+1)
        local packet={count=count,points=ffi.new("im3_vec4[?]",count),
            colors=ffi.new("uint32_t[?]",count),uvs=ffi.new("float[?]",count*2)}
        for i=start,start+count-1,3 do
            local a,b,c=vertices[triangles[i]],vertices[triangles[i+1]],vertices[triangles[i+2]]
            local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
            local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
            local nx,ny,nz=uy*vz-uz*vy,uz*vx-ux*vz,ux*vy-uy*vx
            local length=math.sqrt(nx*nx+ny*ny+nz*nz)
            local light=length>1e-10 and math.abs((nx*.35+ny*.8+nz*.48)/length) or 0
            local shade=math.floor(145+100*light)
            local color=0xFF000000+shade*0x010101
            for corner=0,2 do
                local index=i+corner-start
                local vertex=vertices[triangles[i+corner]]
                local uv=object.uvs and object.uvs[triangles[i+corner]]
                local point=packet.points[index]
                point.x,point.y,point.z=vertex[1],vertex[2],vertex[3]
                if math.abs(tonumber(point.x))==math.huge or math.abs(tonumber(point.y))==math.huge or
                   math.abs(tonumber(point.z))==math.huge then
                    error("Mesh coordinates cannot be represented by the GPU's 32-bit floats")
                end
                packet.colors[index]=color
                packet.uvs[index*2],packet.uvs[index*2+1]=uv and uv[1] or 0,uv and uv[2] or 0
            end
            if (i-start)%192==0 then checkpoint() end
        end
        packets[#packets+1]=packet
        checkpoint()
    end
    return packets
end
function world3d_queue_mesh(ctx,world,fields,action,asynchronous)
    local name,why=world3d_name(ctx,fields.name)
    if not name then return false,"World3D Error: "..why end
    if world.edits and world.edits[name] then return false,"World3D Error: commit or cancel the active mesh edit first" end
    local values={}
    -- Resolve the current invocation's expressions now. Only large geometry
    -- tables remain borrowed, so a returned function does not retain its scope.
    for key,raw in pairs(fields) do
        if key~="into" and key~="async" and key~="name" and key~="mesh" then
            if world3d_allowed.set[key] then
                local number,problem=world3d_number(ctx,raw,key)
                if number==nil then return false,"World3D Error: "..problem end
                values[key]=number
            elseif key=="view" then
                local name,problem=world3d_name(ctx,raw)
                if not name then return false,"World3D Error: "..problem end
                values[key]=name
            elseif key=="texture" then
                local path,problem=world3d_file_path(ctx,raw)
                if not path then return false,"World3D Error: "..problem end
                values[key]=path
            else
                local value=resolve_path(ctx,raw)
                if is_fatal(value) then return false,"World3D Error: "..tostring(value.msg) end
                values[key]=value
            end
        end
    end
    local base
    if action=="instances" then
        local source,problem=world3d_name(ctx,fields.mesh)
        base=source and world.objects[source]
        if not base or base.kind~="mesh" then return false,"World3D Error: instances needs mesh:ExistingMesh" end
        if source==name then return false,"World3D Error: instance batch needs a different name from its source mesh" end
        if type(values.transforms)~="table" then return false,"World3D Error: transforms needs a list of transform records" end
        base={vertices=base.vertices,triangles=base.triangles,uvs=base.uvs,
            texture_path=base.texture_path,texture_bytes=base.texture_bytes,
            texture_mime=base.texture_mime,red=base.red,green=base.green,blue=base.blue}
    elseif not fields.vertices or not fields.triangles then
        return false,"World3D Error: async mesh needs both vertices and triangles"
    end
    if world.objects[name] and world.objects[name].kind~="mesh" then
        return false,"World3D Error: remove the existing box before replacing it with a mesh"
    end
    world3d_mesh_cancel(world,name)
    local status={name=name,state="running",stage="preparing",uploaded=0,
        prepare_ms=0,prepare_peak_ms=0,upload_ms=0,upload_peak_ms=0,packets_uploaded=0,buffers_reused=0,
        elapsed_ms=0,_started_ms=engine_tick_now_ms()}
    local previous=world.objects[name]
    local selected,directory=ctx.world3d_selected,ctx.program_directory
    local checkpoint=coroutine.yield
    local job={status=status}
    job.co=coroutine.create(function()
        local shadow={objects={},order={},version=0,edits={}}
        if previous then
            local copy={}
            for key,value in pairs(previous) do if tostring(key):sub(1,6)~="_mesh_" then copy[key]=value end end
            shadow.objects[name]=copy;shadow.order[1]=name
        end
        local prepared={world3d_selected=selected,world3d_build_world=shadow,
            world3d_mesh_checkpoint=checkpoint,vars={_mesh_name=name},program_directory=directory}
        prepared.active_scope=prepared.vars
        local args={"mesh","name:(_mesh_name)"}
        if action=="instances" then
            local vertices,triangles,uvs={},{},base.uvs and {} or nil
            local total=#values.transforms
            if total==0 then error("transforms cannot be empty") end
            for key in pairs(values.transforms) do
                if type(key)~="number" or key%1~=0 or key<1 or key>total then error("transforms must be a dense list") end
                checkpoint()
            end
            for index,row in ipairs(values.transforms) do
                if type(row)~="table" then error("transform "..index.." must be a record") end
                local pose={x=0,y=0,z=0,yaw=0,pitch=0,roll=0,width=1,height=1,depth=1}
                for key,value in pairs(row) do
                    if pose[key]==nil and key~="scale" then error("unknown instance transform field '"..tostring(key).."'") end
                    if type(value)~="number" or value~=value or math.abs(value)==math.huge then error("instance transforms must be finite numbers") end
                    if key=="scale" then
                        if value<=0 then error("instance scale must be positive") end
                        pose.width,pose.height,pose.depth=value,value,value
                    else
                        if (key=="width" or key=="height" or key=="depth") and value<=0 then error("instance dimensions must be positive") end
                        pose[key]=value
                    end
                end
                -- Explicit axis sizes override the uniform scale deterministically.
                pose.width,pose.height,pose.depth=row.width or pose.width,row.height or pose.height,row.depth or pose.depth
                local offset=#vertices
                for i,point in ipairs(base.vertices) do
                    local x,y,z=point[1]*pose.width,point[2]*pose.height,point[3]*pose.depth
                    x,y,z=world3d_rotate_x(x,y,z,math.rad(pose.pitch))
                    x,y,z=world3d_rotate_y(x,y,z,math.rad(pose.yaw))
                    x,y,z=world3d_rotate_z(x,y,z,math.rad(pose.roll))
                    vertices[#vertices+1]={x+pose.x,y+pose.y,z+pose.z}
                    if uvs then uvs[#uvs+1]=base.uvs[i] end
                    if i%64==0 then checkpoint() end
                end
                for i,vertex in ipairs(base.triangles) do
                    triangles[#triangles+1]=vertex+offset
                    if i%192==0 then checkpoint() end
                end
                checkpoint()
            end
            local object={kind="mesh",x=0,y=0,z=0,width=1,height=1,depth=1,
                yaw=0,pitch=0,roll=0,visible=1,red=base.red,green=base.green,blue=base.blue,
                vertices=vertices,triangles=triangles,uvs=uvs,texture_path=base.texture_path,
                texture_bytes=base.texture_bytes,texture_mime=base.texture_mime,
                geometry_version=(previous and previous.geometry_version or 0)+1,texture_version=1}
            shadow.objects[name]=object
        else
            for key,value in pairs(values) do
                local variable="_mesh_"..key
                prepared.vars[variable]=value
                args[#args+1]=key..":"..(key=="view" and ("("..variable..")") or variable)
            end
            local ok,problem=engine.world3d(prepared,{},args)
            if not ok then error(problem) end
        end
        local object=shadow.objects[name]
        status.stage="packing"
        object._mesh_packets=world3d_prepare_packets(object,checkpoint)
        status.packets=#object._mesh_packets
        local current=world.objects[name]
        if current~=previous then error("mesh changed while preparation was running") end
        if previous then
            for key in pairs(world3d_allowed.set) do
                if key~="name" and not fields[key] then object[key]=previous[key] end
            end
        end
        object._mesh_previous,object._mesh_status=previous,status
        world.objects[name]=object
        if not previous then world.order[#world.order+1]=name end
        world.version=world.version+1
        status.state,status.stage="done","queued"
    end)
    world.mesh_jobs=world.mesh_jobs or {}
    world.mesh_jobs[name]=job
    if fields.into then
        local written=update_variable_state(ctx,fields.into,status)
        if is_fatal(written) then world3d_mesh_cancel(world,name);return false,written.msg end
    end
    if not asynchronous then
        repeat
            local start=engine_tick_now_ms()
            local ok,problem=coroutine.resume(job.co)
            local cost=engine_tick_now_ms()-start
            status.prepare_ms=status.prepare_ms+cost
            status.prepare_peak_ms=math.max(status.prepare_peak_ms,cost)
            status.elapsed_ms=engine_tick_now_ms()-status._started_ms
            if not ok then world.mesh_jobs[name]=nil;return false,"World3D Error: "..tostring(problem) end
        until coroutine.status(job.co)=="dead"
        world.mesh_jobs[name]=nil
    end
    return true
end
function world3d_mesh_tick(deadline)
    local now=function() return engine_tick_now_ms and engine_tick_now_ms() or os.clock()*1000 end
    local jobs={}
    for _,world in pairs(world3d_worlds) do
        for name,job in pairs(world.mesh_jobs or {}) do jobs[#jobs+1]={world=world,name=name,job=job} end
    end
    local first=(world3d_mesh_cursor or 0)%math.max(1,#jobs)+1
    world3d_mesh_cursor=first
    while #jobs>0 and now()<deadline do
        for offset=0,#jobs-1 do
            local entry=jobs[(first+offset-1)%#jobs+1]
            local job=entry.job
            if job.co then
                local start=now()
                local ok,problem=coroutine.resume(job.co)
                local cost=now()-start
                job.status.prepare_ms=job.status.prepare_ms+cost
                job.status.prepare_peak_ms=math.max(job.status.prepare_peak_ms,cost)
                job.status.elapsed_ms=now()-job.status._started_ms
                if not ok or coroutine.status(job.co)=="dead" then
                    if not ok then job.status.state,job.status.stage,job.status.error="error","error",tostring(problem) end
                    job.co=nil;entry.world.mesh_jobs[entry.name]=nil
                end
            end
            if now()>=deadline then return end
        end
        local running=false
        for _,entry in ipairs(jobs) do if entry.job.co then running=true;break end end
        if not running then break end
    end
end
engine["world3d"] = function(ctx, state, args)
    if args._input_handler or INPUT_EVENTS and INPUT_EVENTS.is_handler('world3d',args) then
        return INPUT_EVENTS.register(ctx,args,'world3d')
    end
    local action = tostring(args[1] or ""):lower()
    local allowed = world3d_allowed[action]
    if not allowed then
        return false, "World3D Error: Unknown action '" .. action .. "'"
    end
    local fields, parse_error
    if action == "use" and #args == 2 and not tostring(args[2]):find(":", 1, true) then
        fields = {name=tostring(args[2])}
    else
        fields, parse_error = world3d_parse_fields(args, allowed, action)
        if not fields then return false, "World3D Error: " .. parse_error end
    end
    local publish = fields.into and function(value)
        local written=update_variable_state(ctx,fields.into,value)
        if is_fatal(written) then return false,written.msg end
        return true
    end
    if action == "use" then
        local name, name_error = world3d_name(ctx, fields.name)
        if not name then return false, "World3D Error: " .. name_error end
        if not world3d_worlds[name] then
            return false, "World3D Error: No 3D renderer named '" .. name .. "'; create it first"
        end
        ctx.world3d_selected = name
        return true
    end
    local selected = ctx.world3d_selected
    local world = ctx.world3d_build_world or (selected and world3d_worlds[selected])
    if not world then
        return false, "World3D Error: Create a 3D renderer first with !renderer | create | kind:3d"
    end
    if action=="stats" then
        if not fields.into then return false,"World3D Error: stats needs into:variable or -> | variable" end
        return publish(world3d_copy(world._mesh_stats or {backend="pending",instance_draws=0,instanced_objects=0,native_available=0,view_count=0,view_ms=0}))
    end
    if action=="view" then
        local name,why=world3d_name(ctx,fields.name)
        if not name then return false,"World3D Error: "..why end
        world.views=world.views or {}
        if fields.delete then
            if resolve_path(ctx,fields.delete)~=true then return false,"World3D Error: delete must be true" end
            world.views[name]=nil;world.version=world.version+1
            for _,object in pairs(world.objects) do
                if object.view==name then object.view=nil end
            end
            return true
        end
        local view,problem=world3d_view_record(ctx,world.views[name],fields)
        if not view then return false,"World3D Error: "..problem end
