    for field, raw in pairs(fields) do
        if field ~= "name" and field ~= "vertices" and field ~= "triangles" and
           field ~= "uvs" and field ~= "texture" and field ~= "image" and field ~= "mime" and
           field ~= "into" and field~="view" then
            local value, number_error = world3d_number(ctx, raw, field)
            if value == nil then return false, "World3D Error: " .. number_error end
            changes[field] = value
        end
    end
    if action == "camera" then
        if (changes.near or target.near) >= (changes.far or target.far) then
            return false, "World3D Error: near must be smaller than far"
        end
    end
    if action == "mesh" then
        if fields.view then
            local name,why=world3d_name(ctx,fields.view)
            if not name then return false,"World3D Error: "..why end
            if name~="none" and not (world.views and world.views[name]) then return false,"World3D Error: no camera view named '"..name.."'" end
            if name~="none" and (fields.texture or fields.image) then return false,"World3D Error: use view or a texture asset" end
            changes.view=name~="none" and name or false
        end
        if world.edits and world.edits[object_name] then
            return false, "World3D Error: commit or cancel the active mesh edit first"
        end
        local changing_vertices = fields.vertices ~= nil
        local changing_triangles = fields.triangles ~= nil
        if changing_vertices ~= changing_triangles or (new_object_name and not changing_vertices) then
            return false, "World3D Error: mesh creation or geometry replacement needs both vertices and triangles"
        end
        if changing_vertices then
            local vertices, triangles, geometry_error =
                world3d_mesh_geometry(ctx, fields.vertices, fields.triangles)
            if not vertices then return false, "World3D Error: " .. geometry_error end
            changes.vertices, changes.triangles = vertices, triangles
            changes.geometry_version = (target.geometry_version or 0) + 1
        end
        if fields.uvs then
            local raw=resolve_path(ctx,fields.uvs)
            if is_fatal(raw) or (type(raw)~="string" and type(raw)~="table") then
                return false,"World3D Error: uvs needs a quoted list or numeric table"
            end
            local uv,uv_error=world3d_parse_uvs(raw,#(changes.vertices or target.vertices or {}),ctx.world3d_mesh_checkpoint)
            if not uv then return false,"World3D Error: " .. tostring(uv_error or "empty UV list") end
            changes.uvs=uv
            changes.geometry_version=(target.geometry_version or 0)+1
        end
        if fields.texture and fields.image then
            return false,"World3D Error: use either texture or image"
        end
        if fields.texture then
            local texture,why=world3d_file_path(ctx,fields.texture)
            if not texture then return false,"World3D Error: " .. why end
            local file=io.open(texture,"rb")
            if not file then return false,"World3D Error: texture file not found" end
            file:close()
            changes.texture_path=texture
        end
        if fields.image then
            local raw=resolve_path(ctx,fields.image)
            if is_fatal(raw) or type(raw)~="string" then
                return false,"World3D Error: image needs quoted base64 or string variable"
            end
            local bytes,why=world3d_base64(raw)
            if not bytes then return false,"World3D Error: " .. why end
            changes.texture_bytes=bytes
        end
        if fields.mime then
            local mime=resolve_path(ctx,fields.mime)
            if mime~="image/png" and mime~="image/jpeg" then
                return false,"World3D Error: mime must be image/png or image/jpeg"
            end
            changes.texture_mime=mime
        end
        if (fields.texture or fields.image) and not (changes.uvs or target.uvs) then
            return false,"World3D Error: texture needs uvs"
        end
        if changes.view and not (changes.uvs or (not changing_vertices and target.uvs)) then
            return false,"World3D Error: view surface needs uvs for its current geometry"
        end
        if changes.unlit and changes.unlit~=0 and changes.unlit~=1 then return false,"World3D Error: unlit must be 0 or 1" end
    end
    local changed=new_object_name~=nil
    for field, value in pairs(changes) do
        if target[field]~=value then target[field]=value;changed=true end
    end
    if action=="mesh" then
        if fields.view then
            target.view=changes.view or nil
            if target.view then target.texture_path,target.texture_bytes,target.texture_mime=nil,nil,nil end
        end
        if fields.texture then target.texture_bytes,target.view=nil,nil end
        if fields.image then target.texture_path,target.view=nil,nil end
        if fields.vertices and not fields.uvs then
            target.uvs,target.texture_path,target.texture_bytes,target.texture_mime,target.view=nil,nil,nil,nil,nil
        end
        if fields.texture or fields.image or fields.vertices or fields.view then
            target.texture_version=(target.texture_version or 0)+1
            changed=true
        end
    end
    if new_object_name then
        world.objects[new_object_name] = target
        world.order[#world.order+1] = new_object_name
    end
    if changed then world.version = world.version + 1 end
    if fields.into then return publish(world3d_copy(target)) end
    return true
end

local function raymaze_pixel(frame, x, y, r, g, b)
    if x < 0 or y < 0 or x >= frame.w or y >= frame.h then return end
    local at = (y * frame.w + x) * 4
    local pixels = frame.pixels
    pixels[at], pixels[at + 1], pixels[at + 2], pixels[at + 3] = r, g, b, 255
end

local raymaze_frontend_lib
local input_preview_menu_control
local input_ui_post_projector
local input_ui_focus_preview
local input_ui_projector_controls
local input_projector_controls_command
local function raymaze_mouse_window()
    if interaction_current and interaction_current.input_focused then
        return interaction_current
    end
    if host_os ~= "Windows" then
        return nil, "Open Interact on a 4IM3 renderer source and focus that window"
    end
    if not raymaze_frontend_lib then
        local library, err = host_library("obs-frontend-api")
        if not library then return nil, "Cannot load OBS frontend API: " .. err end
        raymaze_frontend_lib = library
    end
    local ok, handle = pcall(function()
        return raymaze_frontend_lib.obs_frontend_get_main_window_handle()
    end)
    if not ok or handle == nil or handle == ffi.cast("void*", 0) then
        return nil, "OBS returned an invalid main window handle"
    end
    return handle
end

-- OBS's Lua source registration does not forward source interaction callbacks.
-- On X11, read the existing display's keyboard state while an OBS window owns
-- focus. No helper process or project-specific native library is required.
local x11_keyboard
local x11_keyboard_error
local x11_keyboard_checked = false
local function linux_x11_keyboard()
    if x11_keyboard_checked then return x11_keyboard, x11_keyboard_error end
    x11_keyboard_checked = true
    if host_os ~= "Linux" then return nil, "X11 keyboard is Linux-only" end
    local ok, err = pcall(ffi.cdef, [[
        typedef struct im3_x11_display im3_x11_display;
        typedef unsigned long im3_x11_window;
        typedef struct { char *res_name; char *res_class; } im3_x11_class_hint;
        im3_x11_display *XOpenDisplay(const char *);
        int XCloseDisplay(im3_x11_display *);
        int XQueryKeymap(im3_x11_display *, char[32]);
        unsigned char XKeysymToKeycode(im3_x11_display *, unsigned long);
        int XkbLookupKeySym(im3_x11_display *, unsigned char, unsigned int,
                            unsigned int *, unsigned long *);
        int XGetInputFocus(im3_x11_display *, im3_x11_window *, int *);
        int XQueryPointer(im3_x11_display *, im3_x11_window,
                          im3_x11_window *, im3_x11_window *,
                          int *, int *, int *, int *, unsigned int *);
        int XGetGeometry(im3_x11_display *, im3_x11_window,
                         im3_x11_window *, int *, int *,
                         unsigned int *, unsigned int *,
                         unsigned int *, unsigned int *);
        int XFetchName(im3_x11_display *, im3_x11_window, char **);
        int XGetClassHint(im3_x11_display *, im3_x11_window, im3_x11_class_hint *);
        int XQueryTree(im3_x11_display *, im3_x11_window,
                       im3_x11_window *, im3_x11_window *,
                       im3_x11_window **, unsigned int *);
        int XFree(void *);
    ]])
    if not ok then
        x11_keyboard_error = "Input Error: X11 declarations failed: " .. tostring(err)
        return nil, x11_keyboard_error
    end
    local library, load_error = host_library("X11")
    if not library then
        local found, loaded = pcall(ffi.load, "libX11.so.6")
        if found then library = loaded end
    end
    if not library then
        x11_keyboard_error = "Input Error: libX11 is unavailable: " .. tostring(load_error)
        return nil, x11_keyboard_error
    end
    local display = library.XOpenDisplay(nil)
    if display == nil or display == ffi.NULL then
        x11_keyboard_error = "Input Error: Cannot open X11 display. " ..
            "A native Wayland OBS window cannot use X11 keyboard polling"
        return nil, x11_keyboard_error
    end
    x11_keyboard = {library = library, display = display,
                    keymap = ffi.new("char[32]"), codes = {},
                    focus_window = nil, focus_is_obs = false}
    if os.getenv("XDG_SESSION_TYPE") == "wayland" then
        obslua.script_log(obslua.LOG_WARNING,
            "[4IM3-SCRIPT] X11 keyboard input on Wayland works only " ..
            "when OBS itself runs through XWayland")
    end
    return x11_keyboard
end
local x11_keysyms = {
    UP=0xff52, DOWN=0xff54, LEFT=0xff51, RIGHT=0xff53,
    ENTER=0xff0d, SPACE=0x20, ESCAPE=0xff1b, TAB=0xff09,
    BACKSPACE=0xff08, DELETE=0xffff, HOME=0xff50, END=0xff57,
    SHIFT=0xffe1, CTRL=0xffe3, ALT=0xffe9,
    NUMPAD_MULTIPLY=0xffaa, NUMPAD_ADD=0xffab, NUMPAD_SEPARATOR=0xffac,
    NUMPAD_SUBTRACT=0xffad, NUMPAD_DECIMAL=0xffae, NUMPAD_DIVIDE=0xffaf,
}
for digit=0,9 do x11_keysyms["NUMPAD"..digit]=0xffb0+digit end
local function linux_x11_focused(backend)
    local focus = ffi.new("im3_x11_window[1]")
    local revert = ffi.new("int[1]")
    backend.library.XGetInputFocus(backend.display, focus, revert)
    local window = tonumber(focus[0])
    if backend.focus_window == window then return backend.focus_is_obs end
    backend.focus_window, backend.focus_is_obs = window, false
    local cursor = window
    for _ = 1, 16 do
        if cursor <= 1 then break end
        local hint = ffi.new("im3_x11_class_hint[1]")
        if backend.library.XGetClassHint(backend.display, cursor, hint) ~= 0 then
            local class = hint[0].res_class ~= nil and
                ffi.string(hint[0].res_class) or ""
            if hint[0].res_name ~= nil then
                backend.library.XFree(hint[0].res_name)
            end
            if hint[0].res_class ~= nil then
                backend.library.XFree(hint[0].res_class)
            end
            backend.focus_is_obs = class:lower():find("obs", 1, true) ~= nil
            if backend.focus_is_obs then break end
        end
        local root = ffi.new("im3_x11_window[1]")
        local parent = ffi.new("im3_x11_window[1]")
        local children = ffi.new("im3_x11_window *[1]")
        local count = ffi.new("unsigned int[1]")
        if backend.library.XQueryTree(backend.display, cursor, root, parent,
                                      children, count) == 0 then break end
        if children[0] ~= nil then backend.library.XFree(children[0]) end
        local next_window = tonumber(parent[0])
        if next_window <= 1 or next_window == cursor then break end
        cursor = next_window
    end
    return backend.focus_is_obs
end

-- All host input calls live here. Windows uses its native key state; Linux
-- X11 uses the display already provided by the desktop session.
local input_host = {os = host_os}
-- DirectInput exposes relative wheel motion without a window hook, callback,
-- helper executable, or bundled DLL. Initialize only for !input | wheel.
local input_wheel_device
local input_wheel_interface
local input_wheel_library
local input_wheel_attempted = false
local input_wheel_warned = false
local input_wheel_handle
-- LuaJIT allocates a new callback-pointer ctype when ffi.cast receives a
-- signature string. Repeating that cast on every wheel poll eventually raises
-- "table overflow". Compile each COM method type once and reuse it.
local input_wheel_vtable_type
local input_wheel_method_types = {}
local function input_wheel_method(object, index, signature)
    if not input_wheel_vtable_type then
        input_wheel_vtable_type = ffi.typeof("void***")
    end
    local method_type = input_wheel_method_types[signature]
    if not method_type then
        method_type = ffi.typeof(signature)
        input_wheel_method_types[signature] = method_type
    end
    return ffi.cast(method_type, ffi.cast(input_wheel_vtable_type, object)[0][index])
end
local function input_wheel_release()
    if input_wheel_device then
        input_wheel_method(input_wheel_device, 8,
            "int (__stdcall *)(void*)")(input_wheel_device)
        input_wheel_method(input_wheel_device, 2,
            "unsigned long (__stdcall *)(void*)")(input_wheel_device)
        input_wheel_device = nil
    end
    if input_wheel_interface then
        input_wheel_method(input_wheel_interface, 2,
            "unsigned long (__stdcall *)(void*)")(input_wheel_interface)
        input_wheel_interface = nil
    end
    input_wheel_handle = nil
end
local function input_wheel_open(handle)
    if host_os ~= "Windows" or not handle or type(handle) == "table" then
        return false
    end
    if input_wheel_device then
        if input_wheel_handle == handle then return true end
        input_wheel_method(input_wheel_device, 8,
            "int (__stdcall *)(void*)")(input_wheel_device)
        local set_level = input_wheel_method(input_wheel_device, 13,
            "int (__stdcall *)(void*, void*, uint32_t)")
        if set_level(input_wheel_device, handle, 6) < 0 then
            input_wheel_release()
            return false
        end
        input_wheel_handle = handle
        return true
    end
    if input_wheel_attempted then return false end
    input_wheel_attempted = true
    local declared = pcall(ffi.typeof, "im3_di_guid")
    if not declared then declared = pcall(ffi.cdef, [[
        typedef struct { uint32_t a; uint16_t b, c; uint8_t d[8]; } im3_di_guid;
        typedef struct { const im3_di_guid *guid; uint32_t offset, type, flags; }
            im3_di_object_format;
        typedef struct { uint32_t size, object_size, flags, data_size, count;
            const im3_di_object_format *objects; } im3_di_data_format;
        int __stdcall DirectInput8Create(void *, uint32_t,
            const im3_di_guid *, void **, void *);
    ]]) end
    if not declared then return false end
    local loaded, library = pcall(ffi.load, "dinput8")
    if not loaded then return false end
    input_wheel_library = library
    local iid = ffi.new("im3_di_guid[1]", {{0xBF798031,0x483A,0x4DA2,
        {0xAA,0x99,0x5D,0x64,0xED,0x36,0x97,0x00}}})
    local mouse_guid = ffi.new("im3_di_guid[1]", {{0x6F1D2B60,0xD5A0,0x11CF,
        {0xBF,0xC7,0x44,0x45,0x53,0x54,0x00,0x00}}})
    local z_guid = ffi.new("im3_di_guid[1]", {{0xA36D02E2,0xC9F3,0x11CF,
        {0xBF,0xC7,0x44,0x45,0x53,0x54,0x00,0x00}}})
    local output = ffi.new("void*[1]")
    if library.DirectInput8Create(ffi.C.GetModuleHandleA(nil),0x0800,
        iid,output,nil) < 0 or output[0] == nil then return false end
    input_wheel_interface = output[0]
    local create_device = input_wheel_method(input_wheel_interface, 3,
        "int (__stdcall *)(void*, const im3_di_guid*, void**, void*)")
    output[0] = nil
    if create_device(input_wheel_interface,mouse_guid,output,nil) < 0 or
       output[0] == nil then
        input_wheel_release()
        return false
    end
    input_wheel_device = output[0]
    -- Only the Z axis is requested. A mouse without a wheel fails setup cleanly.
    local object = ffi.new("im3_di_object_format[1]")
    object[0].guid = z_guid
    object[0].offset = 0
    object[0].type = 0x00FFFF01 -- DIDFT_ANYINSTANCE | DIDFT_RELAXIS
    local format = ffi.new("im3_di_data_format[1]")
    format[0].size = ffi.sizeof("im3_di_data_format")
    format[0].object_size = ffi.sizeof("im3_di_object_format")
    format[0].flags = 2 -- DIDF_RELAXIS
    format[0].data_size = 4
    format[0].count = 1
    format[0].objects = object
    local set_format = input_wheel_method(input_wheel_device, 11,
        "int (__stdcall *)(void*, const im3_di_data_format*)")
    local set_level = input_wheel_method(input_wheel_device, 13,
        "int (__stdcall *)(void*, void*, uint32_t)")
    if set_format(input_wheel_device,format) < 0 or
       set_level(input_wheel_device,handle,6) < 0 then -- nonexclusive, foreground
        input_wheel_release()
        return false
    end
    input_wheel_handle = handle
    return true
end
function input_host.wheel_delta(handle)
    if not input_wheel_open(handle) then return 0 end
    local state = ffi.new("int32_t[1]")
    local read = input_wheel_method(input_wheel_device, 9,
        "int (__stdcall *)(void*, uint32_t, void*)")
    if read(input_wheel_device,4,state) < 0 then
        input_wheel_method(input_wheel_device,7,
            "int (__stdcall *)(void*)")(input_wheel_device)
        return 0
    end
    return tonumber(state[0]) / 120
end
function input_host.focused(handle)
    if handle == x11_keyboard and x11_keyboard then
        return linux_x11_focused(x11_keyboard)
    end
    if type(handle) == "table" and handle.input_interaction then
        return interaction_current == handle and handle.input_focused == true
    end
    return host_os == "Windows" and ffi.C.GetForegroundWindow() == handle
end
function input_host.screen_pointer()
    if host_os ~= "Windows" then return nil end
    local point = ffi.new("POINT")
    if ffi.C.GetCursorPos(point) == 0 then return nil end
    return tonumber(point.x), tonumber(point.y)
end
function input_host.pointer()
    if interaction_current and interaction_current.input_focused and
       interaction_current.input_inside then
        return interaction_current.input_x, interaction_current.input_y
    end
    return input_host.screen_pointer()
end
function input_host.client_position(handle, x, y)
    if type(handle) == "table" and handle.input_interaction then
        if x and y and x >= 0 and y >= 0 and
           x < handle.width and y < handle.height then return x, y end
        return nil
    end
    if host_os ~= "Windows" then return nil end
    local bounds = ffi.new("RECT")
    local point = ffi.new("POINT")
    point.x, point.y = x, y
    if ffi.C.GetClientRect(handle, bounds) == 0 or
       ffi.C.ScreenToClient(handle, point) == 0 then
        return nil
    end
    if point.x < bounds.left or point.x >= bounds.right or
       point.y < bounds.top or point.y >= bounds.bottom then
        return nil
    end
    return tonumber(point.x), tonumber(point.y)
end
local function input_viewport_coordinates(px,py,area_width,area_height,
                                          source_width,source_height,edge)
    if not area_width or not area_height or not source_width or not source_height or
       source_width<=0 or source_height<=0 then return nil end
    edge=edge or 0
    area_width,area_height=area_width-edge*2,area_height-edge*2
    if area_width<=0 or area_height<=0 then return nil end
    -- Match OBS GetScaleAndCenterPos, including its integer centering. The
    -- main preview reserves PREVIEW_EDGE_SIZE (10 physical pixels); Interact
    -- and projectors fit their whole display and must not inherit that inset.
    local scale,draw_width,draw_height
    if area_width/area_height>source_width/source_height then
        scale=area_height/source_height
        draw_width,draw_height=math.floor(area_height*source_width/source_height),area_height
    else
        scale=area_width/source_width
        draw_width,draw_height=area_width,math.floor(area_width*source_height/source_width)
    end
    local left=edge+math.floor(area_width/2)-math.floor(draw_width/2)
    local top=edge+math.floor(area_height/2)-math.floor(draw_height/2)
    local x=(px-left)/scale
    local y=(py-top)/scale
    if x<0 or y<0 or x>=source_width or y>=source_height then return nil end
    return x,y
end
local function input_windows_title(window, wide)
    local title = ffi.new(wide and "uint16_t[512]" or "char[512]")
    local length = ffi.new("uintptr_t[1]")
    local read = wide and ffi.C.SendMessageTimeoutW or ffi.C.SendMessageTimeoutA
    -- GetWindowText sends WM_GETTEXT to same-process windows and can wait for
    -- the UI indefinitely. A busy projector must not hold the Lua tick lock.
    if read(window, 0x000D, 512, ffi.cast("intptr_t", title), 3, 2, length) == 0 then
        return nil
    end
    return title, tonumber(length[0])
end
local function input_windows_preview_projector(main_window, foreground)
    if not raymaze_frontend_lib or not foreground or
       foreground==ffi.NULL or foreground==main_window then return false end
    local main_pid=ffi.new("unsigned long[1]")
    local foreground_pid=ffi.new("unsigned long[1]")
    if ffi.C.GetWindowThreadProcessId(main_window,main_pid)==0 or
       ffi.C.GetWindowThreadProcessId(foreground,foreground_pid)==0 or
       main_pid[0]==0 or main_pid[0]~=foreground_pid[0] then return false end
    local translated,projector_title,preview_title=pcall(function()
        return ffi.string(raymaze_frontend_lib.obs_frontend_get_locale_string(
            "Projector.Title")),
            ffi.string(raymaze_frontend_lib.obs_frontend_get_locale_string(
                "StudioMode.Preview"))
    end)
    if not translated or not projector_title or not preview_title then return false end
    local title,length=input_windows_title(foreground,true)
    if not title or length<=0 then return false end
    local utf8=ffi.new("char[2048]")
    local bytes=ffi.C.WideCharToMultiByte(65001,0,title,length,utf8,2048,nil,nil)
    if bytes<=0 then return false end
    return ffi.string(utf8,bytes)==projector_title .. " - " .. preview_title
end
local function projector_command(ctx,state,args)
    local action=tostring(args[1] or ""):lower()
    if action=="controls" or action=="close" then return input_projector_controls_command(ctx,args) end
    if tostring(args[1] or ""):lower() ~= "fullscreen" then
        return false,"Projector Error: Expected fullscreen | monitor:0, controls | escape:game/default | exit_key:F11, or close"
    end
    local monitor,seen=0,false
    for i=2,#args do
        local parts,split_error=split_named_attribute_group(tostring(args[i] or ""))
        if not parts then return false,"Projector Error: "..split_error end
        for _,part in ipairs(parts) do
            local key,value=part:match("^%s*([%a_][%w_]*)%s*:%s*(.-)%s*$")
            if not key or key:lower()~="monitor" or value=="" or seen then
                return false,"Projector Error: Expected one optional monitor:index attribute"
            end
            seen=true
            local evaluated=evaluate_math(ctx,value)
            if is_fatal(evaluated) then
                return false,"Projector Error: "..tostring(evaluated.msg)
            end
            monitor=tonumber(evaluated)
            if not monitor or monitor<0 or monitor%1~=0 then
                return false,"Projector Error: monitor must be a nonnegative whole-number index (first monitor is 0)"
            end
        end
    end
    if host_os=="Windows" then
        local screens=ffi.C.GetSystemMetrics(80) -- SM_CMONITORS
        if screens>0 and monitor>=screens then
            return false,"Projector Error: monitor:"..monitor..
                " is unavailable (this computer has "..screens.." monitor(s), indexed from 0)"
        end
    end
    local scene=obslua.obs_frontend_get_current_scene()
    if not scene then return false,"Projector Error: OBS has no current scene" end
    local preview_width,preview_height
    if host_os=="Windows" then
        preview_width=tonumber(obslua.obs_source_get_width(scene))
        preview_height=tonumber(obslua.obs_source_get_height(scene))
    end
    obslua.obs_source_release(scene)
    if not raymaze_frontend_lib then
        local library,err=host_library("obs-frontend-api")
        if not library then return false,"Projector Error: "..tostring(err) end
        raymaze_frontend_lib=library
    end
    if host_os=="Windows" then
        local main=raymaze_frontend_lib.obs_frontend_get_main_window_handle()
        if main~=nil and main~=ffi.NULL and
           input_windows_preview_projector(main,ffi.C.GetForegroundWindow()) then
            if preview_width and preview_height and
               preview_width>0 and preview_height>0 then
                ctx.input_preview={width=preview_width,height=preview_height}
                ctx.input_viewport=nil
            end
            return true -- F in an already focused projector must not open another one.
        end
    end
    if host_os=="Windows" then
        local ok,err=input_ui_post_projector(monitor,ctx.input_preview_menu_blocked)
        if not ok then return false,"Projector Error: "..tostring(err) end
    else
        local ok,err=pcall(function()
            raymaze_frontend_lib.obs_frontend_open_projector("Preview",monitor,nil,nil)
        end)
        if not ok then return false,"Projector Error: "..tostring(err) end
    end
    -- The new projector is a scene preview. Bind it for focused keyboard and
    -- mapped pointer input without requiring a second script command.
    if host_os=="Windows" and preview_width and preview_height and
       preview_width>0 and preview_height>0 then
        ctx.input_preview={width=preview_width,height=preview_height}
        ctx.input_viewport=nil
    end
    return true
end
local function input_windows_viewport(name,width,height)
    local foreground=ffi.C.GetForegroundWindow()
    if foreground==nil or foreground==ffi.NULL then return nil end
    local title=input_windows_title(foreground,false)
    if not title or not ffi.string(title):find(name,1,true) then return nil end
    local point=ffi.new("POINT")
    if ffi.C.GetCursorPos(point)==0 then return nil end
    local child=ffi.C.WindowFromPoint(point)
    if child==nil or child==ffi.NULL or
       ffi.C.GetAncestor(child,2)~=foreground or child==foreground then
        return nil,true
    end
    local bounds=ffi.new("RECT")
    if ffi.C.GetClientRect(child,bounds)==0 or
       ffi.C.ScreenToClient(child,point)==0 then return nil,true end
    local x,y=input_viewport_coordinates(tonumber(point.x),tonumber(point.y),
        tonumber(bounds.right-bounds.left),tonumber(bounds.bottom-bounds.top),
        width,height)
    return x,y,true
end
local function input_windows_scene_preview(handle,width,height)
    if not handle then return nil end
    local foreground=ffi.C.GetForegroundWindow()
    if foreground~=handle then
        if not input_windows_preview_projector(handle,foreground) then return nil end
        local point=ffi.new("POINT")
        if ffi.C.GetCursorPos(point)==0 then return nil,nil,true,foreground end
        local child=ffi.C.WindowFromPoint(point)
        if child==nil or child==ffi.NULL or
           (child~=foreground and ffi.C.GetAncestor(child,2)~=foreground) then
            return nil,nil,true,foreground
        end
        local bounds=ffi.new("RECT")
        if ffi.C.GetClientRect(foreground,bounds)==0 or
           ffi.C.ScreenToClient(foreground,point)==0 then
            return nil,nil,true,foreground
        end
        local x,y=input_viewport_coordinates(tonumber(point.x),tonumber(point.y),
            tonumber(bounds.right-bounds.left),
            tonumber(bounds.bottom-bounds.top),width,height)
        return x,y,true,foreground
    end
    local point=ffi.new("POINT")
    if ffi.C.GetCursorPos(point)==0 then return nil,nil,true end
    local child=ffi.C.WindowFromPoint(point)
    if child==nil or child==ffi.NULL or child==handle or
       ffi.C.GetAncestor(child,2)~=handle then return nil,nil,true end
    local main_bounds=ffi.new("RECT")
    local preview_bounds=ffi.new("RECT")
    if ffi.C.GetClientRect(handle,main_bounds)==0 or
       ffi.C.GetClientRect(child,preview_bounds)==0 then return nil,nil,true end
    local main_width=tonumber(main_bounds.right-main_bounds.left)
    local main_height=tonumber(main_bounds.bottom-main_bounds.top)
    local area_width=tonumber(preview_bounds.right-preview_bounds.left)
    local area_height=tonumber(preview_bounds.bottom-preview_bounds.top)
    if ffi.C.ScreenToClient(child,point)==0 then return nil,nil,true end
    if input_host and input_host.preview_geometry then
        local geometry,available=input_host.preview_geometry(child,width,height)
        if available then
            if not geometry or geometry.area_width~=area_width or geometry.area_height~=area_height then return nil,nil,true,handle end
            local x=(tonumber(point.x)-geometry.left)/geometry.scale
            local y=(tonumber(point.y)-geometry.top)/geometry.scale
            if x<0 or y<0 or x>=width or y>=height then return nil,nil,true,handle end
            return x,y,true,handle
        end
    end
    -- Older OBS/Qt builds without preview metadata retain fit-to-window
    -- polling. Reject docks and controls in that fallback path.
    if area_width<math.max(160,main_width*0.35) or
       area_height<math.max(90,main_height*0.25) then return nil,nil,true end
    local x,y=input_viewport_coordinates(tonumber(point.x),tonumber(point.y),
        area_width,area_height,width,height,10)
    return x,y,true,handle
end
local function input_x11_viewport(name,width,height)
    local backend=x11_keyboard
    if not backend or not linux_x11_focused(backend) then return nil end
    local focus=ffi.new("im3_x11_window[1]")
    local revert=ffi.new("int[1]")
    backend.library.XGetInputFocus(backend.display,focus,revert)
    local window=tonumber(focus[0])
    local title_matches=false
    local ancestor=window
    for _=1,16 do
        if ancestor<=1 then break end
        local title=ffi.new("char *[1]")
        if backend.library.XFetchName(backend.display,ancestor,title)~=0 and
           title[0]~=nil then
            title_matches=ffi.string(title[0]):find(name,1,true)~=nil
            backend.library.XFree(title[0])
            if title_matches then break end
        end
        local root,parent=ffi.new("im3_x11_window[1]"),ffi.new("im3_x11_window[1]")
        local children=ffi.new("im3_x11_window *[1]")
        local count=ffi.new("unsigned int[1]")
        if backend.library.XQueryTree(backend.display,ancestor,root,parent,
                                      children,count)==0 then break end
        if children[0]~=nil then backend.library.XFree(children[0]) end
        local next_window=tonumber(parent[0])
        if next_window<=1 or next_window==ancestor then break end
        ancestor=next_window
    end
    if not title_matches then return nil end
    local px,py,mask
    for _=1,12 do
        local root,child=ffi.new("im3_x11_window[1]"),ffi.new("im3_x11_window[1]")
        local root_x,root_y=ffi.new("int[1]"),ffi.new("int[1]")
        local win_x,win_y=ffi.new("int[1]"),ffi.new("int[1]")
        local state=ffi.new("unsigned int[1]")
        if backend.library.XQueryPointer(backend.display,window,root,child,
                root_x,root_y,win_x,win_y,state)==0 then return nil,true end
        px,py,mask=tonumber(win_x[0]),tonumber(win_y[0]),tonumber(state[0])
        if tonumber(child[0])<=1 then break end
        window=tonumber(child[0])
    end
    backend.pointer_mask=mask
    local root=ffi.new("im3_x11_window[1]")
    local gx,gy=ffi.new("int[1]"),ffi.new("int[1]")
    local gw,gh=ffi.new("unsigned int[1]"),ffi.new("unsigned int[1]")
    local border,depth=ffi.new("unsigned int[1]"),ffi.new("unsigned int[1]")
    if backend.library.XGetGeometry(backend.display,window,root,gx,gy,gw,gh,
                                    border,depth)==0 then return nil,true end
    local x,y=input_viewport_coordinates(px,py,tonumber(gw[0]),tonumber(gh[0]),
                                          width,height)
    return x,y,true
end
function input_host.viewport_pointer(name,width,height)
    if host_os=="Windows" then return input_windows_viewport(name,width,height) end
    if host_os=="Linux" then return input_x11_viewport(name,width,height) end
    return nil
end
function input_host.scene_preview_pointer(handle,width,height)
    if host_os=="Windows" then
        return input_windows_scene_preview(handle,width,height)
    end
    return nil
end
function input_host.key_down(code, name)
    if interaction_current and interaction_current.input_focused then
        return interaction_current.input_keys[name] == true
    end
    if host_os == "Linux" and x11_keyboard and x11_keyboard.focus_is_obs then
        local backend = x11_keyboard
        if name:sub(1,6)=="MOUSE_" then
            local masks={MOUSE_LEFT=256,MOUSE_MIDDLE=512,MOUSE_RIGHT=1024}
            return bit.band(backend.pointer_mask or 0,masks[name] or 0)~=0
        end
        local keysym = x11_keysyms[name]
        if not keysym and #name == 1 then keysym = name:byte() end
        if not keysym and name:match("^F%d+$") then
            keysym = 0xffbd + tonumber(name:sub(2))
        end
        if not keysym then return false end
        local keycode = backend.codes[name]
        if not keycode then
            keycode = tonumber(backend.library.XKeysymToKeycode(
                backend.display, keysym))
            backend.codes[name] = keycode
        end
        if keycode >= 1 and keycode <= 255 and
           bit.band(tonumber(backend.keymap[math.floor(keycode / 8)]),
                    bit.lshift(1, keycode % 8)) ~= 0 then return true end
        -- X11 gives keypad Enter its own keycode; Windows uses VK_RETURN for both.
        if name=="ENTER" then
            local keypad=backend.codes.KP_ENTER
            if not keypad then
                keypad=tonumber(backend.library.XKeysymToKeycode(backend.display,0xff8d))
                backend.codes.KP_ENTER=keypad
            end
            return keypad>=1 and keypad<=255 and
                bit.band(tonumber(backend.keymap[math.floor(keypad/8)]),
                         bit.lshift(1,keypad%8))~=0
        end
        return false
    end
    return host_os == "Windows" and ffi.C.GetAsyncKeyState(code) < 0
end
-- Resolve Num Lock/Shift through XKB only when a keypad text key is pressed.
-- This avoids interpreting keypad navigation as digits with Num Lock disabled.
function input_host.keypad_text(name, character)
    if host_os~="Linux" or not x11_keyboard then return character end
    local backend=x11_keyboard
    local root,child=ffi.new("im3_x11_window[1]"),ffi.new("im3_x11_window[1]")
    local rx,ry,wx,wy=ffi.new("int[1]"),ffi.new("int[1]"),ffi.new("int[1]"),ffi.new("int[1]")
    local state,mods,symbol=ffi.new("unsigned int[1]"),ffi.new("unsigned int[1]"),ffi.new("unsigned long[1]")
    if backend.library.XQueryPointer(backend.display,backend.focus_window,root,child,
            rx,ry,wx,wy,state)==0 then return "" end
    if backend.library.XkbLookupKeySym(backend.display,backend.codes[name],state[0],mods,symbol)==0 then return "" end
    local sym=tonumber(symbol[0])
    if sym>=0xffb0 and sym<=0xffb9 then return tostring(sym-0xffb0) end
    return ({[0xffaa]="*",[0xffab]="+",[0xffac]=",",[0xffad]="-",[0xffae]=".",[0xffaf]="/"})[sym] or ""
end
function input_host.recenter(x, y)
    if interaction_current and interaction_current.input_focused then return true end
    return host_os == "Windows" and ffi.C.SetCursorPos(x, y) ~= 0
end

-- A one-shot warp, not a hook or persistent OS capture. Calls stop having
-- any effect as soon as the script stops polling, loses focus, or leaves play.
function input_host.recenter_pointer(ctx,sample)
    local result={supported=(host_os=="Windows" and not interaction_current) and 1 or 0,warped=0,
        x=sample.x,y=sample.y}
    if result.supported==0 or not sample.focused or not sample.mouse_inside or
       interaction_current then return result end
    local viewport=ctx.input_preview or ctx.input_viewport
    if not viewport then return result end
    local point=ffi.new("POINT")
    if ffi.C.GetCursorPos(point)==0 then return result end
    local window=ffi.C.WindowFromPoint(point)
    -- Scene projectors map their entire client area, while the main preview
    -- and Interact viewport map the native display child under the pointer.
    if ctx.input_preview and ctx.input_active_window~=ctx.input_window then
        window=ctx.input_active_window
    end
    if not window or window==ffi.NULL then return result end
    local bounds=ffi.new("RECT")
    if ffi.C.GetClientRect(window,bounds)==0 then return result end
    local geometry
    if ctx.input_preview and ctx.input_active_window==ctx.input_window and input_host.preview_geometry then
        local available
        geometry,available=input_host.preview_geometry(window,viewport.width,viewport.height)
        if available and not geometry then return result end
    end
    local edge=ctx.input_preview and ctx.input_active_window==ctx.input_window and 10 or 0
    local scale=math.min((tonumber(bounds.right-bounds.left)-edge*2)/viewport.width,
                         (tonumber(bounds.bottom-bounds.top)-edge*2)/viewport.height)
    if geometry then scale=geometry.scale end
    if scale<=0 then return result end
    local x,y=viewport.width/2,viewport.height/2
    if not input_host.focused(ctx.input_active_window) then return result end
    if input_host.recenter(math.floor(tonumber(point.x)+(x-sample.x)*scale+.5),
                           math.floor(tonumber(point.y)+(y-sample.y)*scale+.5)) then
        result.x,result.y,result.warped=x,y,1
    end
    return result
end

-- Focused keyboard and mouse polling. The high bit of GetAsyncKeyState is
-- the current down state; its low "pressed since last call" bit is unreliable.
local input_codes = {
    UP=0x26, DOWN=0x28, LEFT=0x25, RIGHT=0x27,
    ENTER=0x0D, SPACE=0x20, ESCAPE=0x1B, TAB=0x09, BACKSPACE=0x08,
    DELETE=0x2E, HOME=0x24, END=0x23,
    SHIFT=0x10, CTRL=0x11, ALT=0x12,
    NUMPAD_MULTIPLY=0x6A, NUMPAD_ADD=0x6B, NUMPAD_SEPARATOR=0x6C,
    NUMPAD_SUBTRACT=0x6D, NUMPAD_DECIMAL=0x6E, NUMPAD_DIVIDE=0x6F,
    MOUSE_LEFT=0x01, MOUSE_RIGHT=0x02, MOUSE_MIDDLE=0x04,
    MOUSE_X1=0x05, MOUSE_X2=0x06,
}
local input_aliases = {RETURN="ENTER", ESC="ESCAPE", CONTROL="CTRL", DEL="DELETE",
                       MOUSE1="MOUSE_LEFT", MOUSE2="MOUSE_RIGHT",
                       MOUSE3="MOUSE_MIDDLE"}
for code=string.byte("A"),string.byte("Z") do
    local name=string.char(code)
    input_codes[name]=code
end
for code=string.byte("0"),string.byte("9") do
    local name=string.char(code)
    input_codes[name]=code
end
for digit=0,9 do
    input_codes["NUMPAD"..digit]=0x60+digit
    input_aliases["KP_"..digit]="NUMPAD"..digit
    input_aliases["NUMPAD_"..digit]="NUMPAD"..digit
end
input_aliases.KP_ENTER="ENTER"
input_aliases.NUMPAD_ENTER="ENTER"
for i=1,12 do input_codes["F"..i]=0x6F+i end
local function input_name(raw)
    local name=tostring(raw or ""):upper():gsub("[%s%-]", "_")
    name=input_aliases[name] or name
    if not input_codes[name] then return nil end
    return name
end
local function input_poll(ctx, requested, include_pointer)
    local handle=interaction_current
    if not handle and host_os == "Windows" then
        handle=ctx.input_window
    end
    if not handle and host_os == "Windows" then
        local err
        handle,err=raymaze_mouse_window()
        if not handle then return nil,err end
        ctx.input_window=handle
    elseif not handle and host_os == "Linux" then
        local err
        handle,err=linux_x11_keyboard()
        if not handle then return nil,err end
    elseif not handle and not ctx.input_interaction_notice then
        ctx.input_interaction_notice=true
        obslua.script_log(obslua.LOG_WARNING,
            "[4IM3-SCRIPT] Open Interact on a 4IM3 renderer source for keyboard and mouse input on " ..
            tostring(host_os))
    end
    local focused=handle and input_host.focused(handle) or false
    if focused and handle == x11_keyboard then
        x11_keyboard.library.XQueryKeymap(x11_keyboard.display,
                                           x11_keyboard.keymap)
    end
    -- OBS may open a Preview Projector through its own menu rather than the
    -- !projector command. Bind that focused scene automatically as well.
    if host_os=="Windows" and handle and not focused and
       not interaction_current and not ctx.input_preview and
       not ctx.input_viewport and
       input_windows_preview_projector(handle,ffi.C.GetForegroundWindow()) then
        local scene=obslua.obs_frontend_get_current_scene()
        if scene then
            local width=tonumber(obslua.obs_source_get_width(scene))
            local height=tonumber(obslua.obs_source_get_height(scene))
            obslua.obs_source_release(scene)
            if width and height and width>0 and height>0 then
                ctx.input_preview={width=width,height=height}
            end
        end
    end
    local viewport_x,viewport_y,viewport_focused,viewport_window
    if ctx.input_preview and not interaction_current then
        local preview=ctx.input_preview
        viewport_x,viewport_y,viewport_focused,viewport_window=
            input_host.scene_preview_pointer(handle,preview.width,preview.height)
        if viewport_focused then focused=true end
    elseif ctx.input_viewport and not interaction_current then
        local viewport=ctx.input_viewport
        viewport_x,viewport_y,viewport_focused=input_host.viewport_pointer(
            viewport.name,viewport.width,viewport.height)
        if viewport_focused then focused=true end
    end
    local inside=false
    local x,y=-1,-1
    if include_pointer~=false then
        if (ctx.input_preview or ctx.input_viewport) and not interaction_current then
            if viewport_x then
                inside=true
                x,y=viewport_x,viewport_y
            end
        else
            local screen_x,screen_y=input_host.pointer()
            if focused and screen_x then
                local client_x,client_y=input_host.client_position(handle,screen_x,screen_y)
                if client_x then
                    inside=true
                    x,y=client_x,client_y
                end
            end
        end
    end
    local previous=ctx.input_previous or {}
    local blocked=ctx.input_blocked or {}
    local physical_previous=ctx.input_mouse_physical or {}
    local focus_was=ctx.input_focused==true
    local inside_was=ctx.input_mouse_inside==true
    local states={}
    for _,raw in ipairs(requested or {}) do
        local name=input_name(raw)
        if not name then return nil,"Unknown input key '"..tostring(raw).."'" end
        local mouse_key=name:sub(1,6)=="MOUSE_"
        local physical=mouse_key and input_host.key_down(input_codes[name],name) or false
        local down=focused and (not mouse_key or inside) and
            (mouse_key and physical or not mouse_key and input_host.key_down(input_codes[name],name)) or false
        local was_down=previous[name]==true
        if down and (previous[name]==nil or not focus_was or
                     (mouse_key and not inside_was)) then
            -- A fresh mouse press can itself focus the preview/projector.
            -- Suppress buttons already held outside, but accept a known up->down
            -- transition inside. Keyboard focus-regain behavior stays unchanged.
            blocked[name]=not (mouse_key and physical_previous[name]==false) or nil
        elseif not down then
            blocked[name]=nil
        end
        if mouse_key and physical and ctx.input_mouse_sampler and
           ctx.input_mouse_sampler.input_blocked[name] then blocked[name]=true end
        states[name]={down=down,pressed=down and not was_down and not blocked[name],
                      released=not down and was_down}
        if mouse_key then
            if host_os=="Windows" or focused then physical_previous[name]=physical
            else physical_previous[name]=nil end
            if not ctx._input_sampling and not ctx.input_event_owner then
                ctx.input_watched_mouse=ctx.input_watched_mouse or {}
                ctx.input_watched_mouse[name]=true
                local pending=ctx.input_pending_mouse and ctx.input_pending_mouse[name]
                local active=viewport_window or handle
                if pending and focused and pending.window==active then
                    states[name].pressed=states[name].pressed or pending.pressed
                    states[name].released=states[name].released or pending.released
                    if pending.pressed then
                        states[name].pressed_x,states[name].pressed_y=pending.x,pending.y
                    end
                end
                if ctx.input_pending_mouse then ctx.input_pending_mouse[name]=nil end
                if states[name].pressed and not states[name].pressed_x then
                    states[name].pressed_x,states[name].pressed_y=x,y
                end
                -- A command can sample after the tick's background sample. Keep
                -- that sampler aligned so the same press is never replayed.
                local sampler=ctx.input_mouse_sampler
                if sampler then
                    sampler.input_previous[name]=down
                    sampler.input_blocked[name]=blocked[name]
                    sampler.input_mouse_physical[name]=physical
                    sampler.input_focused,sampler.input_mouse_inside=focused,inside
                end
            end
        end
        previous[name]=down
    end
    ctx.input_previous=previous
    ctx.input_blocked=blocked
    ctx.input_mouse_physical=physical_previous
    ctx.input_focused=focused
    ctx.input_active_window=focused and (viewport_window or handle) or nil
    if ctx.input_projector_controls and viewport_window and focused and
       ctx.input_projector_last_window~=viewport_window then
        local controls=ctx.input_projector_controls
        local ok=input_ui_projector_controls(controls.key,controls.escape)
        if ok then ctx.input_projector_last_window=viewport_window end
    end
    if include_pointer~=false then ctx.input_mouse_inside=inside end
    return {focused=focused,mouse_inside=inside,x=x,y=y,keys=states,
            interaction_source=handle==interaction_current and handle and
                handle.name or (ctx.input_preview and inside and
                "ScenePreview" or (ctx.input_viewport and inside and
                ctx.input_viewport.name or ""))}
end
-- Sample registered mouse buttons each OBS tick even when the user's next
-- snapshot is delayed by script work. Coalesce at most one press/release per
-- button, with its original canvas coordinates; never retain input off focus.
function input_host.sample_pending(ctx)
    if not next(ctx.input_watched_mouse or {}) then return true end
    local binding=ctx.input_preview or ctx.input_viewport or ctx.input_window
    local sampler=ctx.input_mouse_sampler
    if not sampler or sampler.binding~=binding then
        sampler={_input_sampling=true,binding=binding,input_window=ctx.input_window,
            input_previous={},input_blocked={},input_mouse_physical={}}
        for name in pairs(ctx.input_watched_mouse) do
            sampler.input_previous[name]=(ctx.input_previous or {})[name]
            sampler.input_blocked[name]=(ctx.input_blocked or {})[name]
            sampler.input_mouse_physical[name]=(ctx.input_mouse_physical or {})[name]
        end
        sampler.input_focused,sampler.input_mouse_inside=ctx.input_focused,ctx.input_mouse_inside
        ctx.input_mouse_sampler=sampler;ctx.input_pending_mouse={}
    end
    sampler.input_preview,sampler.input_viewport=ctx.input_preview,ctx.input_viewport
    local names={};for name in pairs(ctx.input_watched_mouse) do names[#names+1]=name end
    local sample,err=input_poll(sampler,names,true)
    if not sample then return false,"Input Error: "..tostring(err) end
    if not sample.focused then ctx.input_pending_mouse={};return true end
    for name,state in pairs(sample.keys) do
        local pending=ctx.input_pending_mouse[name]
        if pending and pending.window~=sampler.input_active_window then pending=nil;ctx.input_pending_mouse[name]=nil end
        if state.pressed or state.released then
            pending=pending or {window=sampler.input_active_window}
            if state.pressed and not pending.pressed then pending.x,pending.y=sample.x,sample.y end
            pending.pressed=pending.pressed or state.pressed
            pending.released=pending.released or state.released
            ctx.input_pending_mouse[name]=pending
        end
    end
    return true
end
function input_host.clear_pending(ctx)
    ctx.input_watched_mouse=nil;ctx.input_pending_mouse=nil;ctx.input_mouse_sampler=nil
    ctx.input_previous=nil;ctx.input_blocked=nil;ctx.input_mouse_physical=nil
    ctx.input_focused=false;ctx.input_mouse_inside=false
end
input_projector_controls_command=function(ctx,args)
    local action=tostring(args[1]):lower()
    if host_os~="Windows" then return false,"Projector Error: Projector key controls currently require Windows OBS" end
    if action=="close" then
        if #args~=1 then return false,"Projector Error: close takes no attributes and closes only the focused Preview Projector" end
        local ok,why=input_ui_projector_controls(0,0,true)
        return ok,not ok and ("Projector Error: "..tostring(why)) or nil
    end
    local fields={}
    for i=2,#args do
        local parts,why=split_named_attribute_group(tostring(args[i]))
        if not parts then return false,"Projector Error: "..tostring(why) end
        for _,part in ipairs(parts) do
            local key,value=part:match("^%s*([%w_]+)%s*:%s*(.-)%s*$")
            if (key~="escape" and key~="exit_key") or value=="" or fields[key] then
                return false,"Projector Error: controls accepts escape:game/default and exit_key:key/none"
            end
            fields[key]=value
        end
    end
    local mode=(fields.escape or "game"):lower()
    if mode~="game" and mode~="default" then return false,"Projector Error: escape must be game or default" end
    local raw=fields.exit_key or "F11"
    if not input_name(raw) and raw:lower()~="none" then
        local value=resolve_path(ctx,raw)
        if type(value)=="string" then raw=value end
    end
    local exit_name=raw:lower()=="none" and "none" or input_name(raw)
    if not exit_name or exit_name:sub(1,6)=="MOUSE_" then return false,"Projector Error: exit_key must name a keyboard key, or none" end
    if exit_name=="ESCAPE" and mode=="game" then return false,"Projector Error: Esc cannot both stay in the game and exit the projector" end
    local code=exit_name=="none" and 0 or input_codes[exit_name]
    local ok,why=input_ui_projector_controls(code,mode=="game" and 1 or 0)
    if not ok then return false,"Projector Error: "..tostring(why) end
    ctx.input_projector_controls=(mode=="game" or code~=0) and {key=code,escape=mode=="game" and 1 or 0} or nil
    return true
end

