-- !input | key | W | down_var | optional_pressed_var | optional_released_var
-- !input | mouse | left | down_var | optional_pressed_var | optional_released_var
-- !input | pointer | x_var | y_var | inside_var
-- !input | focus | focused_var
-- !input | snapshot | table_var | W | A | UP | MOUSE_LEFT ...
-- !input | keys | table_var | W | A | UP ... (keyboard only, no pointer poll)
-- !input | preview (Windows: pointer coordinates in the main preview or Preview Projector)
-- !input | text | output_var (printable UTF-8 typed since the last read)
-- !input | wheel | output_var (positive zoom-in steps, preview only on Windows)
-- !input | recenter | optional_output_var (one focused Windows pointer warp)
local input_text_keys = {}
for code=string.byte("A"),string.byte("Z") do
    local upper=string.char(code)
    input_text_keys[#input_text_keys+1]={upper,code,upper:lower(),upper}
end
for code=string.byte("0"),string.byte("9") do
    local digit=string.char(code)
    local shifted={")","!","@","#","$","%","^","&","*","("}
    input_text_keys[#input_text_keys+1]={digit,code,digit,shifted[code-47]}
end
for digit=0,9 do
    input_text_keys[#input_text_keys+1]={"NUMPAD"..digit,0x60+digit,tostring(digit),tostring(digit)}
end
for _,key in ipairs({
    {"NUMPAD_MULTIPLY",0x6A,"*","*"},{"NUMPAD_ADD",0x6B,"+","+"},
    {"NUMPAD_SEPARATOR",0x6C,",",","},{"NUMPAD_SUBTRACT",0x6D,"-","-"},
    {"NUMPAD_DECIMAL",0x6E,".","."},{"NUMPAD_DIVIDE",0x6F,"/","/"},
    {"SPACE",0x20," "," "},{"-",0xBD,"-","_"},
    {"=",0xBB,"=","+"},{"[",0xDB,"[","{"},
    {"]",0xDD,"]","}"},{"\\",0xDC,"\\","|"},
    {";",0xBA,";",":"},{"'",0xDE,"'",'"'},
    {",",0xBC,",","<"},{".",0xBE,".",">"},
