        end
        if mode=="block" and not ctx.input_preview then
            return false,"Input Error: Use !input | preview before blocking its menu"
        end
        local ok,err=input_preview_menu_control(mode=="block")
        if not ok then
            if mode=="block" then ctx.input_preview_menu_blocked=true end
