        end
        local scene=obslua.obs_frontend_get_current_scene()
        if not scene then return false,"Input Error: No active scene" end
        local width=tonumber(obslua.obs_source_get_width(scene))
        local height=tonumber(obslua.obs_source_get_height(scene))
        obslua.obs_source_release(scene)
        if not width or not height or width<1 or height<1 then
            return false,"Input Error: Active scene has no dimensions"
        end
        ctx.input_preview={width=width,height=height}
        ctx.input_viewport=nil
        if args[2] == "focus" then
            local ok,err=input_ui_focus_preview()
            if not ok then return false,"Input Error: "..tostring(err) end
        end
        return true
    end
    if action=="viewport" then
        local name=tostring(args[2] or "")
        if name=="" then return false,"Input Error: Missing viewport source name" end
        local source=obslua.obs_get_source_by_name(name)
        if not source then return false,"Input Error: Source '"..name.."' was not found" end
        local id=obslua.obs_source_get_id(source)
        if id~=raymaze_source_info.id and id~=shader_source_info.id and
           id~=world3d_source_info.id then
            obslua.obs_source_release(source)
            return false,"Input Error: Source '"..name.."' is not a 4IM3 renderer"
        end
        local width=tonumber(obslua.obs_source_get_width(source))
        local height=tonumber(obslua.obs_source_get_height(source))
        obslua.obs_source_release(source)
        if not width or not height or width<1 or height<1 then
            return false,"Input Error: Viewport '"..name.."' has no dimensions"
        end
        ctx.input_viewport={name=name,width=width,height=height}
        ctx.input_preview=nil
        return true
    end
    if action=="text" then
        if not args[2] or tostring(args[2])=="" then
            return false,"Input Error: Expected text | output_var"
        end
        local handle=interaction_current
        local typed=""
        local text_focused=false
        if handle and handle.input_focused then
            text_focused=true
            typed=handle.input_text or ""
            handle.input_text=""
        elseif host_os=="Windows" or host_os=="Linux" then
            local sample,err=input_poll(ctx,{},false)
            if not sample then return false,"Input Error: " .. tostring(err) end
            text_focused=sample.focused
            local text_owner=ctx.input_event_owner or ctx
            local previous=text_owner.input_text_previous or {}
            local current={}
            if sample.focused then
                local shifted=input_host.key_down(input_codes.SHIFT,"SHIFT")
                local modified=input_host.key_down(input_codes.CTRL,"CTRL") or
                    input_host.key_down(input_codes.ALT,"ALT")
                local out={}
                for _,key in ipairs(input_text_keys) do
                    local down=input_host.key_down(key[2],key[1])
                    if down and not previous[key[1]] and not modified then
                        local character=shifted and key[4] or key[3]
                        if key[1]:sub(1,6)=="NUMPAD" then
                            character=input_host.keypad_text(key[1],character)
                        end
                        out[#out+1]=character
                    end
                    current[key[1]]=down
                end
                typed=table.concat(out)
            end
            text_owner.input_text_previous=current
        end
        typed=INPUT_EVENTS.stream(ctx,'text',typed or '')
        if not text_focused then typed='' end
        local written=update_variable_state(ctx,tostring(args[2]),typed)
        if type(written)=="table" and written._is_fatal_error then return false,written.msg end
        return true
    end
    if action=="wheel" then
        if not args[2] or tostring(args[2])=="" then
            return false,"Input Error: Expected wheel | output_var"
        end
        local sample,err=input_poll(ctx,{},true)
        if not sample then return false,"Input Error: " .. tostring(err) end
        local delta=0
        if host_os=="Windows" and sample.focused then
            local raw=input_host.wheel_delta(ctx.input_active_window or ctx.input_window)
            if input_wheel_attempted and not input_wheel_device and
               not input_wheel_warned then
                input_wheel_warned=true
                obslua.script_log(obslua.LOG_WARNING,
                    "[4IM3-SCRIPT] Mouse wheel input is unavailable: " ..
                    "Windows DirectInput could not open the system mouse")
            end
            if sample.mouse_inside then delta=raw end
        end
        delta=INPUT_EVENTS.stream(ctx,'wheel',delta)
        if not sample.focused or not sample.mouse_inside then delta=0 end
        local written=update_variable_state(ctx,tostring(args[2]),delta)
        if type(written)=="table" and written._is_fatal_error then return false,written.msg end
        return true
    end
    local key
    if action=="key" or action=="mouse" then
        key=tostring(args[2] or "")
        if action=="mouse" and key:sub(1,6):lower()~="mouse_" then
            key="mouse_"..key
        end
        if not input_name(key) then
            return false,"Input Error: Unknown "..action.." key '"..tostring(args[2]).."'"
        end
        if not args._result_target and (not args[3] or tostring(args[3])=="") then
            return false,"Input Error: Missing down-state variable"
        end
    elseif action=="pointer" then
        if not args._result_target and (not args[2] or not args[3] or not args[4]) then
            return false,"Input Error: Expected pointer | x_var | y_var | inside_var"
        end
    elseif action=="focus" then
        if not args[2] then return false,"Input Error: Missing focus variable" end
    elseif action=="snapshot" or action=="keys" then
        if not args[2] or tostring(args[2])=="" or not args[3] then
            return false,"Input Error: Expected "..action.." | table_var | key1 | key2 ..."
        end
        for i=3,#args do
            local name=input_name(args[i])
            if not name or (action=="keys" and name:sub(1,6)=="MOUSE_") then
                return false,"Input Error: Unknown input key '"..tostring(args[i]).."'"
            end
        end
    else
        return false,"Input Error: Expected key, mouse, pointer, recenter, focus, snapshot, keys, text, wheel, preview, preview_menu, viewport, press, release, hold, or off"
    end
    local requested=key and {key} or {}
    if action=="snapshot" or action=="keys" then
        for i=3,#args do requested[#requested+1]=args[i] end
    end
    local snapshot,err=input_poll(ctx,requested,action~="keys")
    if not snapshot then return false,"Input Error: "..tostring(err) end
    if key then
        local state=snapshot.keys[input_name(key)]
        if args._result_target then
            local written=update_variable_state(ctx,args._result_target,{down=state.down and 1 or 0,
                pressed=state.pressed and 1 or 0,released=state.released and 1 or 0})
            if type(written)=="table" and written._is_fatal_error then return false,written.msg end
            return true
        end
        update_variable_state(ctx,tostring(args[3]),state.down and 1 or 0)
        if args[4] and tostring(args[4])~="" then
            update_variable_state(ctx,tostring(args[4]),state.pressed and 1 or 0)
        end
        if args[5] and tostring(args[5])~="" then
            update_variable_state(ctx,tostring(args[5]),state.released and 1 or 0)
        end
    elseif action=="pointer" then
        if args._result_target then
            local written=update_variable_state(ctx,args._result_target,{x=snapshot.x,y=snapshot.y,
                mouse_inside=snapshot.mouse_inside and 1 or 0,focused=snapshot.focused and 1 or 0})
            if type(written)=="table" and written._is_fatal_error then return false,written.msg end
            return true
        end
        update_variable_state(ctx,tostring(args[2]),snapshot.x)
        update_variable_state(ctx,tostring(args[3]),snapshot.y)
        update_variable_state(ctx,tostring(args[4]),snapshot.mouse_inside and 1 or 0)
    elseif action=="snapshot" or action=="keys" then
        local values={focused=snapshot.focused and 1 or 0}
        if action=="snapshot" then
            values.mouse_inside=snapshot.mouse_inside and 1 or 0
            values.x,values.y=snapshot.x,snapshot.y
            values.interaction_source=snapshot.interaction_source or ""
        end
        for name,key_state in pairs(snapshot.keys) do
            values[name]=key_state.down and 1 or 0
            values[name.."_pressed"]=key_state.pressed and 1 or 0
            values[name.."_released"]=key_state.released and 1 or 0
            if name:sub(1,6)=="MOUSE_" then
                values[name.."_pressed_inside"]=key_state.pressed_x and 1 or 0
                values[name.."_pressed_x"]=key_state.pressed_x or -1
                values[name.."_pressed_y"]=key_state.pressed_y or -1
            end
        end
        local written=update_variable_state(ctx,tostring(args[2]),values)
        if type(written)=="table" and written._is_fatal_error then return false,written.msg end
    else
        local written=update_variable_state(ctx,tostring(args[2]),snapshot.focused and 1 or 0)
        if type(written)=="table" and written._is_fatal_error then return false,written.msg end
    end
    return true
end

-- Inclusive rectangle helper exposed to optional drawing modules.
engine["projector"] = projector_command
local function pixel_fill(frame, x0, y0, x1, y1, color)
    x0, y0 = math.max(0, math.floor(x0)), math.max(0, math.floor(y0))
    x1, y1 = math.min(frame.w - 1, math.floor(x1)), math.min(frame.h - 1, math.floor(y1))
    for y = y0, y1 do
        for x = x0, x1 do
            raymaze_pixel(frame, x, y, color[1], color[2], color[3])
        end
    end
end

