local function canvas_rect(frame,x,y,width,height,color)
    x,y=math.floor(x),math.floor(y)
    width,height=math.floor(width),math.floor(height)
    if width<=0 or height<=0 then return end
    local left,top=math.max(0,x),math.max(0,y)
    local right,bottom=math.min(frame.w,x+width)-1,math.min(frame.h,y+height)-1
    for py=top,bottom do
        local row=py*frame.w
        for px=left,right do frame.words[row+px]=color end
    end
end
local function canvas_number(ctx,raw,label)
    local value
    if type(raw)=="number" then
        value=raw
    elseif type(raw)=="string" then
        -- Most drawing arguments are fixed numeric literals. Resolve those
        -- without entering the full expression parser on every frame.
        local literal=tonumber(raw)
        if literal and (raw:match("^[%+%-]?[%d%.][%d%.eE%+%-]*$") or
                        raw:match("^[%+%-]?0[xX]%x+$")) then
            value=literal
        end
    end
    if value==nil then value=evaluate_math(ctx,tostring(raw or "")) end
    if is_fatal(value) then return nil,label..": "..tostring(value.msg) end
    value=tonumber(value)
    if not value or value~=value or value==math.huge or value==-math.huge then
        return nil,label.." must be a finite number"
    end
    return value
end
-- !canvas | create | renderer_name | width | height
-- !canvas | use | renderer_name (preserves its existing buffer)
-- !canvas | fill | red | green | blue | optional_opacity
-- !canvas | rectangle | x | y | width | height | red | green | blue
-- !canvas | rectangles | x_table | y_table | first | last | origin_x | origin_y |
--           stride_x | stride_y | inset_x | inset_y | width | height | R | G | B
--           [previous_x_table | previous_y_table | interpolation_0_to_1]
-- !canvas | circle | x | y | radius | red | green | blue
-- !canvas | text | "text (var)" | x | y | scale | red | green | blue
-- !canvas | text | text:"HELLO" | x:10 | y:20 | scale:2 |
--           red:255 | green:125 | blue:255 (r/g/b aliases also work)
-- Named form also permits the action anywhere and comma-grouped attributes:
-- !canvas | x:10,y:20 | text | text:'HELLO' | red:255,green:125,blue:255
-- !canvas | snapshot (remember the current pixels for fast repeated backgrounds)
-- !canvas | restore (copy those pixels back before drawing moving objects)
-- !canvas | update (makes changed pixels available on the next OBS render)
-- Legacy aliases: init, select, clear, rect, rects, present.
local canvas_action_aliases={init="create",select="use",clear="fill",
    rect="rectangle",rects="rectangles",present="update"}
local canvas_action_schemas={create="canvas_init",use="canvas_select",
    fill="canvas_clear",rectangle="canvas_rect",rectangles="canvas_rects",
    circle="canvas_circle",text="canvas_text"}
local function canvas_prepare_named_arguments(args)
    local named = false
    for _, raw in ipairs(args) do
        if tostring(raw):match("^%s*[%a_][%w_]*%s*:") then named = true; break end
    end
    if not named then return args end
    local expanded = {}
    for _, raw in ipairs(args) do
        local parts, err = split_named_attribute_group(tostring(raw))
        if not parts then return nil, err end
        for _, part in ipairs(parts) do expanded[#expanded + 1] = part end
    end
    local action_index
    for i, part in ipairs(expanded) do
        local action = canvas_action_aliases[part] or part
        if canvas_action_schemas[action] or action == "update" or
           action == "snapshot" or action == "restore" then
            if action_index then return nil, "Specify one canvas action" end
            action_index = i
        end
    end
    if not action_index then return nil, "Missing canvas action" end
    local reordered = {expanded[action_index]}
    for i, part in ipairs(expanded) do
        if i ~= action_index then reordered[#reordered + 1] = part end
    end
    return reordered
end
-- Drawing helpers inherit the nearest caller's canvas when they have not
-- explicitly selected one. Async calls must use their own task call stack.
function resolve_canvas_selection(ctx)
    local selections=ctx.canvas_selected or {}
    local selected=selections[ctx.context_id or 0]
    if selected then return selected end
    local stack=ctx.current_task and ctx.current_task.call_stack or ctx.call_stack
    for i=#(stack or {}),1,-1 do
        local frame=stack[i]
        if type(frame)=="table" and frame.ctx~=nil and selections[frame.ctx] then
            return selections[frame.ctx]
        end
    end
    return selections[0]
end

engine["canvas"] = function(ctx,state,args)
    -- Compiled commands retain their raw argument table. Reuse its normalized
    -- syntax, while evaluating coordinates/text/colors normally on every draw.
    -- Weak keys release plans when their program is discarded; compare fields
    -- so direct callers may also reuse and change an argument table safely.
    CANVAS_ARGUMENT_PLAN_CACHE=CANVAS_ARGUMENT_PLAN_CACHE or setmetatable({},{__mode="k"})
    local original=args
    local plan=CANVAS_ARGUMENT_PLAN_CACHE[original]
    local matches=plan and #plan.raw==#original
    if matches then
        for i=1,#original do if original[i]~=plan.raw[i] then matches=false;break end end
    end
    local action
    if matches then
        args=plan.args;action=plan.action
    else
        local prepared,prepare_error=canvas_prepare_named_arguments(args)
        if not prepared then return false,"Canvas Error: "..prepare_error end
        args=prepared
        action=canvas_action_aliases[tostring(args[1] or "")] or tostring(args[1] or "")
        if action=="update" or action=="snapshot" or action=="restore" then
            if #args>1 then return false,"Canvas Error: "..action.." takes no attributes" end
        else
            local normalized,named_error=normalize_graphics_arguments(args,canvas_action_schemas[action])
            if not normalized then return false,"Canvas Error: "..named_error end
            args=normalized
        end
        local raw,cacheable={},true
        for i=1,#original do
            raw[i]=original[i]
            local kind=type(original[i])
            if kind~="string" and kind~="number" and kind~="boolean" then cacheable=false end
        end
        if cacheable then
            -- A weak-key value must not retain its key through positional args.
            if args==original then
                local copy={}
                for i=1,#args do copy[i]=args[i] end
                args=copy
            end
            CANVAS_ARGUMENT_PLAN_CACHE[original]={raw=raw,args=args,action=action}
        end
    end
    local context_key=ctx.context_id or 0
    local function active_pixel_item(name)
        if state and state._ui_name==name and state._ui_item then return state._ui_item end
        local scene_source=obslua.obs_frontend_get_current_scene()
        local scene=scene_source and obslua.obs_scene_from_source(scene_source)
        local item=scene and obslua.obs_scene_find_source(scene,name)
        local source=item and obslua.obs_sceneitem_get_source(item)
        local source_id=source and obslua.obs_source_get_id(source)
        local scene_name=scene_source and obslua.obs_source_get_name(scene_source)
        if scene_source then obslua.obs_source_release(scene_source) end
        if source_id~=raymaze_source_info.id and
           source_id~=raymaze_source_info.id.."_v2" then
            return nil,"Canvas Error: Active scene '"..tostring(scene_name)..
                "' needs a direct pixel renderer named '"..name.."'. Run !renderer | ensure first"
        end
        return item
    end
    if action=="create" or action=="use" then
        local name=tostring(args[2] or "")
        if name=="" then return false,"Canvas Error: Missing renderer name" end
        local item,scene_error=active_pixel_item(name)
        if not item then return false,scene_error end
        if action=="use" then
            local selected=ctx.canvas_states and ctx.canvas_states[name]
            if not selected or raymaze_frames[name]~=selected.frame then
                return false,"Canvas Error: Create canvas '"..name.."' before using it"
            end
            ctx.canvas_state=selected
            ctx.canvas_selected=ctx.canvas_selected or {}
            ctx.canvas_selected[context_key]=selected
            obslua.obs_sceneitem_set_visible(item,true)
            return true
        end
        local width,werr=canvas_number(ctx,args[3],"width")
        local height,herr=canvas_number(ctx,args[4],"height")
        if not width or not height then return false,"Canvas Error: "..tostring(werr or herr) end
        if width<1 or width>8192 or width%1~=0 or height<1 or height>8192 or
           height%1~=0 or width*height>16777216 then
            return false,"Canvas Error: Width and height must be whole numbers from 1 to 8192 (at most 16 million pixels)"
        end
        local words=ffi.new("uint32_t[?]",width*height)
        local published=ffi.new("uint32_t[?]",width*height)
        local frame={w=width,h=height,words=words,
            pixels=ffi.cast("uint8_t*",words),published_words=published,
            published_pixels=ffi.cast("uint8_t*",published),version=0,dirty=false}
        ctx.canvas_states=ctx.canvas_states or {}
        local previous=ctx.canvas_states[name]
        local selected={name=name,frame=frame}
        ctx.canvas_states[name]=selected
        ctx.canvas_state=selected
        ctx.canvas_selected=ctx.canvas_selected or {}
        for key,canvas in pairs(ctx.canvas_selected) do
            if canvas==previous then ctx.canvas_selected[key]=selected end
        end
        ctx.canvas_selected[context_key]=selected
        raymaze_frames[name]=frame
        obslua.obs_sceneitem_set_visible(item,true)
        return true
    end
    local canvas=resolve_canvas_selection(ctx)
    if not canvas then return false,"Canvas Error: Run !canvas | create first" end
    local frame=canvas.frame
    if action=="snapshot" then
        if not frame.snapshot_words then
            frame.snapshot_words=ffi.new("uint32_t[?]",frame.w*frame.h)
        end
        ffi.copy(frame.snapshot_words,frame.words,frame.w*frame.h*4)
        return true
    elseif action=="restore" then
        if not frame.snapshot_words then
            return false,"Canvas Error: Run !canvas | snapshot before restore"
        end
        ffi.copy(frame.words,frame.snapshot_words,frame.w*frame.h*4)
        frame.dirty=true
        return true
    end
    if action=="update" then
        -- Loaded modules can write the shared pixel array directly, outside
        -- the canvas commands that set dirty.
        if frame.dirty or (ctx.loaded_modules and next(ctx.loaded_modules)) then
            -- A UI rebuild can span several script ticks. The render callback
            -- may consume a pending version after the next rebuild has begun,
            -- so it must never upload the live drawing buffer. Publish one
            -- complete CPU image before advancing the version. Lua callbacks
            -- serialize this copy with rendering; reuse the allocation.
            if not frame.published_words then
                frame.published_words=ffi.new("uint32_t[?]",frame.w*frame.h)
                frame.published_pixels=ffi.cast("uint8_t*",frame.published_words)
            end
            ffi.copy(frame.published_words,frame.words,frame.w*frame.h*4)
            frame.version=frame.version+1
            frame.dirty=false
        end
        return true
    end
    local function values(start,count)
        local result={}
        for i=start,start+count-1 do
            local value,err=canvas_number(ctx,args[i],"argument "..i)
            if not value then return nil,err end
            result[#result+1]=value
        end
        return result
    end
    local function color_at(start)
        local rgb,err=values(start,3)
        if not rgb then return nil,err end
        for i=1,3 do
            if rgb[i]<0 or rgb[i]>255 then return nil,"Color channels must be from 0 to 255" end
            rgb[i]=math.floor(rgb[i]+0.5)
        end
        return rgb[1]+rgb[2]*256+rgb[3]*65536+255*16777216
    end
    if action=="fill" then
        local color,err=color_at(2)
        if not color then return false,"Canvas Error: "..err end
        local alpha,alpha_error=canvas_number(ctx,args[5] or "255","alpha")
        if not alpha or alpha<0 or alpha>255 then
            return false,"Canvas Error: "..tostring(alpha_error or "alpha must be from 0 to 255")
        end
        color=color-255*16777216+math.floor(alpha+0.5)*16777216
        for i=0,frame.w-1 do frame.words[i]=color end
        for row=1,frame.h-1 do
            ffi.copy(frame.words+row*frame.w,frame.words,frame.w*4)
        end
        frame.dirty=true
        return true
    elseif action=="rectangle" then
        local box,err=values(2,4)
        if not box then return false,"Canvas Error: "..err end
        local color,cerr=color_at(6)
        if not color then return false,"Canvas Error: "..cerr end
        canvas_rect(frame,box[1],box[2],box[3],box[4],color)
        frame.dirty=true
        return true
    elseif action=="rectangles" then
        local xs=resolve_path(ctx,tostring(args[2] or ""))
        local ys=resolve_path(ctx,tostring(args[3] or ""))
        if type(xs)~="table" or type(ys)~="table" then
            return false,"Canvas Error: rectangles needs two coordinate tables"
        end
        local layout,err=values(4,10)
        if not layout then return false,"Canvas Error: "..err end
        local color,cerr=color_at(14)
        if not color then return false,"Canvas Error: "..cerr end
        local old_xs,old_ys,alpha
        if args[17] or args[18] or args[19] then
            old_xs=resolve_path(ctx,tostring(args[17] or ""))
            old_ys=resolve_path(ctx,tostring(args[18] or ""))
            alpha,cerr=canvas_number(ctx,args[19],"interpolation")
            if type(old_xs)~="table" or type(old_ys)~="table" or
                is_fatal(old_xs) or is_fatal(old_ys) or not alpha or alpha<0 or alpha>1 then
                return false,"Canvas Error: rects interpolation needs two tables and a value from 0 to 1"
            end
        end
        local first,last=layout[1],layout[2]
        if first%1~=0 or last%1~=0 or first<1 or last-first+1>4096 then
            return false,"Canvas Error: rects index range must be 1..4096 entries"
        end
        frame.dirty=true
        for i=first,last do
            local x,y=tonumber(xs[i]),tonumber(ys[i])
            if not x or not y or x~=x or y~=y or
                x==math.huge or y==math.huge or x==-math.huge or y==-math.huge then
                return false,"Canvas Error: rects missing numeric cell at index "..i
            end
            if old_xs then
                local old_x=tonumber(old_xs[i]) or x
                local old_y=tonumber(old_ys[i]) or y
                x=old_x+(x-old_x)*alpha
                y=old_y+(y-old_y)*alpha
            end
            canvas_rect(frame,layout[3]+x*layout[5]+layout[7],
                layout[4]+y*layout[6]+layout[8],layout[9],layout[10],color)
        end
        return true
    elseif action=="circle" then
        local circle,err=values(2,3)
        if not circle then return false,"Canvas Error: "..err end
        local color,cerr=color_at(5)
        if not color then return false,"Canvas Error: "..cerr end
        local cx,cy,r=circle[1],circle[2],circle[3]
        if r<0 or r>2048 then return false,"Canvas Error: Invalid circle radius" end
        frame.dirty=true
        local left,right=math.max(0,math.floor(cx-r)),math.min(frame.w-1,math.ceil(cx+r))
        local top,bottom=math.max(0,math.floor(cy-r)),math.min(frame.h-1,math.ceil(cy+r))
        for py=top,bottom do
            for px=left,right do
                if (px-cx)^2+(py-cy)^2<=r*r then frame.words[py*frame.w+px]=color end
            end
        end
        return true
    elseif action=="text" then
        local raw_text=tostring(args[2] or "")
        local message=resolve_path(ctx,raw_text)
        if is_fatal(message) then return false,"Canvas Error: "..tostring(message.msg) end
        local position,err=values(3,3)
        if not position then return false,"Canvas Error: "..err end
        local color,cerr=color_at(6)
        if not color then return false,"Canvas Error: "..cerr end
        local x,y,scale=position[1],position[2],position[3]
        if scale<1 or scale>8 or scale%1~=0 then
            return false,"Canvas Error: Text scale must be a whole number from 1 to 8"
        end
        local font_name=tostring(args[9] or "classic"):lower()
        if font_name~="classic" and font_name~="readable" then
            return false,"Canvas Error: Text font must be classic or readable"
        end
        local glyphs=font_name=="readable" and canvas_readable_font or canvas_font
        local glyph_width=font_name=="readable" and 5 or 3
        local glyph_height=font_name=="readable" and 7 or 5
        local glyph_advance=glyph_width+1
        frame.dirty=true
        message=tostring(message):upper()
        for i=1,#message do
            local glyph=glyphs[message:sub(i,i)] or glyphs[" "]
            for row=1,glyph_height do
                for col=1,glyph_width do
                    if glyph[row]:sub(col,col)=="1" then
                        canvas_rect(frame,x+(i-1)*glyph_advance*scale+(col-1)*scale,
                            y+(row-1)*scale,scale,scale,color)
                    end
                end
            end
        end
        return true
    end
    return false,"Canvas Error: Expected create, use, fill, rectangle, rectangles, circle, text, snapshot, restore, or update"
end

-- A self-contained binary literal for scripts. Decoding is bounded and
-- happens when a definition command runs, never during a sprite draw.
local packed_base64_alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local packed_base64_values = {}
for i = 1, #packed_base64_alphabet do
    packed_base64_values[packed_base64_alphabet:byte(i)] = i - 1
end
local function packed_literal(raw)
    if type(raw) ~= "string" then return tostring(raw or "") end
    local value = safe_trim(raw)
    local quote = value:sub(1, 1)
    if (quote == '"' or quote == "'") and value:sub(-1) == quote then
        return value:sub(2, -2)
    end
    return value
end
local function packed_bytes(raw, encoding)
    local data = packed_literal(raw)
    if #data > 262144 then return nil, "Packed data exceeds 262144 characters" end
    local out = {}
    if encoding == "hex" then
        if #data % 2 ~= 0 or data:find("[^%x]") then
            return nil, "Hex data needs pairs of hexadecimal digits"
        end
        for i = 1, #data, 2 do
            out[#out + 1] = tonumber(data:sub(i, i + 1), 16)
        end
    elseif encoding == "base64" then
        if #data % 4 ~= 0 then return nil, "Base64 length must be a multiple of four" end
        for i = 1, #data, 4 do
            local a, b, c, d = data:byte(i, i + 3)
            local av, bv = packed_base64_values[a], packed_base64_values[b]
            local cv, dv = packed_base64_values[c], packed_base64_values[d]
            local last = i + 3 == #data
            if not av or not bv or (c == 61 and (d ~= 61 or not last)) or
               (d == 61 and not last) or (c ~= 61 and not cv) or
               (d ~= 61 and not dv) then
                return nil, "Invalid base64 character or padding"
            end
            local value = av * 262144 + bv * 4096 + (cv or 0) * 64 + (dv or 0)
            out[#out + 1] = math.floor(value / 65536) % 256
            if c ~= 61 then out[#out + 1] = math.floor(value / 256) % 256 end
            if d ~= 61 then out[#out + 1] = value % 256 end
        end
    else
        return nil, "Encoding must be base64 or hex"
    end
    if #out > 65536 then return nil, "Packed data exceeds 65536 bytes" end
    return out
end
local function packed_fields(args, action, names)
    if tostring(args[1] or "") ~= action then
        return nil, "Expected " .. action .. " action"
    end
    local named = tostring(args[2] or ""):match("^%s*[%a_][%w_]*%s*:") ~= nil
    local values = {}
    if named then
        local allowed = {}
        for _, field in ipairs(names) do allowed[field] = true end
        for i = 2, #args do
            local parts, err = split_named_attribute_group(tostring(args[i]))
            if not parts then return nil, err end
            for _, part in ipairs(parts) do
                local key, value = part:match("^%s*([%a_][%w_]*)%s*:%s*(.-)%s*$")
                if not key then return nil, "Named and positional fields cannot be mixed" end
                key = key:lower()
                if not allowed[key] then return nil, "Unknown attribute '" .. key .. "'" end
                if values[key] ~= nil then return nil, "Duplicate attribute '" .. key .. "'" end
                if value == "" then return nil, "Attribute '" .. key .. "' needs a value" end
                values[key] = value
            end
        end
    else
        if #args > #names + 1 then return nil, "Too many arguments" end
        for i, field in ipairs(names) do values[field] = args[i + 1] end
    end
    return values
end

-- !array | unpack | name:coords | type:u16 | encoding:base64 | count:2 | data:"AQACAA=="
-- u16 uses little-endian byte order. Hex is also accepted. This creates a
-- normal 1-based engine table; later commands can copy or modify it.
engine["array"] = function(ctx, state, args)
    local fields, err = packed_fields(args, "unpack",
        {"name", "type", "encoding", "data", "count"})
    if not fields then return false, "Array Error: " .. err end
    local name = packed_literal(fields.name)
    local kind = packed_literal(fields.type)
    local encoding = packed_literal(fields.encoding)
    if name == "" or (kind ~= "u8" and kind ~= "u16") then
        return false, "Array Error: name and type:u8 or type:u16 are required"
    end
    local bytes, decode_error = packed_bytes(fields.data, encoding)
    if not bytes then return false, "Array Error: " .. decode_error end
    if kind == "u16" and #bytes % 2 ~= 0 then
        return false, "Array Error: u16 data needs an even byte count"
    end
    local count = kind == "u8" and #bytes or #bytes / 2
    if fields.count ~= nil and tonumber(packed_literal(fields.count)) ~= count then
        return false, "Array Error: count does not match decoded data"
    end
    local values = {}
    if kind == "u8" then
        for i = 1, #bytes do values[i] = bytes[i] end
    else
        for i = 1, #bytes, 2 do
            values[(i + 1) / 2] = bytes[i] + 256 * bytes[i + 1]
        end
    end
    local written = update_variable_state(ctx, name, values, "table")
    if is_fatal(written) then return false, "Array Error: " .. written.msg end
    return true
end
engine["array.unpack"] = function(ctx, state, args)
    local forwarded = {"unpack"}
    for i = 1, #args do forwarded[#forwarded + 1] = args[i] end
    return engine["array"](ctx, state, forwarded)
end

-- !sprite | create | name:hero | width:16 | height:16 |
--           palette:"transparent,#FFFF00,#FFFFFF" | pixels:"...base64..."
-- !sprite | draw | name:hero | x:draw_x-8 | y:draw_y-8
-- Pixel bytes index the palette from zero. A transparent entry leaves the
-- selected canvas unchanged. Definitions are scoped to the current script.
local function draw_packed_sprite(frame, sprite, x, y, pixel_offset)
    local at = (pixel_offset or 0) + 1
    for row = 0, sprite.h - 1 do
        local py = y + row
        for col = 0, sprite.w - 1 do
            local px = x + col
            local color = sprite.palette[sprite.pixels[at] + 1]
            if color and px >= 0 and py >= 0 and px < frame.w and py < frame.h then
                frame.words[py * frame.w + px] = color
            end
            at = at + 1
        end
    end
    frame.dirty = true
end

local function packed_palette(raw)
    if raw == nil then return nil, "palette is required" end
    local palette_text = packed_literal(raw)
    local palette = {}
    for entry in (palette_text .. ","):gmatch("(.-),") do
        entry = safe_trim(entry)
        if entry == "transparent" then
            palette[#palette + 1] = false
        else
            local hex = entry:match("^#(%x%x%x%x%x%x)$")
            if not hex then return nil, "palette needs transparent or #RRGGBB entries" end
            local r, g, b = tonumber(hex:sub(1, 2), 16),
                tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16)
            palette[#palette + 1] = r + g * 256 + b * 65536 + 255 * 16777216
        end
    end
    if #palette < 1 or #palette > 256 then
        return nil, "palette needs 1 to 256 colors"
    end
    return palette
end

engine["sprite"] = function(ctx, state, args)
    local action = tostring(args[1] or "")
    if action == "create" then
        local fields, err = packed_fields(args, action,
            {"name", "width", "height", "palette", "pixels"})
        if not fields then return false, "Sprite Error: " .. err end
        local name = packed_literal(fields.name)
        local width, height = tonumber(packed_literal(fields.width)),
                              tonumber(packed_literal(fields.height))
        if not name:match("^[%w_%-]+$") or #name > 80 or
           not width or not height or width % 1 ~= 0 or height % 1 ~= 0 or
           width < 1 or height < 1 or width * height > 65536 then
            return false, "Sprite Error: name and positive whole dimensions up to 65536 pixels are required"
        end
        local palette, palette_error = packed_palette(fields.palette)
        if not palette then return false, "Sprite Error: " .. palette_error end
        local pixels, decode_error = packed_bytes(fields.pixels, "base64")
        if not pixels then return false, "Sprite Error: " .. decode_error end
        if #pixels ~= width * height then
            return false, "Sprite Error: pixel count does not match dimensions"
        end
        for i = 1, #pixels do
            if pixels[i] >= #palette then
                return false, "Sprite Error: pixel " .. i .. " exceeds palette size"
            end
        end
        ctx.sprite_states = ctx.sprite_states or {}
        ctx.sprite_states[name] = {w = width, h = height,
                                   palette = palette, pixels = pixels}
        return true
    elseif action == "draw" then
        local fields, err = packed_fields(args, action, {"name", "x", "y"})
        if not fields then return false, "Sprite Error: " .. err end
        local name = packed_literal(fields.name)
        local sprite = ctx.sprite_states and ctx.sprite_states[name]
        if not sprite then return false, "Sprite Error: Undefined sprite '" .. name .. "'" end
        local selected = resolve_canvas_selection(ctx)
        if not selected then return false, "Sprite Error: Run !canvas | create first" end
        local x, xerr = canvas_number(ctx, fields.x, "x")
        local y, yerr = canvas_number(ctx, fields.y, "y")
        if not x or not y then return false, "Sprite Error: " .. tostring(xerr or yerr) end
        x, y = math.floor(x), math.floor(y)
        local frame = selected.frame
        draw_packed_sprite(frame, sprite, x, y)
        return true
    end
    return false, "Sprite Error: Expected create or draw"
end

-- A timed sequence of existing sprites, or packed frames sharing one palette.
-- Time is supplied by the script so replay, pause, and seek are deterministic.
engine["animation"] = function(ctx, state, args)
    if args._input_handler or INPUT_EVENTS and INPUT_EVENTS.is_handler('animation',args) then
        return INPUT_EVENTS.register(ctx,args,'animation')
    end
    local action = tostring(args[1] or "")
    if action == "create" then
        local fields, err = packed_fields(args, action,
            {"name", "frames", "width", "height", "count", "palette", "pixels", "duration", "loop"})
        if not fields then return false, "Animation Error: " .. err end
        local name = packed_literal(fields.name)
        if not name:match("^[%w_%-]+$") or #name > 80 then
            return false, "Animation Error: name must contain only letters, numbers, _ or -"
        end
        local duration, duration_error = canvas_number(ctx, fields.duration, "duration")
        if not duration or duration <= 0 or duration > 3600 then
            return false, "Animation Error: " .. tostring(duration_error or
                "duration must be greater than 0 and at most 3600 seconds")
        end
        local loop_text = fields.loop and packed_literal(fields.loop):lower() or "false"
        if loop_text ~= "true" and loop_text ~= "false" then
            return false, "Animation Error: loop must be true or false"
        end
        local animation = {duration = duration, loop = loop_text == "true"}
        if fields.frames ~= nil then
            if fields.pixels or fields.palette or fields.width or fields.height then
                return false, "Animation Error: frames cannot be mixed with packed pixel fields"
            end
            local frame_text = packed_literal(fields.frames)
            if not frame_text:match("^%b[]$") then
                return false, "Animation Error: frames needs [sprite_one, sprite_two, ...]"
            end
            local names, names_error = split_named_attribute_group(frame_text:sub(2, -2))
            if not names then return false, "Animation Error: " .. names_error end
            if #names < 1 or #names > 256 then
                return false, "Animation Error: frames needs 1 to 256 sprites"
            end
            for i, frame_name in ipairs(names) do
                frame_name = packed_literal(frame_name)
                if not ctx.sprite_states or not ctx.sprite_states[frame_name] then
                    return false, "Animation Error: Undefined sprite '" .. frame_name .. "' at frame " .. i
                end
                names[i] = frame_name
            end
            if fields.count and tonumber(packed_literal(fields.count)) ~= #names then
                return false, "Animation Error: count does not match frames"
            end
            animation.kind, animation.frames, animation.count = "references", names, #names
        else
            local width, height = tonumber(packed_literal(fields.width)),
                tonumber(packed_literal(fields.height))
            local count = tonumber(packed_literal(fields.count))
            if not width or not height or not count or width % 1 ~= 0 or
                height % 1 ~= 0 or count % 1 ~= 0 or width < 1 or height < 1 or
                count < 1 or count > 256 or width * height * count > 65536 then
                return false, "Animation Error: positive whole width, height, and count are required (up to 65536 pixels total)"
            end
            local palette, palette_error = packed_palette(fields.palette)
            if not palette then return false, "Animation Error: " .. palette_error end
            local pixels, decode_error = packed_bytes(fields.pixels, "base64")
            if not pixels then return false, "Animation Error: " .. decode_error end
            if #pixels ~= width * height * count then
                return false, "Animation Error: pixel count does not match width * height * count"
            end
            for i = 1, #pixels do
                if pixels[i] >= #palette then
                    return false, "Animation Error: pixel " .. i .. " exceeds palette size"
                end
            end
            animation.kind, animation.count = "packed", count
            animation.sprite = {w = width, h = height, palette = palette, pixels = pixels}
        end
        ctx.animation_states = ctx.animation_states or {}
        ctx.animation_states[name] = animation
        return true
    elseif action == "draw" then
        local fields, err = packed_fields(args, action, {"name", "time", "x", "y"})
        if not fields then return false, "Animation Error: " .. err end
        local name = packed_literal(fields.name)
        local animation = ctx.animation_states and ctx.animation_states[name]
        if not animation then return false, "Animation Error: Undefined animation '" .. name .. "'" end
        local selected = resolve_canvas_selection(ctx)
        if not selected then return false, "Animation Error: Run !canvas | create first" end
        local time, time_error = canvas_number(ctx, fields.time, "time")
        local x, x_error = canvas_number(ctx, fields.x, "x")
        local y, y_error = canvas_number(ctx, fields.y, "y")
        if not time or not x or not y then
            return false, "Animation Error: " .. tostring(time_error or x_error or y_error)
        end
        time = math.max(0, time)
        if not animation.loop and time>=animation.duration and (not animation.last_time or animation.last_time<animation.duration) then
            animation.completion_serial=(animation.completion_serial or 0)+1
        end
        animation.last_time=time
        if animation.loop then time = time % animation.duration end
        local frame_index = math.min(animation.count,
            math.floor(time / animation.duration * animation.count) + 1)
        local sprite, offset
        if animation.kind == "references" then
            local frame_name = animation.frames[frame_index]
            sprite = ctx.sprite_states and ctx.sprite_states[frame_name]
            if not sprite then
                return false, "Animation Error: Missing sprite '" .. frame_name .. "' at draw time"
            end
        else
            sprite = animation.sprite
            offset = (frame_index - 1) * sprite.w * sprite.h
        end
        draw_packed_sprite(selected.frame, sprite, math.floor(x), math.floor(y), offset)
        return true
    end
    return false, "Animation Error: Expected create or draw"
end

-- Retained, program-owned controls. A UI owns a separate transparent pixel
-- canvas, so redrawing controls never clears a game's canvas or 3D scene.
ENGINE_UI={keys={'MOUSE_LEFT','TAB','ENTER','SPACE','LEFT','RIGHT','HOME','END','DELETE','BACKSPACE','SHIFT','CTRL','A','C','V','X'},
    kinds={panel=true,label=true,button=true,input=true,checkbox=true,slider=true,tabs=true},
    events={click=true,press=true,release=true,mouse_enter=true,mouse_leave=true,change=true,submit=true,focus=true,blur=true},
    defaults={background='#172334',hover_color='#294259',pressed_color='#375874',
        text_color='#EDF4FF',accent='#55C8E8',disabled_color='#566174',border_color='#34485F',
        border_width=1,radius=6,scale=2,padding=10},
    numbers={x=true,y=true,width=true,height=true,scale=true,font_size=true,padding=true,radius=true,border_width=true,min=true,max=true,step=true,max_length=true,tab=true},
    booleans={visible=true,enabled=true,checked=true,password=true},
    colors={background=true,hover_color=true,pressed_color=true,text_color=true,accent=true,disabled_color=true,border_color=true},
    strings={text=true,placeholder=true,value=true},
    words={name=true,parent=true,bind=true,font=true,style=true,tabs=true},
    aliases={color='text_color',background_color='background',hover='hover_color',pressed='pressed_color',
        border_radius='radius',font_family='font',font_scale='scale'}}
function ENGINE_UI.attributes(ctx,args,first,allowed)
    local result,expanded={},{}
    for i=first,#args do
