        ENGINE_UI.restyle(ui)
        if w.kind=='input' or w.kind=='slider' or w.kind=='checkbox' or w.kind=='tabs' then
            local value=fields.value
            if w.kind=='checkbox' then value=fields.checked;if value==nil then value=w.checked end
            elseif value==nil then value=w.value end
            local ok,err=ENGINE_UI.write(ctx,w,value,false);if not ok then return fail(err) end
            w.caret=#ENGINE_UI.characters(tostring(w.value));w.anchor=w.caret
        end
        w.surface.dirty=true;ENGINE_UI.layout(ctx)
        if ui.focus and (not ui.focus.active or not ui.focus.shown) then ENGINE_UI.focus(ctx,nil) end
        if ui.capture and (not ui.capture.active or not ui.capture.shown) then ui.capture=nil end
        return true
    end
    return fail('Unknown action '..action)
end

local function release_canvas_buffers(ctx)
    if ENGINE_UI then ENGINE_UI.clear(ctx) end
    if ctx.canvas_states then
        for name, canvas in pairs(ctx.canvas_states) do
            if raymaze_frames[name] == canvas.frame then raymaze_frames[name] = nil end
        end
    end
    ctx.canvas_states = nil
    ctx.canvas_selected = nil
    ctx.canvas_state = nil
end

-- Generic TCP messages. Only system socket APIs are used; all I/O is
-- nonblocking and runs under a separate slice of the script tick budget.
local TCP = {}
-- Local interface enumeration is independent of socket/TLS initialization.
-- Only OS-owned addresses are read; no DNS request, external service or socket.
TCP.LAN = {}
function TCP.LAN.declare(os_name)
    if os_name=="Windows" then
        if TCP.LAN.win_declared then return end
        ffi.cdef([[
            typedef struct { void *address; int length; } im3_lan_socket_address;
            typedef struct im3_lan_unicast {
                union { uint64_t alignment; struct { uint32_t Length, Flags; }; };
                struct im3_lan_unicast *Next;
                im3_lan_socket_address Address;
                int PrefixOrigin, SuffixOrigin, DadState;
                uint32_t ValidLifetime, PreferredLifetime, LeaseLifetime;
                uint8_t OnLinkPrefixLength;
            } im3_lan_unicast;
            typedef struct im3_lan_adapter {
                union { uint64_t alignment; struct { uint32_t Length, IfIndex; }; };
                struct im3_lan_adapter *Next;
                char *AdapterName;
                im3_lan_unicast *FirstUnicastAddress;
                void *FirstAnycastAddress, *FirstMulticastAddress, *FirstDnsServerAddress;
                uint16_t *DnsSuffix, *Description, *FriendlyName;
                uint8_t PhysicalAddress[8];
                uint32_t PhysicalAddressLength, Flags, Mtu, IfType;
                int OperStatus;
                uint32_t Ipv6IfIndex, ZoneIndices[16];
                void *FirstPrefix;
                uint64_t TransmitLinkSpeed, ReceiveLinkSpeed;
                void *FirstWinsServerAddress, *FirstGatewayAddress;
                uint32_t Ipv4Metric;
            } im3_lan_adapter;
            uint32_t __stdcall im3_lan_adapters(uint32_t,uint32_t,void*,
                im3_lan_adapter*,uint32_t*) __asm__("GetAdaptersAddresses");
            int __stdcall im3_lan_utf8(unsigned int,uint32_t,const uint16_t*,int,
                char*,int,const char*,int*) __asm__("WideCharToMultiByte");
        ]])
        TCP.LAN.win_declared=true
    else
        if TCP.LAN.posix_declared then return end
        ffi.cdef([[
            typedef struct im3_lan_ifaddrs {
                struct im3_lan_ifaddrs *ifa_next;
                char *ifa_name;
                unsigned int ifa_flags;
                uint8_t *ifa_addr, *ifa_netmask, *ifa_broadaddr;
                void *ifa_data;
            } im3_lan_ifaddrs;
            int im3_lan_getifaddrs(im3_lan_ifaddrs**) __asm__("getifaddrs");
            void im3_lan_freeifaddrs(im3_lan_ifaddrs*) __asm__("freeifaddrs");
        ]])
        TCP.LAN.posix_declared=true
    end
end
function TCP.LAN.wide(pointer)
    if pointer==nil then return "" end
    local kernel=TCP.LAN.kernel or ffi.load("kernel32")
    TCP.LAN.kernel=kernel
    local length=kernel.im3_lan_utf8(65001,0,pointer,-1,nil,0,nil,nil)
    if length<=1 then return "" end
    local out=ffi.new("char[?]",length)
    if kernel.im3_lan_utf8(65001,0,pointer,-1,out,length,nil,nil)~=length then return "" end
    return ffi.string(out,length-1)
end
function TCP.LAN.windows_rows(library)
    local size=ffi.new("uint32_t[1]",15000)
    local buffer,rc
    for _=1,3 do
        buffer=ffi.new("uint8_t[?]",tonumber(size[0]))
        -- IPv4; skip anycast/multicast/DNS, include gateways for ranking.
        rc=tonumber(library.im3_lan_adapters(2,0x8e,nil,ffi.cast("im3_lan_adapter*",buffer),size))
        if rc~=111 then break end -- ERROR_BUFFER_OVERFLOW: adapters changed.
    end
    if rc==232 then return {} end -- ERROR_NO_DATA
    assert(rc==0,"GetAdaptersAddresses failed ("..tostring(rc)..")")
    local rows={}
    local adapter=ffi.cast("im3_lan_adapter*",buffer)
    while adapter~=nil do
        if tonumber(adapter.Length)>=ffi.offsetof("im3_lan_adapter","OperStatus")+4 and
           adapter.OperStatus==1 and adapter.IfType~=24 then -- Up, not loopback.
            local name=TCP.LAN.wide(adapter.FriendlyName)
            if name=="" and adapter.AdapterName~=nil then name=ffi.string(adapter.AdapterName) end
            local description=TCP.LAN.wide(adapter.Description)
            local metric,gateway=0,false
            if tonumber(adapter.Length)>=ffi.offsetof("im3_lan_adapter","Ipv4Metric")+4 then
                metric=tonumber(adapter.Ipv4Metric)
                gateway=adapter.FirstGatewayAddress~=nil
            end
            local unicast=adapter.FirstUnicastAddress
            while unicast~=nil do
                local ptr=unicast.Address.address
                if tonumber(unicast.Length)>=ffi.offsetof("im3_lan_unicast","DadState")+4 and
                   (unicast.DadState==3 or unicast.DadState==4) and ptr~=nil and
                   unicast.Address.length>=16 and ffi.cast("uint16_t*",ptr)[0]==2 then
                    local bytes=ffi.cast("uint8_t*",ptr)
                    rows[#rows+1]={address=string.format("%d.%d.%d.%d",bytes[4],bytes[5],bytes[6],bytes[7]),
                        name=name,description=description,metric=metric,gateway=gateway,
                        kind=adapter.IfType==6 and "ethernet" or adapter.IfType==71 and "wifi" or "other"}
                end
                unicast=unicast.Next
            end
        end
        adapter=adapter.Next
    end
    -- A derived FFI pointer does not own its array. Keep the backing allocation
    -- live through the entire walk, including allocations for Lua result rows.
    assert(ffi.sizeof(buffer)>=tonumber(size[0]),"Adapter result exceeded its buffer")
    return rows
end
function TCP.LAN.posix_rows(library,os_name)
    local head=ffi.new("im3_lan_ifaddrs*[1]")
    assert(library.im3_lan_getifaddrs(head)==0,"getifaddrs failed ("..tostring(ffi.errno())..")")
    local ok,rows=pcall(function()
        local result,node={},head[0]
        while node~=nil do
            local flags=tonumber(node.ifa_flags)
            local address=node.ifa_addr
            -- Both platforms use IFF_UP=1, IFF_LOOPBACK=8, IFF_RUNNING=64.
            if bit.band(flags,1)~=0 and bit.band(flags,64)~=0 and bit.band(flags,8)==0 and
               address~=nil and (os_name=="OSX" and tonumber(address[1]) or
                   tonumber(ffi.cast("uint16_t*",address)[0]))==2 then
                local name=node.ifa_name~=nil and ffi.string(node.ifa_name) or ""
                result[#result+1]={address=string.format("%d.%d.%d.%d",address[4],address[5],address[6],address[7]),
                    name=name,kind=os_name=="Linux" and name:match("^wl") and "wifi" or
                        os_name=="Linux" and name:match("^e[nth]") and "ethernet" or "other"}
            end
            node=node.ifa_next
        end
        return result
    end)
    if head[0]~=nil then library.im3_lan_freeifaddrs(head[0]) end
    if not ok then error(rows) end
    return rows
end
function TCP.LAN.select(rows)
    local candidates={}
    for _,row in ipairs(rows) do
        local a,b,c,d=tostring(row.address):match("^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
        a,b,c,d=tonumber(a),tonumber(b),tonumber(c),tonumber(d)
        if a and b and c and d and a>0 and a<224 and a~=127 and b<=255 and c<=255 and d<=255 then
            local label=((row.name or "").." "..(row.description or "")):lower()
            local virtual=false
            for _,term in ipairs({"virtual","vmware","vbox","hyper-v","vethernet","tunnel",
                    "tap","tun","vpn","wireguard","tailscale","zerotier","docker","veth","br-"}) do
                if label:find(term,1,true) then virtual=true;break end
            end
            local private=a==10 or a==172 and b>=16 and b<=31 or a==192 and b==168
            local link_local=a==169 and b==254
            local kind=virtual and "virtual" or row.kind or "other"
            local score=(link_local and 1000 or 0)+(virtual and 100 or 0)+
                ((kind=="wifi" or kind=="ethernet") and 0 or 10)+(private and 0 or 20)+(row.gateway and 0 or 1)
            candidates[#candidates+1]={address=string.format("%d.%d.%d.%d",a,b,c,d),
                name=row.name or "",kind=kind,private=private and 1 or 0,link_local=link_local and 1 or 0,
                metric=row.metric or 0,score=score,order=((a*256+b)*256+c)*256+d}
        end
    end
    table.sort(candidates,function(a,b)
        if a.score~=b.score then return a.score<b.score end
        if a.metric~=b.metric then return a.metric<b.metric end
        if a.name~=b.name then return a.name<b.name end
        return a.order<b.order
    end)
    local seen,result={},{}
    for _,item in ipairs(candidates) do
        if not seen[item.address] then
            seen[item.address]=true;item.score=nil;item.order=nil
            item.recommended=#result==0 and 1 or 0
            result[#result+1]=item
        end
    end
    return {ok=#result>0 and 1 or 0,address=result[1] and result[1].address or "",candidates=result,count=#result,
        error=#result>0 and "" or "No active non-loopback IPv4 address was found"}
end
function TCP.LAN.addresses()
    local ok,result=pcall(function()
        assert(host_os=="Windows" or host_os=="Linux" or host_os=="OSX","LAN detection is unavailable on "..tostring(host_os))
        TCP.LAN.declare(host_os)
        if host_os=="Windows" then
            TCP.LAN.library=TCP.LAN.library or ffi.load("iphlpapi")
            return TCP.LAN.select(TCP.LAN.windows_rows(TCP.LAN.library))
        end
        return TCP.LAN.select(TCP.LAN.posix_rows(ffi.C,host_os))
    end)
    return ok and result or {ok=0,address="",candidates={},count=0,error="LAN detection failed: "..tostring(result)}
end
function TCP.connection_code(invitation,address,port,transport)
    if address=="localhost" then address="127.0.0.1" end
    local a,b,c,d=tostring(address):match("^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
    a,b,c,d=tonumber(a),tonumber(b),tonumber(c),tonumber(d)
    assert(a and b and c and d and a>0 and a<224 and b<=255 and c<=255 and d<=255,
        "A usable IPv4 address is required for a connection code")
    assert(type(port)=="number" and port%1==0 and port>=1 and port<=65535,"Invalid connection code port")
    local pin,secret=tostring(invitation):match("^IM3TLS1%.(%x+)%.(%x+)$")
    assert(pin and #pin==64 and #secret==64,"A valid host invitation is required")
    return string.format("%s-%02x%02x%02x%02x-%d-%s-%s",transport=="websocket" and "IM3WSS1" or "IM3JOIN1",a,b,c,d,port,pin,secret)
end
function TCP.decode_code(code)
    if type(code)~="string" or #code>153 then return nil,"Invalid private connection code" end
    local prefix,address,port,pin,secret=code:match("^(%w+)%-(%x+)%-(%d+)%-(%x+)%-(%x+)$")
    if prefix~="IM3JOIN1" and prefix~="IM3WSS1" then return nil,"Paste the complete private connection code from the host" end
    if not address or #address~=8 or #port>5 or #pin~=64 or #secret~=64 then
        return nil,"Paste the complete private connection code from the host"
    end
    local a,b,c,d=tonumber(address:sub(1,2),16),tonumber(address:sub(3,4),16),
        tonumber(address:sub(5,6),16),tonumber(address:sub(7,8),16)
    port=tonumber(port)
    if a==0 or a>=224 or port<1 or port>65535 then return nil,"Invalid connection code address or port" end
    return {address=string.format("%d.%d.%d.%d",a,b,c,d),port=port,invite="IM3TLS1."..pin.."."..secret,
        transport=prefix=="IM3WSS1" and "websocket" or "tcp"}
end

-- TLS is implemented by the host's established TLS stack, never Lua crypto.
-- Windows uses Schannel, an in-memory certificate, and a temporary CNG key
-- deleted on close. POSIX uses an already installed OpenSSL. Certificates are pinned by an out-of-band invitation;
-- the random invitation token is sent only AFTER the certificate is verified.
TCP.TLS = {}
function TCP.TLS.hex(raw)
    return (raw:gsub(".",function(c) return string.format("%02x",c:byte()) end))
end
function TCP.TLS.unhex(raw)
    return (raw:gsub("..",function(c) return string.char(tonumber(c,16)) end))
end
function TCP.TLS.equal(a,b)
    if type(a)~="string" or type(b)~="string" or #a~=#b then return false end
    local difference=0
    for i=1,#a do difference=bit.bor(difference,bit.bxor(a:byte(i),b:byte(i))) end
    return difference==0
end
function TCP.TLS.setup()
