                typedef struct { uint32_t size,type; void *data; } im3_tls_buffer;
                typedef struct { uint32_t version,count; im3_tls_buffer *buffers; } im3_tls_desc;
                typedef struct { uint32_t header,trailer,maximum,count,block; } im3_tls_sizes;
                typedef struct { uint32_t size; uint8_t *data; } im3_tls_blob;
                typedef struct { char *oid; im3_tls_blob parameters; } im3_tls_algorithm;
                typedef struct { uint16_t *container,*provider; uint32_t provider_type,flags,param_count; void *params; uint32_t key_spec; } im3_tls_key_info;
                typedef struct { uint32_t encoding; uint8_t *encoded; uint32_t length; void *info,*store; } im3_tls_cert;
                typedef struct {
