                int __stdcall CryptHashCertificate2(const uint16_t*,uint32_t,void*,const uint8_t*,uint32_t,uint8_t*,uint32_t*);
                int32_t __stdcall BCryptGenRandom(void*,uint8_t*,uint32_t,uint32_t);
                int32_t __stdcall NCryptOpenStorageProvider(uintptr_t*,const uint16_t*,uint32_t);
                int32_t __stdcall NCryptCreatePersistedKey(uintptr_t,uintptr_t*,const uint16_t*,const uint16_t*,uint32_t,uint32_t);
