                void *SSL_get_peer_certificate(void*); void *SSL_get1_peer_certificate(void*);
                void *EVP_PKEY_new(void); void EVP_PKEY_free(void*); int EVP_PKEY_assign(void*,int,void*);
                void *EC_KEY_new_by_curve_name(int); int EC_KEY_generate_key(void*); void EC_KEY_free(void*);
                void *X509_new(void); void X509_free(void*); int X509_set_version(void*,long);
                void *X509_get_serialNumber(void*); int ASN1_INTEGER_set(void*,long);
                void *X509_getm_notBefore(void*); void *X509_getm_notAfter(void*); void *X509_gmtime_adj(void*,long);
                int X509_set_pubkey(void*,void*); void *X509_get_subject_name(void*);
                int X509_NAME_add_entry_by_txt(void*,const char*,int,const unsigned char*,int,int,int);
                int X509_set_issuer_name(void*,const void*); int X509_sign(void*,void*,const void*);
                const void *EVP_sha256(void); int X509_digest(const void*,const void*,unsigned char*,unsigned int*);
                int RAND_bytes(unsigned char*,int); void ERR_clear_error(void);
