            im3_net_socket %sim3_net_socket_open(int,int,int) __asm__("socket");
            int %sim3_net_bind(im3_net_socket,const void*,im3_net_socklen) __asm__("bind");
            int %sim3_net_listen(im3_net_socket,int) __asm__("listen");
            im3_net_socket %sim3_net_accept(im3_net_socket,void*,im3_net_socklen*) __asm__("accept");
            int %sim3_net_connect(im3_net_socket,const void*,im3_net_socklen) __asm__("connect");
            int %sim3_net_getname(im3_net_socket,void*,im3_net_socklen*) __asm__("getsockname");
            int %sim3_net_getopt(im3_net_socket,int,int,void*,im3_net_socklen*) __asm__("getsockopt");
            int %sim3_net_setopt(im3_net_socket,int,int,const void*,im3_net_socklen) __asm__("setsockopt");
        ]], cc,cc,cc,cc,cc,cc,cc,cc) .. (win and [[
            int __stdcall im3_net_startup(uint16_t,void*) __asm__("WSAStartup");
            int __stdcall im3_net_cleanup(void) __asm__("WSACleanup");
            int __stdcall im3_net_error(void) __asm__("WSAGetLastError");
            int __stdcall im3_net_close(im3_net_socket) __asm__("closesocket");
            int __stdcall im3_net_ioctl(im3_net_socket,int32_t,unsigned long*) __asm__("ioctlsocket");
            int __stdcall im3_net_poll(im3_net_pollfd*,unsigned long,int) __asm__("WSAPoll");
            int __stdcall im3_net_recv(im3_net_socket,void*,int,int) __asm__("recv");
            int __stdcall im3_net_send(im3_net_socket,const void*,int,int) __asm__("send");
