function TCP.error_code()
    return TCP.backend.win and tonumber(TCP.backend.lib.im3_net_error()) or ffi.errno()
end

function TCP.error_text(operation, code)
    local known = {[10048]="address already in use",[98]="address already in use",[48]="address already in use",
        [10061]="connection refused",[111]="connection refused",[61]="connection refused",
        [10054]="connection reset",[104]="connection reset",[54]="connection reset",
        [10060]="connection timed out",[110]="connection timed out",[60]="connection timed out"}
    return operation .. " failed: " .. (known[code] or "socket error") .. " (" .. tostring(code) .. ")"
