function TCP.address(text, port)
    if text == "localhost" then text = "127.0.0.1" end
    local a,b,c,d = tostring(text):match("^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
    local octets = {tonumber(a),tonumber(b),tonumber(c),tonumber(d)}
    if #octets ~= 4 then return nil, "address must be an IPv4 address or localhost" end
    for _,n in ipairs(octets) do if n > 255 then return nil, "invalid IPv4 address" end end
    local addr = ffi.new("uint8_t[16]")
    if TCP.backend.mac then addr[0],addr[1] = 16,2
    else ffi.cast("uint16_t*",addr)[0] = 2 end
    addr[2],addr[3] = math.floor(port/256),port%256
    for i=1,4 do addr[i+3] = octets[i] end
    return addr
end

function TCP.address_text(addr)
