                    ep.rate_addresses[ep.rate_address_order[ep.rate_address_cursor]]=nil
                    ep.rate_address_order[ep.rate_address_cursor]=address
                else ep.rate_address_order[#ep.rate_address_order+1]=address end
                bucket={};ep.rate_addresses[address]=bucket
            end
            local pending=0;for _,p in pairs(ep.peers) do if not p.ready then pending=pending+1 end end
            local allowed=(ep.max_peers==0 or #ep.peer_order<ep.max_peers) and
                (not ep.secure or ep.max_pending==0 or pending<ep.max_pending) and
                TCP.allow(ep.accept_bucket,ep.connection_rate,1,math.max(8,ep.connection_rate)) and
                TCP.allow(bucket,ep.address_rate,1,math.max(8,ep.address_rate*2))
            if not allowed then b.lib.im3_net_close(fd);ep.rejected=ep.rejected+1
            else
                local ok,err=TCP.socket_ready(fd)
                if ok then
                    local added,why=pcall(TCP.add_peer,ep,fd,addr,false)
                    if not added then
                        local last=ep.peers[ep.next_peer-1]
                        if last and last.fd==fd then TCP.drop(ep,last,"TLS peer setup failed")
                        else b.lib.im3_net_close(fd) end
                    end
                else b.lib.im3_net_close(fd);ep.rejected=ep.rejected+1 end
            end
        else
            local code=TCP.error_code()
            if code~=b.again and code~=4 and code~=10004 then
                ep.error=TCP.error_text("accept",code)
                TCP.close(ep);ep.state="error";TCP.event(ep,"error",nil,ep.error)
            end
        end
    end
    if #ep.peer_order==0 then return end
    ep.peer_cursor=(ep.peer_cursor or 0)%#ep.peer_order+1
    local peer=ep.peers[ep.peer_order[ep.peer_cursor]]
    if peer.ws and peer.ws.closing and engine_tick_now_ms()-peer.ws.close_started>1000 then TCP.drop(ep,peer);return end
    local incomplete=(peer.expected and peer.rx_bytes<peer.expected) or (not peer.expected and peer.rx_bytes>0 and peer.rx_bytes<4)
    if incomplete then peer.partial_since=peer.partial_since or engine_tick_now_ms()
    else peer.partial_since=nil end
    local partial_since=peer.ws and (peer.ws.partial_since or peer.ws.fragment_since) or
        peer.partial_since or peer.tls and peer.tls.record_since
    if partial_since and ep.read_timeout>0 and engine_tick_now_ms()-partial_since>ep.read_timeout then
        TCP.drop(ep,peer,"Incomplete message timed out");return
    end
    if peer.connecting then
        local poll=b.pollfd;poll[0].fd,poll[0].events,poll[0].revents=peer.fd,b.write,0
        local rc=b.lib.im3_net_poll(poll,1,0)
        if rc<0 then TCP.drop(ep,peer,TCP.error_text("connect poll",TCP.error_code()));return end
        if rc>0 then
            local value,len=ffi.new("int[1]"),ffi.new("im3_net_socklen[1]",4)
            if b.lib.im3_net_getopt(peer.fd,b.level,b.so_error,value,len)~=0 then
                TCP.drop(ep,peer,TCP.error_text("connect status",TCP.error_code()));return
            end
            if value[0]~=0 then TCP.drop(ep,peer,TCP.error_text("connect",tonumber(value[0])));return end
            if bit.band(poll[0].revents,b.write)==0 then TCP.drop(ep,peer,"Connection closed during connect");return end
            peer.connecting=false
            if ep.secure then
                local ok=pcall(TCP.TLS.begin,ep,peer)
                if not ok then TCP.drop(ep,peer,"TLS peer setup failed");return end
            else TCP.ready(ep,peer) end
        elseif ep.timeout>0 and engine_tick_now_ms()-ep.started>=ep.timeout then
            TCP.drop(ep,peer,"Connection timed out before reaching host");return
        else return end
    end
    if ep.secure and not peer.ready and ep.handshake_timeout>0 and engine_tick_now_ms()-peer.started>ep.handshake_timeout then
        local phase=TCP.peer_phase(peer)
        local message=phase=="websocket" and "WebSocket upgrade timed out" or phase=="invitation" and "Invitation verification timed out" or
            (peer.tls and (peer.tls.wire_received or 0)==0 and "TLS handshake timed out before peer responded" or "TLS handshake timed out")
        TCP.drop(ep,peer,message);return
    end
    if ep.secure then
        local flushed,why=TCP.TLS.flush(ep,peer)
        if why then TCP.drop(ep,peer,why);return end
        if not flushed then return end
        if peer.ws and peer.ws.closing and peer.tx_bytes==0 then TCP.drop(ep,peer);return end
        local established,err=TCP.TLS.handshake(ep,peer)
        if err then TCP.drop(ep,peer,err);return end
        if not established then return end
        if peer.ws then TCP.WS.start(ep,peer);if not ep.peers[peer.id] then return end end
        if ep.mode=="client" and not peer.authentication_sent and (not peer.ws or peer.ws.open and not peer.ws.closing) then
            peer.authentication_sent=true;TCP.internal(peer,"A"..ep.invitation_secret)
        end
    end
    if peer.tx_bytes>0 then
        local data=peer.tx[peer.tx.first]
        local size=math.min(16384,#data-peer.tx_offset)
        local sent,why
        if ep.secure then sent,why=TCP.TLS.write(ep,peer,data,peer.tx_offset,size)
        else sent=tonumber(b.lib.im3_net_send(peer.fd,ffi.cast("const char*",data)+peer.tx_offset,
            size,not b.win and not b.mac and 0x4000 or 0)) end -- MSG_NOSIGNAL on Linux
        if why then TCP.drop(ep,peer,why);return end
        sent=sent or 0
        if sent>0 then
            peer.tx_offset=peer.tx_offset+sent;peer.tx_bytes=peer.tx_bytes-sent
            if peer.tx_offset==#data then TCP.pop(peer.tx);peer.tx_offset=0 end
        elseif sent<0 then
            local code=TCP.error_code()
            if code~=b.again and code~=4 and code~=10004 then TCP.drop(ep,peer,TCP.error_text("send",code));return end
        end
    end
    TCP.extract(ep,peer)
    if not ep.peers[peer.id] then return end
    local room=ep.buffer_limit>0 and ep.buffer_limit-ep.inbox_bytes-peer.rx_bytes-(peer.ws and peer.ws.fragment_bytes or 0)+
        (peer.ws and peer.ws.open and 14 or 0) or 16384
    -- The four-byte header is framing, not payload. Even a deliberately tiny
    -- payload buffer must be able to finish it instead of stalling forever.
    if not peer.ws and not peer.expected and peer.rx_bytes<4 and
       (ep.buffer_limit==0 or ep.inbox_bytes<ep.buffer_limit) then
        room=math.max(room,4-peer.rx_bytes)
    end
    if room<=0 then return end -- Let TCP apply backpressure until the script receives messages.
    local received,data,why
    if ep.secure then
        data,why=TCP.TLS.read(ep,peer,math.min(16384,room))
        if why then TCP.drop(ep,peer,why);return end
        received=data and #data or -1
    else
        received=tonumber(b.lib.im3_net_recv(peer.fd,b.recv_buffer,math.min(16384,room),0))
        if received>0 and not TCP.charge_bytes(ep,peer,received) then TCP.drop(ep,peer,"Incoming byte rate exceeded");return end
    end
    if received>0 then
        TCP.push(peer.rx,data or ffi.string(b.recv_buffer,received));peer.rx_bytes=peer.rx_bytes+received
        TCP.extract(ep,peer)
    elseif received==0 then
        -- Preserve complete frames already buffered before reporting the close.
        peer.eof=true
        if peer.ws then
            if peer.rx_bytes==0 and not peer.ws.fragment_opcode then TCP.drop(ep,peer)
            else TCP.drop(ep,peer,"Peer disconnected with an incomplete WebSocket message") end
        elseif peer.rx_bytes==0 and not peer.expected then TCP.drop(ep,peer)
        elseif peer.expected and peer.rx_bytes<peer.expected or not peer.expected and peer.rx_bytes<4 then
            TCP.drop(ep,peer,"Peer disconnected with an incomplete message")
        end
    elseif not ep.secure then
        local code=TCP.error_code()
        if code~=b.again and code~=4 and code~=10004 then TCP.drop(ep,peer,TCP.error_text("receive",code)) end
    end
    if ep.peers[peer.id] and ep.queue_limit>0 and TCP.storage(ep)>ep.queue_limit then TCP.drop(ep,peer,"Aggregate network queue limit exceeded") end
end

function TCP.pump(ctx, deadline)
    local names=ctx.tcp_order
    if not names or #names==0 then return end
    local units=0
    for _,name in ipairs(names) do units=units+math.max(1,#ctx.tcp_connections[name].peer_order) end
    deadline=math.min(deadline or math.huge,engine_tick_now_ms()+(ctx.tcp_budget_ms or 1))
    for _=1,units do
        if engine_tick_now_ms()>=deadline then break end
        ctx.tcp_cursor=(ctx.tcp_cursor or 0)%#names+1
        local ep=ctx.tcp_connections[names[ctx.tcp_cursor]]
        if ep.state=="hosting" or ep.state=="connecting" or ep.state=="connected" then TCP.step(ep) end
    end
end

function TCP.json(value, seen, depth)
    local kind=type(value)
    if kind=="number" then
        if value~=value or math.abs(value)==math.huge then error("data contains a non-finite number") end
        return string.format("%.17g",value)
    elseif kind=="boolean" then return value and "true" or "false"
    elseif kind=="string" then
        return '"' .. value:gsub('[%z\1-\31\\"]',function(ch)
            if ch=='"' or ch=='\\' then return '\\'..ch end
            return string.format('\\u%04x',ch:byte())
        end) .. '"'
    elseif kind~="table" then error("data supports numbers, strings, booleans, and tables") end
    seen,depth=seen or {},(depth or 0)+1
    if depth>60 then error("data nesting exceeds 60 levels") end
    if seen[value] then error("data contains a cyclic table") end
    if getmetatable(value) then error("data must contain plain tables") end
    seen[value]=true
    local count,array=0,true
    for key in pairs(value) do
        count=count+1
        if type(key)~="number" or key<1 or key%1~=0 then array=false end
    end
    array=array and count==#value
    local parts={}
    if array and count>0 then
        for i=1,count do parts[i]=TCP.json(value[i],seen,depth) end
    else
        array=false
        for key,item in pairs(value) do
            if type(key)~="string" then error("data tables need string keys or a dense array") end
            parts[#parts+1]=TCP.json(key)..":"..TCP.json(item,seen,depth)
        end
    end
    seen[value]=nil
    return (array and "[" or "{")..table.concat(parts,",")..(array and "]" or "}")
end

function TCP.peer_phase(peer)
    if peer.ready then return "connected" end
    if peer.connecting then return "tcp" end
    if peer.ws and peer.tls and peer.tls.established and not peer.ws.open then return "websocket" end
    if peer.tls and peer.tls.established then return "invitation" end
    return "tls"
end
function TCP.status(ep)
    local peers,queued={},0
    for _,id in ipairs(ep.peer_order) do
        local peer=ep.peers[id]
        peers[#peers+1]={id=id,address=peer.address,state=peer.ready and "connected" or "connecting",authenticated=peer.ready and ep.secure and 1 or 0,
            phase=TCP.peer_phase(peer),tls_sent_bytes=peer.tls and peer.tls.wire_sent or 0,tls_received_bytes=peer.tls and peer.tls.wire_received or 0}
        queued=queued+peer.tx_bytes
    end
    return {state=ep.state,mode=ep.mode,address=ep.address,port=ep.port,error=ep.error or "",
        connections=#peers,peers=peers,queued_bytes=queued,messages=ep.inbox.last-ep.inbox.first+1,
        last_send_error=ep.last_send_error or "",security=ep.secure and "tls" or "plain",
        authenticated=ep.mode=="client" and ep.state=="connected" and ep.secure and 1 or 0,
        rejected=ep.rejected or 0,buffered_bytes=TCP.storage(ep),
        phase=ep.state=="error" and ep.failure_phase or ep.mode=="host" and "listening" or peers[1] and peers[1].phase or ep.state,
        transport=ep.transport or "tcp"}
end

-- Explicit clipboard access for invitation copy/paste. Never invoked by a
-- network message. Other platforms report unsupported instead of launching a
-- shell helper or installing a clipboard package.
function TCP.clipboard(action,text)
    if host_os~="Windows" then return {ok=0,text="",error="Native clipboard is currently available on Windows only"} end
    if not TCP.clipboard_declared then
        ffi.cdef[[
            int __stdcall im3_clip_open(void*) __asm__("OpenClipboard");
            int __stdcall im3_clip_close(void) __asm__("CloseClipboard");
            int __stdcall im3_clip_empty(void) __asm__("EmptyClipboard");
            void* __stdcall im3_clip_get(unsigned int) __asm__("GetClipboardData");
            void* __stdcall im3_clip_set(unsigned int,void*) __asm__("SetClipboardData");
            void* __stdcall im3_clip_alloc(unsigned int,size_t) __asm__("GlobalAlloc");
            void* __stdcall im3_clip_lock(void*) __asm__("GlobalLock");
            int __stdcall im3_clip_unlock(void*) __asm__("GlobalUnlock");
            void* __stdcall im3_clip_free(void*) __asm__("GlobalFree");
            size_t __stdcall im3_clip_size(void*) __asm__("GlobalSize");
            int __stdcall im3_clip_encode(unsigned int,unsigned long,const char*,int,uint16_t*,int) __asm__("MultiByteToWideChar");
            int __stdcall im3_clip_decode(unsigned int,unsigned long,const uint16_t*,int,char*,int,const char*,int*) __asm__("WideCharToMultiByte");
        ]]
        TCP.clipboard_declared=true
    end
    local user,kernel=ffi.load("user32"),ffi.load("kernel32")
    local memory,locked,opened
    local ok,result=pcall(function()
        local frontend=host_library("obs-frontend-api")
        assert(frontend,"OBS main window is unavailable")
        local handle=frontend.obs_frontend_get_main_window_handle()
        assert(handle~=nil and user.im3_clip_open(handle)~=0,"Clipboard is busy; try again")
        opened=true
        if action=="copy" then
            assert(type(text)=="string" and #text<=1048576,"Clipboard text must fit within 1 MiB")
            local count=kernel.im3_clip_encode(65001,8,text,#text,nil,0)
            assert(count>0,"Clipboard text is not valid UTF-8")
            memory=kernel.im3_clip_alloc(0x42,(count+1)*2);assert(memory~=nil,"Clipboard allocation failed")
            locked=kernel.im3_clip_lock(memory);assert(locked~=nil,"Clipboard allocation could not be locked")
            assert(kernel.im3_clip_encode(65001,8,text,#text,ffi.cast("uint16_t*",locked),count)==count)
            kernel.im3_clip_unlock(memory);locked=nil
            assert(user.im3_clip_empty()~=0 and user.im3_clip_set(13,memory)~=nil,"Clipboard write failed")
            memory=nil -- ownership transfers to Windows only on success
            return {ok=1,text="",error=""}
        end
        local data=user.im3_clip_get(13);assert(data~=nil,"Clipboard does not contain text")
        local bytes=tonumber(kernel.im3_clip_size(data));assert(bytes>0 and bytes<=1048576,"Clipboard text exceeds 1 MiB")
        local pointer=kernel.im3_clip_lock(data);assert(pointer~=nil,"Clipboard text could not be locked")
        locked=data
        local wide=ffi.cast("const uint16_t*",pointer);local count=0
        while count<math.floor(bytes/2) and wide[count]~=0 do count=count+1 end
        assert(count<math.floor(bytes/2),"Clipboard text is not terminated")
        local capacity=count>0 and kernel.im3_clip_decode(65001,0,wide,count,nil,0,nil,nil) or 0
        local buffer=ffi.new("char[?]",capacity+1)
        assert(count==0 or kernel.im3_clip_decode(65001,0,wide,count,buffer,capacity,nil,nil)==capacity,"Clipboard decoding failed")
        local value=ffi.string(buffer,capacity)
        kernel.im3_clip_unlock(data);locked=nil
        return {ok=1,text=value,error=""}
    end)
    if locked then kernel.im3_clip_unlock(memory or locked) end
    if memory then kernel.im3_clip_free(memory) end
    if opened then user.im3_clip_close() end
    return ok and result or {ok=0,text="",error="Clipboard access failed; focus OBS and try again"}
end
engine["clipboard"]=function(ctx,state,args)
    local action=tostring(args[1] or ""):lower();local fields={}
    if action~="copy" and action~="paste" then return false,"Clipboard Error: Expected copy or paste" end
    for i=2,#args do
        local parts=split_named_attribute_group(tostring(args[i]));if not parts then return false,"Clipboard Error: Invalid attributes" end
        for _,part in ipairs(parts) do
            local name,value=part:match("^%s*([%w_]+)%s*:%s*(.-)%s*$")
            if not name or fields[name] or name~="into" and (name~="text" or action~="copy") then return false,"Clipboard Error: Invalid attribute" end
            fields[name]=value
        end
    end
    if not fields.into or action=="copy" and not fields.text then return false,"Clipboard Error: into is required, and copy also needs text" end
    local value=fields.text and resolve_path(ctx,fields.text) or nil
    if is_fatal(value) then return false,value.msg end
    local written=update_variable_state(ctx,fields.into,TCP.clipboard(action,value))
    if is_fatal(written) then return false,written.msg end
    return true
end

-- Named fields can appear in any order and can be grouped with commas.
engine["network"] = function(ctx,state,args)
    if args._input_handler or INPUT_EVENTS and INPUT_EVENTS.is_handler('network',args) then
        return INPUT_EVENTS.register(ctx,args,'network')
    end
    local action=tostring(args[1] or ""):lower()
    local requested_transport=args._transport
    local options={name=1,address=1,port=1,message_limit=1,buffer_limit=1,security=1,invite=1,
        max_peers=1,max_pending=1,max_clients=1,event_limit=1,queue_limit=1,
        connection_rate=1,address_rate=1,message_rate=1,byte_rate=1,handshake_timeout=1,read_timeout=1}
    local join_options={};for key,value in pairs(options) do join_options[key]=value end;join_options.timeout=1
    local allowed={host=options,join=join_options,invite={name=1,into=1,address=1},decode={invite=1,into=1},
        send={name=1,peer=1,text=1,data=1,into=1},receive={name=1,into=1},
        status={name=1,into=1},close={name=1,peer=1},configure={budget=1},addresses={into=1}}
    if not allowed[action] then return false,"Network Error: Expected addresses, host, join, invite, decode, send, receive, status, close, or configure" end
    local fields={}
    for i=2,#args do
        local parts,err=split_named_attribute_group(tostring(args[i]))
        if not parts then return false,"Network Error: "..redact_network_credentials(err) end
        for _,part in ipairs(parts) do
            local key,value=part:match("^%s*([%w_]+)%s*:%s*(.-)%s*$")
            key=key and key:lower()
            if not key or not allowed[action][key] or fields[key]~=nil or value=="" then
                return false,"Network Error: Invalid or repeated attribute '"..redact_network_credentials(part).."'"
            end
            fields[key]=value
        end
    end
    local function number(key,default)
        if fields[key]==nil then return default end
        local value=evaluate_math(ctx,fields[key])
        if type(value)~="number" or value~=value or math.abs(value)==math.huge then error(key.." must be numeric") end
        return value
    end
    local function string_field(key,default,allow_empty)
        local raw=fields[key]
        if not raw then return default end
        local value=resolve_path(ctx,raw)
        if value==nil or is_fatal(value) then value=raw end
        if type(value)~="string" or not allow_empty and value=="" then error(key.." must be a nonempty string") end
        return value
    end
    local ok,result=pcall(function()
        if action=="decode" then
            assert(fields.into,"into:variable is required")
            local info,err=TCP.decode_code(string_field("invite","",true))
            if info and requested_transport=="websocket" and info.transport~="websocket" then
                info=nil;err="Copy a new WebSocket invitation from the updated host"
            end
            local value={ok=info and 1 or 0,address=info and info.address or "",port=info and info.port or 0,error=err or "",
                transport=info and info.transport or ""}
            local written=update_variable_state(ctx,fields.into,value)
            if is_fatal(written) then error(written.msg) end
            return true
        end
        if action=="addresses" then
            assert(fields.into,"into:variable is required")
            local written=update_variable_state(ctx,fields.into,TCP.LAN.addresses())
            if is_fatal(written) then error(written.msg) end
            return true
        end
        if action=="configure" then
            local budget=number("budget",1)
            assert(budget>0,"budget must be above zero (milliseconds)")
            ctx.tcp_budget_ms=budget;return true
        end
        local name=string_field("name")
        assert(name,"name:YourConnection is required")
        if action=="close" and name=="all" then
            if requested_transport=="websocket" then
                for _,endpoint in pairs(ctx.tcp_connections or {}) do if endpoint.transport=="websocket" then TCP.close(endpoint) end end
            else TCP.close_all(ctx) end
            return true
        end
        local connections=ctx.tcp_connections or {}
        local ep=connections[name]
        if action=="host" or action=="join" then
            assert(name~="all","name 'all' is reserved for closing every connection")
            if ep and ep.state~="closed" and ep.state~="error" then error("connection '"..name.."' already exists; close it first") end
            local bundled
            local invitation=action=="join" and string_field("invite","") or ""
            if invitation:sub(1,8)=="IM3JOIN1" or invitation:sub(1,7)=="IM3WSS1" then
                local why;bundled,why=TCP.decode_code(invitation);assert(bundled,why)
            end
            local transport=requested_transport or bundled and bundled.transport or "tcp"
            assert(not bundled or transport==bundled.transport,"Invitation belongs to a different message transport")
            local port=number("port",bundled and bundled.port)
            assert(not bundled or port==bundled.port,"Port disagrees with private connection code")
            assert(port and port%1==0 and port>=0 and port<=65535 and (action=="host" or port>0),"port must be a whole number from 1 to 65535 (host also accepts 0)")
            local timeout=number("timeout",10000)
            local message_limit,buffer_limit=number("message_limit",1048576),number("buffer_limit",8388608)
            assert(timeout>=0,"timeout must be zero or positive milliseconds")
            assert(message_limit>=0 and message_limit%1==0 and buffer_limit>=0 and buffer_limit%1==0,"limits must be zero or positive whole bytes")
            local address=string_field("address",bundled and bundled.address or action=="host" and "0.0.0.0" or "127.0.0.1")
            assert(not bundled or (address=="localhost" and "127.0.0.1" or address)==bundled.address,"Address disagrees with private connection code")
            local security=string_field("security","tls")
            assert(security=="tls" or security=="plain","security must be tls or plain")
            assert(transport~="websocket" or security=="tls","WebSocket messaging requires TLS; plaintext is not supported")
            assert(transport~="websocket" or buffer_limit==0 or buffer_limit>=1024,"WebSocket buffer_limit must be at least 1024 bytes, or 0")
            assert(action~="host" or not fields.invite,"The host generates its own invitation")
            assert(security=="tls" or not fields.invite,"invite requires security:tls")
            local pin,secret
            if action=="join" and security=="tls" then
                local a,b=(bundled and bundled.invite or invitation):match("^IM3TLS1%.(%x+)%.(%x+)$")
                assert(a and #a==64 and #b==64,"A valid host invitation is required for secure join")
                pin,secret=TCP.TLS.unhex(a),TCP.TLS.unhex(b)
            end
            assert(security~="tls" or (message_limit==0 or message_limit>=64) and (buffer_limit==0 or buffer_limit>=64),"TLS needs message_limit and buffer_limit of at least 64 bytes, or 0")
            local protection={max_peers=64,max_pending=8,max_clients=0,event_limit=1024,queue_limit=33554432,
                connection_rate=30,address_rate=4,message_rate=120,byte_rate=1048576,handshake_timeout=5000,read_timeout=5000}
            for key,default in pairs(protection) do
                protection[key]=number(key,default)
                assert(protection[key]>=0 and protection[key]%1==0,key.." must be zero or a positive whole number")
            end
            assert(protection.queue_limit==0 or protection.queue_limit>=1024,"queue_limit must be 0 or at least 1024 bytes")
            local b=TCP.setup()
            local addr,err=TCP.address(address,port);assert(addr,err)
            if ep then TCP.close(ep) end
            ep={mode=action=="host" and "host" or "client",transport=transport,state="connecting",address=address,port=port,
                peers={},peer_order={},next_peer=1,inbox=TCP.queue(),inbox_bytes=0,error="",
                timeout=timeout,started=engine_tick_now_ms(),message_limit=message_limit,buffer_limit=buffer_limit,
                secure=security=="tls",expected_pin=pin,invitation_secret=secret,event_bytes=0,rejected=0,
                rate_addresses={},rate_address_order={},accept_bucket={}}
            for key,value in pairs(protection) do ep[key]=value end
            ctx.tcp_connections=connections;connections[name]=ep
            ctx.tcp_order=ctx.tcp_order or {}
            local exists=false
            for _,old in ipairs(ctx.tcp_order) do if old==name then exists=true end end
            if not exists then ctx.tcp_order[#ctx.tcp_order+1]=name end
            if ep.secure then
                local ready,problem=pcall(TCP.TLS.credentials,ep)
                if not ready then
                    TCP.close(ep);ep.state,ep.error="error","Native TLS initialization failed; no plaintext fallback: "..tostring(problem)
                    TCP.event(ep,"error",nil,ep.error);return true
                end
            end
            local fd=b.lib.im3_net_socket_open(2,1,6)
            local why
            if fd==b.invalid then why=TCP.error_text("socket",TCP.error_code())
            else
                local ready;ready,why=TCP.socket_ready(fd)
                if ready then
                    if action=="host" then
                        local option=b.win and -5 or b.mac and 4 or 2
                        if b.lib.im3_net_setopt(fd,b.level,option,ffi.new("int[1]",1),4)~=0 then
                            why=TCP.error_text("listen socket option",TCP.error_code())
                        elseif b.lib.im3_net_bind(fd,addr,16)~=0 then why=TCP.error_text("bind",TCP.error_code())
                        elseif b.lib.im3_net_listen(fd,128)~=0 then why=TCP.error_text("listen",TCP.error_code())
                        else
                            ep.listener,ep.state=fd,"hosting"
                            local actual,len=ffi.new("uint8_t[16]"),ffi.new("im3_net_socklen[1]",16)
                            if b.lib.im3_net_getname(fd,actual,len)==0 then ep.address,ep.port=TCP.address_text(actual) end
                        end
                    else
