        if action=="invite" then
            assert(ep.mode=="host" and ep.secure and ep.state=="hosting" and ep.invite,"A secure listening host is required")
            assert(fields.into,"into:variable is required")
            local value=fields.address and TCP.connection_code(ep.invite,string_field("address"),ep.port,ep.transport) or ep.invite
            local written=update_variable_state(ctx,fields.into,value)
            if is_fatal(written) then error(written.msg) end
            return true
        end
        if action=="status" or action=="receive" then
            assert(fields.into,"into:variable is required")
            local value
            if action=="status" then value=TCP.status(ep)
            else
                value=TCP.receive_event(ep)
            end
            local written=update_variable_state(ctx,fields.into,value)
            if is_fatal(written) then error(written.msg) end
            return true
        end
        local target=fields.peer and tostring(fields.peer) or "all"
        if target~="all" then target=number("peer") end
        if action=="close" then
            assert(target=="all" or ep.peers[target],"peer was not found")
            if target=="all" then TCP.close(ep) else TCP.drop(ep,ep.peers[target]) end
            return true
        end
        assert((fields.text~=nil)~=(fields.data~=nil),"send needs either text:... or data:...")
        local payload
        if fields.text then
            local value=resolve_path(ctx,fields.text)
            assert(type(value)=="string","text must be a string expression")
            payload="T"..value
        else
            local raw=fields.data:match("^%s*(.-)%s*$")
            local value
            if raw:sub(1,1)=="{" or raw:sub(1,1)=="[" then value=parse_table_literal(ctx,raw)
            else value=resolve_path(ctx,raw) end
            assert(value~=nil and not is_fatal(value),"data must be a value or table expression")
            payload='J{"data":'..TCP.json(value)..'}'
        end
        assert(#payload<=4294967295,"message exceeds TCP framing's 32-bit length")
        local length=#payload
        local frame=ep.transport=="websocket" and TCP.WS.frame(payload,ep.mode=="client") or TCP.frame(payload)
        local recipients={}
        local why
        if ep.message_limit>0 and length>ep.message_limit then why="Message exceeds message_limit"
        else
            for _,id in ipairs(ep.peer_order) do
                local peer=ep.peers[id]
                if peer and (target=="all" or target==id) and peer.ready and not (peer.ws and peer.ws.closing) then
                    if ep.buffer_limit>0 and peer.tx_bytes+#frame>ep.buffer_limit then why="Outgoing queue exceeds buffer_limit";break end
