-- Dedicated WSS messaging; reuses OS socket/TLS ownership and tick scheduling.
-- No connection to the OBS WebSocket plugin, OBS password, or control API.
engine["connection"]=function(ctx,state,args)
    if args._input_handler or INPUT_EVENTS and INPUT_EVENTS.is_handler('connection',args) then
        return INPUT_EVENTS.register(ctx,args,'connection')
    end
    local forwarded={_transport="websocket"}
    for i,value in ipairs(args) do forwarded[i]=value end
    return engine.network(ctx,state,forwarded)
end
engine["websocket"]=engine["connection"] -- Compatibility for existing scripts.

function INPUT_EVENTS.condition(ctx,binding,value)
    local op=binding.code.op
    if not op then return true end
    local other=INPUT_EVENTS.value(ctx,binding,binding.code.compare,true)
    local a,b=tonumber(value),tonumber(other)
    if a and b then value,other=a,b end
    if op=='==' then return value==other end
    if op=='!=' or op=='~=' then return value~=other end
    if not a or not b then return false end
    if op=='<' then return a<b elseif op=='>' then return a>b elseif op=='<=' then return a<=b else return a>=b end
end
function INPUT_EVENTS.collect(ctx,binding,dt)
    if binding.code.family=='ui' then return end
    local code=binding.code
    if code.family=='collision' then return end
    if code.family=='change' then
        local value=INPUT_EVENTS.value(ctx,binding,code.target)
        if value~=binding.previous then
            local old=binding.previous;binding.previous=value
            if INPUT_EVENTS.condition(ctx,binding,value) then
                INPUT_EVENTS.emit(binding,{kind='change',name=code.target,old_value=old,new_value=value,value=value,dt=dt})
            end
        end
        return
    end
    if code.family=='connection' then
        if binding.task or binding.pending then return end
        local ep=ctx.tcp_connections and ctx.tcp_connections[binding.endpoint]
        if not ep or code.transport and ep.transport~=code.transport then return end
        for i=ep.inbox.first,ep.inbox.last do
            local packet=ep.inbox[i]
            if packet.event==code.kind then packet=TCP.decode_event(ep,packet) end
            if packet.event==code.kind then
                local event=TCP.receive_event(ep,i);event.kind=event.event;event.name=binding.endpoint;event.dt=dt
                INPUT_EVENTS.emit(binding,event);break
            end
            if ctx.tick_deadline_ms and engine_tick_now_ms()>=ctx.tick_deadline_ms then break end
        end
        return
    end
    local value
    if code.family=='animation' then value=ctx.animation_states and ctx.animation_states[INPUT_EVENTS.value(ctx,binding,code.target,true)]
    elseif code.family=='world3d' and code.kind=='animation_done' then
        local world=world3d_worlds[binding.world]
        value=world and world.animations and world.animations[INPUT_EVENTS.value(ctx,binding,code.target,true)]
    else
        value=INPUT_EVENTS.value(ctx,binding,code.target)
        if code.family=='worker' and type(value)~='table' then
            local job=ctx.native_workers and ctx.native_workers[code.target]
            value=job and (job.output or job.result)
        end
    end
    if type(value)~='table' then binding.watched=nil;binding.observed=nil;return end
    if binding.watched~=value then binding.watched=value;binding.observed=nil end
    if code.family=='animation' or code.kind=='animation_done' then
        local serial=value.completion_serial or 0
        if serial>0 and serial~=binding.observed then
            binding.observed=serial
            local playback=value.playback
            INPUT_EVENTS.emit(binding,{kind='done',name=code.target,clip=value.completed_clip or playback and playback.clip or '',
                time=value.completed_time or value.pose_time or value.last_time or 0,sequence=serial,dt=dt})
        end
    else
        local state=value.state
        local ready=code.kind=='ready' and state=='done' and value.uploaded==1 or code.kind=='prepared' and state=='done' or
            code.kind==state or code.kind=='finished' and (state=='done' or state=='error' or state=='cancelled')
        local token=code.kind=='ready' and (value.uploaded==1 and 'uploaded' or state) or state
        if ready and binding.observed~=token then
            binding.observed=token
            INPUT_EVENTS.emit(binding,{kind=code.kind,state=state,name=code.target,value=value.value,error=value.error or '',status=value,dt=dt})
        elseif not ready then binding.observed=token end
    end
end

