function physics3d_arguments(args)
    if args[1]~="step" then return nil,"Physics Error: expected step" end
    local fields={};local i=2
    while i<=#args do
        if args[i]=="->" then
            if i~=#args-1 or fields.into then return nil,"Physics Error: expected one final -> | variable" end
            fields.into=args[i+1];break
        end
        local parts,why=split_named_attribute_group(tostring(args[i]))
        if not parts then return nil,"Physics Error: "..tostring(why) end
        for _,part in ipairs(parts) do
            local key,value=part:match("^%s*([%w_]+)%s*:%s*(.-)%s*$")
            if not key or not ({state=1,seconds=1,into=1})[key] or value=="" or fields[key] then
                return nil,"Physics Error: invalid or repeated attribute "..tostring(part)
            end
            fields[key]=value
        end
        i=i+1
    end
    if not fields.state or not fields.seconds or not fields.into or not fields.into:match("^[%a_][%w_]*$") then
        return nil,"Physics Error: step needs state:, seconds:, and into:variable or -> | variable"
    end
    return fields
end
engine.physics=function(ctx,state,args)
    local fields,why=physics3d_arguments(args);if not fields then return false,why end
    local input=resolve_path(ctx,fields.state);if is_fatal(input) then return false,input.msg end
    local seconds=evaluate_math(ctx,fields.seconds);if is_fatal(seconds) then return false,seconds.msg end
    local ok,result=pcall(PHYSICS3D.step,input,seconds)
    if not ok then return false,tostring(result) end
    local written=update_variable_state(ctx,fields.into,result)
    if is_fatal(written) then return false,written.msg end
    return true
end

