local function native_worker_setup_api()
    if native_worker_api then return native_worker_api end
    if not native_worker_declared then
        assert(ffi.abi("64bit"), "Native Worker Error: 64-bit OBS is required")
        assert(ffi.os == "Windows" or ffi.os == "Linux" or ffi.os == "OSX",
               "Native Worker Error: unsupported operating system")
        local thread_api
        if ffi.os == "Windows" then
            thread_api = [[
                typedef unsigned long (__stdcall *im3_native_proc)(void *);
                void * __stdcall CreateThread(void *, size_t, im3_native_proc,
                                              void *, unsigned long, unsigned long *);
                unsigned long __stdcall WaitForSingleObject(void *, unsigned long);
                void * __stdcall CreateEventA(void *, int, int, const char *);
                int __stdcall SetEvent(void *);
                int __stdcall CloseHandle(void *);
            ]]
        else
            local pthread_type = ffi.os == "OSX" and
                "typedef void *im3_native_pthread_t;" or
                "typedef unsigned long im3_native_pthread_t;"
            local nfds_type = ffi.os == "OSX" and
                "typedef unsigned int im3_native_nfds_t;" or
                "typedef unsigned long im3_native_nfds_t;"
            thread_api = pthread_type .. nfds_type .. [[
                typedef void *(*im3_native_proc)(void *);
                int pthread_create(im3_native_pthread_t *, const void *,
                                   im3_native_proc, void *);
                int pthread_join(im3_native_pthread_t, void **);
                int pipe(int *);
                long write(int, const void *, size_t);
                int close(int);
                struct im3_native_pollfd { int fd; short events; short revents; };
                int poll(struct im3_native_pollfd *, im3_native_nfds_t, int);
            ]]
        end
        ffi.cdef([[
            typedef struct lua_State lua_State;
            lua_State *luaL_newstate(void);
            void luaL_openlibs(lua_State *);
            int luaL_loadstring(lua_State *, const char *);
            int luaL_loadbuffer(lua_State *, const char *, size_t, const char *);
            int lua_pcall(lua_State *, int, int, int);
            const char *lua_tolstring(lua_State *, int, size_t *);
            void lua_pushnil(lua_State *);
            void lua_pushlightuserdata(lua_State *, void *);
            const char *lua_pushstring(lua_State *, const char *);
            void lua_setfield(lua_State *, int, const char *);
            void lua_close(lua_State *);
        ]] .. native_worker_struct .. thread_api)
        native_worker_declared = true
    end
    assert(pcall(function() return ffi.C.luaL_newstate end),
           "Native Worker Error: OBS LuaJIT C API is unavailable")
    if ffi.os == "Windows" then
        native_worker_api = ffi.load("kernel32")
    else
        local pthread = ffi.C
        if not pcall(function() return pthread.pthread_create end) then
            local candidates = ffi.os == "OSX" and {"System"} or
                               {"pthread", "libpthread.so.0"}
            pthread = nil
            for _, name in ipairs(candidates) do
                local ok, lib = pcall(ffi.load, name)
                if ok and pcall(function() return lib.pthread_create end) then
                    pthread = lib
                    break
                end
            end
            assert(pthread, "Native Worker Error: pthread is unavailable")
        end
        native_worker_api = pthread
    end
    return native_worker_api
end

