    local min_width = math.max(160, (main_rect.right-main_rect.left)*0.35)
    local min_height = math.max(90, (main_rect.bottom-main_rect.top)*0.25)
    local enumerate = ffi.cast("im3_enum_child_t", function(hwnd)
        local rect = ffi.new("im3_menu_rect")
        if user.GetClientRect(hwnd, rect) ~= 0 and
           rect.right-rect.left >= min_width and
           rect.bottom-rect.top >= min_height then
            local native_id = ffi.cast("uintptr_t", hwnd)
            local widget = find_widget(native_id)
            if widget ~= nil and widget ~= ffi.NULL then
                local key = tostring(native_id)
