                local previous = saved[key]
                local policy = get_policy(widget)
                -- OBS configures its preview with CustomContextMenu (3).
                -- Other display widgets, including Studio Mode's program
                -- output, retain their own menus and event handling.
                if policy == 3 or
                   (previous ~= nil and previous.widget == widget_id) then
                    visit(widget, key, native_id, widget_id, policy, previous)
                    changed = changed + 1
                end
            end
        end
        return 1
    end)
    user.EnumChildWindows(main, enumerate, 0)
    enumerate:free()
