local function preview_menu_close()
    if preview_menu_bridge then
        local bridge = preview_menu_bridge
        if bridge.window then
            if ffi.C.GetWindowThreadProcessId(bridge.window, nil) ~= ffi.C.GetCurrentThreadId() then
                return false, "UI message window must be released on OBS's UI thread"
            end
            local data = ffi.new("uintptr_t[4]")
            data[1] = 3
            bridge.callback(data)
            if data[2] == 0 then return false, "Could not release the UI message window" end
        end
        ffi.C.lua_close(preview_menu_bridge.state)
        preview_menu_bridge = nil
    end
    return true
end

local function preview_menu_open(projector_title)
    if preview_menu_bridge then return preview_menu_bridge end
    native_worker_setup_api()
    local state = ffi.C.luaL_newstate()
    if state == nil then return nil, "Could not create isolated UI callback state" end
    local slot = ffi.new("uintptr_t[1]")
    local geometry=ffi.new('volatile double[11]')
    local ok, err = pcall(function()
        ffi.C.luaL_openlibs(state)
        ffi.C.lua_pushlightuserdata(state, slot)
        ffi.C.lua_setfield(state, -10002, "im3_preview_slot")
        ffi.C.lua_pushlightuserdata(state,ffi.cast('void*',geometry))
        ffi.C.lua_setfield(state,-10002,'im3_preview_geometry')
        ffi.C.lua_pushstring(state, projector_title or "")
        ffi.C.lua_setfield(state, -10002, "im3_projector_title")
        local loaded = ffi.C.luaL_loadstring(state, preview_menu_ui_code)
        local ran = loaded == 0 and ffi.C.lua_pcall(state, 0, 0, 0) or loaded
        if ran ~= 0 then
            error(ffi.string(ffi.C.lua_tolstring(state, -1, nil)))
        end
        if slot[0] == 0 then error("UI callback was not initialized") end
    end)
    if not ok then ffi.C.lua_close(state); return nil, tostring(err) end
    preview_menu_bridge = {
        state = state,
        geometry=geometry,
        slot = slot,
        callback = ffi.cast("im3_obs_task_t", slot[0])
    }
    return preview_menu_bridge
end

local function input_ui_initialize()
    if host_os ~= "Windows" or (preview_menu_bridge and preview_menu_bridge.window) then return true end
    local err
    local projector_title
    if not raymaze_frontend_lib then
        raymaze_frontend_lib, err = host_library("obs-frontend-api")
        if not raymaze_frontend_lib then return false, err end
    end
    local main = raymaze_frontend_lib.obs_frontend_get_main_window_handle()
    if main == nil or main == ffi.NULL then return false, "OBS main window is unavailable" end
    if ffi.C.GetWindowThreadProcessId(main, nil) ~= ffi.C.GetCurrentThreadId() then
        return false, "UI message window must be initialized on OBS's UI thread"
    end
    local localized = pcall(function()
        projector_title = ffi.string(raymaze_frontend_lib.obs_frontend_get_locale_string(
            "Projector.Title")) .. " - " ..
            ffi.string(raymaze_frontend_lib.obs_frontend_get_locale_string("StudioMode.Preview"))
    end)
    if not localized then projector_title = "" end
    local bridge
    bridge, err = preview_menu_open(projector_title)
    if not bridge then return false, err end
    local data = ffi.new("uintptr_t[4]")
    data[0], data[1] = ffi.cast("uintptr_t", main), 2
    bridge.callback(data)
    if data[2] == 0 or data[3] == 0 then
        preview_menu_close()
        return false, "Could not initialize OBS UI message window"
    end
    bridge.window = ffi.cast("void *", data[3])
    return true
end

input_ui_post_projector = function(monitor, block)
    local bridge = preview_menu_bridge
    if not bridge or not bridge.window then return false, "OBS UI dispatcher is unavailable; reload the engine" end
    if ffi.C.PostMessageW(bridge.window, 0x8349, monitor, block and 1 or 0) == 0 then
        return false, "Could not queue fullscreen projector request"
    end
