end

input_ui_focus_preview = function()
    local bridge = preview_menu_bridge
    if not bridge or not bridge.window then return false, "OBS UI dispatcher is unavailable; reload the engine" end
    if ffi.C.PostMessageW(bridge.window, 0x834B, 0, 0) == 0 then
        return false, "Could not queue preview keyboard focus request"
