function input_host.preview_geometry(child,width,height)
    local bridge=preview_menu_bridge
    if not bridge or not bridge.window or not bridge.geometry then return nil,false end
    local shared=bridge.geometry
    -- Queue a read on the UI thread; never wait for it from a Lua tick.
    if shared[1]==0 then
        shared[1]=1
        if ffi.C.PostMessageW(bridge.window,0x834E,0,0)==0 then shared[1]=0 end
    end
    local version=tonumber(shared[0])
    if version==0 or version%2~=0 then return nil,true end
    local data={}
    for i=2,10 do data[i]=tonumber(shared[i]) end
    if version~=tonumber(shared[0]) then return nil,true end
    local now=engine_tick_now_ms()
    if bridge.geometry_version~=version then bridge.geometry_version,bridge.geometry_time=version,now end
    if data[10]==-1 then return nil,false end
    if now-(bridge.geometry_time or 0)>250 or data[10]~=1 or
       ffi.cast('void*',data[2])~=child or width<=0 or height<=0 then return nil,true end
    local mode,rw,rh,sx,sy,aw,ah=data[3],data[4],data[5],data[6],data[7],data[8],data[9]
    if aw<=20 or ah<=20 then return nil,true end
    local scale,left,top
    if mode==0 then
        scale=math.min((aw-20)/width,(ah-20)/height)
        local dw,dh
        if (aw-20)/(ah-20)>width/height then dw,dh=math.floor((ah-20)*width/height),ah-20
        else dw,dh=aw-20,math.floor((aw-20)*height/width) end
        left=10+math.floor((aw-20)/2)-math.floor(dw/2)
        top=10+math.floor((ah-20)/2)-math.floor(dh/2)
    else
        if mode==1 then scale=1
        elseif mode==2 and rw>0 then scale=rw/width
        elseif mode==-1 and rw>0 and rh>0 then
            -- OBS exposes the actual scaled dimensions in its manual zoom
            -- placeholder. These retain sub-percent precision unlike its label.
            local low=math.max(rw/width,rh/height)
            local high=math.min((rw+1)/width,(rh+1)/height)
            if high<=low then return nil,true end
            scale=(low+high)/2
            local level=math.floor(math.log(scale)/math.log(8)*32+.5)
            local stepped=8^(level/32)
            if stepped>=low-1e-6 and stepped<high+1e-6 then scale=stepped end
        else return nil,true end
        local function truncate(value) return value<0 and math.ceil(value) or math.floor(value) end
        left=10+truncate((aw-20-width*scale)/2)+sx
        top=10+truncate((ah-20-height*scale)/2)+sy
    end
    return {left=left,top=top,scale=scale,area_width=aw,area_height=ah},true
end

input_ui_projector_controls=function(key,escape,close)
    local bridge=preview_menu_bridge
    if not bridge or not bridge.window then return false,"OBS UI dispatcher is unavailable; reload the engine" end
    if ffi.C.PostMessageW(bridge.window,close and 0x834D or 0x834C,key,escape)==0 then
        return false,"Could not queue projector controls"
    end
    return true
end

input_preview_menu_control = function(block)
    if host_os ~= "Windows" then
        if not block then return true end
        return false, "Preview menu control is available on Windows OBS only"
    end
    local bridge = preview_menu_bridge
    if not bridge or not bridge.window then
        if not block then return true end
        return false, "OBS UI dispatcher is unavailable; reload the engine"
    end
    if ffi.C.GetWindowThreadProcessId(bridge.window, nil) == ffi.C.GetCurrentThreadId() then
        local data = ffi.new("uintptr_t[4]")
        data[0] = ffi.cast("uintptr_t", raymaze_frontend_lib.obs_frontend_get_main_window_handle())
        data[1] = block and 1 or 0
        bridge.callback(data)
        if data[2] == 0 then return false, "Could not update the preview menu policy" end
    elseif ffi.C.PostMessageW(bridge.window, 0x834A, block and 1 or 0, 0) == 0 then
        return false, "Could not queue preview menu request"
    end
    return true
end

local function input_preview_menu_release(ctx)
    if ctx and ctx.input_projector_controls then
        local ok,err=input_ui_projector_controls(0,0)
        if not ok then return false,err end
        ctx.input_projector_controls=nil;ctx.input_projector_last_window=nil
    end
    if not ctx or not ctx.input_preview_menu_blocked then return true end
    local ok, err = input_preview_menu_control(false)
    if ok then
        ctx.input_preview_menu_blocked = false
        ctx.input_preview_menu_last_focus = nil
    end
    return ok, err
end

local function native_worker_pipe()
    local pair = ffi.new("int[2]", {-1, -1})
    assert(ffi.C.pipe(pair) == 0, "Native Worker Error: pipe failed")
    return pair
end

local function native_worker_signal_cancel(task)
    if task.cancel_sent or not task.started or task.phase ~= "running" then return end
    task.cancel_sent = true
    if ffi.os == "Windows" then
        native_worker_api.SetEvent(task.cancel_event)
    else
        local marker = ffi.new("char[1]", {1})
        ffi.C.write(task.cancel_pipe[1], marker, 1)
    end
end

local function native_worker_join(task)
    if not task.started or task.joined then return end
    if ffi.os == "Windows" then
        assert(tonumber(native_worker_api.WaitForSingleObject(task.handle,
               0xffffffff)) == 0, "Native Worker Error: join failed")
    else
        assert(native_worker_api.pthread_join(task.thread[0], nil) == 0,
               "Native Worker Error: pthread_join failed")
    end
    task.joined = true
end

local function native_worker_release_native(task)
    native_worker_join(task)
    if task.handle then native_worker_api.CloseHandle(task.handle); task.handle = nil end
    if task.cancel_event then
        native_worker_api.CloseHandle(task.cancel_event)
        task.cancel_event = nil
    end
    for _, pair in pairs({task.done_pipe, task.cancel_pipe}) do
        if pair then
            if pair[0] >= 0 then ffi.C.close(pair[0]) end
            if pair[1] >= 0 then ffi.C.close(pair[1]) end
        end
    end
    task.done_pipe, task.cancel_pipe = nil, nil
    local runtime=task.runtime
    if runtime then
        if task.failed_start or not runtime.ready then
            if runtime.state then ffi.C.lua_close(runtime.state);runtime.state=nil end
            runtime.ready=false
        elseif runtime.state then
            -- The thread has joined and the decoder is finished/discarded.
            -- Drop its result root without running Lua or a blocking full GC.
            ffi.C.lua_pushnil(runtime.state)
            ffi.C.lua_setfield(runtime.state,-10002,"im3_native_result_storage")
        end
        runtime.busy=false
        task.runtime=nil
        task.state=nil
    elseif task.state then ffi.C.lua_close(task.state); task.state = nil end
    task.slot, task.entry, task.map_buffer = nil, nil, nil
    task.payload_buffer,task.result_buffer = nil,nil
    task.decoder = nil
    if task.job then
        task.job[0].result_data=nil
        task.job[0].result_capacity,task.job[0].result_length=0,0
    end
end

function native_worker_close_pool(ctx)
    local pool=ctx.native_worker_pool
    if not pool then return end
    for _,runtime in ipairs(pool) do
        assert(not runtime.busy,"Native Worker Error: cannot close a busy runtime")
        if runtime.state then ffi.C.lua_close(runtime.state);runtime.state=nil end
        runtime.slot,runtime.entry=nil,nil
    end
    ctx.native_worker_pool=nil
end

function native_worker_scope_owner(ctx)
    local program=ctx.native_worker_program or ctx
    local task=ctx.current_task
    local calls=task and task.call_stack or (not task and ctx.call_stack)
    local identity
    if calls and #calls>0 then identity=ctx.active_scope or program
    elseif ctx.native_worker_base_owner then return ctx.native_worker_base_owner
    else identity=task or program end
    -- Ownership must not retain an entire returned function scope. Weak keys
    -- map each invocation/task identity to a small, stable owner token.
    program.native_worker_owners=program.native_worker_owners or setmetatable({},{__mode="k"})
    local owner=program.native_worker_owners[identity]
    if not owner then owner={};program.native_worker_owners[identity]=owner end
    return owner
end

local function native_worker_cancel_all(ctx)
    ctx=ctx.native_worker_program or ctx
    for _, task in pairs(ctx.native_workers or {}) do
        native_worker_signal_cancel(task)
    end
    -- Let every worker observe cancellation before waiting for any one of them.
    for _, task in pairs(ctx.native_workers or {}) do
        native_worker_release_native(task)
    end
    ctx.native_workers = {}
    if ctx.native_worker_pool then native_worker_close_pool(ctx) end
end

local function native_worker_pure_expression(raw)
    local expression = safe_trim(tostring(raw or ""))
    if #expression < 1 or #expression > 512 or
       expression:find("[^%w_%.%+%-%*/%%%^%(%)%[%],<>=~! ]") or
       expression:find("%-%-") or expression:find("%.%.") then
        return nil, "Native Worker Error: worker expressions must be bounded arithmetic or comparisons"
    end
    local forbidden = { ["function"] = true, ["while"] = true,
        ["repeat"] = true, ["until"] = true, ["for"] = true,
        ["do"] = true, ["end"] = true, ["local"] = true,
        ["return"] = true, ["break"] = true, ["goto"] = true,
        ["if"] = true, ["then"] = true, ["else"] = true,
        ["elseif"] = true, ["in"] = true }
    for identifier in expression:gmatch("[A-Za-z_][A-Za-z0-9_]*") do
        if forbidden[identifier] then
            return nil, "Native Worker Error: unsupported worker expression word '" ..
                        identifier .. "'"
        end
    end
    local normalized = expression:gsub("!=", "~=")
    local chunk, syntax = loadstring("return (" .. normalized .. ")")
    if not chunk then
        return nil, "Native Worker Error: invalid worker expression: " ..
                    tostring(syntax)
    end
    return expression
end

local function native_worker_snapshot_scope(ctx,wanted,encoded)
    local snapshot, budget, inspected = {}, 0, 0
    local literals={}
    local function literal(value)
        local cached=literals[value]
        if cached~=nil then return cached end
        cached=type(value)=="string" and string.format("%q",value) or tostring(value)
        literals[value]=cached;return cached
    end
    local function copy(value, depth, seen_values)
        inspected = inspected + 1
        if inspected > 524288 then return nil end
        local kind = type(value)
        if kind == "number" then
            if value ~= value or value == math.huge or value == -math.huge then
                return nil
            end
            budget = budget + 1
            return encoded and literal(value) or value
        elseif kind == "boolean" then
            budget = budget + 1
            if encoded then return tostring(value) end
            return value
        elseif kind == "string" then
            budget = budget + #value + 1
            if #value>65536 then return nil end
            return encoded and literal(value) or value
        elseif kind ~= "table" or depth > 6 or seen_values[value] then
            return nil
        end
        seen_values[value] = true
        local result = {}
        for key, item in pairs(value) do
            inspected = inspected + 1
            if inspected > 524288 then break end
            if (type(key) == "string" or
                (type(key) == "number" and key % 1 == 0)) then
                local copied = copy(item, depth + 1, seen_values)
                if copied ~= nil then
                    if encoded then
                        local key_text=literal(key)
                        result[#result+1]="["..key_text.."]= "..copied
                    else result[key] = copied end
                end
            end
            if budget > 4194304 then break end
        end
        seen_values[value] = nil
        budget = budget + 1
        return encoded and ("{"..table.concat(result,",").."}") or result
    end
    -- Match normal variable lookup: own scope, inherited scope, then numbered
    -- child scopes. Copy the chosen value once, not every shadowed parent value.
    local function lookup(scope,key,seen,depth)
        if type(scope)~="table" or seen[scope] or depth>64 then return nil end
        seen[scope]=true
        local value=rawget(scope,key)
        if value~=nil then return value end
        local mt=getmetatable(scope)
        if mt and type(mt.__index)=="table" then
            value=lookup(mt.__index,key,seen,depth+1)
            if value~=nil then return value end
        end
        for index,child in pairs(scope) do
            if type(index)=="number" and type(child)=="table" then
                value=lookup(child,key,seen,depth+1)
                if value~=nil then return value end
            end
        end
    end
    for key in pairs(wanted or {}) do
        local value=lookup(ctx.active_scope or ctx.vars,key,{},1)
        local copied=copy(value,1,{})
        if copied~=nil then
            if encoded then snapshot[#snapshot+1]="["..string.format("%q",key).."]="..copied
            else snapshot[key]=copied end
        end
        if budget>4194304 or inspected>524288 then break end
    end
    if budget > 4194304 or inspected > 524288 then
        return nil, "Native Worker Error: copied input exceeds 4 MiB or 524288 inspected values"
    end
    return encoded and ("{"..table.concat(snapshot,",").."}") or snapshot
end

local function native_worker_lua_literal(value)
    if type(value) == "string" then return string.format("%q", value) end
    if type(value) == "number" or type(value) == "boolean" then
        return tostring(value)
    end
    local parts = {}
    for key, item in pairs(value) do
        parts[#parts + 1] = "[" .. native_worker_lua_literal(key) .. "]=" ..
                            native_worker_lua_literal(item)
    end
    return "{" .. table.concat(parts, ",") .. "}"
end

local function native_worker_prepare_program(queue, labels, start)
    local cache=queue._native_worker_cache
    if not cache or cache.source~=queue._worker_steps or cache.labels~=labels then
        cache={source=queue._worker_steps,labels=labels,map={},order={},size=0,next=1}
        queue._native_worker_cache=cache
    end
    local cached=cache.map[start]
    if cached then
        local valid=true
        for pc,source in pairs(cached.sources) do
            local current=queue._worker_steps[pc]
            if current~=source.step or current.cmd~=source.cmd or #current.args~=#source.args then valid=false;break end
            for i,value in ipairs(source.args) do
                if current.args[i]~=value then valid=false;break end
            end
            if not valid then break end
        end
        for name,index in pairs(cached.labels) do
            local destination=labels and labels[name]
            if not destination or destination.queue~=queue or destination.index~=index then valid=false;break end
        end
        if valid then return cached end
        cache.map[start]=nil
    end
    local reachable, targets, sources, count, has_return = {}, {}, {}, 0, false
    local function target(name)
        local destination = labels and labels[name]
        if not destination or destination.queue ~= queue then
            error("worker label cannot reach '" .. tostring(name) .. "'")
        end
        targets[name] = destination.index
        return destination.index
    end
    -- Parse writes as data paths, never as Lua statements. Intermediate tables
    -- must already exist in the isolated copied state; math stays read-only.
    local function assignment(raw)
        local kind,name=raw:match("^(%w+)%s+(.+)$")
        name=name or raw
        if kind and kind~="number" and kind~="table" then error("worker variable type must be number or table") end
        local root,rest=name:match("^([%a_][%w_]*)(.*)$")
        if not root or #name>512 then error("invalid worker assignment target") end
        local path={root}
        while rest~="" do
            if #path>=16 then error("worker assignment path exceeds 16 levels") end
            if rest:sub(1,1)=="." then
                local field,after=rest:match("^%.([%a_][%w_]*)()")
                if not field then error("invalid worker field target") end
                path[#path+1]={field=field};rest=rest:sub(after)
            elseif rest:sub(1,1)=="[" then
                local depth,finish=0
                for index=1,#rest do
                    local ch=rest:sub(index,index)
                    if ch=="[" then depth=depth+1 elseif ch=="]" then depth=depth-1 end
                    if depth==0 then finish=index;break end
                end
                if not finish then error("unclosed worker table index") end
                local expression,problem=native_worker_pure_expression(rest:sub(2,finish-1))
                if not expression then error(problem) end
                path[#path+1]={expression=expression};rest=rest:sub(finish+1)
            else error("worker assignment must be a variable, field or indexed table") end
        end
        if #path>1 and root=="math" then error("worker math functions are read-only") end
        return path,kind
    end
    local function visit(pc)
        if reachable[pc] then return end
        local step = queue._worker_steps[pc]
        if not step then
            error("worker label must return before leaving its computation")
        end
        count = count + 1
        if count > 1024 then error("worker label exceeds 1024 commands") end
        local cmd, args = step.cmd, step.args
        if cmd ~= "label" and cmd ~= "var" and cmd ~= "array.push" and
           cmd ~= "if" and cmd ~= "jump" and cmd ~= "return" and cmd ~= "physics" then
            error("worker label cannot run !" .. tostring(cmd) ..
                  " (line " .. tostring(step.line) .. ")")
        end
        local entry = {cmd = cmd, args = {}}
        for i, value in ipairs(args) do entry.args[i] = value end
        local original={step=step,cmd=cmd,args={}}
        for i,value in ipairs(args) do original.args[i]=value end
        sources[pc]=original
        reachable[pc] = entry
        if cmd == "physics" then
            local fields,problem=physics3d_arguments(args);if not fields then error(problem) end
            local _,why=native_worker_pure_expression(fields.state);if why then error(why) end
            _,why=native_worker_pure_expression(fields.seconds);if why then error(why) end
            entry.cmd="var";entry.args={fields.into,"physics_step("..fields.state..","..fields.seconds..")"}
            entry.target=assignment(fields.into)
            visit(pc+1)
        elseif cmd == "return" then
            has_return = true
            if #args ~= 1 then error("worker !return needs one value") end
            local expression, err = native_worker_pure_expression(args[1])
            if not expression then error(err) end
        elseif cmd == "jump" then
            if #args ~= 1 then error("worker !jump needs one label") end
            visit(target(args[1]))
        elseif cmd == "if" then
            if #args == 4 then
                entry.args = {args[1] .. " " .. args[2] .. " " .. args[3],
                              args[4]}
            elseif #args ~= 2 then
                error("worker !if supports condition | label")
            end
            local expression, err = native_worker_pure_expression(entry.args[1])
            if not expression then error(err) end
            visit(target(entry.args[2]))
            visit(pc + 1)
        else
            if cmd == "var" then
                if #args ~= 2 then error("worker !var needs name | value") end
                entry.target,entry.var_type=assignment(args[1])
                if args[2] ~= "[]" and args[2] ~= "{}" then
                    local _, err = native_worker_pure_expression(args[2])
                    if err then error(err) end
                end
            elseif cmd == "array.push" then
                if #args ~= 2 then error("worker !array.push needs array | value") end
                local kind
                entry.target,kind=assignment(args[1])
                if kind then error("worker !array.push needs a table path without a type declaration") end
                local _, err = native_worker_pure_expression(args[2])
                if err then error(err) end
            end
            visit(pc + 1)
        end
    end
    local ok, problem = pcall(visit, start)
    if not ok then return nil, "Native Worker Error: " .. tostring(problem) end
    if not has_return then
        return nil, "Native Worker Error: worker label needs a reachable !return"
    end
    local program={steps=reachable,labels=targets,start=start,sources=sources}
    -- Backward liveness: capture a root only if some path reads its incoming
    -- value before a whole-root assignment. Branches and loop back-edges are
    -- included; a nested write/append reads its existing container and indexes.
    local live,pred,defs,pending,queued={},{},{},{},{}
    local function reads(set,expression)
        for position,name in expression:gmatch("()([%a_][%w_]*)") do
            local before=expression:sub(position-1,position-1)
            if not before:match("[%w_%.]") and name~="math" and name~="physics_step" and
               name~="and" and name~="or" and name~="not" and name~="true" and name~="false" and name~="nil" then
                set[name]=true
            end
        end
    end
    local function edge(from,to)
        pred[to]=pred[to] or {};pred[to][#pred[to]+1]=from
    end
    for pc,step in pairs(reachable) do
        local set={};live[pc]=set
        local cmd,args,target=step.cmd,step.args,step.target
        if cmd=="var" or cmd=="array.push" then
            reads(set,args[2])
            if cmd=="var" and #target==1 then defs[pc]=target[1]
            else
                if target[1]~="math" then set[target[1]]=true end
                for i=2,#target do
                    if target[i].expression then reads(set,target[i].expression) end
                end
            end
        elseif cmd=="if" or cmd=="return" then reads(set,args[1]) end
        if cmd=="jump" then edge(pc,targets[args[1]])
        elseif cmd=="if" then edge(pc,targets[args[2]]);edge(pc,pc+1)
        elseif cmd~="return" then edge(pc,pc+1) end
        if next(set) then pending[#pending+1]=pc;queued[pc]=true end
    end
    local read=1
    while read<=#pending do
        local pc=pending[read];read=read+1;queued[pc]=nil
        for _,previous in ipairs(pred[pc] or {}) do
            local changed=false
            for name in pairs(live[pc]) do
                if defs[previous]~=name and not live[previous][name] then
                    live[previous][name]=true;changed=true
                end
            end
            if changed and not queued[previous] then
                pending[#pending+1]=previous;queued[previous]=true
            end
        end
    end
    program.inputs=live[start]
    program.payload_tail=",steps="..native_worker_lua_literal(reachable)..
        ",labels="..native_worker_lua_literal(targets)..",start="..start.."}"
    if not cached then
        if cache.size>=32 then
            local old=cache.order[cache.next];cache.map[old]=nil
            cache.order[cache.next]=start;cache.next=cache.next%32+1
        else cache.size=cache.size+1;cache.order[cache.size]=start end
    end
    cache.map[start]=program
    return program
end

local function native_worker_prepare_label(ctx, name)
    local label = (ctx.labels and ctx.labels[name]) or
                  (ctx.global_registry and ctx.global_registry[name])
    if not label or not label.queue or not label.queue._worker_steps then
        return nil, "Native Worker Error: missing worker label '" .. name .. "'"
    end
    return native_worker_prepare_program(label.queue, label.labels,
                                         label.index)
end

local function native_worker_prepare_block(ctx, block)
    local inner = block:match("^%s*(%b{})%s*$")
    if not inner then
        return nil, "Native Worker Error: invalid { ... } block"
    end
    local owner=ctx.native_worker_program or ctx
    local cache=owner.native_worker_blocks
    if not cache then
        cache={map={},order={},size=0,next=1};owner.native_worker_blocks=cache
    end
    local key=tostring(ctx.context_id or 0)..":"..block
    if cache.map[key] then return cache.map[key] end
    -- Keep inline labels private to the worker.
    local source = setmetatable({global_registry = {}}, {__index = ctx})
    local queue, labels = compile_block_text(source, inner:sub(2, -2),
                                              ctx.context_id or 0)
    if not queue[1] then
        return nil, "Native Worker Error: empty { ... } block"
    end
    local program,problem=native_worker_prepare_program(queue,labels,1)
    if not program then return nil,problem end
    if cache.size>=32 then
        local old=cache.order[cache.next];cache.map[old]=nil
        cache.order[cache.next]=key;cache.next=cache.next%32+1
    else cache.size=cache.size+1;cache.order[cache.size]=key end
    cache.map[key]=program
    return program
end

function native_worker_warm_programs(ctx,queue,labels)
    -- Prepare statically named labels after compilation has finished, when
    -- forward targets and function queues are available. This reads no inputs
    -- and launches no jobs. Invalid/unused worker code still errors only when
    -- executed, so prewarming does not change conditional error behavior.
    local seen={}
    local function visit(current,current_labels)
        if seen[current] then return end
        seen[current]=true
        local runner={labels=current_labels,global_registry=ctx.global_registry}
        for _,step in pairs(current._worker_steps or {}) do
            local action=step.cmd=="worker" and step.args[1]
            if action and action:match("^[%a_][%w_]*$") and action~="start" and
               action~="read" and action~="get_result" and action~="cancel" and
               action~="release" and action~="remove" and action~="clear" and action~="stop_all" then
                native_worker_prepare_label(runner,action)
            end
        end
    end
    visit(queue,labels)
    for _,definition in pairs(ctx.functions or {}) do
        if definition.queue then visit(definition.queue,definition.labels) end
    end
end

function native_worker_now_ms()
    return engine_tick_now_ms and engine_tick_now_ms() or os.clock()*1000
end
local function native_worker_launch(ctx, name, operation, args)
    local started=native_worker_now_ms()
    native_worker_setup_api()
    local program=ctx.native_worker_program or ctx
    local jobs = program.native_workers or {}
    program.native_workers = jobs
    local total, running = 0, 0
    for _, job in pairs(jobs) do
        total = total + 1
        if job.phase == "running" then running = running + 1 end
    end
    if jobs[name] then
        if jobs[name].phase == "running" then
            return nil, "Native Worker Error: job '" .. name .. "' is still running"
        end
        jobs[name] = nil
        total = total - 1
    end
    if total >= 8 or running >= 4 then
        return nil, "Native Worker Error: limit is 4 running and 8 retained jobs"
    end
    local task = {name = name, operation = operation, phase = "starting",
        owner=native_worker_scope_owner(ctx),started_ms=started,
        metrics={launch_ms=0,startup_ms=0,capture_ms=0,decode_ms=0,decode_peak_ms=0,
            elapsed_ms=0,input_bytes=args.payload and #args.payload or args.map and #args.map or 0,output_bytes=0}}
    jobs[name] = task
    local ok, err = pcall(function()
        local pool=program.native_worker_pool or {}
        program.native_worker_pool=pool
        local runtime
        for _,candidate in ipairs(pool) do
            if not candidate.busy then runtime=candidate;break end
        end
        if not runtime then runtime={};pool[#pool+1]=runtime end
        assert(#pool<=4,"worker runtime pool exceeds running-job limit")
        runtime.busy=true;task.runtime=runtime
        task.metrics.runtime_reused=runtime.ready and 1 or 0
        if not runtime.ready then
            runtime.state = ffi.C.luaL_newstate()
            assert(runtime.state ~= nil and runtime.state ~= ffi.NULL,"luaL_newstate failed")
            ffi.C.luaL_openlibs(runtime.state)
            runtime.slot = ffi.new("uintptr_t[1]")
            ffi.C.lua_pushlightuserdata(runtime.state, runtime.slot)
            ffi.C.lua_setfield(runtime.state, -10002, "im3_native_slot")
        end
        task.state,task.slot=runtime.state,runtime.slot
        -- Compile the engine-owned bootstrap once. Idle runtimes retain only
        -- engine code and native storage, never the next job's environment.
        -- Loading with an explicit length preserves binary zeros.
        if not native_worker_bootstrap_bytecode then
            local code = "im3_native_struct = " ..
                string.format("%q", native_worker_struct) .. (PHYSICS3D_SOURCE and "\nlocal im3_physics=(function()\n"..PHYSICS3D_SOURCE.."\nend)()\n" or "\nlocal im3_physics=nil\n") ..native_worker_code
            native_worker_bootstrap_bytecode=string.dump(assert(loadstring(code)))
        end
        if not runtime.ready then
            local code=native_worker_bootstrap_bytecode
            local loaded = ffi.C.luaL_loadbuffer(task.state, code, #code, "4IM3 native worker")
            local status = loaded == 0 and ffi.C.lua_pcall(task.state, 0, 0, 0) or loaded
            if status ~= 0 then
                local message = ffi.C.lua_tolstring(task.state, -1, nil)
                error("worker bootstrap failed: " ..(message ~= nil and ffi.string(message) or "unknown error"))
            end
            assert(task.slot[0] ~= 0, "worker callback was not published")
            runtime.entry = ffi.cast("im3_native_proc", task.slot[0])
            runtime.ready=true
        end
        task.entry = runtime.entry
        task.job = ffi.new("im3_native_job[1]")
        if operation == "sum" then
            task.job[0].operation = 1
            task.job[0].limit = args.limit
        elseif operation == "script" then
            task.job[0].operation = 4
            task.payload_buffer = ffi.new("char[?]", #args.payload + 1)
            ffi.copy(task.payload_buffer, args.payload, #args.payload)
            task.job[0].payload = task.payload_buffer
        else
            task.job[0].operation = 2
            task.job[0].width = args.width
            task.job[0].height = args.height
            task.job[0].start_x = args.start_x
            task.job[0].start_y = args.start_y
            task.job[0].goal_x = args.goal_x
            task.job[0].goal_y = args.goal_y
            task.map_buffer = ffi.new("unsigned char[?]", #args.map)
            ffi.copy(task.map_buffer, args.map, #args.map)
            task.job[0].map = task.map_buffer
        end
        if ffi.os == "Windows" then
            task.cancel_event = native_worker_api.CreateEventA(nil, 1, 0, nil)
            assert(task.cancel_event ~= nil and task.cancel_event ~= ffi.NULL,
                   "CreateEventA failed")
            task.job[0].cancel_event = task.cancel_event
            task.job[0].cancel_read = -1
            task.job[0].done_write = -1
            task.handle = native_worker_api.CreateThread(nil, 0,
                task.entry, task.job, 0, nil)
            assert(task.handle ~= nil and task.handle ~= ffi.NULL,
                   "CreateThread failed")
        else
            task.cancel_pipe = native_worker_pipe()
            task.done_pipe = native_worker_pipe()
            task.job[0].cancel_read = task.cancel_pipe[0]
            task.job[0].done_write = task.done_pipe[1]
            task.thread = ffi.new("im3_native_pthread_t[1]")
            assert(native_worker_api.pthread_create(task.thread, nil,
                   task.entry, task.job) == 0, "pthread_create failed")
        end
        task.started = true
        task.phase = "running"
    end)
    if not ok then
        task.failed_start=true
        local cleaned, cleanup_error = pcall(native_worker_release_native, task)
        jobs[name] = nil
        return nil, "Native Worker Error: " .. tostring(err) ..
            (cleaned and "" or "; cleanup: " .. tostring(cleanup_error))
    end
    task.metrics.startup_ms=native_worker_now_ms()-started
    task.metrics.launch_ms=task.metrics.startup_ms
    return task
end

local function native_worker_completed(task)
    if ffi.os == "Windows" then
        local status = tonumber(native_worker_api.WaitForSingleObject(task.handle, 0))
        if status == 0 then return true end
        assert(status == 258, "Native Worker Error: wait failed: " .. tostring(status))
        return false
    end
    local fd = ffi.new("struct im3_native_pollfd[1]")
    fd[0].fd = task.done_pipe[0]
    fd[0].events = 1
    local status = tonumber(ffi.C.poll(fd, 1, 0))
    assert(status >= 0, "Native Worker Error: poll failed")
    return status == 1
end

function native_worker_decode_result(task,checkpoint)
    local length=tonumber(task.job[0].result_length)
    if length<1 or length>tonumber(task.job[0].result_capacity) then error("invalid worker result length") end
    -- Read directly from the owned native buffer. Keep it alive until the
    -- decoder finishes; never publish a partly decoded table to the script.
    local data=ffi.cast("const uint8_t*",task.job[0].result_data)
    local pos,nodes,next_checkpoint=0,0,128
    local number_block
    local number_scratch,uint_scratch=ffi.new("double[1]"),ffi.new("uint32_t[1]")
    local function take(count)
        if count<0 or pos+count>length then error("truncated worker result") end
        local value=data+pos;pos=pos+count;return value
    end
    local function uint()
        ffi.copy(uint_scratch,take(4),4);return tonumber(uint_scratch[0])
    end
    local function decode(depth)
        if depth>16 then error("worker result nesting exceeds 16") end
        nodes=nodes+1
        if checkpoint and nodes>=next_checkpoint then next_checkpoint=nodes+128;checkpoint() end
        local tag=tonumber(take(1)[0])
        if tag==78 then -- N
            ffi.copy(number_scratch,take(8),8)
            local number=tonumber(number_scratch[0]);if number~=number or math.abs(number)==math.huge then error("nonfinite worker result") end
            return number
        elseif tag==89 then return true
        elseif tag==70 then return false
        elseif tag==83 then local count=uint();return ffi.string(take(count),count)
        elseif tag==68 then -- D: contiguous finite doubles, decoded in bounded blocks.
            local count=uint()
            if count>math.floor((length-pos)/8) then error("invalid worker numeric array count") end
            local out={}
            number_block=number_block or ffi.new("double[128]")
            for first=1,count,128 do
                local size=math.min(128,count-first+1)
                ffi.copy(number_block,take(size*8),size*8)
                for offset=0,size-1 do
                    local value=tonumber(number_block[offset])
                    if value~=value or math.abs(value)==math.huge then error("nonfinite worker result") end
                    out[first+offset]=value
                end
                nodes=nodes+size
                if checkpoint and nodes>=next_checkpoint then next_checkpoint=nodes+128;checkpoint() end
            end
            return out
        elseif tag==65 or tag==84 then
            local count=uint();if count>length-pos then error("invalid worker result count") end
            local out={}
            for i=1,count do
                local key=tag==65 and i or decode(depth+1)
                if type(key)~="string" and (type(key)~="number" or key%1~=0) then error("invalid worker result key") end
                out[key]=decode(depth+1)
            end
            return out
        end
        error("invalid worker result tag")
    end
    local result=decode(0);if pos~=length then error("extra worker result bytes") end
    return result
end
local function native_worker_poll_task(task,deadline)
    if task.phase ~= "running" or (not task.joined and not native_worker_completed(task)) then return end
    native_worker_join(task)
    local data = task.job[0]
    if task.cancel_sent then
        task.phase,task.result="cancelled",{state="cancelled"}
    elseif tonumber(data.status) == 1 then
        if task.operation == "script" then
            if not task.decoder then
                task.decoder=coroutine.create(function()
                    if tonumber(data.result_length)>0 then
                        return native_worker_decode_result(task,coroutine.yield)
                    end
                    return tonumber(data.value)
                end)
            end
            local now=function() return engine_tick_now_ms and engine_tick_now_ms() or os.clock()*1000 end
            deadline=deadline or now()+1
            repeat
                local started=now()
                local ok,value=coroutine.resume(task.decoder)
                local cost=now()-started
                task.metrics.decode_ms=task.metrics.decode_ms+cost
                task.metrics.decode_peak_ms=math.max(task.metrics.decode_peak_ms,cost)
                if task.output then
                    task.output.decode_ms,task.output.decode_peak_ms=task.metrics.decode_ms,task.metrics.decode_peak_ms
                end
                if not ok or coroutine.status(task.decoder)=="dead" then
                    task.phase=ok and "done" or "error"
                    task.result=ok and {state="done",value=value} or {state="error",error=tostring(value)}
                    break
                end
            until now()>=deadline
            if not task.result then return end
        else
            task.phase = "done"
            task.result = {
                state = "done", value = tonumber(data.value),
                x = tonumber(data.next_x), y = tonumber(data.next_y),
                distance = tonumber(data.distance)
            }
        end
    elseif tonumber(data.status) == 3 then
        task.phase = "cancelled"
        task.result = {state = "cancelled"}
    else
        task.phase = "error"
        task.result = {state = "error", error = ffi.string(data.error)}
        if obslua and obslua.script_log then
            obslua.script_log(obslua.LOG_ERROR,
                "[4IM3-SCRIPT] Native worker '" .. task.name ..
                "' failed: " .. task.result.error)
        end
    end
    task.metrics.elapsed_ms=native_worker_now_ms()-task.started_ms
    task.metrics.output_bytes=tonumber(data.result_length)
    task.metrics.result_capacity_bytes=tonumber(data.result_capacity)
    for key,value in pairs(task.metrics) do task.result[key]=value end
    if task.output then
        for key, value in pairs(task.result) do task.output[key] = value end
    end
    native_worker_release_native(task)
end

local function native_worker_poll_all(ctx,deadline)
    ctx=ctx.native_worker_program or ctx
    local now=function() return engine_tick_now_ms and engine_tick_now_ms() or os.clock()*1000 end
    deadline=deadline or now()+1
    local active={}
    for name,task in pairs(ctx.native_workers or {}) do active[#active+1]={name,task} end
    -- Rotate the first consumer so a large result cannot starve another job.
    local first=(ctx.native_decode_cursor or 0)%math.max(1,#active)+1
    ctx.native_decode_cursor=first
    for offset=0,#active-1 do
        local entry=active[(first+offset-1)%#active+1]
        local name,task=entry[1],entry[2]
        if task.phase == "running" then
            local ok, err = pcall(native_worker_poll_task, task,math.min(deadline,now()+0.35))
            if not ok and not task.poll_error_reported then
                task.poll_error_reported = true
                if obslua and obslua.script_log then
                    obslua.script_log(obslua.LOG_ERROR,
                        "[4IM3-SCRIPT] Native worker '" .. name ..
                        "' poll failed: " .. tostring(err))
                end
            end
        end
        if task.discard and task.phase ~= "running" then
            ctx.native_workers[name] = nil
        end
        if now()>=deadline then break end
    end
end

function native_worker_clear(ctx,owner)
    local program=ctx.native_worker_program or ctx
    local jobs=program.native_workers or {}
    local selected={}
    for name,task in pairs(jobs) do
        if not owner or task.owner==owner then
            selected[#selected+1]={name=name,task=task}
            native_worker_signal_cancel(task)
        end
    end
    -- Signal every selected job before joining any one of them. Unrelated
    -- owners are neither polled, cancelled nor removed by scoped cleanup.
    for _,entry in ipairs(selected) do
        local task=entry.task
        native_worker_join(task)
        if task.phase=="running" then native_worker_poll_task(task)
        else native_worker_release_native(task) end
        if jobs[entry.name]==task then jobs[entry.name]=nil end
    end
    if not owner then program.native_workers={};native_worker_close_pool(program) end
end

-- !worker | (numeric_expression) | result_table
-- !worker | { !var | number base | value |+| !return | base * 2 |+| } | result_table
-- !worker | computation_label | result_table
-- !worker | start | name | sum | limit
-- !worker | start | name | path | map_string | width | height |
--           start_x | start_y | goal_x | goal_y
-- !worker | read | name | table_variable
-- !worker | cancel | name (or all)
-- !worker | release | name (or all)
-- !worker | clear | scope (jobs created by this invocation/task)
-- !worker | clear | program (all is a compatibility alias)
-- Readable aliases: get_result, remove, stop_all.
local worker_action_aliases={get_result="read",remove="release"}
engine["worker"] = function(ctx, state, args)
    if args._input_handler or INPUT_EVENTS and INPUT_EVENTS.is_handler('worker',args) then
        return INPUT_EVENTS.register(ctx,args,'worker')
    end
    local command_started=native_worker_now_ms()
    local program_ctx=ctx.native_worker_program or ctx
    local requested = safe_trim(tostring(args[1] or ""))
    if requested == "stop_all" then
        native_worker_clear(ctx)
        return true
    end
    local action = worker_action_aliases[requested] or requested
    local name = safe_trim(tostring(args[2] or ""))
    if name == "" then return false, "Native Worker Error: missing job name" end
    if action~="read" and action~="cancel" and action~="release" and action~="clear" then
        local existing=program_ctx.native_workers and program_ctx.native_workers[name]
        if existing and existing.phase=="running" then
            -- Re-entering a start command must not replace an active job or
            -- its live result table, rebuild its payload, or stop the script.
            if action~="start" then
                local output=existing.output or {state="running"}
                local written=update_variable_state(ctx,name,output)
                if is_fatal(written) then return false,written.msg end
                existing.output=output
            end
            return true
        end
    end
    if action ~= "start" and action ~= "read" and
       action ~= "cancel" and action ~= "release" and action ~= "clear" then
        if not name:match("^[%a_][%w_]*$") or #name > 48 then
            return false, "Native Worker Error: result name must be 1-48 letters, digits, or underscores"
        end
        local program
        if action:match("^%b()$") then
            local expression, err = native_worker_pure_expression(
                action:sub(2, -2))
            if not expression then return false, err end
            program = {steps = {[1] = {cmd = "return", args = {expression}}},
                       labels = {}, start = 1}
        elseif action:match("^%b{}$") then
            local err
            program, err = native_worker_prepare_block(ctx, action)
            if not program then return false, err end
        else
            local err
            program, err = native_worker_prepare_label(ctx, action)
            if not program then return false, err end
        end
        -- Program structure is reusable; scope values are a fresh snapshot on
        -- every launch. Expressions need no CFG, but still capture their roots.
        local wanted=program.inputs
        if not wanted then
            wanted={}
            for _,step in pairs(program.steps) do
                for position,name in step.args[1]:gmatch("()([%a_][%w_]*)") do
                    if not step.args[1]:sub(position-1,position-1):match("[%w_%.]") and name~="math" then wanted[name]=true end
                end
            end
        end
        local capture_started=native_worker_now_ms()
        local snapshot, snapshot_error = native_worker_snapshot_scope(ctx,wanted,true)
        if not snapshot then return false, snapshot_error end
        local payload
        local tail=program.payload_tail or (",steps="..native_worker_lua_literal(program.steps)..
            ",labels="..native_worker_lua_literal(program.labels)..",start="..tostring(program.start).."}")
        payload="{vars="..snapshot..tail
        if #payload > 4194304 then
            return false, "Native Worker Error: worker payload exceeds 4 MiB"
        end
        local task, err = native_worker_launch(ctx, name, "script",
                                               {payload = payload})
        if not task then return false, err end
        task.metrics.capture_ms=math.max(0,(task.started_ms or capture_started)-capture_started)
        task.metrics.launch_ms=native_worker_now_ms()-command_started
        task.started_ms=command_started
        local output = {state = "running"}
        for key,value in pairs(task.metrics) do output[key]=value end
        local written = update_variable_state(ctx, name, output)
        if is_fatal(written) then
            native_worker_signal_cancel(task)
            native_worker_release_native(task)
            program_ctx.native_workers[name] = nil
            return false, written.msg
        end
        task.output = output
        return true
    end
    if action == "start" then
        if not name:match("^[%a_][%w_]*$") or #name > 48 then
            return false, "Native Worker Error: name must be 1-48 letters, digits, or underscores"
        end
    end
    if action == "clear" then
        if name=="scope" then
            native_worker_clear(ctx,native_worker_scope_owner(ctx))
        elseif name=="program" or name=="all" then
            native_worker_clear(ctx)
        else
            return false, "Native Worker Error: clear expects scope, program, or all"
        end
        return true
    end
    if action == "start" then
        local operation = safe_trim(tostring(args[3] or ""))
        local values = {}
        if operation == "sum" then
            local limit, err = canvas_number(ctx, args[4], "sum limit")
            if not limit then return false, "Native Worker Error: " .. tostring(err) end
            if limit < 1 or limit > 5000000 or limit % 1 ~= 0 then
                return false, "Native Worker Error: sum limit must be 1..5000000"
            end
            values.limit = limit
        elseif operation == "path" then
            local map = resolve_path(ctx, tostring(args[4] or ""))
            if is_fatal(map) or (type(map) ~= "string" and type(map) ~= "table") then
                return false, "Native Worker Error: path needs a grid table or string"
            end
            local fields = {"width", "height", "start_x", "start_y", "goal_x", "goal_y"}
            for i, field in ipairs(fields) do
                local number, err = canvas_number(ctx, args[i + 4], field)
                if not number then
                    return false, "Native Worker Error: " .. tostring(err)
                end
                if number % 1 ~= 0 then
                    return false, "Native Worker Error: " .. field .. " must be whole"
                end
                values[field] = number
            end
            local w, h = values.width, values.height
            if w < 1 or h < 1 or w > 64 or h > 64 then
                return false, "Native Worker Error: path dimensions must be 1..64"
            end
            if type(map) == "table" then
                local cells = {}
                for i = 1, w * h do
                    local cell = map[i]
                    if cell == nil then cell = map[tostring(i)] end
                    if cell == nil or cell == 0 or cell == false or cell == "0" then
                        cells[i] = "0"
                    elseif cell == 1 or cell == true or cell == "1" then
                        cells[i] = "1"
                    else
                        return false, "Native Worker Error: grid cells must be 0 or 1"
                    end
                end
                map = table.concat(cells)
            end
            if w < 1 or h < 1 or w > 64 or h > 64 or #map ~= w * h or
               map:find("[^01]") then
                return false, "Native Worker Error: path map must contain width*height characters of 0 or 1, at most 64x64"
            end
            for _, prefix in ipairs({"start", "goal"}) do
                local x, y = values[prefix .. "_x"], values[prefix .. "_y"]
                if x < 0 or y < 0 or x >= w or y >= h or
                   map:sub(y * w + x + 1, y * w + x + 1) == "1" then
                    return false, "Native Worker Error: " .. prefix .. " is outside the walkable map"
                end
            end
            values.map = map
        else
            return false, "Native Worker Error: expected sum or path operation"
        end
        local task, err = native_worker_launch(ctx, name, operation, values)
        if not task then return false, err end
        task.metrics.launch_ms=native_worker_now_ms()-command_started
        task.started_ms=command_started
        return true
    elseif action == "read" then
        local target = safe_trim(tostring(args[3] or ""))
        if target == "" then
            return false, "Native Worker Error: read needs a table variable"
        end
        local task = program_ctx.native_workers and program_ctx.native_workers[name]
        if task and task.phase == "running" then
            local ok, err = pcall(native_worker_poll_task, task)
            if not ok then return false, "Native Worker Error: " .. tostring(err) end
        end
        local snapshot = task and (task.result or {state = task.phase}) or
                         {state = "missing"}
        local written = update_variable_state(ctx, target, snapshot)
        if is_fatal(written) then return false, written.msg end
        return true
    elseif action == "cancel" or action == "release" then
        if name == "all" then
            if action == "release" then
                for _, task in pairs(program_ctx.native_workers or {}) do
                    task.discard = true
                    native_worker_signal_cancel(task)
                end
                native_worker_poll_all(ctx)
            else
                for _, task in pairs(program_ctx.native_workers or {}) do
                    native_worker_signal_cancel(task)
                end
            end
            return true
        end
        local task = program_ctx.native_workers and program_ctx.native_workers[name]
        if task then
            native_worker_signal_cancel(task)
            if action == "release" then
                task.discard = true
                native_worker_poll_all(ctx)
            end
        end
        return true
    end
    return false, "Native Worker Error: expected expression, label, start, get_result, cancel, remove, or stop_all"
end

-- Read-only diagnostics. Lua memory belongs to this VM, not exclusively to one
-- program; world counts include all worlds in this engine instance. No forced GC.
engine["runtime"] = function(ctx, state, args)
    if args[1]~="stats" or #args~=2 then
        return false,"Runtime Error: Expected stats | into:variable or -> | variable"
    end
    local target=tostring(args[2] or ""):match("^into:%s*(.+)$")
    if not target then return false,"Runtime Error: stats needs into:variable or -> | variable" end
    local stats={lua_kib=collectgarbage("count"),workers_running=0,workers_retained=0,
        tasks=0,handlers=0,worlds=0,objects=0,connections=0,peers=0}
    local program=ctx.native_worker_program or ctx
    for _,job in pairs(program.native_workers or {}) do
        stats.workers_retained=stats.workers_retained+1
        if job.phase=="running" or job.phase=="starting" then stats.workers_running=stats.workers_running+1 end
    end
    for _ in pairs(ctx.async_tasks or {}) do stats.tasks=stats.tasks+1 end
    for _ in pairs(ctx.input_handlers or {}) do stats.handlers=stats.handlers+1 end
    for _,world in pairs(world3d_worlds) do
        stats.worlds=stats.worlds+1
        for _ in pairs(world.objects or {}) do stats.objects=stats.objects+1 end
    end
    for _,ep in pairs(ctx.tcp_connections or {}) do
        if ep.state~="closed" then
            stats.connections=stats.connections+1
            for _ in pairs(ep.peers or {}) do stats.peers=stats.peers+1 end
        end
    end
    local result=update_variable_state(ctx,target,stats)
    if is_fatal(result) then return false,result.msg end
    return true
end

-- !module | load | path/to/game.lua
-- A module returns a factory that receives reusable renderer and command hooks.
local module_command_names = {}
engine["module"] = function(ctx, state, args)
    if tostring(args[1] or "") ~= "load" then
        return false, "Module Error: Expected load | path/to/module.lua"
    end
    local path = tostring(args[2] or "")
    if path:sub(1, 5) == "file:" then path = path:sub(6) end
    if path == "" then return false, "Module Error: Missing module path" end
    if not path:match("^%a:[/\\]") and not path:match("^[/\\]") then
        path = (ctx and ctx.program_directory or script_path()) .. path
    end
    ctx.loaded_modules = ctx.loaded_modules or {}
    if ctx.loaded_modules[path] then return true end
    local chunk, load_error = loadfile(path)
    if not chunk then return false, "Module Error: " .. tostring(load_error) end
    local ok, factory = pcall(chunk)
    if not ok then return false, "Module Error: " .. tostring(factory) end
    if type(factory) ~= "function" then
        return false, "Module Error: File must return a function"
    end
    local pending,installing,failed={},true,false
    local api = {
        obslua = obslua, ffi = ffi, frames = raymaze_frames,
        pixel = raymaze_pixel, fill = pixel_fill,
        shader_worlds = shader_worlds,
        input = {poll = input_poll},
        update_variable_state = update_variable_state,
        evaluate_math = evaluate_math, is_fatal = is_fatal,
    }
    local function install_command(name,handler,raw)
        ctx.module_commands=ctx.module_commands or {}
        ctx.module_command_raw=ctx.module_command_raw or {}
        ctx.module_commands[name]=handler
        ctx.module_command_raw[name]=raw
        if not module_command_names[name] then
            module_command_names[name]=true
            engine[name]=function(inner_ctx,inner_state,inner_args)
                local callback=inner_ctx.module_commands and inner_ctx.module_commands[name]
                if not callback then
                    return false,"Module Error: Load the module that defines '"..name.."' first"
                end
                if not (inner_ctx.module_command_raw and inner_ctx.module_command_raw[name]) then
                    local processed={}
                    for index,value in ipairs(inner_args) do
                        local result=preprocess_runtime_arg(inner_ctx,name,value)
                        if is_fatal(result) then return false,result.msg end
                        processed[index]=result
                    end
                    inner_args=processed
                end
                return callback(inner_ctx,inner_state,inner_args)
            end
        end
        -- The dispatcher receives raw arguments; evaluation belongs to the
        -- program's registration, never another program's global raw policy.
        engine_raw=engine_raw or {};engine_raw[name]=true
    end
    api.register_command = function(name, handler, raw)
        if failed then error('Module Error: Installer has failed') end
        if type(name) ~= "string" or not name:match("^[%a_][%w_]*$") or
           type(handler) ~= "function" then
            error("Module Error: Invalid command registration")
        end
        if engine[name] and not module_command_names[name] then
            error("Module Error: Command '" .. name .. "' belongs to the engine")
        end
        if installing then pending[name]={handler=handler,raw=raw==true}
        else install_command(name,handler,raw==true) end
    end
    local installed, install_error = pcall(factory, api)
    if not installed then
        failed=true
        return false, "Module Error: " .. tostring(install_error)
    end
    installing=false
    for name,command in pairs(pending) do install_command(name,command.handler,command.raw) end
    ctx.loaded_modules[path] = true
    return true
end

-- !log | property_or_var_or_msg

engine["log"] = function(src, state, args)
    local msg = args[1]
    if msg == nil then
        return true
    end

    for i = 2, #args do
        if args[i] ~= nil and tostring(args[i]):match("%S") then
            msg = tostring(msg) .. "|" .. tostring(args[i])
        end
    end

    -- already-resolved non-string values
    if type(msg) ~= "string" then
        obslua.script_log(obslua.LOG_INFO, "[4IM3-SCRIPT] " .. tostring(msg))
        return true
    end

    local trimmed = safe_trim(msg)
    if trimmed == "" then
        obslua.script_log(obslua.LOG_INFO, "[4IM3-SCRIPT] ")
        return true
    end

    -- If it looks like an expression, evaluate it first.
    local looks_like_expr =
        trimmed:match("[%+%-%*/%%<>=]") or trimmed:match("%s+and%s+") or trimmed:match("%s+or%s+") or
            trimmed:match("%.%.") or trimmed:match("^@") or trimmed:match("^source%s*%(")

    if looks_like_expr then
        local evaluated = evaluate_math(src, trimmed)
        if is_fatal(evaluated) then
            return false, evaluated.msg
        end
        obslua.script_log(obslua.LOG_INFO, "[4IM3-SCRIPT] " .. tostring(evaluated))
        return true
    end

    -- pure quoted string
    if is_quoted_string(trimmed) then
        local resolved = resolve_path(src, trimmed)
        if is_fatal(resolved) then
            return false, resolved.msg
        end
        obslua.script_log(obslua.LOG_INFO, "[4IM3-SCRIPT] " .. tostring(resolved))
        return true
    end

    -- try plain path/variable lookup
    local direct_val = resolve_path(src, trimmed)
    if not is_fatal(direct_val) and direct_val ~= nil then
        obslua.script_log(obslua.LOG_INFO, "[4IM3-SCRIPT] " .. tostring(direct_val))
        return true
    end

    -- fallback: raw text with (var) interpolation
    local success, output = pcall(function()
        return tostring(msg):gsub("%(([^%)]+)%)", function(inner_var)
            local val = resolve_path(src, safe_trim(inner_var))
            if is_fatal(val) then
                error(val.msg)
            end
            return tostring(val)
        end)
    end)

    if not success then
        return false, output
    end

    obslua.script_log(obslua.LOG_INFO, "[4IM3-SCRIPT] " .. tostring(output))
    return true
end

-- !rainbow | speed | duration
engine["rainbow"] = function(src, state, args)
    if not src.scene_item then
        return true
    end

    local speed = tonumber(args[1]) or 0.01
    local duration = parse_time(args[2] or "0ms")

    if not state.init then
        state.hue = 0
        state.start_time = os.clock()
        src.scene_item.style.grad.enable()
        state.init = true
    end

    -- Update Hue
    state.hue = state.hue + (speed * 0.1)
    if state.hue > 1 then
        state.hue = 0
    end

    -- Hue to RGB Helper
    local function h_to_rgb(h)
        local r, g, b
        local i = math.floor(h * 6)
        local f = h * 6 - i
        local q = 1 - f
        local t = f
        i = i % 6
        if i == 0 then
            r, g, b = 1, t, 0
        elseif i == 1 then
            r, g, b = q, 1, 0
        elseif i == 2 then
            r, g, b = 0, 1, t
        elseif i == 3 then
            r, g, b = 0, q, 1
        elseif i == 4 then
            r, g, b = t, 0, 1
        elseif i == 5 then
            r, g, b = 1, 0, q
        end
        return math.floor(r * 255), math.floor(g * 255), math.floor(b * 255)
    end

    local r, g, b = h_to_rgb(state.hue)
    src.scene_item.style.grad.color(r, g, b)
    if duration > 0 then
        return (os.clock() - state.start_time) * 1000 >= duration
    end
    return false
end

-- !shake | intensity | duration
engine["shake"] = function(src, state, args)
    if not src.scene_item then
        return true
    end

    local intensity = tonumber(args[1]) or 10
    local duration = parse_time(args[2] or "500ms")

    if not state.init then
        local pos = src.scene_item.pos()
        state.base_x = pos.x
        state.base_y = pos.y
        state.start_time = os.clock()
        state.init = true
    end

    local dx = math.random(-intensity, intensity)
    local dy = math.random(-intensity, intensity)

    src.scene_item.pos({
        x = state.base_x + dx,
        y = state.base_y + dy
    })

    local elapsed = (os.clock() - state.start_time) * 1000
    if duration > 0 and elapsed >= duration then
        src.scene_item.pos({
            x = state.base_x,
            y = state.base_y
        })
        return true
    end
    return false
end

-- !glitch | intensity | duration
engine["glitch"] = function(src, state, args)
    if not src.scene_item then
        return true
    end

    local intensity = tonumber(args[1]) or 20
    local duration = parse_time(args[2] or "1s")

    if not state.init then
        local pos = src.scene_item.pos()
        state.base_x, state.base_y = pos.x, pos.y
        state.start_time = os.clock()
        state.init = true
    end

    if math.random() > 0.8 then
        local dx = math.random(-intensity, intensity)
        local dy = math.random(-intensity, intensity)
        local ds = 1 + (math.random(-10, 10) / 100)

        src.scene_item.pos({
            x = state.base_x + dx,
            y = state.base_y + dy
        })
        src.scene_item.scale({
            x = ds,
            y = 1
        })
    else
        src.scene_item.pos({
            x = state.base_x,
            y = state.base_y
        })
        src.scene_item.scale({
            x = 1,
            y = 1
        })
    end

    local elapsed = (os.clock() - state.start_time) * 1000
    if duration > 0 and elapsed >= duration then
        src.scene_item.pos({
            x = state.base_x,
            y = state.base_y
        })
        src.scene_item.scale({
            x = 1,
            y = 1
        })
        return true
    end
    return false
end

-- !breathing | speed | duration
engine["breathing"] = function(src, state, args)
    if not src.scene_item then
        return true
    end

    local speed = tonumber(args[1]) or 0.05
    local duration = parse_time(args[2] or "0ms")

    if not state.init then
        state.timer = 0
        state.start_time = os.clock()
        state.init = true
        state.default_scale_x = src.scene_item.scale().x
        state.default_scale_y = src.scene_item.scale().y
    end

    state.timer = state.timer + speed
    local wave = math.sin(state.timer)

    local sx = state.default_scale_x + (wave * 0.025 + 0.025)
    local sy = state.default_scale_y + (wave * 0.025 + 0.025)
    src.scene_item.scale({
        x = sx,
        y = sy
    })

    local op = 70 + (wave * 20)

    if duration > 0 then
        return (os.clock() - state.start_time) * 1000 >= duration
    end
    return false
end

-- !dvd | speed | duration
engine["dvd"] = function(src, state, args)
    if not src.scene_item then
        return true
    end
    local speed = tonumber(args[1]) or 5
    local duration = parse_time(args[2] or "0ms")
    if not state.init then
        local pos = src.scene_item.pos()
        local bounds = obs.scene:size()
        state.x, state.y = pos.x, pos.y
        state.vx, state.vy = speed, speed
        state.w = src.scene_item.width()
        state.h = src.scene_item.height()
        state.sw, state.sh = bounds.width, bounds.height
        state.start_time = os.clock()
        state.init = true
    end
    local next_x = state.x + state.vx
    local next_y = state.y + state.vy
    if next_x <= 0 then
        next_x = 0;
        state.vx = math.abs(state.vx)
    elseif next_x >= (state.sw - state.w) then
        next_x = state.sw - state.w;
        state.vx = -math.abs(state.vx)
    end
    if next_y <= 0 then
        next_y = 0;
        state.vy = math.abs(state.vy)
    elseif next_y >= (state.sh - state.h) then
        next_y = state.sh - state.h;
        state.vy = -math.abs(state.vy)
    end
    state.x, state.y = next_x, next_y
    src.scene_item.pos({
        x = next_x,
        y = next_y
    })
    if duration > 0 then
        return (os.clock() - state.start_time) * 1000 >= duration
    end
    return false
end

-- !sway | speed | duration
engine["sway"] = function(src, state, args)
    if not src.scene_item then
        return true
    end

    local speed = tonumber(args[1]) or 0.05
    local duration = parse_time(args[2] or "0ms")

    if not state.init then
        state.timer = 0
        state.start_time = os.clock()
        state.init = true
    end

    state.timer = state.timer + speed
    local tilt = math.sin(state.timer) * 15

    src.scene_item.rot(tilt)

    if duration > 0 then
        return (os.clock() - state.start_time) * 1000 >= duration
    end
    return false
end

engine["spawn"] = function(src, state, args)
    local target_label = clean_label_name(args[1])
    local label_target, label_queue, label_table = active_label_target(src, target_label)
    local save_var = nil
    local arg2 = type(args[2]) == "string" and args[2]:match("^%s*(.-)%s*$") or args[2]
    if arg2 == "->" and args[3] then
        save_var = type(args[3]) == "string" and args[3]:match("^%s*(.-)%s*$") or args[3]
    end

    src.next_context_id = (src.next_context_id or 1)
    local new_ctx = src.next_context_id
    src.next_context_id = src.next_context_id + 1

    local interrupt_thread = nil

    if type(target_label) == "string" and target_label:match("^%s*%{[%s%S]*%}%s*$") then
        local block_code = target_label:match("^%s*(%b{})%s*$")
        local inner_code = block_code:sub(2, -2)
        local sub_queue, sub_labels = compile_block_text(src, inner_code, new_ctx)

        local thread_name = obs.utils.get_unique_id(2)
        if save_var then
            update_variable_state(src, save_var, thread_name)
        end

        interrupt_thread = build_thread_task(src, {
            queue = sub_queue,
            labels = sub_labels,
            current_idx = 1,
            name = thread_name,
            context_id = new_ctx,
            active_source = nil,
            active_sources = nil,
            step_budget = 10
        })

    elseif label_target then
        local tgt = label_target
        local start_idx = type(tgt) == "table" and tgt.index or tgt
        local start_ctx = type(tgt) == "table" and tgt.ctx or 0

        local thread_name = target_label
        if save_var then
            thread_name = target_label .. "_" .. obs.utils.get_unique_id(2)
            update_variable_state(src, save_var, thread_name)
        end

        interrupt_thread = build_thread_task(src, {
            queue = (type(tgt) == "table" and tgt.queue) or label_queue,
            labels = (type(tgt) == "table" and tgt.labels) or label_table,
            current_idx = start_idx,
            name = thread_name,
            context_id = start_ctx,
            active_source = nil,
            active_sources = nil,
            step_budget = 10
        })
    end

    if interrupt_thread then
        push_thread(src, interrupt_thread)
    end

    return true
end
engine["run"] = function(src, state, args)
    local target_label = clean_label_name(args[1])
    local label_target, label_queue, label_table = active_label_target(src, target_label)
    local interrupt_thread = nil
    local run_ctx = src.context_id or 0

    if type(target_label) == "string" and target_label:match("^%s*%{[%s%S]*%}%s*$") then
        local block_code = target_label:match("^%s*(%b{})%s*$")
        local inner_code = block_code:sub(2, -2)
        local sub_queue, sub_labels = compile_block_text(src, inner_code, run_ctx)

        interrupt_thread = build_thread_task(src, {
            queue = sub_queue,
            labels = sub_labels,
            current_idx = 1,
            name = obs.utils.get_unique_id(2),
            context_id = run_ctx,
            active_source = src.scene_item,
            active_sources = src.active_sources,
            step_budget = 10
        })

    elseif label_target then
        local start_idx = type(label_target) == "table" and label_target.index or label_target
        local start_ctx = type(label_target) == "table" and label_target.ctx or 0

        interrupt_thread = build_thread_task(src, {
            queue = (type(label_target) == "table" and label_target.queue) or label_queue,
            labels = (type(label_target) == "table" and label_target.labels) or label_table,
            current_idx = start_idx,
            name = target_label,
            context_id = start_ctx,
            active_source = src.scene_item,
            active_sources = src.active_sources,
            step_budget = 10
        })
    end

    if not interrupt_thread then
        return true
    end

    if (src.run_depth or 0) >= 16 then
        return false, "Run Error: Nested !run depth exceeded 16"
    end
    src.run_depth = (src.run_depth or 0) + 1
    local deadline_ms = src.tick_deadline_ms or (engine_tick_now_ms() + (src.tick_budget_ms or 6))
    local still_alive = true
    if engine_tick_now_ms() < deadline_ms then
        still_alive = step_thread_task(src, interrupt_thread, 50, deadline_ms)
    end
    src.run_depth = src.run_depth - 1
    if still_alive then
        push_thread(src, interrupt_thread)
    end

    return true
end
-- Both names start cooperative script tasks. The independent form starts with
-- a new context and no selected source; neither form creates an OS thread.
engine["start_task"] = engine["run"]
engine["start_independent_task"] = engine["spawn"]

-- !await | thread_name |+|
-- !await | (player_hp <= 0) |+|
engine["await"] = function(src, state, args)
    local target = args[1]
    if type(target) ~= "string" then
        target = tostring(target)
    end
    target = target:match("^%s*(.-)%s*$")
    local is_expr = false
    if target:match("[%+%-*/<>=!]") or target:match(" and ") or target:match(" or ") then
        is_expr = true
    end

    if is_expr then
        local res = evaluate_math(src, target)
        if type(res) == "table" and res._is_fatal_error then
            return false, res.msg
        end
        if type(res) == "string" and src.async_tasks then
            for _, task in ipairs(src.async_tasks) do
                if task.name == res then
                    return false
                end
            end
            return true
        end

        local is_true = (res == true) or (type(res) == "number" and res > 0)
        if not is_true and type(res) == "string" and string.lower(res) == "true" then
            is_true = true
        end

        if is_true then
            return true
        else
            return false
        end
    end
    if src.async_tasks then
        local pv = resolve_path(src, target)
        for _, task in ipairs(src.async_tasks) do
            if task.name == pv or task.name == target then
                return false
            end
        end
    end

    return true
end

-- !stop | target_source OR label_name OR all
engine["stop"] = function(src, state, args)
    local target = resolve_path(src, args[1])
    if target == nil or is_fatal(target) then
        target = args[1]
    end
    if target == nil or target == "" then
        return true
    end
    if target == "all" then
        if ENGINE_UI then ENGINE_UI.clear(src) end
        input_host.clear_pending(src)
        if src.input_handlers then INPUT_EVENTS.clear(src) end
        if src.tcp_connections then TCP.close_all(src) end
        if src.input_preview_menu_blocked or src.input_projector_controls then input_preview_menu_release(src) end
        if src.native_workers then native_worker_cancel_all(src) end
        for _,world in pairs(world3d_worlds or {}) do world3d_cancel_builds(world) end
        for _, task in ipairs(src.async_tasks or {}) do
            task.cancelled = true
            if task.type == "LIFETIME" then
                cleanup_lifetime_task(src, task)
            end
        end
        src.async_tasks = {}
        src.async_resume_index = nil
        src.async_resume_task = nil
        src.current_idx = #src.queue + 1
        src.call_stack = {}
        src.for_frames = {}
        return true
    end
    if not src.async_tasks then
        return true
    end

    for i = #src.async_tasks, 1, -1 do
        local task = src.async_tasks[i]
        local task_targets = task.active_sources or {task.active_source}

        local kill_thread = false
        if task.name and task.name == target then
            kill_thread = true
        else
            for _, task_item in ipairs(task_targets) do
                if task_item then
                    local item_name
                    pcall(function()
                        item_name = task_item.get_name()
                    end)
                    if task_item == target or item_name == target or
                        (task_item.template_id and task_item.template_id == target) then
                        kill_thread = true
                        break
                    end
                end
            end
        end

        if kill_thread then
            task.cancelled = true
            table.remove(src.async_tasks, i)
        end
    end
    return true
end
engine["then"] = function(src, state, args)
    local cmd = args[1]
    local cmd_args = {};
    for i = 2, #args do
        table.insert(cmd_args, args[i])
    end
    local exe = compile_line(cmd, cmd_args)
    if exe then
        return exe(src, state)
    end
    return true
end
engine["execute_command"] = engine["then"]

-- !camera_shake | intensity | duration
engine["camera_shake"] = function(src, state, args)
    local intensity = tonumber(args[1]) or 10
    local duration = parse_time(args[2] or "200ms")
    if not state.init then
        state.init = true;
        state.start_time = os.clock()
        if src.active_sources and src.active_sources[1] then
            state.cam = src.active_sources[1]
            state.ox = state.cam.pos().x;
            state.oy = state.cam.pos().y
        elseif src.scene_item then
            state.cam = src.scene_item
            state.ox = state.cam.pos().x;
            state.oy = state.cam.pos().y
        end
    end
    if state.cam then
        local dx = math.random(-intensity, intensity)
        local dy = math.random(-intensity, intensity)
        state.cam.pos({
            x = state.ox + dx,
            y = state.oy + dy
        })
    end
    if (os.clock() - state.start_time) * 1000 >= duration then
        if state.cam then
            state.cam.pos({
                x = state.ox,
                y = state.oy
            })
        end
        return true
    end
    return false
end

engine["path"] = function(src, state, args)
    local targets = src.active_sources or {src.scene_item}
    if #targets == 0 then
        return true
    end
    if not state.init then
        state.configs = {}
        state.duration = parse_time(args[3]) or 1000
        state.start_time = os.clock()
        state.easing = args[4] or "quad_out"
        for _, item in ipairs(targets) do
            local start_pos = item.pos()
            local p1 = {
                x = start_pos.x,
                y = start_pos.y
            }
            for _, pair in ipairs(safe_split(args[1])) do
                local k, v = string.match(pair, "([^:]+):(.+)")
                if k and v then
                    k = k:match("^%s*(.-)%s*$")
                    v = v:match("^%s*(.-)%s*$")
                    if k == "x" then
                        p1.x = tonumber(resolve_path(src, v)) or p1.x
                    end
                    if k == "y" then
                        p1.y = tonumber(resolve_path(src, v)) or p1.y
                    end
                end
            end
            local p2 = {
                x = start_pos.x,
                y = start_pos.y
            }
            for _, pair in ipairs(safe_split(args[2])) do
                local k, v = string.match(pair, "([^:]+):(.+)")
                if k and v then
                    k = k:match("^%s*(.-)%s*$")
                    v = v:match("^%s*(.-)%s*$")
                    if k == "x" then
                        p2.x = tonumber(resolve_path(src, v)) or p2.x
                    end
                    if k == "y" then
                        p2.y = tonumber(resolve_path(src, v)) or p2.y
                    end
                end
            end
            table.insert(state.configs, {
                item = item,
                p0 = start_pos,
                p1 = p1,
                p2 = p2
            })
        end
        state.init = true
    end

    local elapsed = (os.clock() - state.start_time) * 1000
    local t = math.min(elapsed / state.duration, 1)

    local ease_func = EASING_FUNCS[state.easing] or EASING_FUNCS.linear
    local eased_t = ease_func(t)

    for _, config in ipairs(state.configs) do
        local inv_t = 1 - eased_t
        local x = (inv_t ^ 2 * config.p0.x) + (2 * inv_t * eased_t * config.p1.x) + (eased_t ^ 2 * config.p2.x)
        local y = (inv_t ^ 2 * config.p0.y) + (2 * inv_t * eased_t * config.p1.y) + (eased_t ^ 2 * config.p2.y)
        config.item.pos({
            x = x,
            y = y
        })
    end
    return t >= 1
end

-- !pin | parent_source | offsets (x:50, y:10)
-- To unpin, use !pin|none
engine["pin"] = function(src, state, args)
    local targets = src.active_sources or {src.scene_item}
    if #targets == 0 then
        return true
    end
    if not src.pinned_sources then
        src.pinned_sources = {}
    end
    local parent_arg = args[1]
    local offset_arg = args[2]
    if not parent_arg or parent_arg == "none" then
        for _, item in ipairs(targets) do
            src.pinned_sources[tostring(item.data)] = nil
        end
        return true
    end
    local parent_item = nil
    local resolved_parent = resolve_path(src, parent_arg)
    if type(resolved_parent) == "table" and resolved_parent.pos then
        parent_item = resolved_parent
    else
        parent_item = SCRIPT_FUNCS.source(src, resolved_parent)
    end
    if not parent_item then
        return true
    end
    local ox, oy = 0, 0
    if offset_arg then
        for _, pair in ipairs(safe_split(offset_arg)) do
            local k, v = string.match(pair, "([^:]+):(.+)")
            if k and v then
                k = k:match("^%s*(.-)%s*$")
                v = v:match("^%s*(.-)%s*$")
                if k == "x" then
                    ox = tonumber(resolve_path(src, v)) or 0
                end
                if k == "y" then
                    oy = tonumber(resolve_path(src, v)) or 0
                end
            end
        end
    end
    for _, item in ipairs(targets) do
        src.pinned_sources[tostring(item.data)] = {
            child = item,
            parent = parent_item,
            ox = ox,
            oy = oy
        }
    end

    return true
end

-- !spiral | center_x, center_y | start_radius | rotations | duration | easing
engine["spiral"] = function(src, state, args)
    local targets = src.active_sources or {src.scene_item}
    if #targets == 0 then
        return true
    end

    if not state.init then
        state.configs = {}
        state.duration = parse_time(args[4]) or 1000
        state.start_time = os.clock()
        state.easing = args[5] or "quad_out"
        local cp_raw = safe_split(args[1])
        state.cx = tonumber(resolve_path(src, cp_raw[1]:match("x:(.+)"))) or 960
        state.cy = tonumber(resolve_path(src, cp_raw[2]:match("y:(.+)"))) or 540
        state.start_r = tonumber(resolve_path(src, args[2])) or 500
        state.rotations = tonumber(resolve_path(src, args[3])) or 2
        state.init = true
    end
    local elapsed = (os.clock() - state.start_time) * 1000
    local t = math.min(elapsed / state.duration, 1)
    local ease_func = EASING_FUNCS[state.easing] or EASING_FUNCS.linear
    local eased_t = ease_func(t)
    local current_r = state.start_r * (1 - eased_t)
    local angle = eased_t * (state.rotations * 2 * math.pi)
    for _, item in ipairs(targets) do
        local x = state.cx + math.cos(angle) * current_r
        local y = state.cy + math.sin(angle) * current_r
        item.pos({
            x = x,
            y = y
        })
    end

    return t >= 1
end

-- !fade | target_opacity | duration | easing
engine["fade"] = function(src, state, args)
    local targets = src.active_sources or {src.scene_item}
    if #targets == 0 then
        return true
    end
    if not state.init then
        state.configs = {}
        state.duration = parse_time(args[2]) or 1000
        state.start_time = os.clock()
        state.easing = args[3] or "linear"
        for _, item in ipairs(targets) do
            local current_opacity = item.opacity() or 1
            local target_opacity = parse_value(src, current_opacity, args[1])

            table.insert(state.configs, {
                item = item,
                start = current_opacity,
                target = target_opacity
            })
        end
        state.init = true
    end
    local elapsed = (os.clock() - state.start_time) * 1000
    local t = math.min(elapsed / state.duration, 1)
    local ease_func = EASING_FUNCS[state.easing] or EASING_FUNCS.linear
    local eased_t = ease_func(t)
    for _, config in ipairs(state.configs) do
        local val = config.start + (config.target - config.start) * eased_t
        config.item.opacity(val)
    end

    return t >= 1
end
-- !add_color | red | green | blue (adds an OBS color filter to selected sources)
-- Legacy alias: !foreground.
engine["foreground"] = function(src, state, args)
    local r = tonumber(args[1]) or 0
    local g = tonumber(args[2]) or 0
    local b = tonumber(args[3]) or 0

    -- OBS expects color integers in 0xBBGGRR format (Blue is the highest byte)
    local color_val = math.floor(r) + (math.floor(g) * 256) + (math.floor(b) * 65536)

    local targets = src.active_sources or {src.scene_item}
    if #targets == 0 then
        return true
    end

    for _, item in ipairs(targets) do
        if item and item.get_source then
            local obs_source = item.get_source()
            if obs_source then
                local filter_name = "4IM3_ColorAdd"
                local filter = obslua.obs_source_get_filter_by_name(obs_source, filter_name)
                if not filter then
                    local settings = obslua.obs_data_create()
                    filter = obslua.obs_source_create_private("color_filter_v2", filter_name, settings)
                    obslua.obs_source_filter_add(obs_source, filter)
                    obslua.obs_data_release(settings)
                    obslua.obs_source_release(filter)
                    filter = obslua.obs_source_get_filter_by_name(obs_source, filter_name)
                end
                if filter then
                    local settings = obslua.obs_source_get_settings(filter)
                    obslua.obs_data_set_int(settings, "color_add", color_val)
                    obslua.obs_source_update(filter, settings)
                    obslua.obs_data_release(settings)
                    obslua.obs_source_release(filter)
                end
            end
        end
    end
    return true
end
engine["add_color"] = engine["foreground"]
engine["sound"] = function(src, state, args)
    local target_name = resolve_path(src, args[1])
    if target_name == nil or is_fatal(target_name) then
        target_name = args[1]
    end
    local action = resolve_path(src, args[2])
    if action == nil or is_fatal(action) then
        action = args[2]
    end
    if type(target_name) ~= "string" then
        return false, "Sound Error: Expected a media source name"
    end
    local source = obslua.obs_get_source_by_name(target_name)
    if not source then
        return true
    end
    if action == "play" then
        obslua.obs_source_media_restart(source)
        obslua.obs_source_release(source)
        return true
    elseif action == "pause" then
        obslua.obs_source_media_play_pause(source, true)
        obslua.obs_source_release(source)
        return true
    elseif action == "stop" then
        obslua.obs_source_media_stop(source)
        obslua.obs_source_release(source)
        return true
    end
    local target_val = tonumber(resolve_path(src, args[3]) or args[3]) or 0
    local raw_time = resolve_path(src, args[4]) or args[4]
    if raw_time == nil or raw_time == "" then
        if action == "volume" then
            obslua.obs_source_set_volume(source, target_val)
        end
        obslua.obs_source_release(source)
        return true
    end
    if not state.initialized then
        state.duration = parse_time(raw_time)
        if state.duration <= 0 then
            state.duration = 0.001
        end
        state.elapsed = 0
        state.target_val = target_val

        if action == "volume" then
            state.start_val = obslua.obs_source_get_volume(source)
        else
            state.start_val = 0
        end
        state.initialized = true
    end
    local dt = (src.active_scope and src.active_scope["tick"]) or 0.016
    state.elapsed = state.elapsed + dt
    local progress = math.min(state.elapsed / state.duration, 1.0)
    local current_val = state.start_val + ((state.target_val - state.start_val) * progress)
    if action == "volume" then
        obslua.obs_source_set_volume(source, current_val)
    end
    obslua.obs_source_release(source)
    if progress >= 1.0 then
        return true
    end
    return false
end
-- !spawn_repeatedly | target_source | max_count | interval_ms | callback-label |+|
-- Legacy alias: !emitter.
engine["emitter"] = function(ctx, state, args)
    local target_name = resolve_path(ctx, args[1]) or args[1]
    local count = tonumber(resolve_path(ctx, args[2])) or 10
    local raw_interval = resolve_path(ctx, args[3]) or args[3]
    local interval = parse_time(raw_interval) or 100
    local setup_label = args[4]
    if not ctx.async_tasks then
        ctx.async_tasks = {}
    end
    local emitter_task = {
        type = "EMITTER",
        target_name = target_name,
        max_count = count,
        spawned = 0,
        interval = interval,
        last_spawn_time = engine_tick_now_ms(),
        setup_label = setup_label,
        name = setup_label,
        target_label = setup_label,
        queue = ctx.queue,
        labels = ctx.labels
    }
    table.insert(ctx.async_tasks, emitter_task)
    return true
end
engine["spawn_repeatedly"] = engine["emitter"]
-- !despawn | duration_ms |+|
engine["despawn"] = function(src, state, args)
    local targets = src.active_sources or {src.scene_item}
    local raw_time = resolve_path(src, args[1]) or args[1]
    local duration = parse_time(raw_time) or 1000
    if not src.async_tasks then
        src.async_tasks = {}
    end
    for _, item in ipairs(targets) do
        table.insert(src.async_tasks, {
            type = "LIFETIME",
            item = item,
            expire_time = engine_tick_now_ms() + duration
        })
    end
    return true
end
engine["remove_after"] = engine["despawn"]
-- [[ PREDEFINED FUNCTIONNS ]]
SCRIPT_FUNCS = {
    fps = function()
        if type(obslua.obs_get_active_fps)~="function" then return 0 end
        local ok,value=pcall(obslua.obs_get_active_fps)
        if ok and type(value)=="number" and value==value and value>0 and value<math.huge then
            return value
        end
        return 0
    end,
    alert = function(src, msg)
        obslua.script_log(obslua.LOG_WARNING, "[4IM3-SCRIPT] " .. tostring(msg))
        return 0
    end,
    dist = function(src, x1, y1, x2, y2)
        local dx = (tonumber(x1) or 0) - (tonumber(x2) or 0)
        local dy = (tonumber(y1) or 0) - (tonumber(y2) or 0)
        return math.sqrt(dx * dx + dy * dy)
    end,
    mouse = function()
        local x, y
        if host_os == "Windows" then x, y = input_host.screen_pointer()
        else x, y = input_host.pointer() end
        if not x then error("mouse() needs an available " .. tostring(host_os) ..
            " pointer backend", 2) end
        return {x = x, y = y}
    end,
    source = function(ctx, name)
        ctx=ctx or src
        if not name then
            return nil
        end
        if type(name) == "table" and name.data then
            return name
        end

        local resolved_name = resolve_path(ctx, name)
        if resolved_name ~= nil and not is_fatal(resolved_name) then
            name = resolved_name
        end

        if type(name) == "table" and name.data ~= nil then
            return name
        elseif type(name) ~= "string" then
            return nil
        elseif type(name) == "string" and ctx.templates and ctx.templates[name] then
            return ctx.templates[name]
        end
        if not ctx.source_cache then
            ctx.source_cache = {}
        end
        local cached=ctx.source_cache[name]
        if cached then
            if cached.data and not obslua.obs_source_removed(cached.get_source()) then return cached end
            -- Deleted wrappers have already released their native scene item.
            -- Do not ask them for sources or retain stale unload records.
            if cached.data then cached.free() end
            ctx.source_cache[name]=nil
            for i=#(obs._unload or {}),1,-1 do
                if obs._unload[i]==cached then table.remove(obs._unload,i) end
            end
        end
        local asource = obs.front.source(name)
        if not asource or not asource.data then
            return nil
        end
        table.insert(obs._unload, asource)
        ctx.source_cache[name] = asource
        return asource
    end,

    clone = function(ctx, auto_delete)
        if not ctx.scene_item then
            return nil
        end
        local original_source = ctx.scene_item.get_source()
        if not original_source then
            return nil
        end
        local unique_name = obslua.obs_source_get_name(original_source) .. "_clone_" .. obs.utils.get_unique_id()
        local scene = obs.scene:get_scene()
        if not scene then
            return nil
        end
        local new_source = obslua.obs_source_duplicate(original_source, unique_name, false)
        if not new_source then
            scene.free();
            return nil
        end
        obslua.obs_scene_add(scene.data, new_source)
        local wrapped = scene.get(unique_name)
        obslua.obs_source_release(new_source)
        scene.free()
        if wrapped and wrapped.data then
            wrapped.transform(ctx.scene_item.transform())
            wrapped.crop(ctx.scene_item.crop())
            if ctx.scene_item.template_id then
                wrapped.template_id = ctx.scene_item.template_id
            end
        else
            return nil
        end
        local unload_cleanup = function()
            if auto_delete then
                wrapped.remove()
            else
                return wrapped.free()
            end
        end
        wrapped._unload_cleanup = unload_cleanup
        table.insert(obs._unload, unload_cleanup)
        obslua.obs_sceneitem_set_locked(wrapped.data, true)
        if auto_delete then
            table.insert(auto_cleanup, wrapped)
        end

        table.insert(all_source_clones, wrapped)
        return wrapped
    end,

    delete_source = function(src)
        if src.scene_item and src.scene_item.data and src.scene_item.remove then
            src.scene_item.remove()
        end
        return 0
    end
}

-- @mass(optional_name, optional_density)
SCRIPT_FUNCS["mass"] = function(src, input, density)
    local num = tonumber(input)
    if num then
        return num
    end

    local target = (not input or input == "") and src.scene_item or SCRIPT_FUNCS.source(src, input)
    if not target then
        return 1
    end

    local d = tonumber(density) or 0.001
    local w = target.width() or 0
    local h = target.height() or 0

    return w * h * d
end

SCRIPT_FUNCS["math"] = {}
for key, fn in pairs(math) do
    if type(fn) == "function" then
        local wrapped = function(sr, ...)
            return fn(...)
        end
        SCRIPT_FUNCS[key] = wrapped
        SCRIPT_FUNCS["math"][key] = wrapped
    end
end

-- Pure swept-circle query. Coordinates describe the end of a movement step;
-- old_* defaults to that endpoint. Inputs are read-only and results are fresh.
SCRIPT_FUNCS.math.sweep_circles=function(ctx,a,b,plane)
    plane=plane or "xy"
    if plane~="xy" and plane~="xz" then error("Collision Error: plane must be xy or xz") end
    if type(a)~="table" or type(b)~="table" then error("Collision Error: two circle records are required") end
    local axis=plane=="xz" and "z" or "y"
    local function number(shape,key,fallback)
        local value=shape[key]
        if value==nil then value=fallback end
        if type(value)~="number" or value~=value or math.abs(value)==math.huge then
            error("Collision Error: "..key.." must be a finite number")
        end
        return value
    end
    local ax,ay=number(a,"x"),number(a,axis)
    local bx,by=number(b,"x"),number(b,axis)
    local aox,aoy=number(a,"old_x",ax),number(a,"old_"..axis,ay)
    local box,boy=number(b,"old_x",bx),number(b,"old_"..axis,by)
    local ar,br=number(a,"radius"),number(b,"radius")
    if ar<=0 or br<=0 then error("Collision Error: radius must be above zero") end
    local rx,ry=aox-box,aoy-boy
    local dx,dy=(ax-aox)-(bx-box),(ay-aoy)-(by-boy)
    local scale=math.max(math.abs(rx),math.abs(ry),math.abs(dx),math.abs(dy),ar,br)
    if scale==math.huge then error("Collision Error: movement difference overflow") end
    -- Scale relative coordinates before squaring to avoid overflow/underflow.
    rx,ry,dx,dy=rx/scale,ry/scale,dx/scale,dy/scale
    local radius=ar/scale+br/scale
    local movement,dot=dx*dx+dy*dy,rx*dx+ry*dy
    local t=movement>0 and math.max(0,math.min(1,-dot/movement)) or 0
    local cx,cy=rx+dx*t,ry+dy*t
    local result={hit=0,time=1,normal_x=0,normal_y=0,normal_z=0,
        penetration=0,correction_x=0,correction_y=0,correction_z=0}
    if cx*cx+cy*cy>radius*radius then return result end
    t=0
    if rx*rx+ry*ry>radius*radius and movement>0 then
        local discriminant=math.max(0,dot*dot-movement*(rx*rx+ry*ry-radius*radius))
        t=math.max(0,math.min(1,(-dot-math.sqrt(discriminant))/movement))
    end
    local nx,ny=rx+dx*t,ry+dy*t
    local length=math.sqrt(nx*nx+ny*ny)
    if length==0 then nx,ny,length=1,0,1 end
    nx,ny=nx/length,ny/length
    local penetration=math.max(0,radius-((rx+dx)*nx+(ry+dy)*ny))*scale
    if penetration==math.huge then error("Collision Error: separation overflow") end
    result.hit,result.time,result.penetration=1,t,penetration
    result.normal_x,result["normal_"..axis]=nx,ny
    result.correction_x,result["correction_"..axis]=nx*(penetration/2),ny*(penetration/2)
    return result
end

function make_fatal(msg)
    return {
        _is_fatal_error = true,
        msg = tostring(msg)
    }
end

function is_fatal(v)
    return type(v) == "table" and v._is_fatal_error == true
end

function safe_trim(s)
    if type(s) ~= "string" then
        return s
    end
    return s:match("^%s*(.-)%s*$")
end

function is_quoted_string(s)
    if type(s)~="string" or #s<2 then return false end
    local quote=s:sub(1,1)
    if (quote~='"' and quote~="'") or s:sub(-1)~=quote then return false end
    local start=2
    while true do
        local closing=s:find(quote,start,true)
        if not closing then return false end
        local slashes,j=0,closing-1
        while j>=1 and s:sub(j,j)=="\\" do slashes=slashes+1;j=j-1 end
        if slashes%2==0 then return closing==#s end
        start=closing+1
    end
end

function unquote_string(s)
    if not is_quoted_string(s) then
        return s
    end
    return s:sub(2, -2)
end

function is_time_literal(s)
    return type(s) == "string" and
               (s:match("^[%+%-]?%d+%.?%d*ms$") or s:match("^[%+%-]?%d+%.?%d*s$") or s:match("^[%+%-]?%d+%.?%d*mi$") or
                   s:match("^[%+%-]?%d+%.?%d*hr$"))
end

function is_plain_identifier(s)
    return type(s) == "string" and s:match("^[A-Za-z_][%w_]*$") ~= nil
end

function is_path_like(s)
    return type(s) == "string" and (s:match("^[A-Za-z_][%w_%.%[%]\"'%(%)]*$") ~= nil)
end

-- A complete value lookup, rather than an expression starting with one.
-- Operators inside brackets belong to the index. Classifying does not read it.
function is_complete_value_path(text)
    if type(text)~="string" then return false end
    local root,at=text:match("^([A-Za-z_][%w_]*)()")
    if not root or root=="math" or root=="string" then return false end
    local accessor=false
    local function balanced(start,open,close)
        local depth,quote,escaped=0,nil,false
        for i=start,#text do
            local ch=text:sub(i,i)
            if quote then
                if escaped then escaped=false
                elseif ch=="\\" then escaped=true
                elseif ch==quote then quote=nil end
            elseif ch=='"' or ch=="'" then quote=ch
            elseif ch==open then depth=depth+1
            elseif ch==close then
                depth=depth-1
                if depth==0 then return i+1 end
            end
        end
    end
    while at<=#text do
        local ch=text:sub(at,at)
        if ch=="[" then
            at=balanced(at,"[","]")
            if not at then return false end
        elseif ch=="." then
            if text:sub(at+1,at+1)=="(" then
                at=balanced(at+1,"(",")")
                if not at then return false end
            else
                local field,after=text:match("^%.([A-Za-z_][%w_]*)()",at)
                if not field then return false end
                at=after
            end
        elseif ch=="(" and text:sub(at-1,at-1)=="_" then
            at=balanced(at,"(",")")
            if not at then return false end
        else return false end
        accessor=true
    end
    return accessor
end

function split_args_safe(str)
    if not str or str == "" then
        return {}
    end
    local out = {}
    local buf = {}
    local depth_paren, depth_brace, depth_bracket = 0, 0, 0
    local in_string = false
    local quote = nil
    local escaped = false

    local function push()
        table.insert(out, safe_trim(table.concat(buf)))
        buf = {}
    end

    for i = 1, #str do
        local c = str:sub(i, i)

        if in_string then
            table.insert(buf, c)
            if escaped then
                escaped = false
            elseif c == "\\" then
                escaped = true
            elseif c == quote then
                in_string = false
                quote = nil
            end
        else
            if c == '"' or c == "'" then
                in_string = true
                quote = c
                table.insert(buf, c)
            elseif c == "(" then
                depth_paren = depth_paren + 1
                table.insert(buf, c)
            elseif c == ")" then
                depth_paren = depth_paren - 1
                table.insert(buf, c)
            elseif c == "{" then
                depth_brace = depth_brace + 1
                table.insert(buf, c)
            elseif c == "}" then
                depth_brace = depth_brace - 1
                table.insert(buf, c)
            elseif c == "[" then
                depth_bracket = depth_bracket + 1
                table.insert(buf, c)
            elseif c == "]" then
                depth_bracket = depth_bracket - 1
                table.insert(buf, c)
            elseif c == "," and depth_paren == 0 and depth_brace == 0 and depth_bracket == 0 then
                push()
            else
                table.insert(buf, c)
            end
        end
    end

    if #buf > 0 then
        push()
    end
    return out
end

function resolve_pointer_keys(src, path)
    if type(path) ~= "string" then
        return {path}
    end
    path = safe_trim(path)

    if path == "" then
        return {}
    end
    -- The common record.field read needs no balanced-accessor scanner.
    -- Return fresh keys: assignment callers must never share mutable state.
    local simple_root,simple_field=path:match("^([A-Za-z_][%w_]*)%.([A-Za-z_][%w_]*)$")
    if simple_root then return {simple_root,simple_field} end
    if path:match("^[A-Za-z_][%w_]*$") then return {path} end
    local keys = {}
    local root = path:match("^([^%.%[]+)")
    if not root then
        return {path}
    end
    table.insert(keys, root)

    local i = #root + 1
    local len = #path

    local function read_balanced(start_i, open_ch, close_ch)
        local depth = 0
        local in_string = false
        local quote = nil
        local escaped = false

        for j = start_i, len do
            local ch = path:sub(j, j)

            if in_string then
                if escaped then
                    escaped = false
                elseif ch == "\\" then
                    escaped = true
                elseif ch == quote then
                    in_string = false
                    quote = nil
                end
            else
                if ch == '"' or ch == "'" then
                    in_string = true
                    quote = ch
                elseif ch == open_ch then
                    depth = depth + 1
                elseif ch == close_ch then
                    depth = depth - 1
                    if depth == 0 then
                        return path:sub(start_i + 1, j - 1), j
                    end
                end
            end
        end

        return nil, nil
    end

    while i <= len do
        local ch = path:sub(i, i)

        if ch == "." then
            local next_ch = path:sub(i + 1, i + 1)

            -- support .(expr) dynamic property access
            if next_ch == "(" then
                local inner, close_i = read_balanced(i + 1, "(", ")")
                if not inner then
                    return make_fatal and make_fatal("Unclosed dynamic dot accessor in path: " .. tostring(path)) or {
                        _is_fatal_error = true,
                        msg = "Unclosed dynamic dot accessor in path: " .. tostring(path)
                    }
                end

                local evaluated = evaluate_math(src, inner)
                if is_fatal and is_fatal(evaluated) then
                    return evaluated
                end

                table.insert(keys, tonumber(evaluated) or tostring(evaluated))
                i = close_i + 1

            else
                local actual = path:match("^%.([A-Za-z_][%w_]*)", i)
                if actual then
                    local num_key = tonumber(actual)
                    table.insert(keys, num_key or actual)

                    -- IMPORTANT:
                    -- +1 for the dot, +#actual for the identifier
                    i = i + 1 + #actual
                else
                    return make_fatal("Invalid dot accessor near: " .. tostring(path:sub(i)))
                end
            end

        elseif ch == "[" then
            local inner, close_i = read_balanced(i, "[", "]")
            if not inner then
                return make_fatal and make_fatal("Unclosed bracket accessor in path: " .. tostring(path)) or {
                    _is_fatal_error = true,
                    msg = "Unclosed bracket accessor in path: " .. tostring(path)
                }
            end

            inner = safe_trim(inner)
            local clean_inner = inner:match('^"(.*)"$') or inner:match("^'(.*)'$")

            if clean_inner ~= nil then
                table.insert(keys, clean_inner)
            else
                local evaluated_key = evaluate_math(src, inner)
                if is_fatal and is_fatal(evaluated_key) then
                    return evaluated_key
                end
                local num_key = tonumber(evaluated_key)
                table.insert(keys, num_key or evaluated_key)
            end

            i = close_i + 1

        else
            return make_fatal and
                       make_fatal("Invalid character in path: " .. tostring(ch) .. " inside " .. tostring(path)) or {
                _is_fatal_error = true,
                msg = "Invalid character in path: " .. tostring(ch) .. " inside " .. tostring(path)
            }
        end
    end

    return keys
end

function resolve_active_object_path(src, path)
    -- obslua.script_log(
    --     obslua.LOG_WARNING,
    --     "[DEBUG OBJ PATH] path=" .. tostring(path) ..
    --     " active_source=" .. tostring(src and src.active_source) ..
    --     " scene_item=" .. tostring(src and src.scene_item) ..
    --     " active_sources_1=" .. tostring(src and src.active_sources and src.active_sources[1])
    -- )
    if type(path) ~= "string" then
        return nil
    end

    local item = nil
    if src then
        item = (src.active_sources and src.active_sources[1]) or src.active_source or src.scene_item or
                   src.original_item
    end

    if not item then
        return nil
    end

    local root, child = path:match("^([A-Za-z_][%w_]*)%.([A-Za-z_][%w_]*)$")
    local single = path:match("^([A-Za-z_][%w_]*)$")

    local ok, result

    if root == "pos" and (child == "x" or child == "y") and item.pos then
        ok, result = pcall(function()
            local p = item.pos()
            return p and p[child] or nil
        end)
        if ok and result ~= nil then
            return result
        end
    end

    if root == "scale" and (child == "x" or child == "y") and item.scale then
        ok, result = pcall(function()
            local s = item.scale()
            return s and s[child] or nil
        end)
        if ok and result ~= nil then
            return result
        end
    end

    if single == "rot" and item.rot then
        ok, result = pcall(function()
            return item.rot()
        end)
        if ok and result ~= nil then
            return result
        end
    end

    if single == "width" and item.width then
        ok, result = pcall(function()
            return item.width()
        end)
        if ok and result ~= nil then
            return result
        end
    end

    if single == "height" and item.height then
        ok, result = pcall(function()
            return item.height()
        end)
        if ok and result ~= nil then
            return result
        end
    end

    return nil
end

function resolve_path(src, path)
    if path == nil then
        return nil
    end
    if type(path) ~= "string" then
        return path
    end

    local trimmed = safe_trim(path)
    local ok, expanded = pcall(function()
        return expand_dynamic_path(src, trimmed)
    end)
    if not ok then
        return make_fatal(expanded)
    end
    trimmed = expanded
    if trimmed == "" then
        return ""
    end
    local obj_shortcut = resolve_active_object_path(src, trimmed)
    if obj_shortcut ~= nil then
        return obj_shortcut
    end
    -- literals
    local num = tonumber(trimmed)
    if num ~= nil then
        return num
    end
    if trimmed == "true" then
        return true
    end
    if trimmed == "false" then
        return false
    end
    -- Plain variable reads need no expression or accessor scanner. Preserve
    -- source-property precedence and false/table values exactly as below.
    if trimmed:match("^[A-Za-z_][%w_]*$") then
        local item=src and (src.active_source or src.scene_item or
            (src.active_sources and src.active_sources[1]) or src.original_item)
        if item and item[trimmed]~=nil then
            local value=item[trimmed]
            if type(value)~="function" then return value end
            local success,result=pcall(value)
            if success then return result end
            return make_fatal("Failed to access source property '"..trimmed.."': "..tostring(result))
        end
        local scope,value=retrieve_scope(src and src.active_scope,trimmed)
        if scope then return value end
        return make_fatal("Unknown identifier: "..trimmed)
    end
    if is_time_literal(trimmed) then
        return trimmed
    end
    if trimmed == "[]" or trimmed == "{}" then
        return trimmed
    end

    -- quoted string + interpolation "(expr)"
    if is_quoted_string(trimmed) then
        local inner = unquote_string(trimmed)
        if inner:find("%(") then
            local ok, result = pcall(function()
                return inner:gsub("(%b())", function(match_block)
                    local expr_inner = match_block:sub(2, -2)
                    local res = evaluate_math(src, expr_inner)
                    if is_fatal(res) then
                        error(res.msg)
                    end
                    return tostring(res)
                end)
            end)
            if not ok then
                return make_fatal(result)
            end
            return result
        end
        return inner
    end

    -- Standard expression namespaces are calls, not source/table paths.
    -- parse_value (including !for bounds) also reaches this resolver; routing
    -- here keeps bare calls consistent with !var and parenthesized expressions.
    if is_bare_math_call(trimmed) or trimmed:match("^math%.[%a_][%w_]*%s*%(") or
       trimmed:match("^string%.[%a_][%w_]*%s*%(") then
        return evaluate_math(src, trimmed)
    end

    -- expression/function call
    -- IMPORTANT:
    -- If it already looks like a path, do NOT send it to evaluate_math,
    -- even if it contains '-' inside a bracket key like ["0-1"].
    local looks_like_path = trimmed:match("^[A-Za-z_][%w_]*%.") or trimmed:match("^[A-Za-z_][%w_]*%[") or
                                trimmed:match("^[A-Za-z_][%w_]*_%(")

    if not looks_like_path and
        (trimmed:match("[%+%-%*/%%<>=]") or trimmed:match("%s+and%s+") or trimmed:match("%s+or%s+") or
            trimmed:match("%.%.") or trimmed:match("^%b()$") or trimmed:match("^@") or trimmed:match("^source%s*%(")) then
        if not trimmed:match("^[A-Za-z0-9_]+%-[A-Za-z0-9_%-]+$") then
            local res = evaluate_math(src, trimmed)
            if is_fatal(res) then
                return res
            end
            return res
        end
    end

    local parts = resolve_pointer_keys(src, trimmed)
    if is_fatal(parts) then
        return parts
    end
    if #parts == 0 then
        return nil
    end

    local root_key = parts[1]
    local current_val = nil
    local found = false

    -- active source methods/properties
    local runtime_item = nil
    if src then
        runtime_item = src.active_source or src.scene_item or (src.active_sources and src.active_sources[1]) or
                           src.original_item
    end

    if not found and runtime_item and runtime_item[root_key] ~= nil then
        found = true
        if type(runtime_item[root_key]) == "function" then
            local ok, val = pcall(runtime_item[root_key])
            if not ok then
                return make_fatal("Failed to access source property '" .. tostring(root_key) .. "': " .. tostring(val))
            end
            current_val = val
        else
            current_val = runtime_item[root_key]
        end
    end

    -- scope lookup
    if not found and src and src.active_scope then
        local scope, val = retrieve_scope(src.active_scope, root_key)
        if scope then
            found = true
            current_val = val
        end
    end

    if not found then
        return make_fatal("Unknown identifier: " .. tostring(root_key))
    end

    for i = 2, #parts do
        local key = parts[i]

        if type(current_val) ~= "table" then
            return make_fatal("Cannot index non-table value at '" .. table.concat(parts, ".", 1, i - 1) ..
                                  "' with key '" .. tostring(key) .. "'")
        end

        local next_val = current_val[key]
        if next_val == nil and type(key) == "number" and current_val[tostring(key)] ~= nil then
            next_val = current_val[tostring(key)]
        elseif next_val == nil and type(key) == "string" then
            local num_key = tonumber(key)
            if num_key ~= nil and current_val[num_key] ~= nil then
                next_val = current_val[num_key]
            end
        end

        -- Sparse-table read: missing child key means empty / 0
        if next_val == nil then
            return 0
        end

        current_val = next_val
    end

    return current_val
end

function value_to_lua_literal(v)
    local t = type(v)
    if t == "string" then
        return string.format("%q", v)
    elseif t == "number" then
        -- A substituted negative path beside subtraction would form Lua's
        -- comment opener: x - values[i] -> x--8. Parentheses preserve math.
        if v < 0 then return "(" .. tostring(v) .. ")" end
        return tostring(v)
    elseif t == "boolean" then
        return tostring(v)
    elseif v == nil then
        return "0"
    end
    return nil
end

function replace_path_tokens_in_expr(src, expr, paths)
    local out = {}
    local i = 1
    local len = #expr

    local function is_ident_start(ch)
        return ch and ch:match("[A-Za-z_]") ~= nil
    end

    local function is_path_char(ch)
        return ch and ch:match("[%w_%.%[%]\"']") ~= nil
    end

    while i <= len do
        local ch = expr:sub(i, i)

        -- preserve quoted strings exactly
        if ch == '"' or ch == "'" then
            local quote = ch
            local j = i
            local escaped = false

            while j <= len do
                local c = expr:sub(j, j)
                if escaped then
                    escaped = false
                elseif c == "\\" then
                    escaped = true
                elseif j > i and c == quote then
                    break
                end
                j = j + 1
            end

            table.insert(out, expr:sub(i, j))
            i = j + 1

        elseif is_ident_start(ch) then
            local j = i
            while j <= len do
                local current = expr:sub(j, j)
                if current == "[" then
                    -- Keep a computed index together with its path. The old
                    -- scanner split sx[i - 1] at the space and produced an
                    -- unsafe fragment instead of resolving the array cell.
                    local depth, quote, escaped = 1, nil, false
                    j = j + 1
                    while j <= len and depth > 0 do
                        local inner = expr:sub(j, j)
                        if quote then
                            if escaped then
                                escaped = false
                            elseif inner == "\\" then
                                escaped = true
                            elseif inner == quote then
                                quote = nil
                            end
                        elseif inner == '"' or inner == "'" then
                            quote = inner
                        elseif inner == "[" then
                            depth = depth + 1
                        elseif inner == "]" then
                            depth = depth - 1
                        end
                        j = j + 1
                    end
                elseif current == "(" and
                    (expr:sub(j-1,j-1)=="." or expr:sub(j-1,j-1)=="_") then
                    -- Dynamic path suffixes use .(expr) and _(expr).
                    -- Ordinary grouping parentheses must stay outside the
                    -- path token, including the ')' after an array index.
                    local depth,quote,escaped=1,nil,false
                    j=j+1
                    while j<=len and depth>0 do
                        local inner=expr:sub(j,j)
                        if quote then
                            if escaped then escaped=false
                            elseif inner=="\\" then escaped=true
                            elseif inner==quote then quote=nil end
                        elseif inner=='"' or inner=="'" then quote=inner
                        elseif inner=="(" then depth=depth+1
                        elseif inner==")" then depth=depth-1 end
                        j=j+1
                    end
                elseif current == "." and expr:sub(j,j+1) == ".." then
                    -- Concatenation ends a path token. In name.."text", the
                    -- dots and opening quote belong to the expression, not
                    -- to the variable name (including after array indexes).
                    break
                elseif is_path_char(current) then
                    j = j + 1
                else
                    break
                end
            end

            local token = expr:sub(i, j - 1)

            local looks_like_path = token:find("%.") or token:find("%[")
            local is_builtin_namespace = token:match("^math%.") or token:match("^string%.") or token == "tonumber" or
                                             token == "tostring"

            if looks_like_path and not is_builtin_namespace then
                -- obslua.script_log(obslua.LOG_WARNING, "[DEBUG PATH TOKEN] " .. tostring(token))

                if paths then
                    paths[#paths+1]=token
                    table.insert(out,paths.prefix..".v"..#paths)
                else
                local resolved = resolve_path(src, token)

                -- IMPORTANT:
                -- if the path does not exist yet or fails to resolve,
                -- coerce it to 0 instead of leaving raw Lua path text behind
                if is_fatal(resolved) then
                    table.insert(out, "0")
                else
                    local literal = value_to_lua_literal(resolved)
                    if literal ~= nil then
                        table.insert(out, literal)
                    else
                        -- unsupported complex values become 0 in math context
                        table.insert(out, "0")
                    end
                end
                end
            else
                table.insert(out, token)
            end

            i = j

        else
            table.insert(out, ch)
            i = i + 1
        end
    end

    return table.concat(out)
end

function scrub_strings_for_safety_check(expr)
    local out = {}
    local i = 1
    local len = #expr
    local in_string = false
    local quote_char = nil
    local escaped = false

    while i <= len do
        local ch = expr:sub(i, i)

        if in_string then
            -- preserve only the quote boundaries; mask the contents
            if escaped then
                escaped = false
                table.insert(out, "_")
            elseif ch == "\\" then
                escaped = true
                table.insert(out, "_")
            elseif ch == quote_char then
                in_string = false
                quote_char = nil
                table.insert(out, ch)
            else
                table.insert(out, "_")
            end
        else
            if ch == '"' or ch == "'" then
                in_string = true
                quote_char = ch
                table.insert(out, ch)
            else
                table.insert(out, ch)
            end
        end

        i = i + 1
    end

    return table.concat(out)
end

function evaluate_math(src, expr)
    if type(expr) ~= "string" then
        return expr
    end

    local working_expr = safe_trim(expr)
    if working_expr == "" then
        return make_fatal("Empty expression")
    end
    -- A validated expression plan can be reused before reclassifying its
    -- syntax. Runtime paths and scope values are still read on every call.
    -- Inline script functions must execute again before their result is cached.
    local cached_plan = EXPR_CHUNK_CACHE and EXPR_CHUNK_CACHE.format == 2 and
        EXPR_CHUNK_CACHE.map[working_expr]
    if cached_plan and not working_expr:find("@",1,true) and not working_expr:find("source",1,true) then
        return evaluate_expression_plan(src,cached_plan,expr)
    end
    -- Plain numeric literals need neither path expansion nor a Lua chunk.
    -- Keep the accepted characters narrow so tonumber cannot bypass the
    -- expression safety check for implementation-specific numeric strings.
    if working_expr:match("^[%+%-]?[%d%.][%d%.eE%+%-]*$") or
        working_expr:match("^[%+%-]?0[xX]%x+$") then
        local literal = tonumber(working_expr)
        if literal ~= nil then return literal end
    end
    -- A complete lookup can return a table, string, or false. Only compound
    -- arithmetic should coerce unsupported path values into numbers.
    local value_path=working_expr
    while value_path:match("^%b()$") do value_path=safe_trim(value_path:sub(2,-2)) end
    if is_complete_value_path(value_path) then return resolve_path(src,value_path) end

    -- direct full-function call: @func(...) or source(...)
    local direct_func, direct_args = working_expr:match("^@([%a_][%w_%.]*)(%b())$")
    if not direct_func then
        local s_func, s_args = working_expr:match("^(source)(%b())$")
        if s_func then
            direct_func = s_func
            direct_args = s_args
        end
    end

    if direct_func then
        local func = SCRIPT_FUNCS
        local builtin_math = false
        for part in string.gmatch(direct_func, "[^%.]+") do
            if type(func) == "table" then
                func = func[part]
            else
                func = nil
                break
            end
        end

        if not func and direct_func:match("^math%.") then
            local math_key = direct_func:match("^math%.(.*)")
            if math[math_key] then
                func = math[math_key]
                builtin_math = true
            end
        end

        if not func then
            return make_fatal("Unknown function: @" .. tostring(direct_func))
        end

        local clean_args = direct_args:sub(2, -2)
        local resolved_args = {}

        for _, arg in ipairs(split_args_safe(clean_args)) do
            arg = safe_trim(arg)

            local value

            if arg:match("[%+%-%*/%%<>=]") and not is_quoted_string(arg) then
                value = evaluate_math(src, arg)

            else
                -- NEW: support active object shorthands like pos.x / pos.y / scale.x
                local obj_shortcut = resolve_active_object_path(src, arg)
                if obj_shortcut ~= nil then
                    value = obj_shortcut
                else
                    value = resolve_path(src, arg)
                end
            end

            if is_fatal(value) then
                return value
            end

            table.insert(resolved_args, value)
        end

        local ok, res
        if builtin_math then
            ok, res = pcall(func, unpack(resolved_args))
        else
            ok, res = pcall(func, src, unpack(resolved_args))
        end
        if not ok then
            return make_fatal("Function call failed @" .. tostring(direct_func) .. ": " .. tostring(res))
        end
        return res
    end

    -- Replace inline function calls with literal-safe values
    local ok_inline,replaced=true,working_expr
    if working_expr:find("@",1,true) or working_expr:find("source",1,true) then
    ok_inline, replaced = pcall(function()
        local out = working_expr

        out = out:gsub("@([%a_][%w_%.]*)(%b())", function(func_name, args_block)
            local func = SCRIPT_FUNCS
            local builtin_math = false
            for part in string.gmatch(func_name, "[^%.]+") do
                if type(func) == "table" then
                    func = func[part]
                else
                    func = nil
                    break
                end
            end

            if not func and func_name:match("^math%.") then
                local math_key = func_name:match("^math%.(.*)")
                if math[math_key] then
                    func = math[math_key]
                    builtin_math = true
                end
            end

            if not func then
                error("Unknown function: @" .. tostring(func_name))
            end

            local clean_args = args_block:sub(2, -2)
            local resolved_args = {}

            for _, arg in ipairs(split_args_safe(clean_args)) do
                arg = safe_trim(arg)

                local value
                if arg:match("[%+%-%*/%%<>=]") and not is_quoted_string(arg) then
                    value = evaluate_math(src, arg)
                else
                    value = resolve_path(src, arg)
                end

                if is_fatal(value) then
                    error(value.msg)
                end
                table.insert(resolved_args, value)
            end

            local success, res
            if builtin_math then
                success, res = pcall(func, unpack(resolved_args))
            else
                success, res = pcall(func, src, unpack(resolved_args))
            end
            if not success then
                error("Function call failed @" .. tostring(func_name) .. ": " .. tostring(res))
            end

            if type(res) == "string" then
                return string.format("%q", res)
            elseif type(res) == "boolean" then
                return tostring(res)
            elseif type(res) == "number" then
                return tostring(res)
            else
                error("Function @" .. tostring(func_name) .. " returned unsupported inline type: " .. type(res))
            end
        end)

        out = out:gsub("source(%b())", function(args_block)
            local clean_args = args_block:sub(2, -2)
            local resolved_args = {}

            for _, arg in ipairs(split_args_safe(clean_args)) do
                arg = safe_trim(arg)
                local value = resolve_path(src, arg)
                if is_fatal(value) then
                    error(value.msg)
                end
                table.insert(resolved_args, value)
            end

            local func = SCRIPT_FUNCS and SCRIPT_FUNCS.source
            if type(func) ~= "function" then
                error("Missing built-in source()")
            end

            local success, res = pcall(func, src, unpack(resolved_args))
            if not success then
                error("source() failed: " .. tostring(res))
            end

            error("source() returns an object and cannot be used inside arithmetic expression")
        end)

        return out
    end)
    end

    if not ok_inline then
        return make_fatal(replaced)
    end

    working_expr = replaced
    -- Cache the source structure, not an expression containing this frame's
    -- numeric path values. Resolved paths are arguments, never executable code.
    if not EXPR_CHUNK_CACHE or EXPR_CHUNK_CACHE.format~=2 then
        EXPR_CHUNK_CACHE={size=0,map={},order={},format=2}
    end
    local plan=EXPR_CHUNK_CACHE.map[working_expr]
    if not plan then
        local paths={prefix="__im3_expr_paths"}
        while working_expr:find(paths.prefix,1,true) do paths.prefix="_"..paths.prefix end
        local ok_paths,code=pcall(replace_path_tokens_in_expr,src,working_expr,paths)
        if not ok_paths then return make_fatal(code) end
        code=code:gsub("!=","~=")
        local scrubbed=scrub_strings_for_safety_check(code)
        if scrubbed:match("[^%w%s%+%-%*/%%<>=~%._%(%),:\"']") then
            return make_fatal("Unsafe expression: "..tostring(code))
        end
        local factory,why=loadstring("return function("..paths.prefix..") return "..code.." end")
        if not factory then return make_fatal("Strict Mode: Invalid expression syntax -> "..tostring(why)) end
        setfenv(factory,{})
        local made,compiled=pcall(factory)
        if not made or type(compiled)~="function" then
            return make_fatal("Strict Mode: Invalid expression syntax -> "..tostring(compiled))
        end
        plan={func=compiled,paths=paths}
        if EXPR_CHUNK_CACHE.size>=512 then
            EXPR_CHUNK_CACHE.next=EXPR_CHUNK_CACHE.next or 1
            local old=EXPR_CHUNK_CACHE.order[EXPR_CHUNK_CACHE.next]
            if old then EXPR_CHUNK_CACHE.map[old]=nil end
            EXPR_CHUNK_CACHE.order[EXPR_CHUNK_CACHE.next]=working_expr
            EXPR_CHUNK_CACHE.next=EXPR_CHUNK_CACHE.next%512+1
        else
            EXPR_CHUNK_CACHE.size=EXPR_CHUNK_CACHE.size+1
            EXPR_CHUNK_CACHE.order[EXPR_CHUNK_CACHE.size]=working_expr
        end
        EXPR_CHUNK_CACHE.map[working_expr]=plan
    end
    return evaluate_expression_plan(src,plan,expr)
end

function evaluate_expression_plan(src,plan,expr)
    local path_values={}
    for i,path in ipairs(plan.paths) do
        local value=resolve_path(src,path)
        local kind=type(value)
        if is_fatal(value) or (kind~="number" and kind~="string" and kind~="boolean") then value=0 end
        if type(value)=="number" and (value~=value or value==math.huge or value==-math.huge) then
            return make_fatal("Expression path '"..path.."' is not finite")
        end
        path_values["v"..i]=value
    end

    local safe_env = src and src.math_eval_env
    if not safe_env then
        safe_env = {
            math = math,
            string = string,
            tonumber = tonumber,
            tostring = tostring,
            [true] = true,
            [false] = false
        }
        setmetatable(safe_env, {
            __index = function(t, key)
                if type(src.active_scope) ~= "table" then
                    src.active_scope = {}
                end

                local scope, val = retrieve_scope(src.active_scope, key)
                if scope then
                    return val
                end

                -- allow scene_item property access like old behavior
                if src and src.scene_item and src.scene_item[key] ~= nil then
                    local target = src.scene_item[key]
                    if type(target) == "function" then
                        local ok, res = pcall(target)
                        if ok then
                            return res
                        end
                    else
                        return target
                    end
                end

                -- COMPATIBILITY MODE:
                -- unknown identifiers in math resolve to 0 instead of fatal error
                return 0
            end
        })
        if src then src.math_eval_env = safe_env end
    end

    -- Reinstalling an unchanged environment inhibits hot expression traces.
    -- Shared plans still switch environments when used by another context.
    if getfenv(plan.func) ~= safe_env then setfenv(plan.func, safe_env) end
    local ok, result = pcall(plan.func,path_values)
    if not ok then
        return make_fatal(result)
    end

    if result == nil then
        return make_fatal("Expression returned nil: " .. tostring(expr))
    end

    return result
end

function expand_dynamic_path(src, path)
    if type(path) ~= "string" then
        return path
    end
    -- Static paths and ordinary expressions have nothing to expand. Avoid
    -- allocating and rebuilding an identical string character by character.
    if not path:find("_(",1,true) and not path:find(".(",1,true) then return path end

    local function eval_expr(expr_text)
        local res = evaluate_math(src, expr_text)
        if is_fatal and is_fatal(res) then
            error(res.msg)
        end
        return res
    end

    local function escape_string(s)
        s = tostring(s)
        s = s:gsub("\\", "\\\\")
        s = s:gsub('"', '\\"')
        return s
    end

    local function read_balanced_paren(str, start_i)
        local len = #str
        local depth = 0
        local in_string = false
        local quote = nil
        local escaped = false

        for i = start_i, len do
            local ch = str:sub(i, i)

            if in_string then
                if escaped then
                    escaped = false
                elseif ch == "\\" then
                    escaped = true
                elseif ch == quote then
                    in_string = false
                    quote = nil
                end
            else
                if ch == '"' or ch == "'" then
                    in_string = true
                    quote = ch
                elseif ch == "(" then
                    depth = depth + 1
                elseif ch == ")" then
                    depth = depth - 1
                    if depth == 0 then
                        return str:sub(start_i + 1, i - 1), i
                    end
                end
            end
        end

        return nil, nil
    end

    local out = {}
    local i = 1
    local len = #path

    while i <= len do
        local ch = path:sub(i, i)

        -- Handle _(expr) or _(expr)_
        -- Handle _(expr)
        -- IMPORTANT:
        -- Do NOT consume a trailing underscore here, because in chains like:
        -- cell_(t_row)_(t_col)
        -- that underscore belongs to the NEXT dynamic segment.
        if ch == "_" and path:sub(i + 1, i + 1) == "(" then
            local inner, close_i = read_balanced_paren(path, i + 1)
            if not inner then
                error("Unclosed dynamic path expression near: " .. tostring(path:sub(i)))
            end

            local val = eval_expr(inner)

            -- preserve the leading underscore only
            table.insert(out, "_")
            table.insert(out, tostring(val))

            i = close_i + 1
        elseif ch == "." and path:sub(i + 1, i + 1) == "(" and path:sub(i - 1, i - 1) ~= "." then
            local inner, close_i = read_balanced_paren(path, i + 1)
            if not inner then
                error("Unclosed dynamic dot expression near: " .. tostring(path:sub(i)))
            end

            local val = eval_expr(inner)

            if type(val) == "number" then
                table.insert(out, "[" .. tostring(val) .. "]")
            else
                table.insert(out, "[\"" .. escape_string(val) .. "\"]")
            end

            i = close_i + 1

        else
            table.insert(out, ch)
            i = i + 1
        end
    end

    return table.concat(out)
end
--
function clone_table_deep(tbl, seen)
    if type(tbl) ~= "table" then
        return tbl
    end
    if seen and seen[tbl] then
        return seen[tbl]
    end

    seen = seen or {}
    local copy = {}
    seen[tbl] = copy

    for k, v in pairs(tbl) do
        copy[clone_table_deep(k, seen)] = clone_table_deep(v, seen)
    end

    return copy
end

function make_isolated_scope(parent_scope)
    local child = {
        __isolated_scope = true
    }
    if type(parent_scope) == "table" then
        setmetatable(child, {
            __index = parent_scope
        })
    end
    return child
end
function retrieve_scope(scope, key, depth)
    depth = (depth or 0) + 1
    if depth > 64 or type(scope) ~= "table" then
        return nil, nil
    end
    if rawget(scope, key) ~= nil then
        return scope, rawget(scope, key)
    end
    local mt = getmetatable(scope)
    if mt and mt.__index and type(mt.__index) == "table" then
        local found_scope, found_val = retrieve_scope(mt.__index, key, depth)
        if found_scope then
            return found_scope, found_val
        end
    end
    for k, nscope in pairs(scope) do
        if type(k) == "number" and type(nscope) == "table" then
            local found_scope, found_val = retrieve_scope(nscope, key, depth)
            if found_scope then
                return found_scope, found_val
            end
        end
    end
    return nil, nil
end

-- [[ MAIN ]]
function defaults(settings)
    settings.str("output", "text", true)
    settings.str("code", "", true)
    settings.str("input", "", true)
    settings.int("tick_budget_ms", 6, true)
end
function setup(settings)
    src = {
        settings = settings,
        tick_budget_ms = 6,
        current_idx = 1,
        state = {},
        async_tasks = {},
        queue = {},
        labels = {},
        scene_item = nil
    }
    obs.script:ui(function(ui)
        local opt = ui.options("output", "")
        opt.add.str("< OUTPUT: TEXT >", "text").add.str("< OUTPUT: INPUT >", "input").add
            .str("< OUTPUT: FILE >", "file")
        local text = ui.input("text", "", obs.enum.text.textarea)
        local input = ui.input("input", "")
        local file = ui.path("file", "")
        ui.number(1, 20, 1, "tick_budget_ms", "Script work budget per tick (ms)")
        file.hide();
        input.hide();
        text.hide()
        local run = ui.button("run_code", "Execute", function()
            run_code(src, settings)
        end)
        local function init_show(value)
            if value == "text" then
                text.show();
                input.hide();
                file.hide()
            elseif value == "input" then
                text.hide();
                input.show();
                file.hide()
            elseif value == "file" then
                text.hide();
                input.hide();
                file.show()
            end
        end
        opt.onchange(function(value)
            init_show(value)
            return true
        end)
        init_show(src.settings.str("output"))
        return ui
    end)

end
-- Capture the selected entry file when Execute is pressed. Changing UI fields
-- during a run must not redirect that program's later imports/saves/includes.
function set_program_location(ctx, output_type, selected_file)
    local base=type(script_path)=="function" and script_path() or ""
    base=base:gsub("\\","/")
    if base~="" and base:sub(-1)~="/" then base=base.."/" end
    ctx.program_output=output_type
    ctx.program_file=nil
    ctx.program_directory=base
    if output_type=="file" then
        local path=tostring(selected_file or ""):gsub("\\","/")
        if path~="" then
            if not path:match("^%a:/") and path:sub(1,1)~="/" then path=base..path end
            ctx.program_file=path
            ctx.program_directory=path:match("^(.*[/])") or base
        end
    end
    return ctx.program_file
end

-- [[ RUN CODE ]]
function run_code(src, settings)
    if not src or not settings then
        return error("4IM3-SCRIPT: Something wrong happened, please try again")
    end
    if not settings then
        settings = src.settings
    end
    local menu_ok, menu_err = input_preview_menu_release(src)
    if not menu_ok then
        obslua.script_log(obslua.LOG_ERROR,
            "[4IM3-SCRIPT] Cannot restart: " .. tostring(menu_err))
        return
    end
    INPUT_EVENTS.clear(src)
    if ENGINE_UI then ENGINE_UI.clear(src) end
    input_host.clear_pending(src)
    if src.native_workers then native_worker_cancel_all(src) end
    local raw_code = ""
    if src.tcp_connections then TCP.close_all(src) end
    local output_type = settings.str("output")
    set_program_location(src, output_type, output_type == "file" and settings.str("file") or nil)
    local file_id = "global"
    if output_type == "text" then
        raw_code = settings.str("text")
    elseif output_type == "input" then
        raw_code = settings.str("input")
    elseif output_type == "file" then

        local file_path = src.program_file or settings.str("file")
        file_id = script_path() .. "_" .. file_path
        local file = io.open(file_path, "r")
        if file then
            raw_code = file:read("*all");
            file:close()
        end
    end
    src.settings = settings
    src.tick_budget_ms = math.max(1, math.min(20, tonumber(settings.int("tick_budget_ms")) or 6))
    src.no_yield_ops = 0
    src.no_yield_budget_ticks = 0
    src.async_resume_index = nil
    src.async_resume_task = nil
    src.current_task = nil
    src.for_frames = {}
    src.run_depth = 0
    src.tick_deadline_ms = nil
    src.next_budget_warning_ms = nil
    src.file_id = file_id:gsub("[^%w_]", "_")
    all_source_clones = {}
    obs.register:remove_all()
    if auto_cleanup then
        for i=#auto_cleanup,1,-1 do
            local item=auto_cleanup[i]
            if item and item.data then
                local ok,removed=pcall(item.remove)
                if not ok or removed==false then
                    obslua.script_log(obslua.LOG_WARNING,'[4IM3-SCRIPT] Clone cleanup failed: '..tostring(removed))
                else forget_clone(item) end
            else forget_clone(item) end
        end
    end
    local function strip_comments_preserve_strings(line)
        local out = {}
        local i = 1
        local len = #line
        local in_string = false
        local quote_char = nil
        local escaped = false

        while i <= len do
            local ch = line:sub(i, i)
            local next_ch = (i < len) and line:sub(i + 1, i + 1) or ""

            if in_string then
                table.insert(out, ch)

                if escaped then
                    escaped = false
                elseif ch == "\\" then
                    escaped = true
                elseif ch == quote_char then
                    in_string = false
                    quote_char = nil
                end

                i = i + 1
            else
                if ch == '"' or ch == "'" then
                    in_string = true
                    quote_char = ch
                    table.insert(out, ch)
                    i = i + 1

                elseif ch == "-" and next_ch == "-" then
                    local char_after = line:sub(i + 2, i + 2)
                    local is_decrement_syntax = char_after:match("[%d%._%a%(]") ~= nil

                    if is_decrement_syntax then
                        table.insert(out, "-")
                        table.insert(out, "-")
                        i = i + 2
                    else
                        -- treat as comment start
                        break
                    end
                else
                    table.insert(out, ch)
                    i = i + 1
                end
            end
        end
        return table.concat(out)
    end
    local clean_lines = {}
    for line in raw_code:gmatch("([^\r\n]*)\r?\n?") do
        table.insert(clean_lines, strip_comments_preserve_strings(line))
    end
    local code = table.concat(clean_lines, "\n")
    release_canvas_buffers(src)
    for name,world in pairs(world3d_worlds) do
        world3d_cancel_builds(world)
        world3d_worlds[name] = nil
    end
    src.world3d_removed_source = nil
    src.world3d_selected = nil
    src.sprite_states = nil
    src.animation_states = nil
    src.loaded_modules = nil
    src.module_commands = nil
    src.module_command_raw = nil
    src.queue = {}
    src.hotkeys = {}
    src.labels = {}
    src.async_tasks = {}
    src.current_idx = 1
    src.frame_tick_active = false
    src.frame_resume_ms = nil
    src.collision_listeners = {}
    src.watchers = {}
    src.active_sources = {}
    src.state = {}
    src.pinned_sources = {}
    src.scene_item = nil
    src.isInitialized = true
    src.colliders = {}
    src.templates = {}
    src.label_hotkeys = {}
    src.type_registry = {}
    src.scope_type_registry = nil

    src.next_context_id = 1
    src.context_id = 0
    src.global_registry = {}
    src.functions = {}
    src.function_contexts = {}
    src.native_worker_owners = nil
    src.native_worker_blocks = nil
    src.active_scope = {
        screen = obs.scene:size(),
        pi = math.pi,
        huge = math.huge
    }
    src.call_stack = {}

    local compiled_queue, compiled_labels = compile_block_text(src, code, 0)
    src.queue = compiled_queue
    src.labels = compiled_labels
    -- for k, _ in pairs(src.labels) do
    --     obslua.script_log(obslua.LOG_WARNING, "[DEBUG LABEL KEY] " .. tostring(k))
    -- end
end

function compile_block_text(src, raw_code, ctx_id)
    ctx_id = ctx_id or 0
    local function_owner=src.function_contexts and
        (src.function_contexts[ctx_id] or src.function_contexts[src.context_id])
    if function_owner then src.function_contexts[ctx_id]=function_owner end

    -- File programs start beside the selected entry file; text/input programs
    -- start beside the engine. Nested includes follow their containing file.
    local function include_absolute(path)
        return path:match("^[/\\]") or path:match("^%a:[/\\]")
    end
    local function include_directory(path)
        return path:match("^(.*[/\\])") or ""
    end
    local function resolve_includes(raw_text, base, active, depth)
        if depth > 16 then error("Include Error: More than 16 nested files") end
        return (raw_text:gsub("!include%s*|%s*([^|]-)%s*|%s*%+%s*|", function(filepath)
            filepath = safe_trim(filepath)
            if filepath == "" then error("Include Error: Missing file path") end
            local full = include_absolute(filepath) and filepath or base .. filepath
            full = full:gsub("\\", "/")
            if active[full] then error("Include Error: File includes itself: " .. full) end
            local f, open_error = io.open(full, "r")
            if not f then error("Include Error: Cannot open '" .. full .. "': " ..
                                tostring(open_error)) end
            local content = f:read("*a") or ""
            f:close()
            active[full] = true
            local expanded = resolve_includes(content, include_directory(full), active, depth + 1)
            active[full] = nil
            return expanded
        end))
    end

    local include_root=src.program_directory or (type(script_path)=="function" and script_path() or "")
    raw_code = resolve_includes(raw_code or "", include_root, {}, 0)
    -- A full-line comment must not become part of the next command when
    -- smart_split joins lines up to the next |+| terminator.
    raw_code = raw_code:gsub("[^\r\n]+", function(line)
        return line:match("^%s*%-%-") and "" or line
    end)

    -- Check the complete function text before registering any labels. Runtime
    -- blocks (tasks, loops and workers) may compile later, so checking only the
    -- current queue would leave labels inside those nested bodies exposed.
    -- Quoted text and comments are masked without changing source positions.
    if function_owner then
        local masked,quote,escaped,comment={},nil,false,false
        for index=1,#raw_code do
            local char=raw_code:sub(index,index)
            if comment then
                masked[index]=char=="\n" and "\n" or " "
                if char=="\n" then comment=false end
            elseif quote then
                masked[index]=char=="\n" and "\n" or " "
                if escaped then escaped=false
                elseif char=="\\" then escaped=true
                elseif char==quote then quote=nil end
            elseif char=='"' or char=="'" then
                quote=char;masked[index]=" "
            elseif char=="-" and raw_code:sub(index,index+1)=="--" and
                   not raw_code:sub(index+2,index+2):match("[%d%._%a%(]") then
                comment=true;masked[index]=" "
            else masked[index]=char end
        end
        local code=table.concat(masked)
        local at,finish,label=code:find("!label%s*|%s*(<[^|]+>)")
        while at do
            local following=code:sub(finish+1):match("^%s*(.)")
            if not following or following=="|" then
                local _,lines=raw_code:sub(1,at-1):gsub("\n","")
                local message="Function Error: Global labels are not allowed inside function '"..
                    function_owner.."': "..label.." (body line "..(lines+1)..")"
                local queue={function() return false,message end}
                queue._line_map={[1]=lines+1}
                queue._command_map={[1]="!label | "..label}
                queue._function_label_error={owner=function_owner,label=label,line=lines+1}
                return queue,{}
            end
            at,finish,label=code:find("!label%s*|%s*(<[^|]+>)",finish+1)
        end
    end

    local queue = {}
    queue._line_map = {}
    queue._command_map = {}
    queue._worker_steps = {}
    local labels = {}

    local raw_steps = smart_split(raw_code)
    local steps = {}

    local function push_resplit_steps(text, base_line)
        text = safe_trim(text or "")
        if text == "" then
            return
        end

        -- Re-split any leftover chunk that may still contain multiple |+| statements
        local sub_steps = smart_split(text)
        if #sub_steps == 0 then
            table.insert(steps, {
                text = text,
                line = base_line
            })
            return
        end

        for _, sub in ipairs(sub_steps) do
            local sub_text = safe_trim(sub.text or "")
            if sub_text ~= "" then
                table.insert(steps, {
                    text = sub_text,
                    line = (base_line or 1) + (sub.line or 1) - 1
                })
            end
        end
    end

    for _, step_obj in ipairs(raw_steps) do
        local work_step = safe_trim(step_obj.text or "")
        local true_line = step_obj.line

        if work_step ~= "" then
            local found_tag = true
            while found_tag do
                found_tag = false

                if work_step:sub(1, 6) == "-skip-" then
                    table.insert(steps, {
                        text = "-skip-",
                        line = true_line
                    })
                    work_step = safe_trim(work_step:sub(7))
                    found_tag = true

                elseif work_step:sub(1, 5) == "-end-" then
                    table.insert(steps, {
                        text = "-end-",
                        line = true_line
                    })
                    work_step = safe_trim(work_step:sub(6))
                    found_tag = true
                end
            end

            if work_step ~= "" then
                push_resplit_steps(work_step, true_line)
            end
        end
    end
    -- Expand inline control blocks into ordinary queued commands and private
    -- labels. The OBS tick loop charges every body command against its budget.
    local for_number, if_number = 0, 0
    local function expand_control_blocks(input,ui_parent)
        local output = {}
        local function emit(value, line)
            output[#output + 1] = {text = value, line = line}
        end
        local function emit_body(body, line,child_parent)
            for _, nested in ipairs(expand_control_blocks(smart_split(body:sub(2, -2)),child_parent or ui_parent)) do
                emit(nested.text, (line or 1) + (nested.line or 1) - 1)
            end
        end
        local function inline_else_body(text)
            text = safe_trim(text or "")
            local direct = text:match("^!else%s+(%b{})%s*$")
            if direct then return direct end
            if text:match("^!else%s*|") then
                local parts = split_command_args_safe(text:sub(2))
                if parts and #parts == 2 and safe_trim(parts[1]) == "else" and
                    safe_trim(parts[2]):match("^%b{}$") then
                    return safe_trim(parts[2])
                end
            end
            return nil
        end
        local index = 1
        while index <= #input do
            local step_obj = input[index]
            local step_text = safe_trim(step_obj.text or "")
            local replaced = false
            if step_text:match('^!ui%s*|') then
                local parts=split_command_args_safe(step_text:sub(2))
                local action=parts and safe_trim(parts[2] or '')
                if action=='frame' or action=='box' or action=='panel' then
                    local body=parts[#parts] and safe_trim(parts[#parts])
                    if body and body:match('^%b{}$') and #parts>=4 then
                        table.remove(parts);parts[2]='panel'
                        if ui_parent then
                            local explicit=false
                            for i=4,#parts do for _,field in ipairs(split_named_attribute_group(parts[i]) or {}) do
                                if field:match('^%s*parent%s*:') then explicit=true end
                            end end
                            if not explicit then parts[#parts+1]='parent:'..ui_parent end
                        end
                        emit('!'..table.concat(parts,' | '),step_obj.line)
                        local before=step_text:sub(1,(step_text:find(body,1,true) or 1)-1)
                        local _,lines=before:gsub('\n','')
                        emit_body(body,(step_obj.line or 1)+lines,INPUT_EVENTS.selector(parts[3]))
                        replaced=true
                    end
                end
                if not replaced and ui_parent and parts and (ENGINE_UI.kinds[action] or action=='frame' or action=='box') then
                    local explicit=false
                    for i=4,#parts do for _,field in ipairs(split_named_attribute_group(parts[i]) or {}) do
                        if field:match('^%s*parent%s*:') then explicit=true end
                    end end
                    if not explicit then parts[#parts+1]='parent:'..ui_parent end
                    emit('!'..table.concat(parts,' | '),step_obj.line);replaced=true
                end
            end
            if not replaced and step_text:match("^!for%s*|") then
                local parts = split_command_args_safe(step_text:sub(2))
                if parts and #parts == 2 and safe_trim(parts[1]) == "for" then
                    local header, body = parts[2]:match("^(.-)%s*(%b{})%s*$")
                    if header and body then
                        header = safe_trim(header)
                        local name, source = header:match("^([%a_][%w_]*)%s+in%s+([^%s]+)$")
                        local first, last
                        if not name then
                            name, first, last = header:match("^([%a_][%w_]*)%s+from%s+(.-)%s+to%s+(.+)$")
                        end
                        if name and (source or (first and last)) then
                            for_number = for_number + 1
                            local id = "__for_" .. tostring(ctx_id or 0) .. "_" .. for_number
                            local check_label = id .. "_check"
                            local exit_label = id .. "_exit"
                            if source then
                                emit("!__for_start | " .. id .. " | in | " .. name .. " | " .. source, step_obj.line)
                            else
                                emit("!__for_start | " .. id .. " | range | " .. name .. " | " ..
                                    safe_trim(first) .. " | " .. safe_trim(last), step_obj.line)
                            end
                            emit("!label | " .. check_label, step_obj.line)
                            emit("!__for_check | " .. id .. " | " .. exit_label, step_obj.line)
                            emit_body(body, step_obj.line)
                            emit("!__for_next | " .. id .. " | " .. check_label, step_obj.line)
                            emit("!label | " .. exit_label, step_obj.line)
                            replaced = true
                        end
                    end
                end
            end
            if not replaced and step_text:match("^!if%s*|") then
                local parts = split_command_args_safe(step_text:sub(2))
                if parts and safe_trim(parts[1]) == "if" then
                    local condition, body
                    if #parts == 3 and safe_trim(parts[3]):match("^%b{}$") then
                        condition, body = safe_trim(parts[2]), safe_trim(parts[3])
                    elseif #parts == 2 then
                        condition, body = parts[2]:match("^(.-)%s+(%b{})%s*$")
                        condition = safe_trim(condition or "")
                    end
                    if condition and condition ~= "" and body then
                        if_number = if_number + 1
                        local id = "__if_" .. tostring(ctx_id or 0) .. "_" .. if_number
                        local else_label, end_label = id .. "_else", id .. "_end"
                        local following = input[index + 1]
                        local else_body = following and inline_else_body(following.text)
                        emit("!__if_false | " .. condition .. " | " ..
                            (else_body and else_label or end_label), step_obj.line)
                        emit_body(body, step_obj.line)
                        if else_body then
                            emit("!jump | " .. end_label, step_obj.line)
                            emit("!label | " .. else_label, following.line)
                            emit_body(else_body, following.line)
                            index = index + 1
                        end
                        emit("!label | " .. end_label, step_obj.line)
                        replaced = true
                    end
                end
            end
            if not replaced and inline_else_body(step_text) then
                emit("!else", step_obj.line)
                replaced = true
            end
            if not replaced then emit(step_obj.text, step_obj.line) end
            index = index + 1
        end
        return output
    end
    steps = expand_control_blocks(steps)
    local skip_ranges = {}
    local skip_stack = {}

    for i, step_obj in ipairs(steps) do
        if step_obj.text == "-skip-" then
            table.insert(skip_stack, i)
        elseif step_obj.text == "-end-" then
            if #skip_stack > 0 then
                table.insert(skip_ranges, {
                    start = table.remove(skip_stack),
                    finish = i
                })
            end
        end
    end

    for _, start_idx in ipairs(skip_stack) do
        table.insert(skip_ranges, {
            start = start_idx,
            finish = start_idx + 1
        })
    end

    local active_skips = {}

    local function extract_prefixes(step)
        local clean_step = step
        local watch_vars_str = nil
        local interrupt_label = nil
        local material_guard = nil

        local watch_match, rest = clean_step:match("^%[%[(.-)%]%]%s*(.*)")
        if watch_match then
            watch_vars_str = safe_trim(watch_match)
            clean_step = rest

            local label_match, rest_after_label = clean_step:match("^%[(.-)%]%s*(.*)")
            if label_match then
                interrupt_label = safe_trim(label_match)
                clean_step = rest_after_label
            end
        end

        local mat_match, mat_rest = clean_step:match("^%<%<(.-)%>%>%s*(.*)")
        if mat_match then
            material_guard = string.lower(safe_trim(mat_match))
            clean_step = mat_rest
        end

        return safe_trim(clean_step), watch_vars_str, interrupt_label, material_guard
    end

    local function build_watch_wrapper(exe_func, watch_vars_str, interrupt_label)
        if not watch_vars_str then
            return exe_func
        end

        local watch_vars = {}
        for var in string.gmatch(watch_vars_str, "[^,%s]+") do
            table.insert(watch_vars, safe_trim(var))
        end

        return function(ctx, state)
            state = state or ctx.state
            state.__watch_init = state.__watch_init or false
            state.__watch_vals = state.__watch_vals or {}

            if not state.__watch_init then
                for _, var_name in ipairs(watch_vars) do
                    state.__watch_vals[var_name] = resolve_path(ctx, var_name)
                end
                state.__watch_init = true
            else
                for _, var_name in ipairs(watch_vars) do
                    local new_val = resolve_path(ctx, var_name)
                    local old_val = state.__watch_vals[var_name]
                    if new_val ~= old_val then
                        state.__watch_vals[var_name] = new_val
                        if interrupt_label and interrupt_label ~= "" then
                            ctx.interrupt_label = interrupt_label
                        end
                        break
                    end
                end
            end

            return exe_func(ctx, state)
        end
    end
    for i, step_obj in ipairs(steps) do
        local step = safe_trim(step_obj.text)
        local true_line = step_obj.line

        for _, range in ipairs(skip_ranges) do
            if range.start == i then
                local end_lbl = "__skip_end_" .. i
                table.insert(queue, function(ctx, state)
                    return "JUMP", end_lbl
                end)
                queue._line_map[#queue] = true_line
                queue._command_map[#queue] = "-skip-"

                if not active_skips[range.finish] then
                    active_skips[range.finish] = {}
                end
                table.insert(active_skips[range.finish], end_lbl)
            end
        end

        if step ~= "" and step ~= "-skip-" and step ~= "-end-" then
            local clean_step, watch_vars_str, interrupt_label, material_guard = extract_prefixes(step)
            local exe_func = nil
            local worker_step = nil

            if clean_step:sub(1, 1) == "!" then
                local parts, split_err = split_command_args_safe(clean_step:sub(2))
                if not parts then
                    exe_func = function()
                        return false, split_err .. " (Line " .. tostring(true_line) .. ")"
                    end
                else
                    local cmd = safe_trim(parts[1] or "")
                    table.remove(parts, 1)
                    -- Unknown command names may resolve to program-owned UI
                    -- controls at execution time. Preserve callback locations
                    -- without interpreting function arguments as UI syntax.
                    if not engine[cmd] then parts._source_line=true_line;parts._source_command=clean_step end
                    if not watch_vars_str and not material_guard then
                        local copied_parts = {}
                        for part_index, part in ipairs(parts) do
                            copied_parts[part_index] = part
                        end
                        worker_step = {cmd = cmd, args = copied_parts,
                                       line = true_line}
                    end

                    if cmd == "" then
                        exe_func = function()
                            return false, "Compile Error: Empty command at line " .. tostring(true_line)
                        end
                    else
                        local should_validate = {
                            ["if"] = true,
                            ["move"] = true,
                            ["path"] = true,
                            ["spiral"] = true,
                            ["filter"] = true,
                            ["var"] = false,
                            ["return"] = false,
                            ["log"] = false,
                            ["source"] = false
                        }

                        if should_validate[cmd] then
                            if cmd == "if" then
                                local expr_to_validate = nil

                                -- Forms:
                                -- !if | expr | label
                                -- !if | expr | label | ret
                                -- !if | left | op | right | label
                                -- !if | left | op | right | label | ret
                                if #parts == 2 or #parts == 3 then
                                    expr_to_validate = parts[1]
                                elseif #parts >= 4 then
                                    expr_to_validate = tostring(parts[1] or "") .. " " .. tostring(parts[2] or "") ..
                                                           " " .. tostring(parts[3] or "")
                                end

                                if expr_to_validate and safe_trim(expr_to_validate) ~= "" then
                                    local ok, err = validate_expression_safely(src, expr_to_validate)
                                    if not ok then
                                        exe_func = function()
                                            return false, err .. " (Line " .. tostring(true_line) .. ")"
                                        end
                                    end
                                end
                            else
                                for _, arg in ipairs(parts) do
                                    local ok, err = validate_expression_safely(src, arg)
                                    if not ok then
                                        exe_func = function()
                                            return false, err .. " (Line " .. tostring(true_line) .. ")"
                                        end
                                        break
                                    end
                                end
                            end
                        end
                        if not exe_func then
                            if INPUT_EVENTS and INPUT_EVENTS.is_handler(cmd,parts) then
                                local handler,problem=INPUT_EVENTS.compile(src,parts,true_line,clean_step,cmd)
                                if not handler then exe_func=function() return false,problem end
                                else parts._input_handler=handler;exe_func=compile_line(cmd,parts) end
                            elseif cmd == "fn" then
                                local name = safe_trim(parts[1] or "")
                                local signature = #parts == 3 and safe_trim(parts[2] or "") or nil
                                local body = safe_trim(parts[#parts] or "")
                                local fn_error
                                local parameters, param_names = {}, {}
                                if (#parts ~= 2 and #parts ~= 3) or
                                    not name:match("^[A-Za-z_][%w_]*$") or
                                    not body:match("^%b{}$") then
                                    fn_error = "Function Error: Expected !fn | name | [parameters |] { ... } at line " ..
                                        tostring(true_line)
                                elseif engine[name] or name == "fn" then
                                    fn_error = "Function Error: '" .. name .. "' is a built-in command"
                                elseif src.functions and src.functions[name] then
                                    fn_error = "Function Error: Duplicate function '" .. name .. "'"
                                end
                                if not fn_error and signature then
                                    for _, field in ipairs(split_args_safe(signature)) do
                                        field = safe_trim(field)
                                        local param, default = field:match("^([A-Za-z_][%w_]*)%s*:%s*(.+)$")
                                        if not param then param = field end
                                        if not param:match("^[A-Za-z_][%w_]*$") or param == "args" or
                                            param_names[param] then
                                            fn_error = "Function Error: Invalid or duplicate parameter '" ..
                                                tostring(param) .. "' at line " .. tostring(true_line)
                                            break
                                        end
                                        param_names[param] = true
                                        parameters[#parameters + 1] = {name = param, default = default}
                                    end
                                end
                                if fn_error then
                                    exe_func = function() return false, fn_error end
                                else
                                    src.functions = src.functions or {}
                                    local fn_ctx = src.next_context_id or 1
                                    src.next_context_id = fn_ctx + 1
                                    local inner = body:sub(2, -2) .. "\n!return |+|"
                                    src.function_contexts=src.function_contexts or {}
                                    src.function_contexts[fn_ctx]=name
                                    local fn_queue, fn_labels = compile_block_text(src, inner, fn_ctx)
                                    local issue=fn_queue._function_label_error
                                    if issue then
                                        local body_at=clean_step:find(body,1,true) or 1
                                        local _,header_lines=clean_step:sub(1,body_at-1):gsub("\n","")
                                        local message="Function Error: Global labels are not allowed inside function '"..
                                            name.."': "..issue.label.." (Line "..
                                            (true_line+header_lines+issue.line-1)..")"
                                        exe_func=function() return false,message end
                                    else
                                        src.functions[name] = {
                                            index = 1, ctx = fn_ctx, global = true,
                                            queue = fn_queue, labels = fn_labels,
                                            params = parameters, param_names = param_names
                                        }
                                    end
                                    -- A definition registers code; it never enters the running queue.
                                end
                            elseif cmd == "label" and parts[1] then
                                local raw_name = safe_trim(parts[1])
                                local is_global = false
                                local name = raw_name

                                if raw_name:match("^<.+>$") then
                                    is_global = true
                                    name = safe_trim(raw_name:sub(2, -2))
                                end

                                if is_global and function_owner then
                                    local message="Function Error: Global labels are not allowed inside function '"..
                                        function_owner.."': <"..name.."> (Line "..true_line..")"
                                    exe_func=function() return false,message end
                                    queue._function_label_error={owner=function_owner,label="<"..name..">",line=true_line}
                                elseif name == "" then
                                    exe_func = function()
                                        return false, "Compile Error: Empty label name at line " .. tostring(true_line)
                                    end
                                else
                                    local label_data = {
                                        index = #queue + 1,
                                        ctx = ctx_id,
                                        global = is_global,
                                        queue = queue,
                                        labels = labels
                                    }

                                    labels[name] = label_data

                                    if is_global then
                                        if not src.global_registry then
                                            src.global_registry = {}
                                        end
                                        src.global_registry[name] = label_data
                                    end

                                    exe_func = function()
                                        return true
                                    end
                                end
                            else
                                exe_func = compile_line(cmd, parts)
                            end
                        end
                    end
                end
            else
                exe_func = function()
                    return false, "Compile Error: Invalid statement at line " .. tostring(true_line) .. ": " ..
                        tostring(clean_step)
                end
            end

            if exe_func then
                exe_func = build_watch_wrapper(exe_func, watch_vars_str, interrupt_label)

                if material_guard then
                    local original_exe = exe_func
                    exe_func = function(ctx, state)
                        state = state or ctx.state
                        local res, target = original_exe(ctx, state)

                        if not ctx.colliders then
                            ctx.colliders = {}
                        end
                        local targets = ctx.active_sources or {ctx.scene_item}

                        for _, item in ipairs(targets) do
                            if item then
                                local id = item.get_name()
                                if not ctx.colliders[id] then
                                    ctx.colliders[id] = {
                                        item = item,
                                        material = material_guard
                                    }
                                end
                                ctx.colliders[id].is_active = (res == false)
                            end
                        end

                        return res, target
                    end
                end

                table.insert(queue, exe_func)
                queue._line_map[#queue] = true_line
                queue._command_map[#queue] = clean_step
                queue._worker_steps[#queue] = worker_step
            end
        end

        if active_skips[i] then
            for _, lbl in ipairs(active_skips[i]) do
                labels[lbl] = {
                    index = #queue + 1,
                    ctx = ctx_id,
                    global = false,
                    queue = queue,
                    labels = labels
                }
            end
        end
    end

    for finish_idx, lbls in pairs(active_skips) do
        if finish_idx > #steps then
            for _, lbl in ipairs(lbls) do
                labels[lbl] = {
                    index = #queue + 1,
                    ctx = ctx_id,
                    global = false,
                    queue = queue,
                    labels = labels
                }
            end
        end
    end

    if ctx_id==0 and native_worker_warm_programs then native_worker_warm_programs(src,queue,labels) end
    return queue, labels
end

function smart_split(str)
    local chunks = {}
    local depth_brace = 0
    local start = 1
    local len = #str
    local current_line = 1
    local chunk_start_line = 1

    local in_string = false
    local quote_char = nil
    local escaped = false

    for i = 1, len do
        local c = str:sub(i, i)

        if c == "\n" then
            current_line = current_line + 1
        end

        if in_string then
            if escaped then
                escaped = false
            elseif c == "\\" then
                escaped = true
            elseif c == quote_char then
                in_string = false
                quote_char = nil
            end
        else
            if c == '"' or c == "'" then
                in_string = true
                quote_char = c
            elseif c == "{" then
                depth_brace = depth_brace + 1
            elseif c == "}" then
                depth_brace = depth_brace - 1
            elseif depth_brace == 0 and str:sub(i, i + 2) == "|+|" then
                local raw_chunk = str:sub(start, i - 1)
                local chunk = raw_chunk:match("^%s*(.-)%s*$")
                if chunk and chunk ~= "" then
                    local leading_ws = raw_chunk:match("^(%s*)")
                    local _, newlines_in_leading = leading_ws:gsub("\n", "")
                    table.insert(chunks, {
                        text = chunk,
                        line = chunk_start_line + newlines_in_leading
                    })
                end
                start = i + 3
                chunk_start_line = current_line
            end
        end
    end

    local raw_last = str:sub(start)
    local last = raw_last:match("^%s*(.-)%s*$")
    if last and last ~= "" then
        local leading_ws = raw_last:match("^(%s*)")
        local _, newlines_in_leading = leading_ws:gsub("\n", "")
        table.insert(chunks, {
            text = last,
            line = chunk_start_line + newlines_in_leading
        })
    end

    return chunks
end

function unset()
    if ACTIVE_FETCH_FILES then
        for fetch_id, files in pairs(ACTIVE_FETCH_FILES) do
            for _, filepath in ipairs(files) do
                pcall(function()
                    return os.remove(filepath)
                end)
            end
            ACTIVE_FETCH_FILES[fetch_id] = nil
        end
    end
end

function script_tick(fps)
    if obs and obs.utils and obs.utils.script_shutdown then return end
    local tick_start_ms = engine_tick_now_ms()
    if src.world3d_removed_source then
        local removed_name = src.world3d_removed_source
        src.world3d_removed_source = nil
        src.world3d_selected = nil
        if src.isInitialized and src.queue then
            if engine and engine["stop"] then
                engine["stop"](src, {}, {"all"})
            else
                src.current_idx = #src.queue + 1
                src.async_tasks = {}
            end
            obslua.script_log(obslua.LOG_WARNING,
                "[4IM3-SCRIPT] 3D renderer '" .. tostring(removed_name) ..
                "' was removed in OBS; stopped the running program. Press Execute to recreate it.")
        end
        input_preview_menu_release(src)
        return
    end
    local tick_budget_ms = math.max(1, math.min(20, tonumber(src.tick_budget_ms) or 6))
    if not src.isInitialized or not src.queue then
        if ENGINE_UI then ENGINE_UI.clear(src) end
        if src.input_handlers then INPUT_EVENTS.clear(src) end
        if src.native_workers then native_worker_poll_all(src,tick_start_ms+tick_budget_ms*0.15) end
        if src.tcp_connections then TCP.close_all(src) end
        input_preview_menu_release(src)
        return
    end
    local tick_deadline_ms = tick_start_ms + tick_budget_ms
    src.tick_deadline_ms = tick_deadline_ms
    -- Result decoding and mesh preparation share the remaining time after the
    -- foreground commands. Reserve a small slice so a busy script cannot
    -- indefinitely starve jobs it is polling without explicitly awaiting.
    local background_pending=false
    for _,task in pairs(src.native_workers or {}) do
        if task.phase=="running" or task.discard then background_pending=true;break end
    end
    if not background_pending then
        for _,world in pairs(world3d_worlds or {}) do
            if next(world.mesh_jobs or {}) then background_pending=true;break end
        end
    end
    local main_deadline_ms=tick_deadline_ms-
        (background_pending and math.min(.5,tick_budget_ms*.10) or 0)
    if next(src.input_watched_mouse or {}) and
       (src.current_idx<=#src.queue or #(src.call_stack or {})>0 or
        #(src.async_tasks or {})>0 or next(src.input_handlers or {})) then
        local ok,accepted,why=pcall(input_host.sample_pending,src)
        if not ok then why=accepted;accepted=false end
        if not accepted then
            generate_stack_trace(src,'Main Execution Loop',src.queue,src.labels,src.call_stack,
                src.current_idx,src.context_id,why)
            src.current_idx=#src.queue+1
        end
    end
    local animation_start_ms=engine_tick_now_ms()
    if world3d_animation_tick then
        world3d_animation_tick(fps,
            math.min(tick_deadline_ms,animation_start_ms+tick_budget_ms*0.25),src)
    end
    src.tick_last_animation_ms=engine_tick_now_ms()-animation_start_ms
    local function find_async_task_index(ctx, wanted, preferred_index)
        local tasks = ctx.async_tasks or {}
        if preferred_index and tasks[preferred_index] == wanted then
            return preferred_index
        end
        for i = #tasks, 1, -1 do
            if tasks[i] == wanted then
                return i
            end
        end
        return nil
    end
    if src.tcp_connections then
        local network_start_ms=engine_tick_now_ms()
        TCP.pump(src,tick_deadline_ms)
        src.tick_last_network_ms=engine_tick_now_ms()-network_start_ms
    else src.tick_last_network_ms=0 end
    if not src.active_scope then
        src.active_scope = {}
    end
    -- Keep the same delta throughout a logical script frame if the command
    -- budget makes it span multiple OBS ticks. !wait | frame sets the real
    -- elapsed time when the next logical frame begins.
    if not src.frame_tick_active then
        src.active_scope["tick"] = fps or 0.016
    end
    -- [[ INTERRUPT INTERCEPTOR ]]
    if src.interrupt_label then
        local jmp = src.labels[src.interrupt_label] or
                        (src.global_registry and src.global_registry[src.interrupt_label])
        if jmp then
            if type(jmp) == "table" then
                src.current_idx = jmp.index
                src.queue = jmp.queue or src.queue
                src.labels = jmp.labels or src.labels
                src.context_id = jmp.ctx or src.context_id
            else
                src.current_idx = jmp
            end
            src.state = {}
        end
        src.interrupt_label = nil
    end

    -- [[ PHYSICS ENGINE ]]
    if src.collision_listeners then
        local group_cache = {}
        local bounds_cache = {}
        local function resolve_collision_group(src, identifier)
            if identifier and group_cache[identifier] then return group_cache[identifier] end
            local group = {}
            if type(identifier) == "table" and identifier.data then
                if not obslua.obs_source_removed(identifier.get_source()) then
                    table.insert(group, identifier)
                end
                group_cache[identifier] = group
                return group
            end

            if type(identifier) == "string" then
                local found_any = false
                if src.templates and src.templates[identifier] then
                    local tpl = src.templates[identifier]
                    if not obslua.obs_source_removed(tpl.get_source()) then
                        table.insert(group, tpl)
                        found_any = true
                    end
                end
                if all_source_clones then
                    for _, clone in ipairs(all_source_clones) do
                        if clone.template_id == identifier and not obslua.obs_source_removed(clone.get_source()) then
                            table.insert(group, clone)
                            found_any = true
                        end
                    end
                end
                if not found_any then
                    local obj = SCRIPT_FUNCS["source"] and SCRIPT_FUNCS["source"](src, identifier)
                    if obj and not obslua.obs_source_removed(obj.get_source()) then
                        table.insert(group, obj)
                    end
                end
            end

            if identifier then group_cache[identifier] = group end
            return group
        end
        local function collision_bounds(obj)
            local cached = bounds_cache[obj]
            if cached then return cached end
            local pos = obj.pos()
            cached = {
                x = pos.x, y = pos.y,
                w = obj.width(), h = obj.height(),
                visible = obslua.obs_sceneitem_visible(obj.data)
            }
            bounds_cache[obj] = cached
            return cached
        end

        for _, col in ipairs(src.collision_listeners) do
            local group1 = resolve_collision_group(src, col.s1)
            local group2 = resolve_collision_group(src, col.s2)
            if not col.pair_states then
                col.pair_states = {}
            end
            local current_frame_pairs = {}
            for _, obj1 in ipairs(group1) do
                for _, obj2 in ipairs(group2) do
                    if obj1 ~= obj2 then
                        local pair_id = tostring(obj1.data) .. "_" .. tostring(obj2.data)
                        current_frame_pairs[pair_id] = true

                        local p1 = collision_bounds(obj1)
                        local p2 = collision_bounds(obj2)
                        local p1x, p1y = p1.x, p1.y
                        local p2x, p2y = p2.x, p2.y
                        local state = col.pair_states[pair_id]
                        if not state then
                            state = {
                                is_colliding = false,
                                last_p1x = p1x,
                                last_p1y = p1y
                            }
                        end
                        local w1, h1 = p1.w, p1.h
                        local w2, h2 = p2.w, p2.h
                        local vx = p1x - state.last_p1x
                        local vy = p1y - state.last_p1y
                        state.last_p1x, state.last_p1y = p1x, p1y
                        local check_x = (vx < 0) and p1x or (p1x - vx)
                        local check_y = (vy < 0) and p1y or (p1y - vy)
                        local check_w = w1 + math.abs(vx)
                        local check_h = h1 + math.abs(vy)
                        local is_vis = p1.visible and p2.visible
                        local collision = is_vis and
                                              not ((check_x + check_w < p2x) or (check_x > p2x + w2) or
                                                  (check_y + check_h < p2y) or (check_y > p2y + h2))
                        if collision then
                            if not state.is_colliding then
                                state.is_colliding = true
                                if col.binding then
                                    local first_ok,first_name=pcall(obj1.get_name)
                                    local second_ok,second_name=pcall(obj2.get_name)
                                    INPUT_EVENTS.emit(col.binding,{kind='collision',source=obj1,other=obj2,
                                        source_name=first_ok and first_name or '',other_name=second_ok and second_name or '',pair=pair_id,dt=fps or .016})
                                end
                                local clean_target = type(col.target_label) == "string" and
                                                         col.target_label:match("^%<(.+)%>$") or col.target_label
                                local target_data = (src.labels and src.labels[clean_target]) or
                                                        (src.global_registry and src.global_registry[clean_target])
                                if target_data then
                                    local snapshot = {}
                                    if src.active_scope then
                                        table.insert(snapshot, src.active_scope)
                                    end
                                    pcall(function()
                                        snapshot[obj2.get_name()] = obj2
                                    end)
                                    snapshot["_collider"] = obj1
                                    snapshot["_collided_with"] = obj2
                                    local start_idx = type(target_data) == "table" and target_data.index or target_data
                                    local start_ctx = type(target_data) == "table" and target_data.ctx or 0
                                    local target_queue = type(target_data) == "table" and target_data.queue or src.queue
                                    local target_labels_tbl =
                                        type(target_data) == "table" and target_data.labels or src.labels
                                    local interrupt_thread = {
                                        type = "THREAD",
                                        queue = target_queue,
                                        labels = target_labels_tbl,
                                        current_idx = start_idx,
                                        context_id = start_ctx,
                                        state = {},
                                        active_source = obj1,
                                        active_sources = {obj1},
                                        scopes = snapshot,
                                        call_stack = {},
                                        name = obs.utils.get_unique_id(2)
                                    }
                                    src.next_context_id = src.next_context_id + 1
                                    if not src.async_tasks then
                                        src.async_tasks = {}
                                    end
                                    table.insert(src.async_tasks, interrupt_thread)
                                end
                            end
                        else
                            state.is_colliding = false
                        end

                        col.pair_states[pair_id] = state
                    end
                end
            end

            for pid, _ in pairs(col.pair_states) do
                if not current_frame_pairs[pid] then
                    col.pair_states[pid] = nil
                end
            end
        end
    end

    if src.pinned_sources then
        for pin_id, pin_data in pairs(src.pinned_sources) do
            if pin_data.child and pin_data.parent then
                local p_status, p_pos = pcall(function()
                    return pin_data.parent.pos()
                end)
                local c_status, c_pos = pcall(function()
                    return pin_data.child.pos()
                end)
                if p_status and p_pos and c_status and c_pos then
                    pcall(function()
                        pin_data.child.pos({
                            x = p_pos.x + pin_data.ox,
                            y = p_pos.y + pin_data.oy
                        })
                    end)
                else
                    src.pinned_sources[pin_id] = nil
                end
            end
        end
    end
    if src.watchers then
        for _, w in ipairs(src.watchers) do
            local current_val = resolve_path(src, w.var)
            local current_str = tostring(current_val)
            if current_str ~= w.last_val then
                w.last_val = current_str

                local condition_met = false

                if w.op and w.val then
                    local check_val = resolve_path(src, w.val)
                    local v1, v2 = tonumber(current_val), tonumber(check_val)

                    if v1 and v2 then
                        if w.op == "==" then
                            condition_met = (v1 == v2)
                        elseif w.op == ">" then
                            condition_met = (v1 > v2)
                        elseif w.op == "<" then
                            condition_met = (v1 < v2)
                        elseif w.op == ">=" then
                            condition_met = (v1 >= v2)
                        elseif w.op == "<=" then
                            condition_met = (v1 <= v2)
                        elseif w.op == "!=" or w.op == "~=" then
                            condition_met = (v1 ~= v2)
                        end
                    else
                        if w.op == "==" then
                            condition_met = (current_str == tostring(check_val))
                        elseif w.op == "!=" or w.op == "~=" then
                            condition_met = (current_str ~= tostring(check_val))
                        end
                    end
                else
                    condition_met = true
                end

                if condition_met then
                    local clean_target = type(w.label) == "string" and w.label:match("^%<(.+)%>$") or w.label
                    local target_data = (src.labels and src.labels[clean_target]) or
                                            (src.global_registry and src.global_registry[clean_target])

                    if target_data then
                        local snapshot = {}
                        if src.active_scope then
                            table.insert(snapshot, src.active_scope)
                        end
                        local start_idx = type(target_data) == "table" and target_data.index or target_data
                        local start_ctx = type(target_data) == "table" and target_data.ctx or 0
                        local target_queue = type(target_data) == "table" and target_data.queue or src.queue
                        local target_labels_tbl = type(target_data) == "table" and target_data.labels or src.labels
                        local interrupt_thread = {
                            type = "THREAD",
                            queue = target_queue,
                            labels = target_labels_tbl,
                            current_idx = start_idx,
                            context_id = start_ctx,
                            state = {},
                            active_source = src.scene_item,
                            active_sources = src.active_sources,
                            scopes = snapshot,
                            call_stack = {},
                            collision_listeners = src.collision_listeners,
                            name = obs.utils.get_unique_id(2)
                        }
                        src.next_context_id = src.next_context_id + 1
                        table.insert(src.async_tasks, interrupt_thread)
                    end
                end
            end
        end
    end
    if next(src.input_handlers or {}) or src.ui_state then
        local poll_ok,input_ok,input_err=pcall(INPUT_EVENTS.poll,src,fps or .016,main_deadline_ms)
        if not poll_ok then input_err=input_ok;input_ok=false end
        if not input_ok then
            generate_stack_trace(src,'Main Execution Loop',src.queue,src.labels,src.call_stack,
                src.current_idx,src.context_id,input_err)
            src.current_idx=#src.queue+1
        end
    end
    local async_start_ms = engine_tick_now_ms()
    src.tick_last_events_ms = async_start_ms - tick_start_ms
    if src.async_tasks then
        local async_snapshot = {}
        for i, task in ipairs(src.async_tasks) do
            async_snapshot[i] = task
        end
        local async_start = math.min(src.async_resume_index or #async_snapshot, #async_snapshot)
        if src.async_resume_task then
            for i, task in ipairs(async_snapshot) do
                if task == src.async_resume_task then
                    async_start = i
                    break
                end
            end
        end
        src.async_resume_index = nil
        src.async_resume_task = nil
        local processed_async = 0
        for i = async_start, 1, -1 do
            if processed_async > 0 and engine_tick_now_ms() >= tick_deadline_ms then
                src.async_resume_index = i
                src.async_resume_task = async_snapshot[i]
                break
            end
            local task = async_snapshot[i]
            if task and not find_async_task_index(src, task, i) then
                task = nil
            end
            if task then
                processed_async = processed_async + 1
            end
            if task and task.type == "EMITTER" then
                local now = engine_tick_now_ms()
                if now - task.last_spawn_time >= task.interval then
                    task.last_spawn_time = now
                    task.spawned = task.spawned + 1

                    local template = SCRIPT_FUNCS.source(src, task.target_name)
                    if template then
                        local old_item = src.scene_item
                        src.scene_item = template
                        local cloned_item = SCRIPT_FUNCS.clone(src, true)
                        src.scene_item = old_item

                        if cloned_item and task.labels[task.setup_label] then
                            local snapshot = {}
                            if src.active_scope then
                                table.insert(snapshot, src.active_scope)
                            end
                            local start_idx = type(task.labels[task.setup_label]) == "table" and
                                                  task.labels[task.setup_label].index or task.labels[task.setup_label]
                            local start_ctx = type(task.labels[task.setup_label]) == "table" and
                                                  task.labels[task.setup_label].ctx or 0

                            local new_thread = {
                                type = "THREAD",
                                queue = task.queue,
                                labels = task.labels,
                                current_idx = start_idx,
                                state = {},
                                context_id = start_ctx,
                                active_source = cloned_item,
                                active_sources = {cloned_item},
                                scopes = snapshot,
                                call_stack = {},
                                collision_listeners = src.collision_listeners,
                                name = task.name or obs.utils.get_unique_id(2)
                            }
                            src.next_context_id = src.next_context_id + 1
                            table.insert(src.async_tasks, new_thread)
                        end
                    end

                    if task.spawned >= task.max_count then
                        local live_index = find_async_task_index(src, task, i)
                        if live_index then table.remove(src.async_tasks, live_index) end
                    end
                end
            elseif task and task.type == "LIFETIME" then
                if engine_tick_now_ms() >= task.expire_time then
                    cleanup_lifetime_task(src, task)
                    local live_index = find_async_task_index(src, task, i)
                    if live_index then table.remove(src.async_tasks, live_index) end
                end
            elseif task and task.type == "THREAD" then
                local input_error_generation=src.input_error_generation
                local still_alive = step_thread_task(src, task, task.step_budget or 10, tick_deadline_ms)
                if not still_alive then
                    if task.input_binding and src.input_error_generation~=input_error_generation then
                        INPUT_EVENTS.cancel(src,task.input_binding)
                    end
                    local live_index = find_async_task_index(src, task, i)
                    if live_index then table.remove(src.async_tasks, live_index) end
                end
            else
                if task then
                    if not task.exe then
                        task.exe = compile_line(task.cmd, task.args)
                    end
                    if task.exe then
                        local is_finished = task.exe(src, task.state)
                        if is_finished then
                            local live_index = find_async_task_index(src, task, i)
                            if live_index then table.remove(src.async_tasks, live_index) end
                        end
                    end
                end
            end
        end
    end
    local main_start_ms = engine_tick_now_ms()
    src.tick_last_async_ms = main_start_ms - async_start_ms
    local brake = 0
    -- [[ EXECUTION LOOP ]]
    while src and src.queue and src.queue[src.current_idx] do
        if brake >= 1000 or (brake > 0 and engine_tick_now_ms() >= main_deadline_ms) then
            src.no_yield_budget_ticks = (src.no_yield_budget_ticks or 0) + 1
            if (src.no_yield_ops or 0) >= 20000 or src.no_yield_budget_ticks >= 120 then
                generate_stack_trace(src, "Main Execution Loop", src.queue, src.labels, src.call_stack,
                    src.current_idx, src.context_id,
                    "Runaway script: execution kept exhausting tick budgets without yielding. Add !wait | frame or fix the loop.")
                src.current_idx = #src.queue + 1
                src.state = {}
            end
            break
        end
        local execute_func = src.queue[src.current_idx]
        if not execute_func then
            src.current_idx = src.current_idx + 1;
            src.state = {};
            break
        end

        local success, result, target = pcall(execute_func, src)
        if not success then
            generate_stack_trace(src, "Main Execution Loop", src.queue, src.labels, src.call_stack, src.current_idx,
                src.context_id, result)
            src.current_idx = #src.queue + 1
            result = false
        elseif result == false and type(target) == "string" then
            generate_stack_trace(src, "Main Execution Loop", src.queue, src.labels, src.call_stack, src.current_idx,
                src.context_id, target)
            src.current_idx = #src.queue + 1
            result = false
        end

        if result == false then
            src.no_yield_ops = 0
            src.no_yield_budget_ticks = 0
            break
        end
        brake = brake + 1
        src.no_yield_ops = (src.no_yield_ops or 0) + 1
        if result == "CALL" or result == "FN_CALL" then
            local call_meta = type(target) == "table" and target or {
                target = target
            }
            local clean_target = type(call_meta.target) == "string" and call_meta.target:match("^%<(.+)%>$") or
                                     call_meta.target
            local angle_target = type(clean_target) == "string" and ("<" .. clean_target .. ">") or clean_target

            local jmp
            if result == "FN_CALL" then
                jmp = resolve_function_target(src, clean_target)
            else
                jmp = src.labels[clean_target] or src.labels[angle_target] or
                    (src.global_registry and
                        (src.global_registry[clean_target] or src.global_registry[angle_target]))
            end
            if jmp then
                local jmp_idx = type(jmp) == "table" and jmp.index or jmp
                local jmp_ctx = type(jmp) == "table" and jmp.ctx or 0
                local is_global = type(jmp) == "table" and jmp.global or false
                local jmp_queue = type(jmp) == "table" and jmp.queue or src.queue
                local jmp_labels = type(jmp) == "table" and jmp.labels or src.labels
                local current_ctx = src.context_id or 0

                if jmp_ctx == current_ctx or is_global then
                    if not src.call_stack then
                        src.call_stack = {}
                    end
                    if result == "FN_CALL" and #src.call_stack >= 128 then
                        generate_stack_trace(src, "Main Execution Loop", src.queue, src.labels, src.call_stack,
                            src.current_idx, src.context_id, "Function Error: Maximum call depth (128) exceeded")
                        src.current_idx = #src.queue + 1
                        result = false
                        break
                    end
                    table.insert(src.call_stack, {
                        idx = src.current_idx + 1,
                        queue = src.queue,
                        labels = src.labels,
                        ctx = src.context_id,
                        scope = src.active_scope,
                        ret_var = call_meta.ret_var
                    })

                    local parent_scope = src.active_scope or {}
                    local new_scope = {}
                    setmetatable(new_scope, {
                        __index = parent_scope,
                        __newindex = function(t, k, v)
                            local target_scope, _ = retrieve_scope(parent_scope, k)
                            if target_scope then
                                target_scope[k] = v
                            else
                                rawset(t, k, v)
                            end
                        end
                    })

                    if call_meta.args then
                        for k, v in pairs(call_meta.args) do
                            rawset(new_scope, k, v)
                        end
                    end

                    src.active_scope = new_scope
                    src.context_id = jmp_ctx
                    src.current_idx = jmp_idx
                    src.queue = jmp_queue
                    src.labels = jmp_labels
                else
                    generate_stack_trace(src, "Main Execution Loop", src.queue, src.labels, src.call_stack,
                        src.current_idx, src.context_id, "Call Error: Blocked cross-context [call] to '" ..
                            tostring(clean_target) .. "'")
                    src.current_idx = #src.queue + 1
                    result = false
                end
            else
                generate_stack_trace(src, "Main Execution Loop", src.queue, src.labels, src.call_stack, src.current_idx,
                    src.context_id, (result == "FN_CALL" and "Function Error: Unknown function '" or
                        "Call Error: Unknown label '") .. tostring(clean_target) .. "'")
                src.current_idx = #src.queue + 1
                result = false
            end

        elseif result == "RETURN" then
            local ret_val = target
            if src.call_stack and #src.call_stack > 0 then
                local popped = table.remove(src.call_stack)
                if type(popped) == "table" then
                    -- [[ ENGINE PATCH: Correct Scope Recovery ]]
                    -- We must restore the parent scope BEFORE writing the return value
                    -- so that the value is written to the scope that called the function.
                    local target_write_scope = popped.scope or src.scopes

                    src.current_idx = popped.idx or 1
                    src.queue = popped.queue or src.queue
                    src.labels = popped.labels or src.labels
                    src.context_id = popped.ctx or src.context_id
                    src.scopes = target_write_scope
                    src.active_scope = target_write_scope

                    if popped.ret_var and ret_val ~= nil then
                        local ok,written=pcall(update_variable_state,src,popped.ret_var,ret_val)
                        if not ok or is_fatal(written) then
                            generate_stack_trace(src,"Main Execution Loop",src.queue,src.labels,src.call_stack,
                                src.current_idx,src.context_id,ok and written.msg or written)
                            src.current_idx=#src.queue+1
                            src.state={}
                            break
                        end
                    end
                else
                    src.current_idx = popped or 1
                end
            else
                src.current_idx = #(src.queue or {}) + 1
            end
            src.state = {}
        elseif result == "JUMP" then
            local clean_target = type(target) == "string" and target:match("^%<(.+)%>$") or target

            local jmp = src.labels[clean_target] or (src.global_registry and src.global_registry[clean_target])

            if jmp then
                local jmp_idx = type(jmp) == "table" and jmp.index or jmp
                local jmp_ctx = type(jmp) == "table" and jmp.ctx or 0
                local is_global = type(jmp) == "table" and jmp.global or false
                local jmp_queue = type(jmp) == "table" and jmp.queue or src.queue
                local jmp_labels = type(jmp) == "table" and jmp.labels or src.labels
                local current_ctx = src.context_id or 0

                if jmp_ctx == current_ctx or is_global then
                    src.current_idx = jmp_idx
                    src.context_id = jmp_ctx
                    src.queue = jmp_queue
                    src.labels = jmp_labels
                else
                    generate_stack_trace(src, "Main Execution Loop", src.queue, src.labels, src.call_stack,
                        src.current_idx, src.context_id, "Jump Error: Blocked cross-context [jump] to '" ..
                            tostring(clean_target) .. "'")
                    src.current_idx = #src.queue + 1
                    result = false
                end
            else
                generate_stack_trace(src, "Main Execution Loop", src.queue, src.labels, src.call_stack, src.current_idx,
                    src.context_id, "Jump Error: Unknown label '" .. tostring(clean_target) .. "'")
                src.current_idx = #src.queue + 1
                result = false
            end
        elseif result == true then
            src.current_idx = (src.current_idx or 1) + 1;
            src.state = {}
        end
    end
    if not src.queue or not src.queue[src.current_idx] then
        src.no_yield_ops = 0
        src.no_yield_budget_ticks = 0
    end

    local collision_start_ms = engine_tick_now_ms()
    src.tick_last_main_ms = collision_start_ms - main_start_ms
    -- ==========================================================
    -- [[ COLLISION SOLVER ]]
    -- ==========================================================
    if src.colliders then
        local rects = {}
        for id, col in pairs(src.colliders) do
            if col.item then
                local s, pos = pcall(function()
                    return col.item.pos()
                end)
                if s and pos then
                    table.insert(rects, {
                        id = id,
                        item = col.item,
                        material = col.material,
                        is_active = col.is_active,
                        x = pos.x,
                        y = pos.y,
                        w = col.item.width() or 0,
                        h = col.item.height() or 0,
                        last_x = col.last_x or pos.x,
                        last_y = col.last_y or pos.y,
                        col_ref = col
                    })
                end
            else
                src.colliders[id] = nil
            end
        end
        for i = 1, #rects do
            local a = rects[i]
            if a.material == "solid" then
                for j = i + 1, #rects do
                    local b = rects[j]
                    if b.material == "solid" and (a.x < b.x + b.w) and (a.x + a.w > b.x) and
                        (a.y < b.y + b.h) and (a.y + a.h > b.y) then

                        local p_left = (a.x + a.w) - b.x
                        local p_right = (b.x + b.w) - a.x
                        local p_up = (a.y + a.h) - b.y
                        local p_down = (b.y + b.h) - a.y

                        if p_left > 0 and p_right > 0 and p_up > 0 and p_down > 0 then
                            local px, py = 0, 0

                            local vx = (a.x - a.last_x) - (b.x - b.last_x)
                            local vy = (a.y - a.last_y) - (b.y - b.last_y)

                            local min_x = math.min(p_left, p_right)
                            local min_y = math.min(p_up, p_down)

                            if min_x < min_y then
                                if vx > 0.1 then
                                    px = -p_left
                                elseif vx < -0.1 then
                                    px = p_right
                                else
                                    px = (p_left < p_right) and -p_left or p_right
                                end
                            else
                                if vy > 0.1 then
                                    py = -p_up
                                elseif vy < -0.1 then
                                    py = p_down
                                else
                                    py = (p_up < p_down) and -p_up or p_down
                                end
                            end

                            if a.is_active and not b.is_active then
                                a.x = a.x + px;
                                a.y = a.y + py
                            elseif b.is_active and not a.is_active then
                                b.x = b.x - px;
                                b.y = b.y - py
                            else
                                a.x = a.x + (px * 0.5);
                                a.y = a.y + (py * 0.5)
                                b.x = b.x - (px * 0.5);
                                b.y = b.y - (py * 0.5)
                            end
                        end
                    end
                end
            end
        end

        for _, r in ipairs(rects) do
            if r.is_active then
                pcall(function()
                    r.item.pos({
                        x = r.x,
                        y = r.y
                    })
                end)
            end

            if r.col_ref then
                r.col_ref.last_x = r.x
                r.col_ref.last_y = r.y
            end
        end
    end
    local ui_start_ms=engine_tick_now_ms()
    if src.ui_state then ENGINE_UI.render(src) end
    src.tick_last_ui_ms=engine_tick_now_ms()-ui_start_ms
    local tick_end_ms = engine_tick_now_ms()
    src.tick_last_collision_ms = ui_start_ms - collision_start_ms
    -- Rotate the first background consumer so both kinds make progress when
    -- only a fraction of their usual maximum slice remains.
    local background_start_ms=tick_end_ms
    local turn=src.tick_background_turn or 0
    src.tick_background_turn=1-turn
    for stage=1,2 do
        local now=engine_tick_now_ms()
        if now>=tick_deadline_ms then break end
        if (stage+turn)%2==1 then
            if src.native_workers then
                native_worker_poll_all(src,math.min(tick_deadline_ms,now+tick_budget_ms*.15))
            end
        elseif world3d_mesh_tick then
            world3d_mesh_tick(math.min(tick_deadline_ms,now+tick_budget_ms*.20))
        end
    end
    tick_end_ms=engine_tick_now_ms()
    src.tick_last_background_ms=tick_end_ms-background_start_ms
    src.tick_last_ms = tick_end_ms - tick_start_ms
    src.tick_deadline_ms = nil
    if src.tcp_connections and src.current_idx > #src.queue and #(src.async_tasks or {}) == 0 and
       not next(src.input_handlers or {}) and not src.ui_state then
        TCP.close_all(src)
    end
    if (src.input_preview_menu_blocked or src.input_projector_controls) and
       src.current_idx > #src.queue and #(src.async_tasks or {}) == 0 and not next(src.input_handlers or {}) and not src.ui_state then
        input_preview_menu_release(src)
    end
    if src.tick_last_ms > math.max(tick_budget_ms * 2, 12) and
        (not src.next_budget_warning_ms or tick_end_ms >= src.next_budget_warning_ms) then
        src.next_budget_warning_ms = tick_end_ms + 5000
        -- if obslua and obslua.script_log then
        --     obslua.script_log(obslua.LOG_WARNING,
        --         string.format("[4IM3-SCRIPT] Tick took %.1f ms (events %.1f, async %.1f, main %.1f, collision %.1f; budget %d ms). A single command or collision pass cannot be interrupted mid-operation.",
        --             src.tick_last_ms, src.tick_last_events_ms, src.tick_last_async_ms,
        --             src.tick_last_main_ms, src.tick_last_collision_ms, tick_budget_ms))
        -- end
    end
end

-- [[ OBS CUSTOM API LIBRARY ]]

-- [[ OBS CUSTOM API BEGIN ]]
-- [[ OBS CUSTOM CALLBACKS ]]
local engine_frontend_callback
function script_load(settings)

    -- print("[OBS CUSTOM WRAPPER API]")
    local ck = os.clock()
    obs.utils.script_shutdown = false
    obs.utils.settings = obs.PairStack(settings, nil, nil, true)
    -- print("api_exit: " .. tostring(obs.utils.settings.bul("obs_custom_api_exited")))
    if obs.utils.settings.get_bul("obs_custom_api_exited") == false then
        obs.utils.loaded = true
    end
    if setup and type(setup) == "function" then
        setup(obs.utils.settings)
    end

    raymaze_source_info.type = obslua.OBS_SOURCE_TYPE_INPUT
    local interaction_flag = obslua.OBS_SOURCE_INTERACTION or 32
    raymaze_source_info.output_flags = bit.bor(obslua.OBS_SOURCE_VIDEO, interaction_flag)
    obslua.obs_register_source(raymaze_source_info)
    shader_source_info.type = obslua.OBS_SOURCE_TYPE_INPUT
    shader_source_info.output_flags = bit.bor(obslua.OBS_SOURCE_VIDEO,
        obslua.OBS_SOURCE_CUSTOM_DRAW or 8, interaction_flag)
    obslua.obs_register_source(shader_source_info)
    world3d_source_info.type = obslua.OBS_SOURCE_TYPE_INPUT
    world3d_source_info.output_flags = bit.bor(obslua.OBS_SOURCE_VIDEO,
        obslua.OBS_SOURCE_CUSTOM_DRAW or 8, interaction_flag)
    obslua.obs_register_source(world3d_source_info)
    for _, filter in pairs(obs.utils.filters) do
        obslua.obs_register_source(filter)
    end
    if host_os == "Windows" then
        local ui_ok, ui_err = input_ui_initialize()
        if not ui_ok then
            obslua.script_log(obslua.LOG_WARNING,
                "[4IM3-SCRIPT] UI dispatcher initialization failed: " .. tostring(ui_err))
        end
    end
    local script_is_unloading = false
    engine_frontend_callback = function(event_id)
        -- print("[OBS CUSTOM API] Frontend event triggered: " .. tostring(event_id))
        if event_id == obslua.OBS_FRONTEND_EVENT_FINISHED_LOADING then
            -- print("[OBS CUSTOM API] Finished loading, initializing script... took " .. string.format("%.2f", (os.clock() - ck) * 1000) .. "ms")
            obs.utils.first_time_load = true
            obs.utils.loaded = true
            obs.utils.settings.bul("obs_custom_api_exited", false)
        elseif event_id == obslua.OBS_FRONTEND_EVENT_EXIT or
            (script_is_unloading and event_id == obslua.OBS_FRONTEND_EVENT_SCENE_COLLECTION_CLEANUP) then
            obs.utils.obs_closing = true
        elseif event_id == obslua.OBS_FRONTEND_EVENT_SCRIPTING_SHUTDOWN then
            script_is_unloading = true
            obs.utils.obs_closing = true
            obs.utils.script_shutdown = true
            if ENGINE_UI then ENGINE_UI.clear(src) end
            if src.input_handlers then INPUT_EVENTS.clear(src) end
            if TCP then TCP.shutdown(src) end
            -- OBS is still processing UI events here. Restoring the preview
            -- hook from script_unload can otherwise wait on a UI thread that
            -- is already waiting for script teardown to finish.
            local menu_ok, menu_err = input_preview_menu_release(src)
            if not menu_ok then
                obslua.script_log(obslua.LOG_WARNING,
                    "[4IM3-SCRIPT] Preview menu restore failed: " .. tostring(menu_err))
            end
            local ui_ok, ui_err = preview_menu_close()
            if not ui_ok then
                obslua.script_log(obslua.LOG_WARNING,
                    "[4IM3-SCRIPT] UI dispatcher cleanup failed: " .. tostring(ui_err))
            end
            if src.native_workers then native_worker_cancel_all(src) end
            for _,world in pairs(world3d_worlds or {}) do world3d_cancel_builds(world) end
            input_wheel_release()
            if x11_keyboard then
                x11_keyboard.library.XCloseDisplay(x11_keyboard.display)
                x11_keyboard = nil
            end
        end
    end
    obslua.obs_frontend_add_event_callback(engine_frontend_callback)
    obs.time.schedule(function()
        obs.utils.loaded = true
    end).after(1200)
end

function script_save(settings)
    -- print("[UNI-SAVE-IT]")
    obs.utils.settings.bul("obs_custom_api_exited", true)
    if obs.utils.script_shutdown then
        return
    end

    -- [[ OBS REGISTER HOTKEY SAVE DATA]]
    for name, iter in pairs(obs.register.hotkey_id_list) do
        local new_data = obslua.obs_hotkey_save(iter.id)
        if new_data then
            obs.utils.settings.arr(name, new_data)
            obslua.obs_data_array_release(new_data)
        end
    end
    -- [[ OBS REGISTER HOTKEY SAVE DATA END]]

    if type(onSaving) == "function" then
        return onSaving(obs.PairStack(settings, nil, nil, true))
    end
end

function script_unload()
    obs.utils.script_shutdown = true
    if src and ENGINE_UI then ENGINE_UI.clear(src) end
    if src and src.input_handlers then INPUT_EVENTS.clear(src) end
    if TCP then TCP.shutdown(src) end
    local menu_ok, menu_err = input_preview_menu_release(src)
    if not menu_ok then
        obslua.script_log(obslua.LOG_WARNING,
            "[4IM3-SCRIPT] Preview menu restore failed: " .. tostring(menu_err))
    end
    local ui_ok, ui_err = preview_menu_close()
    if not ui_ok then
        obslua.script_log(obslua.LOG_WARNING,
            "[4IM3-SCRIPT] UI dispatcher cleanup failed: " .. tostring(ui_err))
    end
    if src.native_workers then native_worker_cancel_all(src) end
    for _,world in pairs(world3d_worlds or {}) do world3d_cancel_builds(world) end
    input_wheel_release()
    if x11_keyboard then
        x11_keyboard.library.XCloseDisplay(x11_keyboard.display)
        x11_keyboard = nil
    end

    for callback in pairs(obs.utils.scheduled or {}) do
        obslua.timer_remove(callback)
        obs.utils.scheduled[callback] = nil
    end

    -- for _, iter in pairs(obs.mem.freeup) do
    --     if iter and iter.data then
    --         iter.free()
    --     end
    -- end
    if obs._unload and type(obs._unload) == "table" then
        for _, iter in pairs(obs._unload) do
            if type(iter) == "table" and iter.data and iter.free then
                iter.free()
            elseif type(iter) == "function" then
                pcall(function()
                    iter()
                end)
            end
        end
    end
    obs.register:hotkey_remove()
    if engine_frontend_callback then
        obslua.obs_frontend_remove_event_callback(engine_frontend_callback)
        engine_frontend_callback = nil
    end
    for _, event in pairs(obs.register.event_id_list) do
        if event and type(event.remove) == "function" then
            event.remove(true)
        end
    end
    if unset and type(unset) == "function" then
        return unset()
    end
end

function script_defaults(settings, pp)
    settings = obs.PairStack(settings, nil, nil, true)
    settings.bul("obs_custom_api_exited", false, true)
    if type(defaults) == "function" then
        return defaults(settings)
    end
end

function script_properties()
    if obs.utils.ui and type(obs.utils.ui) == "function" then
        return obs.utils.ui()
    end
end

